INSERT INTO public.language_content_items VALUES (174, 1, 'reading', 'C2', 'lesson', 'The Geopolitics of Quantum Sovereignty', '{"text": "The impending realization of fault-tolerant quantum computing scales has ignited an aggressive international race for quantum sovereignty, fundamentally redefining the parameter of macroeconomic stability and state security. Unlike conventional semiconductor innovations, which offer incremental upgrades to computational velocity, quantum architecture leverages superposition and entanglement to execute complex calculations at speeds that completely invalidate existing cryptographic standards. The primary geopolitical implication centers on the vulnerability of current public-key encryption infrastructure, specifically RSA algorithms, which safeguard global financial transactions, state secrets, and critical industrial networks. A sovereign state that achieves mathematical supremacy via a scalable quantum system would possess the asymmetric capacity to decrypt legacy data retroactively, thereby neutralizing the strategic intelligence shields of foreign adversaries. Recognizing this systemic risk, European research institutes and regulatory frameworks are accelerating the development of post-quantum cryptography (PQC) standards to fortify critical digital infrastructure before decryption capabilities materialize. However, the transition to quantum-resistant ecosystems is profoundly complicated by the sheer material scarcity of essential components, such as superconducting materials and highly specialized dilution refrigerators. Consequently, the geopolitical landscape is splintering into technocratic blocs, with major global powers implementing aggressive export controls on quantum hardware and intellectual capital to prevent strategic spillover. This strategic imperative forces smaller economies to navigate complex technological dependencies, demonstrating that future geopolitical autonomy will depend heavily on a nation''s capacity to build and sustain a localized quantum infrastructure, independent of transnational supply chains.", "topic": "advanced science", "passage": "The impending realization of fault-tolerant quantum computing scales has ignited an aggressive international race for quantum sovereignty, fundamentally redefining the parameter of macroeconomic stability and state security. Unlike conventional semiconductor innovations, which offer incremental upgrades to computational velocity, quantum architecture leverages superposition and entanglement to execute complex calculations at speeds that completely invalidate existing cryptographic standards. The primary geopolitical implication centers on the vulnerability of current public-key encryption infrastructure, specifically RSA algorithms, which safeguard global financial transactions, state secrets, and critical industrial networks. A sovereign state that achieves mathematical supremacy via a scalable quantum system would possess the asymmetric capacity to decrypt legacy data retroactively, thereby neutralizing the strategic intelligence shields of foreign adversaries. Recognizing this systemic risk, European research institutes and regulatory frameworks are accelerating the development of post-quantum cryptography (PQC) standards to fortify critical digital infrastructure before decryption capabilities materialize. However, the transition to quantum-resistant ecosystems is profoundly complicated by the sheer material scarcity of essential components, such as superconducting materials and highly specialized dilution refrigerators. Consequently, the geopolitical landscape is splintering into technocratic blocs, with major global powers implementing aggressive export controls on quantum hardware and intellectual capital to prevent strategic spillover. This strategic imperative forces smaller economies to navigate complex technological dependencies, demonstrating that future geopolitical autonomy will depend heavily on a nation''s capacity to build and sustain a localized quantum infrastructure, independent of transnational supply chains.", "text_ar": "قرب الوصول الحقيقي لـ حوسبة كمية قادرة على تصحيح الأخطاء شعل سباق دولي شرس على السيادة الكمية، وهاد الشي عم يعيد تعريف معايير الاستقرار الاقتصادي الكلي وأمن الدول من الجذور. وعكس ابتكارات أشباه الموصلات التقليدية، يلي بتقدم تحسينات تدريجية لسرعة الحساب، البنية التحتية الكمية عم تستغل التراكب والتشابك لتنفذ عمليات حسابية معقدة بسرعة بتلغي وبتطير تماماً معايير التشفير الموجودة هلق. النتيجة الجيوسياسية الأساسية بتركز على ضعف بنية التشفير الحالية ذات المفتاح العام، وخاصة خوارزميات (RSA)، يلي بتحمي التحويلات المادية العالمية، وأسرار الدول، وشبكات الصناعة الحساسة. يعني الدولة يلي بتقدر تحقق تفوق رياضي عبر سيستم كمي قابل للتوسع رح تملك قدرة غير متماثلة لتفك تشفير البيانات القديمة وبأثر رجعي، وهاد الشي بيعطل دروع المخابرات الاستراتيجية للدول المنافسة. ولأنهم عرفوا هاد الخطر الممنهج، المعاهد البحثية والأطر التنظيمية الأوروبية عم تسرع هلق تطوير معايير التشفير المابعد كمي (PQC) لتحصين البنية التحتية الرقمية الحساسة قبل ما تطلع قدرات فك التشفير للعلن. بس الانتقال لبيئات مقاومة للكم معقد كتير بسبب النقص الحاد بالمواد الأساسية والمكونات، متل المواد فائقة التوصيل وثلاجات التبريد المتخصصة كتير. وبناءً على هاد الشي، المشهد الجيوسياسي عم ينقسم لتكتلات تكنوقراطية، وصارت القوى العالمية الكبيرة تطبق قوانين تصدير قاسية على معدات الكم ورأس المال الفكري لمنع تسرب الاستراتيجيات. وهي الضرورة الاستراتيجية عم تجبر الاقتصادات الأصغر تمشي بقلب تبعيات تكنولوجية معقدة، وهاد بيوضح إنه الاستقلال الجيوسياسي بالمستقبل رح يعتمد بشكل كبير على قدرة البلد على بناء ودعم بنية تحتية كمية محلية ومستقلة عن سلاسل التوريد العابرة للدول.", "title_ar": "الجيوسياسة للسيادة الكمية", "questions": [{"id": "q1", "stem": "What is the primary geopolitical threat associated with a scalable quantum computing system?", "choices": ["The immediate physical destruction of international semiconductor manufacturing plants.", "An absolute global prohibition on post-quantum cryptography research frameworks.", "The complete replacement of global financial transactions with hardware barter systems.", "The asymmetric capacity to retroactively decrypt legacy public-key encryption infrastructure."], "correct_index": 3}], "passage_ar": "قرب الوصول الحقيقي لـ حوسبة كمية قادرة على تصحيح الأخطاء شعل سباق دولي شرس على السيادة الكمية، وهاد الشي عم يعيد تعريف معايير الاستقرار الاقتصادي الكلي وأمن الدول من الجذور. وعكس ابتكارات أشباه الموصلات التقليدية، يلي بتقدم تحسينات تدريجية لسرعة الحساب، البنية التحتية الكمية عم تستغل التراكب والتشابك لتنفذ عمليات حسابية معقدة بسرعة بتلغي وبتطير تماماً معايير التشفير الموجودة هلق. النتيجة الجيوسياسية الأساسية بتركز على ضعف بنية التشفير الحالية ذات المفتاح العام، وخاصة خوارزميات (RSA)، يلي بتحمي التحويلات المادية العالمية، وأسرار الدول، وشبكات الصناعة الحساسة. يعني الدولة يلي بتقدر تحقق تفوق رياضي عبر سيستم كمي قابل للتوسع رح تملك قدرة غير متماثلة لتفك تشفير البيانات القديمة وبأثر رجعي، وهاد الشي بيعطل دروع المخابرات الاستراتيجية للدول المنافسة. ولأنهم عرفوا هاد الخطر الممنهج، المعاهد البحثية والأطر التنظيمية الأوروبية عم تسرع هلق تطوير معايير التشفير المابعد كمي (PQC) لتحصين البنية التحتية الرقمية الحساسة قبل ما تطلع قدرات فك التشفير للعلن. بس الانتقال لبيئات مقاومة للكم معقد كتير بسبب النقص الحاد بالمواد الأساسية والمكونات، متل المواد فائقة التوصيل وثلاجات التبريد المتخصصة كتير. وبناءً على هاد الشي، المشهد الجيوسياسي عم ينقسم لتكتلات تكنوقراطية، وصارت القوى العالمية الكبيرة تطبق قوانين تصدير قاسية على معدات الكم ورأس المال الفكري لمنع تسرب الاستراتيجيات. وهي الضرورة الاستراتيجية عم تجبر الاقتصادات الأصغر تمشي بقلب تبعيات تكنولوجية معقدة، وهاد بيوضح إنه الاستقلال الجيوسياسي بالمستقبل رح يعتمد بشكل كبير على قدرة البلد على بناء ودعم بنية تحتية كمية محلية ومستقلة عن سلاسل التوريد العابرة للدول.", "vocabulary": ["fault-tolerant", "entanglement", "retroactively", "fortify", "spillover"]}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (121, 1, 'reading', 'A1', 'lesson', 'Hello from Berlin', '{"text": "Hello! My name is Ahmad. I am from Syria. Now, I live in Berlin, Germany. I am twenty-five years old. I am a student here. I speak Arabic and a little English. I learn German every day. Berlin is big and very beautiful. I like my new life here.", "topic": "self-introduction", "passage": "Hello! My name is Ahmad. I am from Syria. Now, I live in Berlin, Germany. I am twenty-five years old. I am a student here. I speak Arabic and a little English. I learn German every day. Berlin is big and very beautiful. I like my new life here.", "text_ar": "الأهلين! اسمي أحمد. أنا من سوريا. هلق أنا عايش ببرلين بألمانيا. عمري خمسة وعشرين سنة. أنا طالب هون. بحكي عربي وشوي إنكليزي. عم اتعلم ألماني كل يوم. برلين كبيرة وحلوة كتير. عاجبتني حياتي الجديدة هون.", "title_ar": "مرحبا من برلين", "questions": [{"id": "q1", "stem": "Where does Ahmad live now?", "choices": ["In Berlin", "In Syria", "In London", "In Damascus"], "correct_index": 0}], "passage_ar": "الأهلين! اسمي أحمد. أنا من سوريا. هلق أنا عايش ببرلين بألمانيا. عمري خمسة وعشرين سنة. أنا طالب هون. بحكي عربي وشوي إنكليزي. عم اتعلم ألماني كل يوم. برلين كبيرة وحلوة كتير. عاجبتني حياتي الجديدة هون.", "vocabulary": ["student", "live", "beautiful", "learn", "life"]}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (122, 1, 'reading', 'A1', 'lesson', 'My Roommate''s Family', '{"text": "This is my friend. His name is Thomas. He is German. We live in a small flat in Munich. Thomas has a nice family. He has one brother and two sisters. His father is a doctor. His mother is a teacher. They live in a small village. They visit Thomas on Sunday.", "topic": "family", "passage": "This is my friend. His name is Thomas. He is German. We live in a small flat in Munich. Thomas has a nice family. He has one brother and two sisters. His father is a doctor. His mother is a teacher. They live in a small village. They visit Thomas on Sunday.", "text_ar": "هاد رفيقي. اسمه توماس. هو ألماني. نحنا عايشين بشقة صغيرة بميونيخ. توماس عنده عيلة حبابة. عنده أخ واحد وأختين. أبوه دكتور وأمه معلمة. هنن عايشين بضيعة صغيرة. بيجوا بيزوروا توماس يوم الأحد.", "title_ar": "عيلة رفيقي بالسكن", "questions": [{"id": "q1", "stem": "How many sisters does Thomas have?", "choices": ["One sister", "Two sisters", "Three sisters", "No sisters"], "correct_index": 1}], "passage_ar": "هاد رفيقي. اسمه توماس. هو ألماني. نحنا عايشين بشقة صغيرة بميونيخ. توماس عنده عيلة حبابة. عنده أخ واحد وأختين. أبوه دكتور وأمه معلمة. هنن عايشين بضيعة صغيرة. بيجوا بيزوروا توماس يوم الأحد.", "vocabulary": ["friend", "flat", "brother", "sister", "visit"]}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (123, 1, 'reading', 'A1', 'lesson', 'My Daily Trip', '{"text": "Every day, I get up at seven o''clock. I drink hot coffee. Then, I go to the bus station. I take the blue bus at eight o''clock. The bus is always on time. I go to my school. The ticket costs three euros. I buy a ticket every morning. I love my bus.", "topic": "public transport", "passage": "Every day, I get up at seven o''clock. I drink hot coffee. Then, I go to the bus station. I take the blue bus at eight o''clock. The bus is always on time. I go to my school. The ticket costs three euros. I buy a ticket every morning. I love my bus.", "text_ar": "كل يوم بفيق الساعة سبعة الصبح. بشرب قهوة سخنة. بعدين بروح عموقف الباص. بركب بالباص الأزرق الساعة تمنية. الباص دايماً بيجي عالموعد. بروح عالمدرسة تبعي. التكت حقه تلاتة يورو. بشتري تكت كل يوم الصبح. بحب الباص تبعي.", "title_ar": "مشواري اليومي", "questions": [{"id": "q1", "stem": "What time does the bus come?", "choices": ["At seven o''clock", "At three o''clock", "At eight o''clock", "At nine o''clock"], "correct_index": 2}], "passage_ar": "كل يوم بفيق الساعة سبعة الصبح. بشرب قهوة سخنة. بعدين بروح عموقف الباص. بركب بالباص الأزرق الساعة تمنية. الباص دايماً بيجي عالموعد. بروح عالمدرسة تبعي. التكت حقه تلاتة يورو. بشتري تكت كل يوم الصبح. بحب الباص تبعي.", "vocabulary": ["morning", "station", "always", "ticket", "cost"]}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (124, 1, 'reading', 'A1', 'lesson', 'Shopping for Food', '{"text": "Today is Friday. I go to the German supermarket. I need fresh food. I buy red apples and green bananas. I buy warm bread and white milk. I also buy five brown eggs. The food is cheap. I pay ten euros. The supermarket is clean and big. I walk home now.", "topic": "food", "passage": "Today is Friday. I go to the German supermarket. I need fresh food. I buy red apples and green bananas. I buy warm bread and white milk. I also buy five brown eggs. The food is cheap. I pay ten euros. The supermarket is clean and big. I walk home now.", "text_ar": "اليوم الجمعة. عم روح عالسوبرماركت الألماني. بدي أكل طازة. بشتري تفاح أحمر وموز أخضر. بشتري خبز سخن وحليب أبيض. وكمان بشتري خمس بيضات بنيين. الأكل رخيص. بدفع عشرة يورو. السوبرماركت نضيف وكبير. هلق عم امشي عالبيت.", "title_ar": "عم اتسوق للأكل", "questions": [{"id": "q1", "stem": "How much does the food cost?", "choices": ["Five euros", "Three euros", "Friday euros", "Ten euros"], "correct_index": 3}], "passage_ar": "اليوم الجمعة. عم روح عالسوبرماركت الألماني. بدي أكل طازة. بشتري تفاح أحمر وموز أخضر. بشتري خبز سخن وحليب أبيض. وكمان بشتري خمس بيضات بنيين. الأكل رخيص. بدفع عشرة يورو. السوبرماركت نضيف وكبير. هلق عم امشي عالبيت.", "vocabulary": ["supermarket", "fresh", "cheap", "pay", "clean"]}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (130, 1, 'reading', 'A1', 'lesson', 'Cooking Dinner', '{"text": "Tonight, I cook dinner for my roommates. I make chicken and fresh yellow rice. I use hot salt and black pepper. I slice three red tomatoes for the salad. The small kitchen smells very good. We sit together at eight o''clock. We eat our dinner happily. We drink cold water and apple juice. The homemade food is very delicious. We clean the kitchen together.", "topic": "food", "passage": "Tonight, I cook dinner for my roommates. I make chicken and fresh yellow rice. I use hot salt and black pepper. I slice three red tomatoes for the salad. The small kitchen smells very good. We sit together at eight o''clock. We eat our dinner happily. We drink cold water and apple juice. The homemade food is very delicious. We clean the kitchen together.", "text_ar": "الليلة عم اطبخ عشا لرفقاتي بالسكن. عم اعمل جاج ورز أصفر طازة. بحط ملح وفلفل أسود حار. بفرم تلات حبات بندورة حمرا للسلطة. المطبخ الصغير ريحته كتير طيبة. بنقعد سوا الساعة تمنية. بناكل عشانا بمبسطة. بنشرب مي باردة وعصير تفاح. الأكل المعمول بالبيت كتير طيب. بننظف المطبخ سوا.", "title_ar": "عم اطبخ العشا", "questions": [{"id": "q1", "stem": "What do they drink with their dinner?", "choices": ["Hot coffee", "Cold water and apple juice", "Black tea", "White milk"], "correct_index": 1}], "passage_ar": "الليلة عم اطبخ عشا لرفقاتي بالسكن. عم اعمل جاج ورز أصفر طازة. بحط ملح وفلفل أسود حار. بفرم تلات حبات بندورة حمرا للسلطة. المطبخ الصغير ريحته كتير طيبة. بنقعد سوا الساعة تمنية. بناكل عشانا بمبسطة. بنشرب مي باردة وعصير تفاح. الأكل المعمول بالبيت كتير طيب. بننظف المطبخ سوا.", "vocabulary": ["dinner", "roommates", "rice", "salad", "delicious"]}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (125, 1, 'reading', 'A1', 'lesson', 'My New Apartment', '{"text": "I have a new flat in Frankfurt. It is small but very nice. It has a small kitchen and a bathroom. It also has a big bedroom. The walls are clean and white. I have one very big window. I see a green park from it. The monthly rent is four hundred euros. I like my cozy home every day.", "topic": "home", "passage": "I have a new flat in Frankfurt. It is small but very nice. It has a small kitchen and a bathroom. It also has a big bedroom. The walls are clean and white. I have one very big window. I see a green park from it. The monthly rent is four hundred euros. I like my cozy home every day.", "text_ar": "عندي شقة جديدة بفرانكفورت. هي صغيرة بس كتير حلوة. فيها مطبخ صغير وحمام. وكمان فيها غرفة نوم كبيرة. الحيطان نضاف وبيض. عندي شباك واحد كتير كبير. بشوف جنينة خضرا منه. الآجار الشهري أربعمية يورو. بحب بيتي الدافي كل يوم.", "title_ar": "شقتي الجديدة", "questions": [{"id": "q1", "stem": "What can be seen from the window?", "choices": ["A green park", "A big kitchen", "A blue bus", "A small supermarket"], "correct_index": 0}], "passage_ar": "عندي شقة جديدة بفرانكفورت. هي صغيرة بس كتير حلوة. فيها مطبخ صغير وحمام. وكمان فيها غرفة نوم كبيرة. الحيطان نضاف وبيض. عندي شباك واحد كتير كبير. بشوف جنينة خضرا منه. الآجار الشهري أربعمية يورو. بحب بيتي الدافي كل يوم.", "vocabulary": ["kitchen", "bathroom", "bedroom", "window", "rent"]}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (126, 1, 'reading', 'A1', 'lesson', 'My English Class', '{"text": "I go to a language school in Berlin. My class has twelve students. We have four men and eight women. We meet at nine o''clock every morning. We study English for three hours. Our teacher is very kind. We have fifteen new books. We count numbers from one to one hundred. Learning a new language is fun. I like my school very much.", "topic": "numbers", "passage": "I go to a language school in Berlin. My class has twelve students. We have four men and eight women. We meet at nine o''clock every morning. We study English for three hours. Our teacher is very kind. We have fifteen new books. We count numbers from one to one hundred. Learning a new language is fun. I like my school very much.", "text_ar": "عم روح عالمدرسة تبع اللغات ببرلين. صفي فيه طنعش طالب وطالبة. عنا أربع رجال وتمن نسوان. بنلتقي الساعة تسعة كل يوم الصبح. مندرس إنكليزي لتلات ساعات. الأستاذ تبعنا كتير حباب. عنا خمسطشر كتاب جديد. منعد الأرقام من الواحد للمية. تعليم لغة جديدة بيمتع. كتير بحب مدرستي.", "title_ar": "صف الإنكليزي تبعي", "questions": [{"id": "q1", "stem": "How many hours do they study English every morning?", "choices": ["Four hours", "Three hours", "Twelve hours", "Nine hours"], "correct_index": 1}], "passage_ar": "عم روح عالمدرسة تبع اللغات ببرلين. صفي فيه طنعش طالب وطالبة. عنا أربع رجال وتمن نسوان. بنلتقي الساعة تسعة كل يوم الصبح. مندرس إنكليزي لتلات ساعات. الأستاذ تبعنا كتير حباب. عنا خمسطشر كتاب جديد. منعد الأرقام من الواحد للمية. تعليم لغة جديدة بيمتع. كتير بحب مدرستي.", "vocabulary": ["class", "students", "hours", "kind", "count"]}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (127, 1, 'reading', 'A1', 'lesson', 'Cold Days in Germany', '{"text": "The winter in Germany is very cold. Today, the sky is grey and dark. It is raining outside right now. I wear my heavy black coat today. I wear blue jeans and warm boots. I have a big yellow umbrella. I do not walk to school today. I take the fast underground train. The train is warm and clean. I like my train trip.", "topic": "weather", "passage": "The winter in Germany is very cold. Today, the sky is grey and dark. It is raining outside right now. I wear my heavy black coat today. I wear blue jeans and warm boots. I have a big yellow umbrella. I do not walk to school today. I take the fast underground train. The train is warm and clean. I like my train trip.", "text_ar": "الشتوية بألمانيا كتير باردة. اليوم السما رمادية ومعتمة. عم تشتي برّا هلق. عم البس جاكيتي الأسود التقيل اليوم. بلبس بنطلون جينز أزرق وبوط دافي. عندي شمسية كبيرة وصفرا. ما عم امشي عالمدرسة اليوم. بركب بمترو الأنفاق السريع. المترو دافي ونضيف. بحب مشواري بالمترو.", "title_ar": "الأيام الباردة بألمانيا", "questions": [{"id": "q1", "stem": "How does the person travel to school today?", "choices": ["By walking", "By a blue bus", "By underground train", "By a black coat"], "correct_index": 2}], "passage_ar": "الشتوية بألمانيا كتير باردة. اليوم السما رمادية ومعتمة. عم تشتي برّا هلق. عم البس جاكيتي الأسود التقيل اليوم. بلبس بنطلون جينز أزرق وبوط دافي. عندي شمسية كبيرة وصفرا. ما عم امشي عالمدرسة اليوم. بركب بمترو الأنفاق السريع. المترو دافي ونضيف. بحب مشواري بالمترو.", "vocabulary": ["winter", "grey", "heavy", "umbrella", "underground"]}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (128, 1, 'reading', 'A1', 'lesson', 'My Saturday Morning', '{"text": "On Saturday, I do not study at school. I sleep until nine o''clock in the morning. Then, I go to a small bakery. I buy two sweet cakes there. I drink black tea with my Syrian friend. We sit in a beautiful green park. We talk about our families in Syria. The sun is very warm today. I feel happy on my weekend.", "topic": "daily routine", "passage": "On Saturday, I do not study at school. I sleep until nine o''clock in the morning. Then, I go to a small bakery. I buy two sweet cakes there. I drink black tea with my Syrian friend. We sit in a beautiful green park. We talk about our families in Syria. The sun is very warm today. I feel happy on my weekend.", "text_ar": "يوم السبت ما بدرس بالمدرسة. بنام للساعة تسعة الصبح. بعدين بروح عفرن صغير. بشتري قطعتين كيك حلوين هنيك. بشرب شاي أسود مع رفيقي السوري. بنقعد بجنينة خضرا وحلوة. بنحكي عن عيلاتنا بسوريا. الشمس كتير دافية اليوم. حاسس حالي مبسوط بعطلتي.", "title_ar": "سبت الصبح تبعي", "questions": [{"id": "q1", "stem": "What does the person buy at the bakery?", "choices": ["Black tea", "Warm bread", "Fresh food", "Two sweet cakes"], "correct_index": 3}], "passage_ar": "يوم السبت ما بدرس بالمدرسة. بنام للساعة تسعة الصبح. بعدين بروح عفرن صغير. بشتري قطعتين كيك حلوين هنيك. بشرب شاي أسود مع رفيقي السوري. بنقعد بجنينة خضرا وحلوة. بنحكي عن عيلاتنا بسوريا. الشمس كتير دافية اليوم. حاسس حالي مبسوط بعطلتي.", "vocabulary": ["bakery", "sweet", "cakes", "friend", "weekend"]}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (129, 1, 'reading', 'A1', 'lesson', 'My First Job', '{"text": "I work in a small cafe in Hamburg. My new job is very nice. I work four days every week. I make hot coffee and delicious tea. I clean all the wooden tables. I speak English with many international tourists. My boss is a friendly German man. I earn some money for my rent. I like working here every day.", "topic": "daily city life", "passage": "I work in a small cafe in Hamburg. My new job is very nice. I work four days every week. I make hot coffee and delicious tea. I clean all the wooden tables. I speak English with many international tourists. My boss is a friendly German man. I earn some money for my rent. I like working here every day.", "text_ar": "عم اشتغل بقهوة صغيرة بهامبورغ. شغلي الجديد كتير حلو. بشتغل أربعة أيام كل أسبوع. بعمل قهوة سخنة وشاي طيب. بنضف كل الطاولات الخشب. بحكي إنكليزي مع سواح أجانب كتار. معملّمي زلمة ألماني ودود. عم اطلع شويّة مصاري عشان الآجار. بحب اشتغل هون كل يوم.", "title_ar": "أول شغل إلي", "questions": [{"id": "q1", "stem": "How many days a week does the person work?", "choices": ["Four days", "Three days", "Five days", "Seven days"], "correct_index": 0}], "passage_ar": "عم اشتغل بقهوة صغيرة بهامبورغ. شغلي الجديد كتير حلو. بشتغل أربعة أيام كل أسبوع. بعمل قهوة سخنة وشاي طيب. بنضف كل الطاولات الخشب. بحكي إنكليزي مع سواح أجانب كتار. معملّمي زلمة ألماني ودود. عم اطلع شويّة مصاري عشان الآجار. بحب اشتغل هون كل يوم.", "vocabulary": ["job", "cafe", "tables", "tourists", "boss"]}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (161, 1, 'reading', 'C1', 'lesson', 'The Paradigmatic Shift in Contemporary Higher Education', '{"text": "Seldom have we witnessed a more profound transformation within European higher education than the current integration of interdisciplinary methodologies into traditional research frameworks. Historically, academic institutions operated within rigid departmental silos, wherein scholars pursued highly specialized inquiries detached from broader societal contexts. However, contemporary global challenges—ranging from climate change to systemic socio-economic disparities—demand a radical synthesis of distinct academic disciplines. It is this systemic reconfiguration that has prompted German universities to overhaul their postgraduate curricula, actively prioritizing collaborative paradigms over isolated research. What remains a critical impediment, however, is the structural inertia embedded within institutional funding allocation mechanisms. Financial resources are predominantly distributed based on historical prestige and disciplinary metrics, thereby inadvertently discouraging younger researchers from embarking on speculative, cross-disciplinary ventures. Were funding bodies to establish permanent endowments specifically designated for interdisciplinary exploration, the pace of academic innovation would accelerate exponentially. Furthermore, international doctoral candidates often bear the brunt of these structural friction points, navigating not only complex pedagogical adjustments but also the nuances of academic bureaucracy. To address this, progressive institutions are pioneering integrated support hubs that synthesize linguistic refinement with professional development. Ultimately, the long-term viability of academic research hinges entirely upon its capacity to dismantle antiquated institutional barriers, fostering an environment where cognitive diversity is celebrated as the cornerstone of intellectual advancement.", "topic": "academic research", "passage": "Seldom have we witnessed a more profound transformation within European higher education than the current integration of interdisciplinary methodologies into traditional research frameworks. Historically, academic institutions operated within rigid departmental silos, wherein scholars pursued highly specialized inquiries detached from broader societal contexts. However, contemporary global challenges—ranging from climate change to systemic socio-economic disparities—demand a radical synthesis of distinct academic disciplines. It is this systemic reconfiguration that has prompted German universities to overhaul their postgraduate curricula, actively prioritizing collaborative paradigms over isolated research. What remains a critical impediment, however, is the structural inertia embedded within institutional funding allocation mechanisms. Financial resources are predominantly distributed based on historical prestige and disciplinary metrics, thereby inadvertently discouraging younger researchers from embarking on speculative, cross-disciplinary ventures. Were funding bodies to establish permanent endowments specifically designated for interdisciplinary exploration, the pace of academic innovation would accelerate exponentially. Furthermore, international doctoral candidates often bear the brunt of these structural friction points, navigating not only complex pedagogical adjustments but also the nuances of academic bureaucracy. To address this, progressive institutions are pioneering integrated support hubs that synthesize linguistic refinement with professional development. Ultimately, the long-term viability of academic research hinges entirely upon its capacity to dismantle antiquated institutional barriers, fostering an environment where cognitive diversity is celebrated as the cornerstone of intellectual advancement.", "text_ar": "نادر لتشوف عيوننا تحول جذري وجوهري بقطاع التعليم العالي الأوروبي متل يلي عم نعيشه هلق، والمتمثل بدمج المناهج العابرة للتخصصات بقلب أطر الأبحاث التقليدية. وتاريخياً، كانت المؤسسات الأكاديمية بتشتغل بقلب جزر منعزلة وناشفة بين الأقسام، وكانوا الباحثين بيلحقوا دراسات تخصصية دقيقة ومفصولة تماماً عن السياق المجتمعي الأوسع. بس هلق، التحديات العالمية المعاصرة—يلي بتبلش من التغير المناخي وبتوصل للفجوات الاقتصادية والاجتماعية الممنهجة—عم تفرض دمج جذري بين التخصصات الأكاديمية المختلفة. وهاد التعديل الهيكلي بالظبط هو يلي دفع الجامعات الألمانية لتعديل مناهج الدراسات العليا عندها بالكامل، وصارت تحط الأولوية بوضوح للنماذج التشاركية على حساب الأبحاث الفردية المنعزلة. بس شو يلي عم يضل عائق أساسي بوجه هاد التحول؟ هو الجمود الهيكلي المزروع بآليات توزيع التمويل بقلب هي المؤسسات. المصاري والموارد لساتها عم تتوزع بناءً على البرستيج التاريخي ومعايير التخصصات القديمة، وهاد الشي—بلا ما يقصدوا—عم يحبط الباحثين الشباب ويمنعهم يبلشوا بمشاريع استكشافية بتجمع كذا تخصص سوا. لو كانت الهيئات المانحة للتمويل بتأسس أوقاف مالية دائمة ومخصصة بس للأبحاث المشتركة، كان ريتم الابتكار الأكاديمي رح يتسارع بشكل مخيف. وكمان، الباحثين الأجانب بمرحلة الدكتوراه هنن أكتر عالم عم يتبهدلوا بهي النقط العالقة بالسيستم، لأنهم عم يمشوا بتعديلات تعليمية معقدة وكمان بقلب تفاصيل البيروقراطية الأكاديمية الناشفة. وعشان يحلوا هي القصة، بلشت المؤسسات المتطورة تفتح مراكز دعم متكاملة بتجمع بين تطوير اللغة والتمكين المهني. بالنهاية، استمرار نجاح الأبحاث الأكاديمية على المدى الطويل بيعتمد تماماً على قدرتها على تكسير الحيطان القديمة بالسيستم، لتعمل بيئة بتقدر التنوع المعرفي كحجر أساس للتقدم الفكري.", "title_ar": "التحول الجذري بالتعليم العالي المعاصر", "questions": [{"id": "q1", "stem": "According to the text, what constitutes the primary impediment to interdisciplinary research integration?", "choices": ["The structural inertia within institutional funding mechanisms that rely on historical metrics", "A total lack of interest among international doctoral candidates regarding cross-disciplinary exploration", "The recent legislative complete elimination of integrated pedagogical support hubs in Germany", "An absolute consensus that climate change and socio-economic disparities are irrelevant to universities"], "correct_index": 0}], "passage_ar": "نادر لتشوف عيوننا تحول جذري وجوهري بقطاع التعليم العالي الأوروبي متل يلي عم نعيشه هلق، والمتمثل بدمج المناهج العابرة للتخصصات بقلب أطر الأبحاث التقليدية. وتاريخياً، كانت المؤسسات الأكاديمية بتشتغل بقلب جزر منعزلة وناشفة بين الأقسام، وكانوا الباحثين بيلحقوا دراسات تخصصية دقيقة ومفصولة تماماً عن السياق المجتمعي الأوسع. بس هلق، التحديات العالمية المعاصرة—يلي بتبلش من التغير المناخي وبتوصل للفجوات الاقتصادية والاجتماعية الممنهجة—عم تفرض دمج جذري بين التخصصات الأكاديمية المختلفة. وهاد التعديل الهيكلي بالظبط هو يلي دفع الجامعات الألمانية لتعديل مناهج الدراسات العليا عندها بالكامل، وصارت تحط الأولوية بوضوح للنماذج التشاركية على حساب الأبحاث الفردية المنعزلة. بس شو يلي عم يضل عائق أساسي بوجه هاد التحول؟ هو الجمود الهيكلي المزروع بآليات توزيع التمويل بقلب هي المؤسسات. المصاري والموارد لساتها عم تتوزع بناءً على البرستيج التاريخي ومعايير التخصصات القديمة، وهاد الشي—بلا ما يقصدوا—عم يحبط الباحثين الشباب ويمنعهم يبلشوا بمشاريع استكشافية بتجمع كذا تخصص سوا. لو كانت الهيئات المانحة للتمويل بتأسس أوقاف مالية دائمة ومخصصة بس للأبحاث المشتركة، كان ريتم الابتكار الأكاديمي رح يتسارع بشكل مخيف. وكمان، الباحثين الأجانب بمرحلة الدكتوراه هنن أكتر عالم عم يتبهدلوا بهي النقط العالقة بالسيستم، لأنهم عم يمشوا بتعديلات تعليمية معقدة وكمان بقلب تفاصيل البيروقراطية الأكاديمية الناشفة. وعشان يحلوا هي القصة، بلشت المؤسسات المتطورة تفتح مراكز دعم متكاملة بتجمع بين تطوير اللغة والتمكين المهني. بالنهاية، استمرار نجاح الأبحاث الأكاديمية على المدى الطويل بيعتمد تماماً على قدرتها على تكسير الحيطان القديمة بالسيستم، لتعمل بيئة بتقدر التنوع المعرفي كحجر أساس للتقدم الفكري.", "vocabulary": ["paradigmatic", "silos", "inertia", "endowments", "antiquated"]}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (131, 1, 'reading', 'A2', 'lesson', 'Shopping at the Flea Market', '{"text": "Last Sunday, I went to a famous flea market in Berlin. The weather was very nice and sunny, so many people were walking around. I wanted to buy a cheap lamp for my small bedroom. I saw many interesting old things like vintage books, clothes, and colorful pictures. Suddenly, I found a beautiful metal lamp on a wooden table. The friendly man asked for twenty euros, but I offered twelve euros. He smiled and accepted my offer. I also bought a small box for three euros. It was a great shopping day, and I walked back home happily with my nice things.", "topic": "shopping", "passage": "Last Sunday, I went to a famous flea market in Berlin. The weather was very nice and sunny, so many people were walking around. I wanted to buy a cheap lamp for my small bedroom. I saw many interesting old things like vintage books, clothes, and colorful pictures. Suddenly, I found a beautiful metal lamp on a wooden table. The friendly man asked for twenty euros, but I offered twelve euros. He smiled and accepted my offer. I also bought a small box for three euros. It was a great shopping day, and I walked back home happily with my nice things.", "text_ar": "الأحد الماضي، رحت عالماركت المشهور تبع الأشياء المستعملة ببرلين. الجو كان كتير حلو ومشمس، كرمال هيك كان في ناس كتار عم يتمشوا. كان بدي اشتري ضو رخيص لغرفة نومي الصغيرة. شفت غراض قديمة وبتجنن متل كتب قديمة، وثياب، ولوحات ملونة. فجأة، لقيت ضو معدن كتير حلو على طاولة خشب. الزلمة الودود طلب عشرين يورو، بس أنا عرضت عليه طنعش يورو. ابتسم وقبل العرض تبعي. وكمان اشتريت صندوق صغير بتلاتة يورو. كان يوم تسوق بياخد العقل، ورجعت عالبيت مشي وأنا مبسوط بغراضي الجداد.", "title_ar": "التسوق بسوق الأشياء المستعملة", "questions": [{"id": "q1", "stem": "How much did the person finally pay for the metal lamp?", "choices": ["Twelve euros", "Twenty euros", "Three euros", "Fifteen euros"], "correct_index": 0}], "passage_ar": "الأحد الماضي، رحت عالماركت المشهور تبع الأشياء المستعملة ببرلين. الجو كان كتير حلو ومشمس، كرمال هيك كان في ناس كتار عم يتمشوا. كان بدي اشتري ضو رخيص لغرفة نومي الصغيرة. شفت غراض قديمة وبتجنن متل كتب قديمة، وثياب، ولوحات ملونة. فجأة، لقيت ضو معدن كتير حلو على طاولة خشب. الزلمة الودود طلب عشرين يورو، بس أنا عرضت عليه طنعش يورو. ابتسم وقبل العرض تبعي. وكمان اشتريت صندوق صغير بتلاتة يورو. كان يوم تسوق بياخد العقل، ورجعت عالبيت مشي وأنا مبسوط بغراضي الجداد.", "vocabulary": ["flea market", "sunny", "lamp", "suddenly", "accepted"]}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (132, 1, 'reading', 'A2', 'lesson', 'The Train to Frankfurt', '{"text": "Yesterday morning, I travelled by train from Berlin to Frankfurt to see my uncle. I arrived at the huge central station at eight o''clock. The station was very crowded and busy. I bought my ticket from a modern machine, and it cost forty euros. My train left exactly on time from platform four. During the long journey, I sat next to a window and watched the green hills and small villages. I was also reading an interesting English storybook. The train was fast and comfortable, and I arrived safely in the afternoon.", "topic": "transport", "passage": "Yesterday morning, I travelled by train from Berlin to Frankfurt to see my uncle. I arrived at the huge central station at eight o''clock. The station was very crowded and busy. I bought my ticket from a modern machine, and it cost forty euros. My train left exactly on time from platform four. During the long journey, I sat next to a window and watched the green hills and small villages. I was also reading an interesting English storybook. The train was fast and comfortable, and I arrived safely in the afternoon.", "text_ar": "مبارح الصبح، سافرت بالقطار من برلين لفرانكفورت عشان شوف عمي. وصلت عالمحطة المركزية الضخمة الساعة تمنية. المحطة كانت كتير زحمة وعجقة. اشتريت التكت تبعي من ماكينة حديثة، وكلفتني أربعين يورو. القطار تبعي مشي عالوقت تماماً من الرصيف رقم أربعة. خلال الرحلة الطويلة، قعدت جنب الشباك وصرت اتفرج عالتلال الخضرا والضيع الصغيرة. وكمان كنت عم اقرأ كتاب قصص إنكليزي كتير ممتع. القطار كان سريع ومريح، ووصلت بالسلامة بعد الظهر.", "title_ar": "القطار لفرانكفورت", "questions": [{"id": "q1", "stem": "From which platform did the train leave?", "choices": ["Platform eight", "Platform four", "Platform forty", "Platform three"], "correct_index": 1}], "passage_ar": "مبارح الصبح، سافرت بالقطار من برلين لفرانكفورت عشان شوف عمي. وصلت عالمحطة المركزية الضخمة الساعة تمنية. المحطة كانت كتير زحمة وعجقة. اشتريت التكت تبعي من ماكينة حديثة، وكلفتني أربعين يورو. القطار تبعي مشي عالوقت تماماً من الرصيف رقم أربعة. خلال الرحلة الطويلة، قعدت جنب الشباك وصرت اتفرج عالتلال الخضرا والضيع الصغيرة. وكمان كنت عم اقرأ كتاب قصص إنكليزي كتير ممتع. القطار كان سريع ومريح، ووصلت بالسلامة بعد الظهر.", "vocabulary": ["crowded", "machine", "platform", "journey", "comfortable"]}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (133, 1, 'reading', 'A2', 'lesson', 'Joining a Football Club', '{"text": "I love playing football, so last week I decided to join a local German sports club. I went to the club office on Tuesday evening. A kind woman gave me an application form to fill out. The monthly membership is only fifteen euros for students, which is very cheap. Yesterday, I attended my first training session on the big green field. We practiced passing the ball for one hour, and then we played a short match. I met three friendly players from Spain and Italy. We are planning to practice together every Thursday after school.", "topic": "hobbies", "passage": "I love playing football, so last week I decided to join a local German sports club. I went to the club office on Tuesday evening. A kind woman gave me an application form to fill out. The monthly membership is only fifteen euros for students, which is very cheap. Yesterday, I attended my first training session on the big green field. We practiced passing the ball for one hour, and then we played a short match. I met three friendly players from Spain and Italy. We are planning to practice together every Thursday after school.", "text_ar": "أنا بحب العب فوتبول كتير، كرمال هيك الأسبوع الماضي قررت سجل بنادي رياضي ألماني محلي. رحت عالمكتب تبع النادي يوم التلاتا المسا. في مرّة حبابة عطتني فورم طلب عشان عبيه. الاشتراك الشهري بس خمسطشر يورو للطلاب، وهاد شي كتير رخيص. مبارح، حضرت أول حصة تدريبية بالملعب الأخضر الكبير. تدربنا على تمرير الطابة لساعة كاملة، وبعدين لعبنا مباراة قصيرة. التقيت بتلات لاعبين ودودين من إسبانيا وإيطاليا. عم نخطط نتدرب سوا كل يوم خميس بعد المدرسة.", "title_ar": "التسجيل بنادي الفوتبول", "questions": [{"id": "q1", "stem": "When are the players planning to practice together in the future?", "choices": ["Every Tuesday", "Last week", "Every Thursday", "Every Sunday"], "correct_index": 2}], "passage_ar": "أنا بحب العب فوتبول كتير، كرمال هيك الأسبوع الماضي قررت سجل بنادي رياضي ألماني محلي. رحت عالمكتب تبع النادي يوم التلاتا المسا. في مرّة حبابة عطتني فورم طلب عشان عبيه. الاشتراك الشهري بس خمسطشر يورو للطلاب، وهاد شي كتير رخيص. مبارح، حضرت أول حصة تدريبية بالملعب الأخضر الكبير. تدربنا على تمرير الطابة لساعة كاملة، وبعدين لعبنا مباراة قصيرة. التقيت بتلات لاعبين ودودين من إسبانيا وإيطاليا. عم نخطط نتدرب سوا كل يوم خميس بعد المدرسة.", "vocabulary": ["decided", "membership", "attended", "field", "practice"]}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (134, 1, 'reading', 'A2', 'lesson', 'A Strange Summer Day', '{"text": "We had a very strange summer day in Hamburg yesterday. In the morning, the weather was extremely hot and sunny. The temperature was thirty-two degrees, so my friends and I went to a nearby lake. We were swimming in the cool water and eating strawberry ice cream. However, at three o''clock in the afternoon, the sky suddenly became very dark. Strong winds started blowing, and we heard loud thunder. It started raining heavily, so we ran quickly to a small coffee shop. We waited there for one hour until the storm finally stopped.", "topic": "weather", "passage": "We had a very strange summer day in Hamburg yesterday. In the morning, the weather was extremely hot and sunny. The temperature was thirty-two degrees, so my friends and I went to a nearby lake. We were swimming in the cool water and eating strawberry ice cream. However, at three o''clock in the afternoon, the sky suddenly became very dark. Strong winds started blowing, and we heard loud thunder. It started raining heavily, so we ran quickly to a small coffee shop. We waited there for one hour until the storm finally stopped.", "text_ar": "مر علينا يوم صيف غريب كتير بهامبورغ مبارح. بالصبح، الجو كان شوب كتير ومشمس. درجة الحرارة كانت اتنين وتلاتين، كرمال هيك رحت أنا ورفقاتي عبحيرة قريبة. كنا عم نسبح بالمي الباردة وعم ناكل بوظة على فريز. بس الساعة تلاتة بعد الظهر، السما فجأة صارت كتير معتمة. بلشت هواء قوي يضرب، وسمعنا صوت رعد قوي. بلشت تشتي بغزارة، كرمال هيك ركضنا بسرعة عقهوة صغيرة. استنينا هنيك ساعة كاملة لحتى العاصفة أخيراً وقفت.", "title_ar": "يوم صيف غريب", "questions": [{"id": "q1", "stem": "Why did the writer and their friends run to a coffee shop?", "choices": ["To buy strawberry ice cream", "To swim in the cool water", "Because the temperature was thirty-two degrees", "Because it started raining heavily"], "correct_index": 3}], "passage_ar": "مر علينا يوم صيف غريب كتير بهامبورغ مبارح. بالصبح، الجو كان شوب كتير ومشمس. درجة الحرارة كانت اتنين وتلاتين، كرمال هيك رحت أنا ورفقاتي عبحيرة قريبة. كنا عم نسبح بالمي الباردة وعم ناكل بوظة على فريز. بس الساعة تلاتة بعد الظهر، السما فجأة صارت كتير معتمة. بلشت هواء قوي يضرب، وسمعنا صوت رعد قوي. بلشت تشتي بغزارة، كرمال هيك ركضنا بسرعة عقهوة صغيرة. استنينا هنيك ساعة كاملة لحتى العاصفة أخيراً وقفت.", "vocabulary": ["extremely", "lake", "thunder", "heavily", "storm"]}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (135, 1, 'reading', 'A2', 'lesson', 'My New Neighbors', '{"text": "Two weeks ago, a new family moved into the apartment next to mine. They came from a small town in the south of Germany. The family has four people: the parents, a young son, and a beautiful white cat. Yesterday evening, they knocked on my door and invited me to have tea with them. They were very polite and brought a delicious homemade chocolate cake. We sat in their living room and talked for two hours. They asked me about Syria and my life in Germany. I am very happy because I have wonderful neighbors now.", "topic": "neighborhood", "passage": "Two weeks ago, a new family moved into the apartment next to mine. They came from a small town in the south of Germany. The family has four people: the parents, a young son, and a beautiful white cat. Yesterday evening, they knocked on my door and invited me to have tea with them. They were very polite and brought a delicious homemade chocolate cake. We sat in their living room and talked for two hours. They asked me about Syria and my life in Germany. I am very happy because I have wonderful neighbors now.", "text_ar": "قبل أسبوعين، في عيلة جديدة سكنت بالشقة يلي جنبي تماماً. إجو من مدينة صغيرة بجنوب ألمانيا. العيلة فيها أربع أشخاص: الأب والأم، وابن صغير، وبسة بيضا بتجنن. مبارح المسا، دقوا الباب تبعي وعزموني اشرب شاي معهم. كانوا كتير أكابر وجابوا معهم كيكة شوكولا طيبة كتير معمول بالبيت. قعدنا بغرفة القعدة وحكينا لساعتين. سألوني عن سوريا وعن حياتي بألمانيا. أنا كتير مبسوط كرمال صار عندي جيران بياخدوا العقل هلق.", "title_ar": "جيراني الجداد", "questions": [{"id": "q1", "stem": "What did the new neighbors bring with them when they met the writer?", "choices": ["A chocolate cake", "A beautiful white cat", "A map of South Germany", "Some Syrian tea"], "correct_index": 0}], "passage_ar": "قبل أسبوعين، في عيلة جديدة سكنت بالشقة يلي جنبي تماماً. إجو من مدينة صغيرة بجنوب ألمانيا. العيلة فيها أربع أشخاص: الأب والأم، وابن صغير، وبسة بيضا بتجنن. مبارح المسا، دقوا الباب تبعي وعزموني اشرب شاي معهم. كانوا كتير أكابر وجابوا معهم كيكة شوكولا طيبة كتير معمول بالبيت. قعدنا بغرفة القعدة وحكينا لساعتين. سألوني عن سوريا وعن حياتي بألمانيا. أنا كتير مبسوط كرمال صار عندي جيران بياخدوا العقل هلق.", "vocabulary": ["moved", "apartment", "polite", "homemade", "wonderful"]}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (162, 1, 'reading', 'C1', 'lesson', 'Navigating the Epistemological Crisis of the Digital Age', '{"text": "The contemporary digital landscape has precipitated an unprecedented epistemological crisis, altering how public audiences consume, evaluate, and synthesize information. In an era dominated by algorithmic curation, corporate digital platforms actively prioritize sensationalized content designed to maximize user engagement rather than factual accuracy. Consequently, the public square has fragmented into echo chambers, wherein individuals are continuously exposed to hyper-partisan perspectives that reinforce existing cognitive biases. It is this pervasive algorithmic bias that complicates democratic discourse, rendering constructive consensus virtually unattainable. To counteract this destabilizing trend, educational specialists strongly advocate for the universal implementation of comprehensive media literacy frameworks. Such curricula must transcend basic fact-checking techniques, focusing instead on equipping citizens with the analytical tools necessary to deconstruct systemic media bias and detect sophisticated digital manipulations. Not only do these digital echo chambers distort public perception of critical socio-political issues, but they also systematically erode institutional trust. Were European regulatory bodies to enforce more stringent oversight on corporate algorithms, the proliferation of malicious disinformation could be substantively curtailed. However, legislation alone remains insufficient; individual cognitive resilience must be meticulously cultivated through continuous critical inquiry. Ultimately, restoring the integrity of public discourse requires a multi-faceted approach that synthesizes rigorous governmental oversight with an unwavering commitment to societal media education.", "topic": "media literacy", "passage": "The contemporary digital landscape has precipitated an unprecedented epistemological crisis, altering how public audiences consume, evaluate, and synthesize information. In an era dominated by algorithmic curation, corporate digital platforms actively prioritize sensationalized content designed to maximize user engagement rather than factual accuracy. Consequently, the public square has fragmented into echo chambers, wherein individuals are continuously exposed to hyper-partisan perspectives that reinforce existing cognitive biases. It is this pervasive algorithmic bias that complicates democratic discourse, rendering constructive consensus virtually unattainable. To counteract this destabilizing trend, educational specialists strongly advocate for the universal implementation of comprehensive media literacy frameworks. Such curricula must transcend basic fact-checking techniques, focusing instead on equipping citizens with the analytical tools necessary to deconstruct systemic media bias and detect sophisticated digital manipulations. Not only do these digital echo chambers distort public perception of critical socio-political issues, but they also systematically erode institutional trust. Were European regulatory bodies to enforce more stringent oversight on corporate algorithms, the proliferation of malicious disinformation could be substantively curtailed. However, legislation alone remains insufficient; individual cognitive resilience must be meticulously cultivated through continuous critical inquiry. Ultimately, restoring the integrity of public discourse requires a multi-faceted approach that synthesizes rigorous governmental oversight with an unwavering commitment to societal media education.", "text_ar": "الفضاء الرقمي المعاصر عمل أزمة معرفية مسبوقة، وغيرت تماماً كيف الناس عم تستهلك وتقيم وتجمع المعلومات. وبعصر عم تتحكم فيه الخوارزميات، منصات الشركات الرقمية عم تحط الأولوية بوضوح للمحتوى المثير يلي بيلعب ع العواطف عشان تضمن أعلى نسبة تفاعل من المستخدمين، من دون ما تطلع على دقة الحقائق. ونتيجة لهاد الشي، الساحة العامة انقسمت لغرف صدى منغلقة، وصاروا الأفراد عم يتعرضوا بشكل مستمر لآراء متعصبة كتير بتثبت وتدعم انحيازاتهم الفكرية القديمة. وهاد الانحياز الخوارزمي المنتشر هو بالظبط شو يلي عم يعقد النقاش الديمقراطي، وعم يخلي الوصول لإجماع بناء شبه مستحيل. وعشان يواجهوا هاد التوجه يلي عم يضرب الاستقرار، خبراء التعليم عم ينصحوا بقوة بتطبيق شامل لأطر التربية الإعلامية المتكاملة. وهي المناهج لازم تتخطى الطرق البدائية لتدقيق الحقائق، وتركز بدالها على تسليح المواطنين بالأدوات التحليلية الضرورية لتفكيك الانحياز الممنهج بالإعلام وكشف التلاعب الرقمي المتطور. غرف الصدى الرقمية هي ما عم تشوه بس نظرة الناس للقضايا السياسية والاجتماعية الحساسة، بل عم تضرب وتأكل الثقة بالمؤسسات بشكل ممنهج. لو كانت الهيئات الرقابية الأوروبية بتفرض إشراف أشد على خوارزميات الشركات، كان ممكن انتشار التضليل الخبيث ينزل ويتحجم بشكل حقيقي. بس القوانين لحالها ما بتكفي؛ المناعة الفكرية عند الشخص لازم تنبني وتتطور بحذر من خلال البحث النقدي المستمر. بالنهاية، ترجيع قيمة ونزاهة النقاش العام بدها خطة متعددة الجوانب بتجمع بين الرقابة الحكومية الصارمة والالتزام الحقيقي بالتعليم الإعلامي لكل المجتمع.", "title_ar": "مواجهة أزمة المعرفة بالعصر الرقمي", "questions": [{"id": "q2", "stem": "What distinguishes comprehensive media literacy from basic fact-checking, as described by the author?", "choices": ["It focuses exclusively on deleting user accounts that spread political disinformation", "It equips citizens with analytical tools to deconstruct systemic bias and detect manipulation", "It relies entirely on European regulatory bodies to manage corporate online platforms", "It prioritizes maximizing user engagement through advanced algorithmic methods"], "correct_index": 1}], "passage_ar": "الفضاء الرقمي المعاصر عمل أزمة معرفية مسبوقة، وغيرت تماماً كيف الناس عم تستهلك وتقيم وتجمع المعلومات. وبعصر عم تتحكم فيه الخوارزميات، منصات الشركات الرقمية عم تحط الأولوية بوضوح للمحتوى المثير يلي بيلعب ع العواطف عشان تضمن أعلى نسبة تفاعل من المستخدمين، من دون ما تطلع على دقة الحقائق. ونتيجة لهاد الشي، الساحة العامة انقسمت لغرف صدى منغلقة، وصاروا الأفراد عم يتعرضوا بشكل مستمر لآراء متعصبة كتير بتثبت وتدعم انحيازاتهم الفكرية القديمة. وهاد الانحياز الخوارزمي المنتشر هو بالظبط شو يلي عم يعقد النقاش الديمقراطي، وعم يخلي الوصول لإجماع بناء شبه مستحيل. وعشان يواجهوا هاد التوجه يلي عم يضرب الاستقرار، خبراء التعليم عم ينصحوا بقوة بتطبيق شامل لأطر التربية الإعلامية المتكاملة. وهي المناهج لازم تتخطى الطرق البدائية لتدقيق الحقائق، وتركز بدالها على تسليح المواطنين بالأدوات التحليلية الضرورية لتفكيك الانحياز الممنهج بالإعلام وكشف التلاعب الرقمي المتطور. غرف الصدى الرقمية هي ما عم تشوه بس نظرة الناس للقضايا السياسية والاجتماعية الحساسة، بل عم تضرب وتأكل الثقة بالمؤسسات بشكل ممنهج. لو كانت الهيئات الرقابية الأوروبية بتفرض إشراف أشد على خوارزميات الشركات، كان ممكن انتشار التضليل الخبيث ينزل ويتحجم بشكل حقيقي. بس القوانين لحالها ما بتكفي؛ المناعة الفكرية عند الشخص لازم تنبني وتتطور بحذر من خلال البحث النقدي المستمر. بالنهاية، ترجيع قيمة ونزاهة النقاش العام بدها خطة متعددة الجوانب بتجمع بين الرقابة الحكومية الصارمة والالتزام الحقيقي بالتعليم الإعلامي لكل المجتمع.", "vocabulary": ["epistemological", "curation", "pervasive", "curtailed", "resilience"]}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (163, 1, 'reading', 'C1', 'lesson', 'The Strategic Imperative of Circular Economic Models', '{"text": "As supply chain vulnerabilities continue to expose the inherent fragility of traditional linear economies, forward-thinking European corporations are accelerating their transition toward circular business strategies. The conventional ''take-make-waste'' manufacturing paradigm has generated catastrophic ecological consequences while increasingly exposing enterprises to volatile raw material markets. In contrast, circular economic frameworks prioritize systemic regeneration, designing products to be entirely modular, easily repairable, and fundamentally recyclable from inception. It is this profound shift in organizational philosophy that underpins contemporary corporate sustainability initiatives. Adopting these models requires not merely superficial adjustments to operational processes, but a comprehensive redesign of the entire corporate ecosystem. Not only must enterprises reinvent their physical manufacturing methodologies, but they must also cultivate entirely new customer relationships predicated on product stewardship rather than outright ownership. What complicates this corporate transition is the short-term financial pressure exerted by conventional investment markets, which frequently demand immediate quarterly returns at the expense of long-term ecological viability. Had financial institutions integrated comprehensive environmental ESG metrics into their core valuation frameworks sooner, the corporate adoption of circularity would be vastly more advanced. Moving forward, businesses that fail to integrate these sustainable paradigms risk institutional obsolescence as regulatory compliance standards tighten and consumer preferences pivot decisively toward ecological accountability.", "topic": "business strategy", "passage": "As supply chain vulnerabilities continue to expose the inherent fragility of traditional linear economies, forward-thinking European corporations are accelerating their transition toward circular business strategies. The conventional ''take-make-waste'' manufacturing paradigm has generated catastrophic ecological consequences while increasingly exposing enterprises to volatile raw material markets. In contrast, circular economic frameworks prioritize systemic regeneration, designing products to be entirely modular, easily repairable, and fundamentally recyclable from inception. It is this profound shift in organizational philosophy that underpins contemporary corporate sustainability initiatives. Adopting these models requires not merely superficial adjustments to operational processes, but a comprehensive redesign of the entire corporate ecosystem. Not only must enterprises reinvent their physical manufacturing methodologies, but they must also cultivate entirely new customer relationships predicated on product stewardship rather than outright ownership. What complicates this corporate transition is the short-term financial pressure exerted by conventional investment markets, which frequently demand immediate quarterly returns at the expense of long-term ecological viability. Had financial institutions integrated comprehensive environmental ESG metrics into their core valuation frameworks sooner, the corporate adoption of circularity would be vastly more advanced. Moving forward, businesses that fail to integrate these sustainable paradigms risk institutional obsolescence as regulatory compliance standards tighten and consumer preferences pivot decisively toward ecological accountability.", "text_ar": "مع استمرار نقاط الضعف بسلاسل التوريد بكشف الهشاشة المزروعة بالاقتصادات الخطية التقليدية، الشركات الأوروبية يلي بتفكر لبعيد عم تسرع انتقالها نحو استراتيجيات الشغل الدائرية. نموذج التصنيع القديم القائم على ''أخد، صنع، كب'' عمل كوارث بيئية بتبكي، وبنفس الوقت عم يعرض الشركات لتقلبات سوق المواد الخام يلي بتخوف. وبالمقابل، أطر الاقتصاد الدائري بتحط الأولوية لإعادة التدوير والتجدد الممنهج، وعم تصمم المنتجات لتكون مفككة وسهلة التصليح وقابلة لإعادة التدوير بالكامل من لحظة ابتكارها. وهاد التحول العميق بفلسفة المؤسسات هو بالظبط الأساس يلي عم تدعم عليه الشركات مبادرات الاستدامة المعاصرة. وتطبيق هي النماذج ما بده مجرد تعديلات قشرية وسطحية بالعمليات التشغيلية، بل بده إعادة تصميم شاملة لكل السيستم والبيئة تبع الشركة. الشركات مو بس مجبورة تعيد ابتكار طرق التصنيع الحقيقية تبعها، بل كمان لازم تبني علاقات جديدة تماماً مع الزباين قائمة على رعاية المنتج والمسؤولية عنه بدل ملكيته المطلقة. وشو يلي عم يعقد هاد التحول بالشركات؟ هو الضغط المادي قصير الأمد من أسواق الاستثمار التقليدية، يلي دايماً بتطالب بأرباح ربع سنوية سريعة على حساب الاستمرار البيئي طويل الأمد. لو كانت المؤسسات المالية دمجت معايير الاستدامة البيئية والاجتماعية الشاملة (ESG) بأنظمة التقييم الأساسية تبعها من قبل، كان تطبيق الشركات للاقتصاد الدائري متطور أكتر بكتير هلق. وإذا طلعنا لـ قدام، الشركات يلي ما رح تقدر تدمج هي النماذج المستدامة عم تخاطر بإنها تصير برّا التاريخ، كرمال شروط القوانين عم تصير أصعب وتوجهات المستهلكين عم تفتل بوضوح نحو المسؤولية البيئية.", "title_ar": "الضرورة الاستراتيجية لنماذج الاقتصاد الدائري", "questions": [{"id": "q3", "stem": "What is identified as a major external financial pressure that complicates the corporate transition to circular models?", "choices": ["The absolute refusal of modern consumers to purchase modular or repairable products", "The global legal prohibition against product stewardship frameworks in Western Europe", "The constant demand from conventional investment markets for immediate quarterly returns", "The complete disappearance of raw material volatility within international markets"], "correct_index": 2}], "passage_ar": "مع استمرار نقاط الضعف بسلاسل التوريد بكشف الهشاشة المزروعة بالاقتصادات الخطية التقليدية، الشركات الأوروبية يلي بتفكر لبعيد عم تسرع انتقالها نحو استراتيجيات الشغل الدائرية. نموذج التصنيع القديم القائم على ''أخد، صنع، كب'' عمل كوارث بيئية بتبكي، وبنفس الوقت عم يعرض الشركات لتقلبات سوق المواد الخام يلي بتخوف. وبالمقابل، أطر الاقتصاد الدائري بتحط الأولوية لإعادة التدوير والتجدد الممنهج، وعم تصمم المنتجات لتكون مفككة وسهلة التصليح وقابلة لإعادة التدوير بالكامل من لحظة ابتكارها. وهاد التحول العميق بفلسفة المؤسسات هو بالظبط الأساس يلي عم تدعم عليه الشركات مبادرات الاستدامة المعاصرة. وتطبيق هي النماذج ما بده مجرد تعديلات قشرية وسطحية بالعمليات التشغيلية، بل بده إعادة تصميم شاملة لكل السيستم والبيئة تبع الشركة. الشركات مو بس مجبورة تعيد ابتكار طرق التصنيع الحقيقية تبعها، بل كمان لازم تبني علاقات جديدة تماماً مع الزباين قائمة على رعاية المنتج والمسؤولية عنه بدل ملكيته المطلقة. وشو يلي عم يعقد هاد التحول بالشركات؟ هو الضغط المادي قصير الأمد من أسواق الاستثمار التقليدية، يلي دايماً بتطالب بأرباح ربع سنوية سريعة على حساب الاستمرار البيئي طويل الأمد. لو كانت المؤسسات المالية دمجت معايير الاستدامة البيئية والاجتماعية الشاملة (ESG) بأنظمة التقييم الأساسية تبعها من قبل، كان تطبيق الشركات للاقتصاد الدائري متطور أكتر بكتير هلق. وإذا طلعنا لـ قدام، الشركات يلي ما رح تقدر تدمج هي النماذج المستدامة عم تخاطر بإنها تصير برّا التاريخ، كرمال شروط القوانين عم تصير أصعب وتوجهات المستهلكين عم تفتل بوضوح نحو المسؤولية البيئية.", "vocabulary": ["fragility", "inception", "stewardship", "obsolescence", "accountability"]}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (164, 1, 'reading', 'C1', 'lesson', 'Jurisdictional Harmonization and Individual Autonomy', '{"text": "The evolution of trans-European legal frameworks represents a continuous negotiation between jurisdictional harmonization and the preservation of national individual autonomy. As member states increasingly integrate their administrative systems to facilitate cross-border commerce and migration, the tension between centralized European regulations and localized statutory traditions becomes pronounced. Nowhere is this delicate balance more heavily contested than in the domain of data privacy jurisprudence, where the enforcement of standardized protections frequently conflicts with regional security mandates. Legal scholars observe that while centralized regulations provide an essential shield against corporate surveillance, they occasionally restrict the administrative agility of local judicial bodies. It is this institutional friction that necessitates a sophisticated, continuous calibration of legal mechanisms. What remains problematic is the complex nominalization embedded within transnational legislative texts, which frequently obscures the immediate practical application of statutory rights for ordinary citizens. Were local jurisdictions to establish dedicated bilingual legal clinics, the accessibility of trans-European judicial pathways would be significantly enhanced. Not only must legal professionals master these intricate administrative networks, but they must also develop a profound sensitivity to the cultural contexts that inform localized legal interpretations. Ultimately, the long-term legitimacy of European jurisprudence depends upon its capacity to guarantee robust collective integration without eroding the fundamental constitutional protections unique to each sovereign entity.", "topic": "law", "passage": "The evolution of trans-European legal frameworks represents a continuous negotiation between jurisdictional harmonization and the preservation of national individual autonomy. As member states increasingly integrate their administrative systems to facilitate cross-border commerce and migration, the tension between centralized European regulations and localized statutory traditions becomes pronounced. Nowhere is this delicate balance more heavily contested than in the domain of data privacy jurisprudence, where the enforcement of standardized protections frequently conflicts with regional security mandates. Legal scholars observe that while centralized regulations provide an essential shield against corporate surveillance, they occasionally restrict the administrative agility of local judicial bodies. It is this institutional friction that necessitates a sophisticated, continuous calibration of legal mechanisms. What remains problematic is the complex nominalization embedded within transnational legislative texts, which frequently obscures the immediate practical application of statutory rights for ordinary citizens. Were local jurisdictions to establish dedicated bilingual legal clinics, the accessibility of trans-European judicial pathways would be significantly enhanced. Not only must legal professionals master these intricate administrative networks, but they must also develop a profound sensitivity to the cultural contexts that inform localized legal interpretations. Ultimately, the long-term legitimacy of European jurisprudence depends upon its capacity to guarantee robust collective integration without eroding the fundamental constitutional protections unique to each sovereign entity.", "text_ar": "تطور الأطر القانونية العابرة لأوروبا بيمثل عملية نقاش ومفاوضات مستمرة بين توحيد القوانين والحفاظ على الاستقلالية الفردية والوطنية لكل بلد. ومع زيادة دمج الدول الأعضاء لأنظمتها الإدارية لتسهيل التجارة والهجرة عبر الحدود، عم يصير التوتر واضح بين القوانين الأوروبية المركزية والتقاليد القانونية المحلية. وما في مكان عم يشهد هاد الصراع الحساس أكتر من مجال أحكام خصوصية البيانات، كرمال تطبيق الحمايات الموحدة عم يتعارض كتير أوقات مع الأوامر الأمنية الإقليمية. باحثين بالقانون عم يلاحظوا إنه مع إنه القوانين المركزية بتقدم حماية أساسية بوش مراقبة الشركات، بس هي أوقات عم تقيد المرونة الإدارية للهيئات القضائية المحلية. وهاد الاحتكاك بين المؤسسات هو بالظبط شو يلي عم يفرض ضبط ومعايرة ذكية ومستمرة للآليات القانونية. والشي يلي عم يضل بيعمل مشاكل هو الصياغة الاسمية المعقدة بقلب النصوص التشريعية العابرة للدول، يلي كتير أوقات عم تغطي وتعمي التطبيق العملي المباشر للحقوق القانونية للمواطنين العاديين. لو كانت المحاكم المحلية بتعمل عيادات قانونية متخصصة ومترجمة، كان الوصول للطرق القضائية الأوروبية المشتركة رح يتحسن بكتير. ورجال القانون مو بس مجبورين يتقنوا هي الشبكات الإدارية المعقدة، بل كمان لازم يطوروا حساسية عالية للسياقات الثقافية يلي بتشكل التفسيرات القانونية المحلية. بالنهاية، شرعية القوانين الأوروبية على المدى الطويل بتعتمد على قدرتها على ضمان اندماج جماعي قوي من دون ما تأكل الحمايات الدستورية الأساسية والفريدة لكل بلد عنده سيادة.", "title_ar": "التنسيق القانوني والاستقلالية الفردية", "questions": [{"id": "q4", "stem": "What effect do legal scholars observe regarding centralized European data privacy regulations?", "choices": ["They completely eliminate cross-border commerce and migration within member states", "They automatically resolve all cultural conflicts embedded in regional statutory traditions", "They render the use of bilingual legal clinics illegal across all sovereign jurisdictions", "They provide a shield against corporate surveillance but can restrict local judicial agility"], "correct_index": 3}], "passage_ar": "تطور الأطر القانونية العابرة لأوروبا بيمثل عملية نقاش ومفاوضات مستمرة بين توحيد القوانين والحفاظ على الاستقلالية الفردية والوطنية لكل بلد. ومع زيادة دمج الدول الأعضاء لأنظمتها الإدارية لتسهيل التجارة والهجرة عبر الحدود، عم يصير التوتر واضح بين القوانين الأوروبية المركزية والتقاليد القانونية المحلية. وما في مكان عم يشهد هاد الصراع الحساس أكتر من مجال أحكام خصوصية البيانات، كرمال تطبيق الحمايات الموحدة عم يتعارض كتير أوقات مع الأوامر الأمنية الإقليمية. باحثين بالقانون عم يلاحظوا إنه مع إنه القوانين المركزية بتقدم حماية أساسية بوش مراقبة الشركات، بس هي أوقات عم تقيد المرونة الإدارية للهيئات القضائية المحلية. وهاد الاحتكاك بين المؤسسات هو بالظبط شو يلي عم يفرض ضبط ومعايرة ذكية ومستمرة للآليات القانونية. والشي يلي عم يضل بيعمل مشاكل هو الصياغة الاسمية المعقدة بقلب النصوص التشريعية العابرة للدول، يلي كتير أوقات عم تغطي وتعمي التطبيق العملي المباشر للحقوق القانونية للمواطنين العاديين. لو كانت المحاكم المحلية بتعمل عيادات قانونية متخصصة ومترجمة، كان الوصول للطرق القضائية الأوروبية المشتركة رح يتحسن بكتير. ورجال القانون مو بس مجبورين يتقنوا هي الشبكات الإدارية المعقدة، بل كمان لازم يطوروا حساسية عالية للسياقات الثقافية يلي بتشكل التفسيرات القانونية المحلية. بالنهاية، شرعية القوانين الأوروبية على المدى الطويل بتعتمد على قدرتها على ضمان اندماج جماعي قوي من دون ما تأكل الحمايات الدستورية الأساسية والفريدة لكل بلد عنده سيادة.", "vocabulary": ["harmonization", "jurisprudence", "calibration", "nominalization", "legitimacy"]}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (165, 1, 'reading', 'C1', 'lesson', 'The Ontological Value of Architectural Heritage', '{"text": "The conceptual framework surrounding urban preservation has shifted from aesthetic appreciation to an investigation into the ontological value of architectural heritage. Contemporary philosophical discourse posits that historical buildings are not merely decorative remnants of bygone eras, but vital spatial structures that activate human consciousness and ground communal identity. In an age characterized by hyper-rapid urbanization and the proliferation of homogenized corporate architecture, ancient structures offer a tangible link to collective memory. It is this profound grounding capacity that renders preservation efforts culturally essential. However, the operationalization of preservation principles within modern real estate markets remains highly problematic. Urban planners frequently confront intense commercial pressure to demolish historic quarters in favor of high-density, economically lucrative developments. What is desperately needed is a philosophical framework that synthesizes historical preservation with functional modern utility, a paradigm often referred to as adaptive reuse. Not only does the adaptive reuse of historic buildings conserve material resources, but it also maintains the architectural continuity of urban landscapes. Were municipal councils to enforce strict legislative mandates protecting spatial heritage from speculative development, cities would retain their unique historical character. Ultimately, the survival of urban architectural heritage depends on society''s capacity to value spaces for their capacity to enrich human existential experience, rather than treating them purely as speculative commodities.", "topic": "philosophy", "passage": "The conceptual framework surrounding urban preservation has shifted from aesthetic appreciation to an investigation into the ontological value of architectural heritage. Contemporary philosophical discourse posits that historical buildings are not merely decorative remnants of bygone eras, but vital spatial structures that activate human consciousness and ground communal identity. In an age characterized by hyper-rapid urbanization and the proliferation of homogenized corporate architecture, ancient structures offer a tangible link to collective memory. It is this profound grounding capacity that renders preservation efforts culturally essential. However, the operationalization of preservation principles within modern real estate markets remains highly problematic. Urban planners frequently confront intense commercial pressure to demolish historic quarters in favor of high-density, economically lucrative developments. What is desperately needed is a philosophical framework that synthesizes historical preservation with functional modern utility, a paradigm often referred to as adaptive reuse. Not only does the adaptive reuse of historic buildings conserve material resources, but it also maintains the architectural continuity of urban landscapes. Were municipal councils to enforce strict legislative mandates protecting spatial heritage from speculative development, cities would retain their unique historical character. Ultimately, the survival of urban architectural heritage depends on society''s capacity to value spaces for their capacity to enrich human existential experience, rather than treating them purely as speculative commodities.", "text_ar": "الإطار الفكري المحيط بالحفاظ على المدن تحول من مجرد تقدير جمالي للقصة لصار بحث حقيقي بالقيمة الوجودية للإرث المعماري. النقاش الفلسفي المعاصر عم يفترض إنه البنايات التاريخية ماله مجرد بقايا للزينة من عصور مضت، بل هي هياكل ومساحات حيوية بتشغل الوعي البشري وبترسخ الهوية الجماعية للمجتمع. وبعصر عم يتسم بالتوسع العمراني السريع بيموّت وانتشار العمارة التجارية الموحدة والمملة، البنايات القديمة بتقدم صلة حقيقية وملموسة بالذاكرة الجماعية. وهي القدرة العميقة على الترسيخ والتثبيت هي بالظبط شو يلي عم يخلي جهود الحفاظ على الآثار ضرورة ثقافية. بس المشكلة إنه تطبيق مبادئ الحفاظ بقلب أسواق العقارات الحديثة عم يضل يعمل مشاكل كبيرة. مخططي المدن عم يواجهوا دايماً ضغوطات تجارية قوية لنهد أحياء تاريخية كرمال مشاريع سكنية عالية الكثافة وبتطالع مصاري كتيرة. والشي يلي بحاجة إله هلق بشكل إسعافي هو إطار فلسفي بيجمع بين الحفاظ التاريخي والمنفعة الحديثة والعملية، وهاد النموذج بيسموه أوقات إعادة الاستخدام التكيفي. إعادة استخدام البنايات التاريخية مو بس بيحمي وبيوفر بالموارد والمواد، بل كمان بيحافظ ع الاستمرارية المعمارية لشكل المدن. لو كانت مجالس البلديات بتفرض قوانين حازمة بتحمي الإرث المكاني من جشع تجار العقارات، كانت المدن حافظت على طابعها التاريخي الفريد. بالنهاية، نجاة الإرث المعماري بالمدن بيعتمد على قدرة المجتمع على تقدير الأماكن لقدرتها على غنى التجربة الوجودية للبشر، بدل ما نعاملها مجرد بضاعة للمضاربة المالية.", "title_ar": "القيمة الوجودية للإرث المعماري", "questions": [{"id": "q5", "stem": "What alternative approach is proposed by the author to reconcile historical preservation with modern urban utility?", "choices": ["The implementation of a philosophical and practical paradigm called adaptive reuse", "The total demolition of historic quarters to build high-density corporate developments", "Treating historic architectural structures purely as speculative market commodities", "Restricting human existential experiences within homogenized modern spaces"], "correct_index": 0}], "passage_ar": "الإطار الفكري المحيط بالحفاظ على المدن تحول من مجرد تقدير جمالي للقصة لصار بحث حقيقي بالقيمة الوجودية للإرث المعماري. النقاش الفلسفي المعاصر عم يفترض إنه البنايات التاريخية ماله مجرد بقايا للزينة من عصور مضت، بل هي هياكل ومساحات حيوية بتشغل الوعي البشري وبترسخ الهوية الجماعية للمجتمع. وبعصر عم يتسم بالتوسع العمراني السريع بيموّت وانتشار العمارة التجارية الموحدة والمملة، البنايات القديمة بتقدم صلة حقيقية وملموسة بالذاكرة الجماعية. وهي القدرة العميقة على الترسيخ والتثبيت هي بالظبط شو يلي عم يخلي جهود الحفاظ على الآثار ضرورة ثقافية. بس المشكلة إنه تطبيق مبادئ الحفاظ بقلب أسواق العقارات الحديثة عم يضل يعمل مشاكل كبيرة. مخططي المدن عم يواجهوا دايماً ضغوطات تجارية قوية لنهد أحياء تاريخية كرمال مشاريع سكنية عالية الكثافة وبتطالع مصاري كتيرة. والشي يلي بحاجة إله هلق بشكل إسعافي هو إطار فلسفي بيجمع بين الحفاظ التاريخي والمنفعة الحديثة والعملية، وهاد النموذج بيسموه أوقات إعادة الاستخدام التكيفي. إعادة استخدام البنايات التاريخية مو بس بيحمي وبيوفر بالموارد والمواد، بل كمان بيحافظ ع الاستمرارية المعمارية لشكل المدن. لو كانت مجالس البلديات بتفرض قوانين حازمة بتحمي الإرث المكاني من جشع تجار العقارات، كانت المدن حافظت على طابعها التاريخي الفريد. بالنهاية، نجاة الإرث المعماري بالمدن بيعتمد على قدرة المجتمع على تقدير الأماكن لقدرتها على غنى التجربة الوجودية للبشر، بدل ما نعاملها مجرد بضاعة للمضاربة المالية.", "vocabulary": ["ontological", "remnants", "proliferation", "lucrative", "continuity"]}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (166, 1, 'reading', 'C1', 'lesson', 'Geopolitical Realignment in the Renewable Energy Era', '{"text": "The global transition away from fossil fuels is orchestrating a profound geopolitical realignment, challenging established international power dynamics and redefining the strategic value of geographical territories. For decades, international relations were heavily dominated by the protection of hydrocarbon supply chains, with resource-rich nations exercising immense diplomatic leverage. However, the rapid proliferation of renewable energy technologies—particularly solar, wind, and hydrogen infrastructures—is shifting power toward nations that control critical mineral supply chains and manufacturing technologies. Not only do these technological advancements alter resource dependencies, but they also rewrite international trade agreements. It is this systemic shift that forces European policymakers to rethink their regional sovereignty strategies. What remains a critical vulnerability for Europe is its heavy reliance on foreign nations for the extraction and processing of rare earth elements, which are indispensable for producing electric batteries and wind turbines. Were the European Union to establish decentralized domestic mining and recycling frameworks, its strategic independence would be significantly strengthened. Furthermore, the economic destabilization of traditional petrostates could induce regional conflicts, necessitating a highly nuanced diplomatic approach to global resource realignment. Ultimately, navigating the geopolitical intricacies of the renewable energy era demands a comprehensive strategy that synthesizes national environmental sustainability initiatives with aggressive technological innovation and diversified diplomatic alliances.", "topic": "geopolitics", "passage": "The global transition away from fossil fuels is orchestrating a profound geopolitical realignment, challenging established international power dynamics and redefining the strategic value of geographical territories. For decades, international relations were heavily dominated by the protection of hydrocarbon supply chains, with resource-rich nations exercising immense diplomatic leverage. However, the rapid proliferation of renewable energy technologies—particularly solar, wind, and hydrogen infrastructures—is shifting power toward nations that control critical mineral supply chains and manufacturing technologies. Not only do these technological advancements alter resource dependencies, but they also rewrite international trade agreements. It is this systemic shift that forces European policymakers to rethink their regional sovereignty strategies. What remains a critical vulnerability for Europe is its heavy reliance on foreign nations for the extraction and processing of rare earth elements, which are indispensable for producing electric batteries and wind turbines. Were the European Union to establish decentralized domestic mining and recycling frameworks, its strategic independence would be significantly strengthened. Furthermore, the economic destabilization of traditional petrostates could induce regional conflicts, necessitating a highly nuanced diplomatic approach to global resource realignment. Ultimately, navigating the geopolitical intricacies of the renewable energy era demands a comprehensive strategy that synthesizes national environmental sustainability initiatives with aggressive technological innovation and diversified diplomatic alliances.", "text_ar": "التحول العالمي بعيداً عن الوقود الأحفوري عم يرتب إعادة تموضع جيوسياسي عميق، وعم يتحدى موازين القوى الدولية المعروفة ويعيد تعريف القيمة الاستراتيجية للمناطق الجغرافية. ولعقود طويلة، كانت العلاقات الدولية محكومة بشكل كبير بحماية سلاسل توريد النفط والغاز، وكانت الدول المليانة موارد بتملك قدرة ضغط دبلوماسي بتخوف. بس هلق، الانتشار السريع لتكنولوجيا الطاقة المتجددة—وخصوصي بنيتها التحتية للطاقة الشمسية، والهواء، والهيدروجين—عم ينقل القوة للدول يلي عم تتحكم بسلاسل توريد المعادن الحساسة وتكنولوجيا التصنيع. هي التطورات التكنولوجية مو بس عم تغير التبعية للموارد، بل كمان عم تعيد كتابة اتفاقيات التجارة الدولية. وهاد التحول الممنهج بالظبط هو شو يلي عم يجبر صناع القرار بأوروبا يعيدوا التفكير باستراتيجيات السيادة الإقليمية تبعهم. والشي يلي عم يضل يمثل نقطة ضعف خطيرة لأوروبا هو اعتمادها الكبير على دول برّانية لاستخراج ومعالجة العناصر الأرضية النادرة، يلي ما فينا نستغني عنها لتصنيع البطاريات الكهربائية وعنفات الهواء. لو كان الاتحاد الأوروبي بيعمل شبكات محلية ولامركزية للتعدين وإعادة تدوير المعادن، كانت استقلاليته الاستراتيجية تقوت بشكل كتير كبير. وكمان، الهزة الاقتصادية للدول النفطية التقليدية ممكن تعمل صراعات إقليمية، وهاد الشي بيطلب خطط دبلوماسية دقيقة كتير للتعامل مع إعادة توزيع الموارد العالمية. بالنهاية، المشي بقلب تعقيدات الجيوسياسة بعصر الطاقة المتجددة بده استراتيجية شاملة بتجمع بين مبادرات الاستدامة البيئية الوطنية والابتكار التكنولوجي القوي والتحالفات الدبلوماسية المتنوعة.", "title_ar": "إعادة التموضع الجيوسياسي بعصر الطاقة المتجددة", "questions": [{"id": "q6", "stem": "What is highlighted as a critical vulnerability for Europe in the new renewable energy era?", "choices": ["An absolute lack of wind and solar radiation within the European continent", "Its heavy reliance on foreign nations for extracting and processing rare earth elements", "The complete replacement of international trade agreements with localized mining bans", "A total rejection of electric batteries and wind turbines by European policymakers"], "correct_index": 1}], "passage_ar": "التحول العالمي بعيداً عن الوقود الأحفوري عم يرتب إعادة تموضع جيوسياسي عميق، وعم يتحدى موازين القوى الدولية المعروفة ويعيد تعريف القيمة الاستراتيجية للمناطق الجغرافية. ولعقود طويلة، كانت العلاقات الدولية محكومة بشكل كبير بحماية سلاسل توريد النفط والغاز، وكانت الدول المليانة موارد بتملك قدرة ضغط دبلوماسي بتخوف. بس هلق، الانتشار السريع لتكنولوجيا الطاقة المتجددة—وخصوصي بنيتها التحتية للطاقة الشمسية، والهواء، والهيدروجين—عم ينقل القوة للدول يلي عم تتحكم بسلاسل توريد المعادن الحساسة وتكنولوجيا التصنيع. هي التطورات التكنولوجية مو بس عم تغير التبعية للموارد، بل كمان عم تعيد كتابة اتفاقيات التجارة الدولية. وهاد التحول الممنهج بالظبط هو شو يلي عم يجبر صناع القرار بأوروبا يعيدوا التفكير باستراتيجيات السيادة الإقليمية تبعهم. والشي يلي عم يضل يمثل نقطة ضعف خطيرة لأوروبا هو اعتمادها الكبير على دول برّانية لاستخراج ومعالجة العناصر الأرضية النادرة، يلي ما فينا نستغني عنها لتصنيع البطاريات الكهربائية وعنفات الهواء. لو كان الاتحاد الأوروبي بيعمل شبكات محلية ولامركزية للتعدين وإعادة تدوير المعادن، كانت استقلاليته الاستراتيجية تقوت بشكل كتير كبير. وكمان، الهزة الاقتصادية للدول النفطية التقليدية ممكن تعمل صراعات إقليمية، وهاد الشي بيطلب خطط دبلوماسية دقيقة كتير للتعامل مع إعادة توزيع الموارد العالمية. بالنهاية، المشي بقلب تعقيدات الجيوسياسة بعصر الطاقة المتجددة بده استراتيجية شاملة بتجمع بين مبادرات الاستدامة البيئية الوطنية والابتكار التكنولوجي القوي والتحالفات الدبلوماسية المتنوعة.", "vocabulary": ["realignment", "leverage", "sovereignty", "indispensable", "intricacies"]}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (136, 1, 'reading', 'A2', 'lesson', 'The First Day at Language School', '{"text": "I started my intermediate English course at a modern language institute last Monday. On the first day, I was very nervous because I did not know anyone. I entered the classroom at nine o''clock and met our teacher, Miss Sarah. She welcomed me warmly and gave me a big vocabulary textbook. There are ten other students in my class from different countries like Turkey and Brazil. We practiced speaking about our hobbies in pairs. The lesson was very interesting and active. Now, I feel more confident about learning English and making new international friends.", "topic": "school", "passage": "I started my intermediate English course at a modern language institute last Monday. On the first day, I was very nervous because I did not know anyone. I entered the classroom at nine o''clock and met our teacher, Miss Sarah. She welcomed me warmly and gave me a big vocabulary textbook. There are ten other students in my class from different countries like Turkey and Brazil. We practiced speaking about our hobbies in pairs. The lesson was very interesting and active. Now, I feel more confident about learning English and making new international friends.", "text_ar": "بلشت كورس الإنكليزي المتوسط بمعهد لغات حديث الاثنين الماضي. بأول يوم، كنت كتير متوتر كرمال ما كنت اعرف حدا. دخلت عالصف الساعة تسعة والتقيت بمعلمتنا، الآنسة سارة. رحبت فيني بحفاوة وعطتني كتاب مفردات كبير. في عشر طلاب غيري بالصف من بلاد مختلفة متل تركيا والبرازيل. تدربنا عالحكي عن هواياتنا بضهر بعض (كل اتنين سوا). الدرس كان كتير ممتع وفيه حركة. هلق، حاسس حالي واثق أكتر من تعلم الإنكليزي ومن عمل رفقات أجانب جداد.", "title_ar": "أول يوم بمدرسة اللغات", "questions": [{"id": "q1", "stem": "How did the writer feel at the very beginning of the first day?", "choices": ["Confident", "Nervous", "Warm", "Active"], "correct_index": 1}], "passage_ar": "بلشت كورس الإنكليزي المتوسط بمعهد لغات حديث الاثنين الماضي. بأول يوم، كنت كتير متوتر كرمال ما كنت اعرف حدا. دخلت عالصف الساعة تسعة والتقيت بمعلمتنا، الآنسة سارة. رحبت فيني بحفاوة وعطتني كتاب مفردات كبير. في عشر طلاب غيري بالصف من بلاد مختلفة متل تركيا والبرازيل. تدربنا عالحكي عن هواياتنا بضهر بعض (كل اتنين سوا). الدرس كان كتير ممتع وفيه حركة. هلق، حاسس حالي واثق أكتر من تعلم الإنكليزي ومن عمل رفقات أجانب جداد.", "vocabulary": ["intermediate", "nervous", "textbook", "different", "confident"]}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (137, 1, 'reading', 'A2', 'lesson', 'A Visit to the Doctor', '{"text": "Yesterday, I woke up with a terrible headache and a bad cough. I decided to visit a local doctor near my house. I called the medical clinic at eight o''clock, and the nurse gave me an appointment at ten. When I arrived, I waited in a quiet room for twenty minutes. The doctor was very kind and professional. He checked my throat and measured my temperature. He said I had a simple winter cold. He wrote a prescription for some medicine and told me to rest in bed for three days.", "topic": "daily city life", "passage": "Yesterday, I woke up with a terrible headache and a bad cough. I decided to visit a local doctor near my house. I called the medical clinic at eight o''clock, and the nurse gave me an appointment at ten. When I arrived, I waited in a quiet room for twenty minutes. The doctor was very kind and professional. He checked my throat and measured my temperature. He said I had a simple winter cold. He wrote a prescription for some medicine and told me to rest in bed for three days.", "text_ar": "مبارح، فقت وعندي وجع راس بيموّت وسعلة قوية. قررت زور دكتور محلي قريب من بيتي. اتصلت بالعيادة الطبية الساعة تمنية، والممرضة عطتني موعد الساعة عشرة. لما وصلت، استنيت بغرفة هادية لعشرين دقيقة. الدكتور كان كتير حباب وبروفيسيونال. فحصلي حلقي وقاسلي حرارتي. قال إنه عندي رشة شتوية بسيطة. كتبلي روشتة لعلاج وشوية أدوية وقلي ارتاح بالتخت لتلات أيام.", "title_ar": "زيارة لعند الدكتور", "questions": [{"id": "q1", "stem": "How long did the doctor tell the patient to rest in bed?", "choices": ["Twenty minutes", "Eight days", "Three days", "Ten hours"], "correct_index": 2}], "passage_ar": "مبارح، فقت وعندي وجع راس بيموّت وسعلة قوية. قررت زور دكتور محلي قريب من بيتي. اتصلت بالعيادة الطبية الساعة تمنية، والممرضة عطتني موعد الساعة عشرة. لما وصلت، استنيت بغرفة هادية لعشرين دقيقة. الدكتور كان كتير حباب وبروفيسيونال. فحصلي حلقي وقاسلي حرارتي. قال إنه عندي رشة شتوية بسيطة. كتبلي روشتة لعلاج وشوية أدوية وقلي ارتاح بالتخت لتلات أيام.", "vocabulary": ["terrible", "clinic", "appointment", "throat", "prescription"]}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (138, 1, 'reading', 'A2', 'lesson', 'Registering my Address', '{"text": "When I arrived in Stuttgart last month, I needed to register my new home address. I went to the local city hall on Wednesday morning. The building was large and modern. I took a waiting number from a small machine near the entrance. My number was forty-five. I sat in the waiting area for thirty minutes. Finally, an officer called my name. I showed him my passport and my rental contract. He typed my information into his computer and stamped my document. The process was fast, and the officer was very helpful.", "topic": "bureaucracy", "passage": "When I arrived in Stuttgart last month, I needed to register my new home address. I went to the local city hall on Wednesday morning. The building was large and modern. I took a waiting number from a small machine near the entrance. My number was forty-five. I sat in the waiting area for thirty minutes. Finally, an officer called my name. I showed him my passport and my rental contract. He typed my information into his computer and stamped my document. The process was fast, and the officer was very helpful.", "text_ar": "لما وصلت عشتوتغارت الشهر الماضي، كان لازم سجل عنوان بيتي الجديد. رحت عبلدية المدينة المحلية يوم الأربعا الصبح. البناية كانت كبيرة وحديثة. أخذت رقم دور من ماكينة صغيرة جنب المدخل. رقمي كان خمسة وأربعين. قعدت بمنطقة الانتظار لثلاثين دقيقة. وأخيراً، الموظف نادى اسمي. فرجيته جواز سفري وعقد الآجار تبعي. كتب معلوماتي عكمبيوتره وختم الورقة تبعي. المعاملة كانت سريعة، والموظف كان كتير متعاون.", "title_ar": "تسجيل عنوان السكن", "questions": [{"id": "q1", "stem": "Which documents did the writer show to the city hall officer?", "choices": ["A waiting number and a computer", "A map of Stuttgart and a ticket", "A student card and a prescription", "A passport and a rental contract"], "correct_index": 3}], "passage_ar": "لما وصلت عشتوتغارت الشهر الماضي، كان لازم سجل عنوان بيتي الجديد. رحت عبلدية المدينة المحلية يوم الأربعا الصبح. البناية كانت كبيرة وحديثة. أخذت رقم دور من ماكينة صغيرة جنب المدخل. رقمي كان خمسة وأربعين. قعدت بمنطقة الانتظار لثلاثين دقيقة. وأخيراً، الموظف نادى اسمي. فرجيته جواز سفري وعقد الآجار تبعي. كتب معلوماتي عكمبيوتره وختم الورقة تبعي. المعاملة كانت سريعة، والموظف كان كتير متعاون.", "vocabulary": ["register", "entrance", "passport", "contract", "stamped"]}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (139, 1, 'reading', 'A2', 'lesson', 'Buying a Used Bicycle', '{"text": "I needed a bicycle to go to my university every day because transport is expensive. Yesterday, I searched on a famous German website for used items. I found a nice green bicycle for only fifty euros. I called the owner, and he invited me to see it in the evening. The bicycle was in a very good condition, and the brakes worked perfectly. I paid the man fifty euros, and he also gave me a free blue helmet. I rode my new bicycle back to my flat. I am very happy with it.", "topic": "shopping", "passage": "I needed a bicycle to go to my university every day because transport is expensive. Yesterday, I searched on a famous German website for used items. I found a nice green bicycle for only fifty euros. I called the owner, and he invited me to see it in the evening. The bicycle was in a very good condition, and the brakes worked perfectly. I paid the man fifty euros, and he also gave me a free blue helmet. I rode my new bicycle back to my flat. I am very happy with it.", "text_ar": "كان بدي بسكليت عشان روح عجامعتي كل يوم كرمال المواصلات غالية. مبارح، دورت على موقع ألماني مشهور للأشياء المستعملة. لقيت بسكليت خضرا حلوة بس بخمسين يورو. اتصلت بصاحبها، وعزمني شوفها بالمسا. البسكليت كانت بحالة كتير ممتازة، والفرامل عم تشتغل تمام. دفعت للزلمة خمسين يورو، وهو كمان عطاني خوذة زرقا ببلاش. ركبت بسكليتي الجديدة ورجعت ع شقتي. أنا كتير مبسوط فيها.", "title_ar": "شرا بسكليت مستعملة", "questions": [{"id": "q1", "stem": "What free item did the seller give along with the bicycle?", "choices": ["A blue helmet", "A green bag", "A university map", "A modern computer"], "correct_index": 0}], "passage_ar": "كان بدي بسكليت عشان روح عجامعتي كل يوم كرمال المواصلات غالية. مبارح، دورت على موقع ألماني مشهور للأشياء المستعملة. لقيت بسكليت خضرا حلوة بس بخمسين يورو. اتصلت بصاحبها، وعزمني شوفها بالمسا. البسكليت كانت بحالة كتير ممتازة، والفرامل عم تشتغل تمام. دفعت للزلمة خمسين يورو، وهو كمان عطاني خوذة زرقا ببلاش. ركبت بسكليتي الجديدة ورجعت ع شقتي. أنا كتير مبسوط فيها.", "vocabulary": ["expensive", "website", "condition", "brakes", "helmet"]}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (140, 1, 'reading', 'A2', 'lesson', 'Lost in the Subway', '{"text": "Last night, I had a confusing experience in the Cologne subway system. I wanted to meet my friends at a famous restaurant downtown. I took the underground train line three at seven o''clock. However, I accidentally looked at the wrong map and got off at the wrong station. The station was very dark and unfamiliar to me. I did not know which way to go. Fortunately, I saw a friendly transport worker. I asked him for help in English. He explained the correct route clearly, and I reached the restaurant successfully.", "topic": "transport", "passage": "Last night, I had a confusing experience in the Cologne subway system. I wanted to meet my friends at a famous restaurant downtown. I took the underground train line three at seven o''clock. However, I accidentally looked at the wrong map and got off at the wrong station. The station was very dark and unfamiliar to me. I did not know which way to go. Fortunately, I saw a friendly transport worker. I asked him for help in English. He explained the correct route clearly, and I reached the restaurant successfully.", "text_ar": "مبارح بالليل، صار معي قصة بتبكّك بنظام مترو الأنفاق بكولونيا. كان بدي التقي برفقاتي بمطعم مشهور بوسط البلد. ركبت خط المترو رقم تلاتة الساعة سبعة. بس بالغلط تطلعت عالخريطة الغلط ونزلت بالمحطة الغلط. المحطة كانت كتير عتمة وما بعرفها بنوب. ما كنت اعرف بأي اتجاه لازم اروح. لحسن الحظ، شفت موظف مواصلات ودود. سألته عالمساعدة بالإنكليزي. شرحلي الطريق الصح بوضوح، ووصلت عالمطعم بنجاح.", "title_ar": "ضيعة بالمترو", "questions": [{"id": "q1", "stem": "Why did the writer get off at the wrong subway station?", "choices": ["Because the restaurant was closed", "Because they looked at the wrong map", "Because the train broke down", "Because they were talking to a worker"], "correct_index": 1}], "passage_ar": "مبارح بالليل، صار معي قصة بتبكّك بنظام مترو الأنفاق بكولونيا. كان بدي التقي برفقاتي بمطعم مشهور بوسط البلد. ركبت خط المترو رقم تلاتة الساعة سبعة. بس بالغلط تطلعت عالخريطة الغلط ونزلت بالمحطة الغلط. المحطة كانت كتير عتمة وما بعرفها بنوب. ما كنت اعرف بأي اتجاه لازم اروح. لحسن الحظ، شفت موظف مواصلات ودود. سألته عالمساعدة بالإنكليزي. شرحلي الطريق الصح بوضوح، ووصلت عالمطعم بنجاح.", "vocabulary": ["confusing", "accidentally", "unfamiliar", "fortunately", "route"]}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (141, 1, 'reading', 'B1', 'lesson', 'Applying for a Part-Time Job', '{"text": "I have recently applied for a part-time job at a logistics company in Frankfurt. If I get this position, I would be able to pay my university fees easily. I have already sent my resume and a motivation letter. Yesterday, the manager called me for an interview. He said that I must bring my certificates and registration document. I was quite nervous, but I managed to explain my previous experience in customer service. He told me that they are looking for someone who can work on weekends and handle flexible hours. If they offer me the job, I will start next Monday. I should hear from them by tomorrow afternoon. This job is a great opportunity because it allows me to practice my English and German with colleagues. Working in a new country can be challenging, but I have learned to adapt quickly to different environments. Furthermore, my roommates told me that this company treats its international employees very well, which gives me more confidence.", "topic": "work", "passage": "I have recently applied for a part-time job at a logistics company in Frankfurt. If I get this position, I would be able to pay my university fees easily. I have already sent my resume and a motivation letter. Yesterday, the manager called me for an interview. He said that I must bring my certificates and registration document. I was quite nervous, but I managed to explain my previous experience in customer service. He told me that they are looking for someone who can work on weekends and handle flexible hours. If they offer me the job, I will start next Monday. I should hear from them by tomorrow afternoon. This job is a great opportunity because it allows me to practice my English and German with colleagues. Working in a new country can be challenging, but I have learned to adapt quickly to different environments. Furthermore, my roommates told me that this company treats its international employees very well, which gives me more confidence.", "text_ar": "مؤخراً قدمت على شغل بارت تايم بشركة لوجستية بفرانكفورت. إذا جاني هاد الشغل، رح أقدر أدفع رسوم الجامعة تبعي بكل سهولة. أنا أصلاً بعتت السي في ورسالة الدوافع تبعي. ومبارح، المدير اتصل فيني عشان المقابلة. قاللي إنه لازم جيب معي الشهادات وورقة التسجيل تبعي. كنت متوتر شوي، بس قدرت أشرح خبرتي القديمة بخدمة الزباين. هو قاللي إنهم عم يدوروا على حدا بيقدر يشتغل بعطلة نهاية الأسبوع وبيتأقلم مع الساعات المرنة. إذا عرضوا عليّ الشغل، رح بلش الاثنين الجايه. لازم يرجعولي خبر بكرا بعد الظهر. هاد الشغل فرصة كتير حلوة لأنه بيسمحلي مارس الإنكليزي والألماني تبعي مع رفقاتي بالشغل. الشغل ببلد جديد ممكن يكون فيه تحديات، بس أنا تعلمت كيف اتأقلم بسرعة مع الأجواء المختلفة. وكمان، رفقاتي بالسكن قالولي إنه هي الشركة بتعامل موظفيها الأجانب كتير منيح، وهاد الشي عطاني ثقة أكتر بنفسي.", "title_ar": "التقديم على شغل بارت تايم", "questions": [{"id": "q1", "stem": "What must the writer bring to the job interview?", "choices": ["Certificates and registration document", "A new laptop", "A motivation letter only", "Their roommates"], "correct_index": 0}], "passage_ar": "مؤخراً قدمت على شغل بارت تايم بشركة لوجستية بفرانكفورت. إذا جاني هاد الشغل، رح أقدر أدفع رسوم الجامعة تبعي بكل سهولة. أنا أصلاً بعتت السي في ورسالة الدوافع تبعي. ومبارح، المدير اتصل فيني عشان المقابلة. قاللي إنه لازم جيب معي الشهادات وورقة التسجيل تبعي. كنت متوتر شوي، بس قدرت أشرح خبرتي القديمة بخدمة الزباين. هو قاللي إنهم عم يدوروا على حدا بيقدر يشتغل بعطلة نهاية الأسبوع وبيتأقلم مع الساعات المرنة. إذا عرضوا عليّ الشغل، رح بلش الاثنين الجايه. لازم يرجعولي خبر بكرا بعد الظهر. هاد الشغل فرصة كتير حلوة لأنه بيسمحلي مارس الإنكليزي والألماني تبعي مع رفقاتي بالشغل. الشغل ببلد جديد ممكن يكون فيه تحديات، بس أنا تعلمت كيف اتأقلم بسرعة مع الأجواء المختلفة. وكمان، رفقاتي بالسكن قالولي إنه هي الشركة بتعامل موظفيها الأجانب كتير منيح، وهاد الشي عطاني ثقة أكتر بنفسي.", "vocabulary": ["recently", "position", "certificates", "flexible", "colleagues"]}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (142, 1, 'reading', 'B1', 'lesson', 'The Art of Recycling', '{"text": "When I first moved into my apartment in Stuttgart, I found the waste disposal and recycling system quite complicated. In Germany, people are very strict about sorting their trash into different colored bins. There is a blue bin for paper, a green or brown one for organic waste, and a yellow bag for plastic packaging. If you throw glass bottles into the regular garbage, your neighbors might get upset with you. I have recently learned that most plastic and glass bottles have a deposit called ''Pfand''. This means that when you buy a drink, you pay a little extra money, which you can get back if you return the empty bottle to the supermarket machine. If everyone followed these rules, the environment would be much cleaner. At first, I made a few mistakes and mixed things up, but my flatmate kindly explained everything to me. Now, recycling has become a natural part of my daily routine, and I feel proud to help protect nature.", "topic": "environment", "passage": "When I first moved into my apartment in Stuttgart, I found the waste disposal and recycling system quite complicated. In Germany, people are very strict about sorting their trash into different colored bins. There is a blue bin for paper, a green or brown one for organic waste, and a yellow bag for plastic packaging. If you throw glass bottles into the regular garbage, your neighbors might get upset with you. I have recently learned that most plastic and glass bottles have a deposit called ''Pfand''. This means that when you buy a drink, you pay a little extra money, which you can get back if you return the empty bottle to the supermarket machine. If everyone followed these rules, the environment would be much cleaner. At first, I made a few mistakes and mixed things up, but my flatmate kindly explained everything to me. Now, recycling has become a natural part of my daily routine, and I feel proud to help protect nature.", "text_ar": "أول ما سكنت بشقتي بشتوتغارت، لقيت نظام كب الزبالة وإعادة التدوير معقد شوي. بألمانيا، الناس كتير دقيقين بفرز الزبالة بحاويات ملونة مختلفة. في حاوية زرقا للورق، وخضرا أو بني للزبالة العضوية، وكيس أصفر للمعلبات والبلاستيك. إذا كبيت قناني القزاز بالزبالة العادية، جيرانك ممكن يدايقوا منك. مؤخراً تعلمت إنه أغلب قناني البلاستيك والقزاز عليها رهن اسمه ''بفاند''. هاد بيعني لما تشتري مشروب، بتدفع فوق حقه مصاري زيادة شوي، واليوم فيك ترجعهم إذا رجعت القنينة الفاضية عالماكينة بالسوبرماركت. إذا الكل بيمشي على هي القواعد، البيئة رح تصير أنظف بكثير. بالبدايه، عملت شوية أغلاط وخلطت الأمور ببعضها، بس رفيقي بالسكن بكل لطف شرحلي كل شي. هلق، إعادة التدوير صارت جزء طبيعي من روتيني اليومي، وحاسس حالي فخور إني عم ساعد بحماية الطبيعة.", "title_ar": "فن إعادة التدوير", "questions": [{"id": "q1", "stem": "What is ''Pfand'' in Germany?", "choices": ["A type of organic waste", "A deposit on plastic and glass bottles", "A fine for throwing glass away", "A special colored trash bin"], "correct_index": 1}], "passage_ar": "أول ما سكنت بشقتي بشتوتغارت، لقيت نظام كب الزبالة وإعادة التدوير معقد شوي. بألمانيا، الناس كتير دقيقين بفرز الزبالة بحاويات ملونة مختلفة. في حاوية زرقا للورق، وخضرا أو بني للزبالة العضوية، وكيس أصفر للمعلبات والبلاستيك. إذا كبيت قناني القزاز بالزبالة العادية، جيرانك ممكن يدايقوا منك. مؤخراً تعلمت إنه أغلب قناني البلاستيك والقزاز عليها رهن اسمه ''بفاند''. هاد بيعني لما تشتري مشروب، بتدفع فوق حقه مصاري زيادة شوي، واليوم فيك ترجعهم إذا رجعت القنينة الفاضية عالماكينة بالسوبرماركت. إذا الكل بيمشي على هي القواعد، البيئة رح تصير أنظف بكثير. بالبدايه، عملت شوية أغلاط وخلطت الأمور ببعضها، بس رفيقي بالسكن بكل لطف شرحلي كل شي. هلق، إعادة التدوير صارت جزء طبيعي من روتيني اليومي، وحاسس حالي فخور إني عم ساعد بحماية الطبيعة.", "vocabulary": ["complicated", "strict", "sorting", "deposit", "environment"]}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (167, 1, 'reading', 'C1', 'lesson', 'Linguistic Hybridity and Socio-Cultural Capital', '{"text": "Academic research into migrant communities in Western Europe has increasingly focused on the concept of linguistic hybridity and its correlation with socio-cultural capital. Traditional pedagogical perspectives often treated the emergence of mixed linguistic codes—such as blending Arabic syntactic structures with German vocabulary—as a deficit indicating incomplete language acquisition. However, contemporary sociolinguistic frameworks deconstruct this outdated narrative, demonstrating that linguistic hybridity represents a highly sophisticated communicative competence. It is this multi-layered linguistic flexibility that allows individuals to navigate distinct cultural spheres fluidly, maximizing their social network opportunities. Not only do hybrid language practices preserve heritage identity, but they also facilitate tactical integration into host societies. What complicates the academic valuation of these linguistic skills is the institutional rigidity of official educational systems, which continue to demand adherence to monolingual standard registers during professional examinations. Were school curricula to validate code-switching and multilingual practices as cognitive assets, the educational achievements of international students would improve substantially. Sociologists emphasize that linguistic flexibility functions as a form of cultural capital, empowering individuals to challenge systemic marginalization. Ultimately, fostering an inclusive educational ecosystem requires a shift away from monolingual biases, embracing instead the rich communicative repertoires that characterize modern diverse urban populations.", "topic": "academic research", "passage": "Academic research into migrant communities in Western Europe has increasingly focused on the concept of linguistic hybridity and its correlation with socio-cultural capital. Traditional pedagogical perspectives often treated the emergence of mixed linguistic codes—such as blending Arabic syntactic structures with German vocabulary—as a deficit indicating incomplete language acquisition. However, contemporary sociolinguistic frameworks deconstruct this outdated narrative, demonstrating that linguistic hybridity represents a highly sophisticated communicative competence. It is this multi-layered linguistic flexibility that allows individuals to navigate distinct cultural spheres fluidly, maximizing their social network opportunities. Not only do hybrid language practices preserve heritage identity, but they also facilitate tactical integration into host societies. What complicates the academic valuation of these linguistic skills is the institutional rigidity of official educational systems, which continue to demand adherence to monolingual standard registers during professional examinations. Were school curricula to validate code-switching and multilingual practices as cognitive assets, the educational achievements of international students would improve substantially. Sociologists emphasize that linguistic flexibility functions as a form of cultural capital, empowering individuals to challenge systemic marginalization. Ultimately, fostering an inclusive educational ecosystem requires a shift away from monolingual biases, embracing instead the rich communicative repertoires that characterize modern diverse urban populations.", "text_ar": "الأبحاث الأكاديمية يلي بتخص مجتمعات المهاجرين بأوروبا الغربية عم تركز هلق أكتر وأكتر على مفهوم الهجين اللغوي وعلاقته برأس المال الاجتماعي والثقافي. النظريات التعليمية التقليدية كانت كتير أوقات تعامل ظهور لغات مخلطة—متل دمج قواعد الجمل العربية مع كلمات ألمانية—على أساس إنه نقص وعيب وبيدل على عدم اكتمال تعلم اللغة. بس هلق، أطر علم اللغة الاجتماعي المعاصر عم تفكك هي الرواية الموديل قديم، وعم توضح إنه الهجين اللغوي بيمثل مهارة تواصل متطورة وذكية كتير. وهي المرونة اللغوية متعددة الطبقات هي بالظبط شو يلي عم يخلي الأشخاص يمشوا بين أجواء ثقافية مختلفة بكل سلاسة، ويطلعوا بأكبر فائدة من علاقاتهم الاجتماعية. الممارسات اللغوية الهجينة مو بس بتحافظ ع الهوية والإرث، بل كمان بتسهل الاندماج الذكي بالمجتمعات المضيفة. وشو يلي عم يعقد التقييم الأكاديمي لهي المهارات اللغوية؟ هو الناشفة والجمود المؤسساتي بأنظمة التعليم الرسمية، يلي لساتها عم تطالب بالالتزام التام بلغة معيارية وحدة خلال الامتحانات المهنية. لو كانت المناهج المدرسية بتعترف بالتبديل بين اللغات والممارسات متعددة اللغات كميزة فكرية حقيقية، كان التحصيل الدراسي للطلاب الأجانب رح يتحسن كتير. علماء الاجتماع عم يشددوا إنه المرونة اللغوية بتشتغل كنوع من رأس المال الثقافي، وبيثبت قدرة الأشخاص على مواجهة التهميش الممنهج. بالنهاية، بناء بيئة تعليمية شاملة بده تحول بعيداً عن الانحياز للغة الوحدة، ونحضن بدالها المخزون التواصلي الغني يلي بيميز سكان المدن المتنوعة والحديثة هلق.", "title_ar": "الهوية اللغوية الهجينة ورأس المال الاجتماعي والثقافي", "questions": [{"id": "q7", "stem": "How do contemporary sociolinguistic frameworks view the emergence of mixed linguistic codes?", "choices": ["As a severe communicative deficit that indicates incomplete language acquisition", "As a major institutional reason for educational failure in professional exams", "As a highly sophisticated communicative competence and cognitive asset", "As a direct violation of international law regarding monolingual standard registers"], "correct_index": 2}], "passage_ar": "الأبحاث الأكاديمية يلي بتخص مجتمعات المهاجرين بأوروبا الغربية عم تركز هلق أكتر وأكتر على مفهوم الهجين اللغوي وعلاقته برأس المال الاجتماعي والثقافي. النظريات التعليمية التقليدية كانت كتير أوقات تعامل ظهور لغات مخلطة—متل دمج قواعد الجمل العربية مع كلمات ألمانية—على أساس إنه نقص وعيب وبيدل على عدم اكتمال تعلم اللغة. بس هلق، أطر علم اللغة الاجتماعي المعاصر عم تفكك هي الرواية الموديل قديم، وعم توضح إنه الهجين اللغوي بيمثل مهارة تواصل متطورة وذكية كتير. وهي المرونة اللغوية متعددة الطبقات هي بالظبط شو يلي عم يخلي الأشخاص يمشوا بين أجواء ثقافية مختلفة بكل سلاسة، ويطلعوا بأكبر فائدة من علاقاتهم الاجتماعية. الممارسات اللغوية الهجينة مو بس بتحافظ ع الهوية والإرث، بل كمان بتسهل الاندماج الذكي بالمجتمعات المضيفة. وشو يلي عم يعقد التقييم الأكاديمي لهي المهارات اللغوية؟ هو الناشفة والجمود المؤسساتي بأنظمة التعليم الرسمية، يلي لساتها عم تطالب بالالتزام التام بلغة معيارية وحدة خلال الامتحانات المهنية. لو كانت المناهج المدرسية بتعترف بالتبديل بين اللغات والممارسات متعددة اللغات كميزة فكرية حقيقية، كان التحصيل الدراسي للطلاب الأجانب رح يتحسن كتير. علماء الاجتماع عم يشددوا إنه المرونة اللغوية بتشتغل كنوع من رأس المال الثقافي، وبيثبت قدرة الأشخاص على مواجهة التهميش الممنهج. بالنهاية، بناء بيئة تعليمية شاملة بده تحول بعيداً عن الانحياز للغة الوحدة، ونحضن بدالها المخزون التواصلي الغني يلي بيميز سكان المدن المتنوعة والحديثة هلق.", "vocabulary": ["hybridity", "acquisition", "rigidity", "adherence", "repertoires"]}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (168, 1, 'reading', 'C1', 'lesson', 'The Algorithmic Curating of Public Consciousness', '{"text": "The pervasive influence of algorithmic curation on digital information networks has structurally transformed the nature of public discourse, presenting unprecedented challenges to media literacy. Contemporary data platforms leverage complex machine-learning protocols to analyze vast arrays of individual behavioral data, thereby predicting and delivering content customized to maximize screen time. This automated feedback loop inherently capitalizes on psychological triggers, systematically amplifying sensationalized or divisive narratives. It is this underlying commercial architecture that systematically distorts collective consciousness, creating deeply polarized societal factions. Media researchers note that the standard consumer remains largely oblivious to the invisible mechanisms shaping their digital environment, frequently confusing curated feeds with objective reality. Not only do these corporate algorithms dictate information visibility, but they also fundamentally undermine the public''s capacity to engage in rational democratic consensus. Were regulatory institutions to mandate algorithmic transparency and enforce data sovereignty laws, citizens would regain a degree of cognitive agency over their digital consumption. However, mitigating this systemic crisis demands more than legislative intervention; it requires a pedagogical overhaul that positions algorithmic literacy as a core civic competence. Ultimately, preserving democratic integrity in the digital era depends on our collective ability to cultivate critical skepticism toward the automated systems that filter our shared socio-political reality.", "topic": "media literacy", "passage": "The pervasive influence of algorithmic curation on digital information networks has structurally transformed the nature of public discourse, presenting unprecedented challenges to media literacy. Contemporary data platforms leverage complex machine-learning protocols to analyze vast arrays of individual behavioral data, thereby predicting and delivering content customized to maximize screen time. This automated feedback loop inherently capitalizes on psychological triggers, systematically amplifying sensationalized or divisive narratives. It is this underlying commercial architecture that systematically distorts collective consciousness, creating deeply polarized societal factions. Media researchers note that the standard consumer remains largely oblivious to the invisible mechanisms shaping their digital environment, frequently confusing curated feeds with objective reality. Not only do these corporate algorithms dictate information visibility, but they also fundamentally undermine the public''s capacity to engage in rational democratic consensus. Were regulatory institutions to mandate algorithmic transparency and enforce data sovereignty laws, citizens would regain a degree of cognitive agency over their digital consumption. However, mitigating this systemic crisis demands more than legislative intervention; it requires a pedagogical overhaul that positions algorithmic literacy as a core civic competence. Ultimately, preserving democratic integrity in the digital era depends on our collective ability to cultivate critical skepticism toward the automated systems that filter our shared socio-political reality.", "text_ar": "التأثير المنتشر للتوجيه والفرز الخوارزمي على شبكات المعلومات الديجيتال غير هيكلية طبيعة النقاش العام، وعم يعمل تحديات مسبوقة للتربية الإعلامية. منصات البيانات المعاصرة عم تستغل بروتوكولات التعلم الآلي المعقدة لتحلل كميات ضخمة من بيانات سلوك الأفراد، كرمال تتوقع وتقدم محتوى مفصل تفصيل لتزيد وقت القعدة قدام الشاشة. هي حلقة التغذية الراجعة المؤتمتة بتعتمد بأساسها ع اللعب على المحفزات النفسية، وعم تضخم بشكل ممنهج الروايات المثيرة للعواطف أو يلي بتعمل انقسامات. وهي البنية التجارية المخفية هي بالظبط شو يلي عم يشوه الوعي الجماعي، ويعمل جماعات منقسمة ومتحزبة كتير بالمجتمع. باحثين بمجال الإعلام عم يلاحظوا إنه المستهلك العادي عم يضل مغيب تماماً عن الآليات المخفية يلي عم تشكل بيئته الرقمية، وكتير أوقات بيخلط بين الصفحات الموجهة والواقع الموضوعي. هي الخوارزميات تبع الشركات مو بس عم تتحكم بشو عم يشوفوا العالم من معلومات، بل كمان عم تضرب من الجذور قدرة الناس على الدخول بإجماع ديمقراطي وعقلاني. لو كانت المؤسسات الرقابية بتفرض شفافية الخوارزميات وتطبق قوانين سيادة البيانات، كان المواطنين استرجعوا جزء من قدرتهم الفكرية على التحكم باستهلاكهم الرقمي. بس عشان نخفف من هي الأزمة الممنهجة، الموضوع بده أكتر من تدخل قانوني؛ بده ثورة بالمناهج التعليمية بتحط الوعي بالخوارزميات كمهارة مدنية أساسية. بالنهاية، الحفاظ على النزاهة الديمقراطية بالعصر الرقمي بيعتمد على قدرتنا الجماعية على بناء حس نقدي وشكاك تجاه الأنظمة المؤتمتة يلي عم تفرز واقعنا السياسي والاجتماعي المشترك.", "title_ar": "التوجيه الخوارزمي للوعي العام", "questions": [{"id": "q8", "stem": "According to the author, what is the underlying motive behind corporate algorithmic content curation?", "choices": ["To promote factual accuracy and guarantee comprehensive media literacy for all users", "To enforce data sovereignty laws and support municipal regulatory institutions", "To eliminate machine-learning protocols from public digital information networks", "To maximize screen time and user engagement by exploiting psychological triggers"], "correct_index": 3}], "passage_ar": "التأثير المنتشر للتوجيه والفرز الخوارزمي على شبكات المعلومات الديجيتال غير هيكلية طبيعة النقاش العام، وعم يعمل تحديات مسبوقة للتربية الإعلامية. منصات البيانات المعاصرة عم تستغل بروتوكولات التعلم الآلي المعقدة لتحلل كميات ضخمة من بيانات سلوك الأفراد، كرمال تتوقع وتقدم محتوى مفصل تفصيل لتزيد وقت القعدة قدام الشاشة. هي حلقة التغذية الراجعة المؤتمتة بتعتمد بأساسها ع اللعب على المحفزات النفسية، وعم تضخم بشكل ممنهج الروايات المثيرة للعواطف أو يلي بتعمل انقسامات. وهي البنية التجارية المخفية هي بالظبط شو يلي عم يشوه الوعي الجماعي، ويعمل جماعات منقسمة ومتحزبة كتير بالمجتمع. باحثين بمجال الإعلام عم يلاحظوا إنه المستهلك العادي عم يضل مغيب تماماً عن الآليات المخفية يلي عم تشكل بيئته الرقمية، وكتير أوقات بيخلط بين الصفحات الموجهة والواقع الموضوعي. هي الخوارزميات تبع الشركات مو بس عم تتحكم بشو عم يشوفوا العالم من معلومات، بل كمان عم تضرب من الجذور قدرة الناس على الدخول بإجماع ديمقراطي وعقلاني. لو كانت المؤسسات الرقابية بتفرض شفافية الخوارزميات وتطبق قوانين سيادة البيانات، كان المواطنين استرجعوا جزء من قدرتهم الفكرية على التحكم باستهلاكهم الرقمي. بس عشان نخفف من هي الأزمة الممنهجة، الموضوع بده أكتر من تدخل قانوني؛ بده ثورة بالمناهج التعليمية بتحط الوعي بالخوارزميات كمهارة مدنية أساسية. بالنهاية، الحفاظ على النزاهة الديمقراطية بالعصر الرقمي بيعتمد على قدرتنا الجماعية على بناء حس نقدي وشكاك تجاه الأنظمة المؤتمتة يلي عم تفرز واقعنا السياسي والاجتماعي المشترك.", "vocabulary": ["pervasive", "protocols", "oblivious", "sovereignty", "skepticism"]}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (169, 1, 'reading', 'C1', 'lesson', 'Deconstructing Institutional Inertia through Agile Frameworks', '{"text": "The application of agile methodologies within traditionally bureaucratic European corporate structures has emerged as a core business strategy to combat institutional inertia. Historically, corporate enterprises operating in stable markets relied on hierarchical command structures and extensive, long-term planning cycles. However, the contemporary commercial landscape, characterized by hyper-accelerated technological disruptions and volatile consumer demands, has rendered these static models obsolete. To remain competitive, organizations are forced to decentralize decision-making authority, organizing internal workforces into cross-functional, autonomous teams. It is this operational restructuring that facilitates rapid iteration and continuous adaptation to market shifts. What frequently sabotages these organizational transformations is the entrenched psychological resistance from middle management, whose institutional authority is fundamentally challenged by decentralized frameworks. Corporate analysts emphasize that unless leadership teams actively cultivate an organizational culture that views failure as an essential learning metric, structural agility remains unattainable. Were corporate entities to decouple performance evaluations from rigid, short-term targets, employee innovation would flourish. Not only must enterprises adopt agile digital tools, but they must also fundamentally re-engineer their communication channels to ensure absolute transparency. Ultimately, dismantling institutional inertia requires a profound philosophical commitment to continuous evolution, transforming rigid corporations into adaptive ecosystems capable of thriving amidst global market uncertainty.", "topic": "business strategy", "passage": "The application of agile methodologies within traditionally bureaucratic European corporate structures has emerged as a core business strategy to combat institutional inertia. Historically, corporate enterprises operating in stable markets relied on hierarchical command structures and extensive, long-term planning cycles. However, the contemporary commercial landscape, characterized by hyper-accelerated technological disruptions and volatile consumer demands, has rendered these static models obsolete. To remain competitive, organizations are forced to decentralize decision-making authority, organizing internal workforces into cross-functional, autonomous teams. It is this operational restructuring that facilitates rapid iteration and continuous adaptation to market shifts. What frequently sabotages these organizational transformations is the entrenched psychological resistance from middle management, whose institutional authority is fundamentally challenged by decentralized frameworks. Corporate analysts emphasize that unless leadership teams actively cultivate an organizational culture that views failure as an essential learning metric, structural agility remains unattainable. Were corporate entities to decouple performance evaluations from rigid, short-term targets, employee innovation would flourish. Not only must enterprises adopt agile digital tools, but they must also fundamentally re-engineer their communication channels to ensure absolute transparency. Ultimately, dismantling institutional inertia requires a profound philosophical commitment to continuous evolution, transforming rigid corporations into adaptive ecosystems capable of thriving amidst global market uncertainty.", "text_ar": "تطبيق مناهج العمل المرنة (Agile) بقلب الشركات الأوروبية ذات الهيكل البيروقراطي التقليدي طلع كاستراتيجية شغل أساسية لمحاربة الجمود المؤسساتي. وتاريخياً، كانت الشركات يلي بتشتغل بأسواق مستقرة بتعتمد على هياكل القيادة الهرمية ودورات تخطيط طويلة الأمد وموسعة. بس هلق، الأجواء التجارية المعاصرة، يلي بتتسم بالهزات التكنولوجية السريعة كتير وتقلبات طلبات المستهلكين، خلت هي النماذج الجامدة برّا التاريخ وما عاد تنفع. وعشان تضل عم تنافس، الشركات صارت مجبورة تعمل لامركزية بصلاحيات اتخاذ القرار، وتنظم الموظفين بفرق مستقلة ومتعددة الوظائف. وهاد إعادة الهيكلة التشغيلية بالظبط هو شو يلي عم يسهل التجريب السريع والتأقلم المستمر مع تغيرات السوق. بس شو يلي كتير أوقات عم يخرب هذا التحول بقلب المؤسسات؟ هو المقاومة النفسية المزروعة عند المدراء بمنتصف الهرم الوظيفي، يلي عم يحسوا إنه سلطتهم بالمؤسسة عم تتهدد بسبب أطر العمل اللامركزية. محللين الشركات عم يشددوا إنه إذا ما كانت فرق القيادة بتبني ثقافة بالشركة بتشوف الفشل كمعيار أساسي للتعلم، رح تضل المرونة الهيكلية مستحيلة. لو كانت الشركات بتفصل تقييم الأداء عن الأهداف الناشفة وقصيرة الأمد، كان ابتكار الموظفين رح ينفجر ويزدهر. الشركات مو بس مجبورة تعتمد أدوات رقمية مرنة، بل كمان لازم تعيد هندسة قنوات التواصل من الجذور لتضمن شفافية كاملة. بالنهاية، تفكيك جمود المؤسسات بده التزام فلسفي عميق بالتطور المستمر، ليحول الشركات الجامدة لبيئات حيوية مرنة قادرة تنجح بقلب عدم استقرار الأسواق العالمية.", "title_ar": "تفكيك جمود المؤسسات من خلال أطر العمل المرنة", "questions": [{"id": "q9", "stem": "What is identified by corporate analysts as a primary threat to successful agile transformation within traditional companies?", "choices": ["The entrenched psychological resistance from middle management regarding decentralized authority", "The extreme lack of technological disruption within contemporary commercial landscapes", "The total removal of hierarchical command structures from historical stable markets", "An absolute lack of communication tools and autonomous cross-functional teams"], "correct_index": 0}], "passage_ar": "تطبيق مناهج العمل المرنة (Agile) بقلب الشركات الأوروبية ذات الهيكل البيروقراطي التقليدي طلع كاستراتيجية شغل أساسية لمحاربة الجمود المؤسساتي. وتاريخياً، كانت الشركات يلي بتشتغل بأسواق مستقرة بتعتمد على هياكل القيادة الهرمية ودورات تخطيط طويلة الأمد وموسعة. بس هلق، الأجواء التجارية المعاصرة، يلي بتتسم بالهزات التكنولوجية السريعة كتير وتقلبات طلبات المستهلكين، خلت هي النماذج الجامدة برّا التاريخ وما عاد تنفع. وعشان تضل عم تنافس، الشركات صارت مجبورة تعمل لامركزية بصلاحيات اتخاذ القرار، وتنظم الموظفين بفرق مستقلة ومتعددة الوظائف. وهاد إعادة الهيكلة التشغيلية بالظبط هو شو يلي عم يسهل التجريب السريع والتأقلم المستمر مع تغيرات السوق. بس شو يلي كتير أوقات عم يخرب هذا التحول بقلب المؤسسات؟ هو المقاومة النفسية المزروعة عند المدراء بمنتصف الهرم الوظيفي، يلي عم يحسوا إنه سلطتهم بالمؤسسة عم تتهدد بسبب أطر العمل اللامركزية. محللين الشركات عم يشددوا إنه إذا ما كانت فرق القيادة بتبني ثقافة بالشركة بتشوف الفشل كمعيار أساسي للتعلم، رح تضل المرونة الهيكلية مستحيلة. لو كانت الشركات بتفصل تقييم الأداء عن الأهداف الناشفة وقصيرة الأمد، كان ابتكار الموظفين رح ينفجر ويزدهر. الشركات مو بس مجبورة تعتمد أدوات رقمية مرنة، بل كمان لازم تعيد هندسة قنوات التواصل من الجذور لتضمن شفافية كاملة. بالنهاية، تفكيك جمود المؤسسات بده التزام فلسفي عميق بالتطور المستمر، ليحول الشركات الجامدة لبيئات حيوية مرنة قادرة تنجح بقلب عدم استقرار الأسواق العالمية.", "vocabulary": ["inertia", "hierarchical", "obsolete", "entrenched", "decouple"]}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (170, 1, 'reading', 'C1', 'lesson', 'Legislating the Boundaries of Digital Labor', '{"text": "The rapid normalization of remote employment models across Europe has necessitated a fundamental re-examination of labor law, specifically regarding individual boundary management. While digital connectivity offers unparalleled flexibility, it simultaneously facilitates a corporate culture of constant availability, systematically blurring the distinction between professional duties and private life. To safeguard employee health, several European nations have pioneered statutory interventions, universally referred to as the ''right to disconnect.'' This legal doctrine establishes that employees are under no obligation to engage with corporate communications outside of official working hours. It is this protective legislation that aims to mitigate the rising incidence of psychological burnout among digital workforces. However, enforcing these statutory boundaries within highly fluid, transnational corporate environments remains immensely complex. Legal experts note that global companies frequently operate across multiple time zones, complicating the application of localized labor regulations. Were international labor bodies to draft unified, enforceable digital employment standards, cross-border exploitation could be effectively neutralized. Furthermore, individual compliance with these laws is often compromised by the subtle professional pressure to remain constantly accessible to secure career advancement. Ultimately, the successful containment of digital exploitation requires a synchronized strategy that reinforces robust legislative mandates with a cultural shift that treats uninterrupted leisure as an absolute human right.", "topic": "law", "passage": "The rapid normalization of remote employment models across Europe has necessitated a fundamental re-examination of labor law, specifically regarding individual boundary management. While digital connectivity offers unparalleled flexibility, it simultaneously facilitates a corporate culture of constant availability, systematically blurring the distinction between professional duties and private life. To safeguard employee health, several European nations have pioneered statutory interventions, universally referred to as the ''right to disconnect.'' This legal doctrine establishes that employees are under no obligation to engage with corporate communications outside of official working hours. It is this protective legislation that aims to mitigate the rising incidence of psychological burnout among digital workforces. However, enforcing these statutory boundaries within highly fluid, transnational corporate environments remains immensely complex. Legal experts note that global companies frequently operate across multiple time zones, complicating the application of localized labor regulations. Were international labor bodies to draft unified, enforceable digital employment standards, cross-border exploitation could be effectively neutralized. Furthermore, individual compliance with these laws is often compromised by the subtle professional pressure to remain constantly accessible to secure career advancement. Ultimately, the successful containment of digital exploitation requires a synchronized strategy that reinforces robust legislative mandates with a cultural shift that treats uninterrupted leisure as an absolute human right.", "text_ar": "التحول السريع والمألوف لنماذج الشغل عن بعد بكل أوروبا فرض إعادة دراسة جذرية لقانون العمل، وخصوصي بما يتعلق بإدارة الحدود الشخصية للعمال. ومع إنه الاتصال الرقمي بيقدم مرونة ماله نظير، بس بنفس الوقت عم يسهل وجود ثقافة بالشركات قائمة على التواجد المستمر، وعم يمحي بشكل ممنهج الخط الفاصل بين الواجبات المهنية والحياة الخاصة. وعشان يحموا صحة الموظفين، في كذا بلد أوروبي بلشوا يحطوا قوانين وتدخلات رسمية، والكل بيسميها ''الحق بفصل الاتصال''. هاد المبدأ القانوني بيحدد إنه الموظفين مالهن مجبرين بنوب يتفاعلوا مع إيميلات أو اتصالات الشغل برّا ساعات الدوام الرسمية. وهي القوانين الحمائية بالظبط بتهدف لتخفيف حالات الاحتراق النفسي يلي عم تزيد بين العمال الرقميين. بس تطبيق هي الحدود القانونية بقلب شركات مرنة كتير وعابرة للقارات عم يضل معقد بشكل كتير كبير. خبراء القانون عم يلاحظوا إنه الشركات العالمية كتير أوقات بتشتغل عبر كذا توقيت زمني، وهاد الشي عم يعقد تطبيق قوانين العمل المحلية. لو كانت هيئات العمل الدولية بتصيغ معايير موحدة وقابلة للتطبيق للشغل الرقمي، كان ممكن نقضي ع الاستغلال عبر الحدود بشكل فعال. وكمان، التزام الأفراد بهي القوانين كتير أوقات عم ينضرب بسبب الضغط المهني المبطن عشان يضل الواحد متاح دايماً ليضمن ترقية بشغله. بالنهاية، السيطرة الناجحة ع الاستغلال الرقمي بدها خطة متزامنة بتدعم القوانين التشريعية القوية مع تحول ثقافي حقيقي بيعامل وقت الفراغ والراحة من دون إزعاج كحق إنساني مطلق.", "title_ar": "تقنين حدود الشغل الرقمي", "questions": [{"id": "q10", "stem": "What complicates the enforcement of localized ''right to disconnect'' laws according to the passage?", "choices": ["The total elimination of remote employment models across European nations", "The fact that global companies frequently operate across multiple time zones", "The complete absence of psychological burnout among digital workforces", "A global legal mandate that forces all employees to work across borders"], "correct_index": 1}], "passage_ar": "التحول السريع والمألوف لنماذج الشغل عن بعد بكل أوروبا فرض إعادة دراسة جذرية لقانون العمل، وخصوصي بما يتعلق بإدارة الحدود الشخصية للعمال. ومع إنه الاتصال الرقمي بيقدم مرونة ماله نظير، بس بنفس الوقت عم يسهل وجود ثقافة بالشركات قائمة على التواجد المستمر، وعم يمحي بشكل ممنهج الخط الفاصل بين الواجبات المهنية والحياة الخاصة. وعشان يحموا صحة الموظفين، في كذا بلد أوروبي بلشوا يحطوا قوانين وتدخلات رسمية، والكل بيسميها ''الحق بفصل الاتصال''. هاد المبدأ القانوني بيحدد إنه الموظفين مالهن مجبرين بنوب يتفاعلوا مع إيميلات أو اتصالات الشغل برّا ساعات الدوام الرسمية. وهي القوانين الحمائية بالظبط بتهدف لتخفيف حالات الاحتراق النفسي يلي عم تزيد بين العمال الرقميين. بس تطبيق هي الحدود القانونية بقلب شركات مرنة كتير وعابرة للقارات عم يضل معقد بشكل كتير كبير. خبراء القانون عم يلاحظوا إنه الشركات العالمية كتير أوقات بتشتغل عبر كذا توقيت زمني، وهاد الشي عم يعقد تطبيق قوانين العمل المحلية. لو كانت هيئات العمل الدولية بتصيغ معايير موحدة وقابلة للتطبيق للشغل الرقمي، كان ممكن نقضي ع الاستغلال عبر الحدود بشكل فعال. وكمان، التزام الأفراد بهي القوانين كتير أوقات عم ينضرب بسبب الضغط المهني المبطن عشان يضل الواحد متاح دايماً ليضمن ترقية بشغله. بالنهاية، السيطرة الناجحة ع الاستغلال الرقمي بدها خطة متزامنة بتدعم القوانين التشريعية القوية مع تحول ثقافي حقيقي بيعامل وقت الفراغ والراحة من دون إزعاج كحق إنساني مطلق.", "vocabulary": ["normalization", "blurring", "doctrine", "transnational", "accessibility"]}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (171, 1, 'reading', 'C2', 'lesson', 'The Fiscal Architecture of the Eurozone', '{"text": "The structural design of the Eurozone represents one of the most audacious experiments in modern macroeconomic history, yet it remains fundamentally hamstrung by an architectural asymmetry: the implementation of a unified monetary policy without a corresponding fiscal unification. When sovereign states relinquish control over their domestic monetary instruments—specifically the ability to manipulate interest rates or devalue their currency to absorb economic shocks—they become exceptionally vulnerable to asymmetric economic downturns. In the absence of a centralized Eurozone fiscal treasury capable of executing counter-cyclical budgetary transfers, distressed member states are forced to rely almost exclusively on internal deflation and stringent fiscal austerity to regain international competitiveness. This structural dynamic frequently ignites severe socio-economic crises, as the burden of adjustment falls disproportionately on public infrastructure, social welfare systems, and employment rates. Economists have long argued that a monetary union cannot achieve long-term equilibrium without a robust mechanism for fiscal risk-sharing, such as a permanent common budget or the issuance of joint sovereign debt instruments. However, the path toward deeper fiscal integration is deeply contested by national electorates, polarizing the continent along geopolitical and ideological fault lines. Wealthier member states routinely express profound concerns regarding the moral hazard of subsidizing structurally weaker economies, fearing that a permanent transfer union would disincentivize necessary domestic structural reforms. Conversely, peripheral nations contend that the current framework systematically favors export-driven core economies, thereby exacerbating structural imbalances across the single market. The ongoing policy debate highlights the fundamental tension between national sovereignty and transnational economic governance, illustrating that the survival of the currency union ultimately hinges on a political consensus that transcends localized electoral calculations.", "topic": "economics", "passage": "The structural design of the Eurozone represents one of the most audacious experiments in modern macroeconomic history, yet it remains fundamentally hamstrung by an architectural asymmetry: the implementation of a unified monetary policy without a corresponding fiscal unification. When sovereign states relinquish control over their domestic monetary instruments—specifically the ability to manipulate interest rates or devalue their currency to absorb economic shocks—they become exceptionally vulnerable to asymmetric economic downturns. In the absence of a centralized Eurozone fiscal treasury capable of executing counter-cyclical budgetary transfers, distressed member states are forced to rely almost exclusively on internal deflation and stringent fiscal austerity to regain international competitiveness. This structural dynamic frequently ignites severe socio-economic crises, as the burden of adjustment falls disproportionately on public infrastructure, social welfare systems, and employment rates. Economists have long argued that a monetary union cannot achieve long-term equilibrium without a robust mechanism for fiscal risk-sharing, such as a permanent common budget or the issuance of joint sovereign debt instruments. However, the path toward deeper fiscal integration is deeply contested by national electorates, polarizing the continent along geopolitical and ideological fault lines. Wealthier member states routinely express profound concerns regarding the moral hazard of subsidizing structurally weaker economies, fearing that a permanent transfer union would disincentivize necessary domestic structural reforms. Conversely, peripheral nations contend that the current framework systematically favors export-driven core economies, thereby exacerbating structural imbalances across the single market. The ongoing policy debate highlights the fundamental tension between national sovereignty and transnational economic governance, illustrating that the survival of the currency union ultimately hinges on a political consensus that transcends localized electoral calculations.", "text_ar": "التصميم الهيكلي لمنطقة اليورو بيمثل وحدة من أجرأ التجارب بتاريخ الاقتصاد الكلي الحديث، ومع هيك لساته مشلول ومقيد من الجذور بسبب عدم التوازن بالبنية: يعني عم يطبقوا سياسة نقدية موحدة من دون ما يكون في توحيد مالي حقيقي بيقابلها. ولما الدول ذات السيادة تتنازل عن التحكم بأدواتها النقدية المحلية—وخصوصي القدرة على التلاعب بأسعار الفائدة أو تخفيض قيمة عملتها لتمتص الهزات الاقتصادية—بتصير ضعيفة ومعرضة كتير للأزمات الاقتصادية غير المتماثلة. وبظل غياب وزارة مالية مركزية لمنطقة اليورو قادرة تنفذ تحويلات بالميزانية لمواجهة التقلبات، الدول الأعضاء يلي عم تعاني بتنجبر تعتمد بشكل شبه كامل على الانكماش الداخلي وسياسات التقشف المالي الناشفة لترجع تكسب قدرتها على المنافسة الدولية. وهي الحركية الهيكلية كتير أوقات عم تشعل أزمات اقتصادية واجتماعية خطيرة، لأنه حمل وعواقب هاد التعديل عم يوقع بشكل غير عادل على البنية التحتية العامة، وأنظمة الرفاه الاجتماعي، ومعدلات الشغل. خبراء الاقتصاد صر لهم زمان عم يقولوا إنه الاتحاد النقدي ما فيه يوصل لاستقرار وتوازن على المدى الطويل بلا وجود آلية قوية لمشاركة المخاطر المالية، متل ميزانية مشتركة دائمة أو إصدار أدوات ديون سيادية مشتركة. بس هاد الطريق نحو اندماج مالي أعمق عليه خلافات كبيرة كتير بين الناخبين بكل بلد، وهاد الشي عم يقسم القارة على طول خطوط الصدع الجيوسياسية والأيديولوجية. الدول الأعضاء الأغنى عم تبدي دايماً مخاوف عميقة من الخطر الأخلاقي الكامن وراء دعم الاقتصادات الأضعف هيكلياً، كرمال خايفين إنه وجود اتحاد تحويلات دائم ممكن يشيل الحافز لعمل إصلاحات هيكلية محلية ضرورية. وبالمقابل، الدول الطرفية عم تقول إنه الإطار الحالي عم يدعم وبشكل ممنهج الاقتصادات الأساسية القائمة ع التصدير، وهاد الشي عم يزيد من عدم التوازن الهيكلي بكل السوق المشتركة. وهاد النقاش السياسي المستمر عم يوضح التوتر الأساسي بين السيادة الوطنية والحوكمة الاقتصادية العابرة للدول، وعم يفرجينا إنه نجاة اتحاد العملة بيمشي بالنهاية على وجود إجماع سياسي بيتخطى الحسابات الانتخابية المحلية الضيقة.", "title_ar": "الهيكل المالي لمنطقة اليورو", "questions": [{"id": "q1", "stem": "Why do structurally wealthier Eurozone nations often resist a permanent fiscal transfer union?", "choices": ["They worry it creates a moral hazard that would discourage weaker economies from pursuing necessary structural reforms.", "They fear that joint debt instruments would entirely eliminate domestic interest rates across the continent.", "They contend that internal deflation is the only viable method to expand public welfare systems.", "They anticipate that permanent common budgets would automatically devalue the unified currency."], "correct_index": 0}], "passage_ar": "التصميم الهيكلي لمنطقة اليورو بيمثل وحدة من أجرأ التجارب بتاريخ الاقتصاد الكلي الحديث، ومع هيك لساته مشلول ومقيد من الجذور بسبب عدم التوازن بالبنية: يعني عم يطبقوا سياسة نقدية موحدة من دون ما يكون في توحيد مالي حقيقي بيقابلها. ولما الدول ذات السيادة تتنازل عن التحكم بأدواتها النقدية المحلية—وخصوصي القدرة على التلاعب بأسعار الفائدة أو تخفيض قيمة عملتها لتمتص الهزات الاقتصادية—بتصير ضعيفة ومعرضة كتير للأزمات الاقتصادية غير المتماثلة. وبظل غياب وزارة مالية مركزية لمنطقة اليورو قادرة تنفذ تحويلات بالميزانية لمواجهة التقلبات، الدول الأعضاء يلي عم تعاني بتنجبر تعتمد بشكل شبه كامل على الانكماش الداخلي وسياسات التقشف المالي الناشفة لترجع تكسب قدرتها على المنافسة الدولية. وهي الحركية الهيكلية كتير أوقات عم تشعل أزمات اقتصادية واجتماعية خطيرة، لأنه حمل وعواقب هاد التعديل عم يوقع بشكل غير عادل على البنية التحتية العامة، وأنظمة الرفاه الاجتماعي، ومعدلات الشغل. خبراء الاقتصاد صر لهم زمان عم يقولوا إنه الاتحاد النقدي ما فيه يوصل لاستقرار وتوازن على المدى الطويل بلا وجود آلية قوية لمشاركة المخاطر المالية، متل ميزانية مشتركة دائمة أو إصدار أدوات ديون سيادية مشتركة. بس هاد الطريق نحو اندماج مالي أعمق عليه خلافات كبيرة كتير بين الناخبين بكل بلد، وهاد الشي عم يقسم القارة على طول خطوط الصدع الجيوسياسية والأيديولوجية. الدول الأعضاء الأغنى عم تبدي دايماً مخاوف عميقة من الخطر الأخلاقي الكامن وراء دعم الاقتصادات الأضعف هيكلياً، كرمال خايفين إنه وجود اتحاد تحويلات دائم ممكن يشيل الحافز لعمل إصلاحات هيكلية محلية ضرورية. وبالمقابل، الدول الطرفية عم تقول إنه الإطار الحالي عم يدعم وبشكل ممنهج الاقتصادات الأساسية القائمة ع التصدير، وهاد الشي عم يزيد من عدم التوازن الهيكلي بكل السوق المشتركة. وهاد النقاش السياسي المستمر عم يوضح التوتر الأساسي بين السيادة الوطنية والحوكمة الاقتصادية العابرة للدول، وعم يفرجينا إنه نجاة اتحاد العملة بيمشي بالنهاية على وجود إجماع سياسي بيتخطى الحسابات الانتخابية المحلية الضيقة.", "vocabulary": ["hamstrung", "asymmetry", "relinquish", "austerity", "disincentivize"]}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (143, 1, 'reading', 'B1', 'lesson', 'Traveling by ICE Train', '{"text": "Last month, I decided to take a trip to Paris using the high-speed ICE train. I had never traveled on such a fast train before, so I was looking forward to the journey. I booked my ticket online two weeks in advance to get a cheaper price. If I had waited until the last minute, it would have cost twice as much. The train was incredibly modern, offering free Wi-Fi and comfortable seats with plenty of legroom. During the journey, the conductor checked my digital ticket on my smartphone. I also visited the onboard bistro to buy a warm cheese sandwich and some coffee. The train traveled at over three hundred kilometers per hour, but the ride was so smooth that I could easily read my book. We arrived at the central station in Paris exactly on schedule. I have already recommended this train journey to all my friends who want to explore Europe comfortably without flying.", "topic": "travel", "passage": "Last month, I decided to take a trip to Paris using the high-speed ICE train. I had never traveled on such a fast train before, so I was looking forward to the journey. I booked my ticket online two weeks in advance to get a cheaper price. If I had waited until the last minute, it would have cost twice as much. The train was incredibly modern, offering free Wi-Fi and comfortable seats with plenty of legroom. During the journey, the conductor checked my digital ticket on my smartphone. I also visited the onboard bistro to buy a warm cheese sandwich and some coffee. The train traveled at over three hundred kilometers per hour, but the ride was so smooth that I could easily read my book. We arrived at the central station in Paris exactly on schedule. I have already recommended this train journey to all my friends who want to explore Europe comfortably without flying.", "text_ar": "الشهر الماضي، قررت أعمل رحلة لباريس باستعمال قطار السريع الـ ICE. ما كنت مسافر بقطار سريع هيك من قبل، كرمال هيك كنت كتير متحمس للرحلة. حجزت التكت تبعي أونلاين قبل بأسبوعين لتطلع أرخص. لو استنيت لآخر دقيقة، كانت كلفتني الضعف. القطار كان حديث بشكل بياخد العقل، وفيه واي فاي ببلاش وكراسي مريحة وفيها مساحة واسعة للرجلين. خلال الرحلة، الكونترولية فحص التكت الديجيتال تبعي ع الموبايل. وكمان رحت ع البوفيه يلي بالقطار لأشتري سندويشة جبنة سخنة وشوية قهوة. القطار كان عم يمشي بسرعة أكتر من تلتماية كيلومتر بالساعة، بس المشية كانت ناعمة لدرجة إنه قدرت اقرأ كتابي بكل سهولة. وصلنا عالمحطة المركزية بباريس عالموعد تماماً. أنا أصلاً نصحت كل رفقاتي بهي الرحلة بالقطار يلي حابين يكتشفوا أوروبا براحة ومن دون طيران.", "title_ar": "السفر بقطار الـ ICE", "questions": [{"id": "q1", "stem": "Why did the writer book the ICE train ticket two weeks early?", "choices": ["To get free Wi-Fi", "Because the train was full", "To get a cheaper price", "To visit the onboard bistro"], "correct_index": 2}], "passage_ar": "الشهر الماضي، قررت أعمل رحلة لباريس باستعمال قطار السريع الـ ICE. ما كنت مسافر بقطار سريع هيك من قبل، كرمال هيك كنت كتير متحمس للرحلة. حجزت التكت تبعي أونلاين قبل بأسبوعين لتطلع أرخص. لو استنيت لآخر دقيقة، كانت كلفتني الضعف. القطار كان حديث بشكل بياخد العقل، وفيه واي فاي ببلاش وكراسي مريحة وفيها مساحة واسعة للرجلين. خلال الرحلة، الكونترولية فحص التكت الديجيتال تبعي ع الموبايل. وكمان رحت ع البوفيه يلي بالقطار لأشتري سندويشة جبنة سخنة وشوية قهوة. القطار كان عم يمشي بسرعة أكتر من تلتماية كيلومتر بالساعة، بس المشية كانت ناعمة لدرجة إنه قدرت اقرأ كتابي بكل سهولة. وصلنا عالمحطة المركزية بباريس عالموعد تماماً. أنا أصلاً نصحت كل رفقاتي بهي الرحلة بالقطار يلي حابين يكتشفوا أوروبا براحة ومن دون طيران.", "vocabulary": ["high-speed", "booked", "conductor", "smooth", "schedule"]}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (144, 1, 'reading', 'B1', 'lesson', 'Navigating German Healthcare', '{"text": "In Germany, having health insurance is mandatory for everyone, including international students. I have been registered with a public health insurance company since I arrived. Last week, I developed a severe toothache that kept me awake all night. I knew I had to see a dentist immediately. If I did not have my insurance card, the dental treatment would be extremely expensive. I called a local clinic, and they managed to give me an emergency appointment for the same afternoon. When I arrived, the receptionist asked for my health card and asked me to fill out a medical questionnaire. The dentist discovered that I had a small cavity that needed a filling. The procedure was completely painless because she used an injection to numb the area. She advised me that I should avoid eating sugary foods and brush my teeth twice a day. I am very grateful that the insurance covered the whole cost, so I did not have to pay anything.", "topic": "health", "passage": "In Germany, having health insurance is mandatory for everyone, including international students. I have been registered with a public health insurance company since I arrived. Last week, I developed a severe toothache that kept me awake all night. I knew I had to see a dentist immediately. If I did not have my insurance card, the dental treatment would be extremely expensive. I called a local clinic, and they managed to give me an emergency appointment for the same afternoon. When I arrived, the receptionist asked for my health card and asked me to fill out a medical questionnaire. The dentist discovered that I had a small cavity that needed a filling. The procedure was completely painless because she used an injection to numb the area. She advised me that I should avoid eating sugary foods and brush my teeth twice a day. I am very grateful that the insurance covered the whole cost, so I did not have to pay anything.", "text_ar": "بألمانيا، التأمين الصحي إجباري للكل، حتى للطلاب الأجانب. أنا مسجل بشركة تأمين صحي حكومية من وقت ما وصلت. الأسبوع الماضي، جاني وجع سنين قوي خلاني سهران طول الليل. عرفت إنه لازم شوف دكتور سنان فوراً. إذا ما كان عندي كرت التأمين، كان علاج السنان رح يطلع غالي كتير. اتصلت بعيادة محلية، وقدروا يعطوني موعد إسعافي بنفس اليوم بعد الظهر. لما وصلت، موظفة الاستقبال طلبت كرت الصحة تبعي وطلبت مني عبي استبيان طبي. الدكتورة شافت إنه عندي سوسة صغيرة وبدا حشوة. العملية كانت بلا وجع بنوب لأنها استعملت إبرة تخدير للمنطقة. نصحتني إنه لازم اتجنب الأكل يلي فيه سكر وفري سناني مرتين باليوم. كتير ممنون إنه التأمين غطى كل التكلفة، كرمال هيك ما اضطريت ادفع ولا فرنك.", "title_ar": "فهم نظام الرعاية الصحية بألمانيا", "questions": [{"id": "q1", "stem": "Why was the dentist procedure completely painless?", "choices": ["Because it was a small cavity", "Because the writer avoided sugary foods", "Because the health insurance card covered it", "Because she used an injection to numb the area"], "correct_index": 3}], "passage_ar": "بألمانيا، التأمين الصحي إجباري للكل، حتى للطلاب الأجانب. أنا مسجل بشركة تأمين صحي حكومية من وقت ما وصلت. الأسبوع الماضي، جاني وجع سنين قوي خلاني سهران طول الليل. عرفت إنه لازم شوف دكتور سنان فوراً. إذا ما كان عندي كرت التأمين، كان علاج السنان رح يطلع غالي كتير. اتصلت بعيادة محلية، وقدروا يعطوني موعد إسعافي بنفس اليوم بعد الظهر. لما وصلت، موظفة الاستقبال طلبت كرت الصحة تبعي وطلبت مني عبي استبيان طبي. الدكتورة شافت إنه عندي سوسة صغيرة وبدا حشوة. العملية كانت بلا وجع بنوب لأنها استعملت إبرة تخدير للمنطقة. نصحتني إنه لازم اتجنب الأكل يلي فيه سكر وفري سناني مرتين باليوم. كتير ممنون إنه التأمين غطى كل التكلفة، كرمال هيك ما اضطريت ادفع ولا فرنك.", "vocabulary": ["mandatory", "severe", "dentist", "cavity", "grateful"]}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (145, 1, 'reading', 'B1', 'lesson', 'Finding a Flat Online', '{"text": "Finding a shared apartment, or what Germans call a ''WG'', can be quite difficult in big cities like Munich. I have been searching for a suitable room online for over a month using a popular website. If you want to find a good place, you must write a personalized message to the current flatmates. Many students just copy and paste the same text, which makes a bad impression. Yesterday, I received a positive reply from a flatmate group who invited me for an online interview via video call. They wanted to know about my lifestyle, hobbies, and whether I prefer a quiet environment. If they choose me, I would move in at the beginning of next month. The apartment has modern technology, including high-speed internet and a smart washing machine. I told them that I am a tidy person who respects house rules. I really hope they select me because the location is perfect and the rent is quite reasonable.", "topic": "technology", "passage": "Finding a shared apartment, or what Germans call a ''WG'', can be quite difficult in big cities like Munich. I have been searching for a suitable room online for over a month using a popular website. If you want to find a good place, you must write a personalized message to the current flatmates. Many students just copy and paste the same text, which makes a bad impression. Yesterday, I received a positive reply from a flatmate group who invited me for an online interview via video call. They wanted to know about my lifestyle, hobbies, and whether I prefer a quiet environment. If they choose me, I would move in at the beginning of next month. The apartment has modern technology, including high-speed internet and a smart washing machine. I told them that I am a tidy person who respects house rules. I really hope they select me because the location is perfect and the rent is quite reasonable.", "text_ar": "تلاقى شقة مشتركة، أو يلي الألمان بيسموها ''في غيه'' (WG)، ممكن يكون صعب كتير بالمدن الكبيرة متل ميونيخ. صرلي عم دور على غرفة مناسبة أونلاين أكتر من شهر باستعمال موقع مشهور. إذا بدك تلاقي مكان منيح، لازم تكتب رسالة مخصصة لشركاء السكن الحاليين. طلاب كتار بس بيعملوا نسخ ولصق لنفس النص، وهاد الشي بيعطي انطباع سيء. مبارح، جاني رد إيجابي من مجموعة شباب بالسكن وعزموني على مقابلة أونلاين مكالمة فيديو. كان بدهم يعرفوا عن نمط حياتي، هواياتي، وإذا بفضل الأجواء الهادية. إذا اختاروني، رح انقل بأول الشهر الجايه. الشقة فيها تكنولوجيا حديثة، بما فيها إنترنت سريع وغسالة ذكية. قلتلهم إني شخص مرتب وبحترم قواعد البيت. كتير بتمنى يختاروني لأن الموقع بياخد العقل والآجار كتير مقبول.", "title_ar": "تلاقى شقة أونلاين", "questions": [{"id": "q1", "stem": "What mistake do many students make when applying for a room online?", "choices": ["They copy and paste the same message", "They call via video call directly", "They forget to state their hobbies", "They request smart washing machines"], "correct_index": 0}], "passage_ar": "تلاقى شقة مشتركة، أو يلي الألمان بيسموها ''في غيه'' (WG)، ممكن يكون صعب كتير بالمدن الكبيرة متل ميونيخ. صرلي عم دور على غرفة مناسبة أونلاين أكتر من شهر باستعمال موقع مشهور. إذا بدك تلاقي مكان منيح، لازم تكتب رسالة مخصصة لشركاء السكن الحاليين. طلاب كتار بس بيعملوا نسخ ولصق لنفس النص، وهاد الشي بيعطي انطباع سيء. مبارح، جاني رد إيجابي من مجموعة شباب بالسكن وعزموني على مقابلة أونلاين مكالمة فيديو. كان بدهم يعرفوا عن نمط حياتي، هواياتي، وإذا بفضل الأجواء الهادية. إذا اختاروني، رح انقل بأول الشهر الجايه. الشقة فيها تكنولوجيا حديثة، بما فيها إنترنت سريع وغسالة ذكية. قلتلهم إني شخص مرتب وبحترم قواعد البيت. كتير بتمنى يختاروني لأن الموقع بياخد العقل والآجار كتير مقبول.", "vocabulary": ["suitable", "personalized", "impression", "lifestyle", "reasonable"]}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (146, 1, 'reading', 'B1', 'lesson', 'Solving Roommate Conflicts', '{"text": "Living with roommates is a wonderful way to make friends, but it can sometimes lead to minor misunderstandings. In our shared apartment, we have created a cleaning schedule to divide the chores fairly. However, one of my flatmates has recently neglected his duties, leaving dirty dishes in the kitchen sink for days. This situation has caused some tension among us. If we did not address this issue openly, it would create a hostile environment in the house. Therefore, we decided to hold a house meeting yesterday evening to discuss the problem calmly. We explained how a messy kitchen affects everyone''s daily routine. He apologized sincerely and explained that he had been under a lot of stress due to his university exams. We agreed to help him this week, provided that he follows the schedule in the future. Communicating honestly has saved our friendship and helped us maintain a peaceful atmosphere at home.", "topic": "relationships", "passage": "Living with roommates is a wonderful way to make friends, but it can sometimes lead to minor misunderstandings. In our shared apartment, we have created a cleaning schedule to divide the chores fairly. However, one of my flatmates has recently neglected his duties, leaving dirty dishes in the kitchen sink for days. This situation has caused some tension among us. If we did not address this issue openly, it would create a hostile environment in the house. Therefore, we decided to hold a house meeting yesterday evening to discuss the problem calmly. We explained how a messy kitchen affects everyone''s daily routine. He apologized sincerely and explained that he had been under a lot of stress due to his university exams. We agreed to help him this week, provided that he follows the schedule in the future. Communicating honestly has saved our friendship and helped us maintain a peaceful atmosphere at home.", "text_ar": "العيشة مع رفقات سكن هي طريقة بتجنن لتعمل رفقات، بس أوقات ممكن تؤدي لسوء تفاهم بسيط. بشقتنا المشتركة، عملنا جدول تنظيف عشان نقسم الشغل بالعدل. بس، واحد من رفقاتي بالسكن مؤخراً همل واجباته، وترك الصحون الوسخة بالمجلى لأيام. هاد الوضع عمل شوية حزازيات بيناتنا. إذا ما حكينا بهي المشكلة علنّي، كانت رح تعمل أجواء مشحونة بالبيت. كرمال هيك، قررنا نعمل اجتماع بالبيت مبارح المسا لنناقش المشكلة بروقان. شرحنا كيف المطبخ المكركب بيأثر على روتين الكل اليومي. هو اعتذر من قلبو وشرح إنه كان تحت ضغط كبير بسبب امتحانات الجامعة. اتفقنا نساعده هالأسبوع، بشرط إنه يمشي عالجدول بالمستقبل. الحكي بصراحة أنقذ صداقتنا وساعدنا نحافظ على أجواء هادية بالبيت.", "title_ar": "حل المشاكل بين رفقات السكن", "questions": [{"id": "q1", "stem": "Why did one flatmate neglect his cleaning duties?", "choices": ["He wanted to create a hostile environment", "He was under stress due to university exams", "He did not understand the cleaning schedule", "He left the flat to live with other friends"], "correct_index": 1}], "passage_ar": "العيشة مع رفقات سكن هي طريقة بتجنن لتعمل رفقات، بس أوقات ممكن تؤدي لسوء تفاهم بسيط. بشقتنا المشتركة، عملنا جدول تنظيف عشان نقسم الشغل بالعدل. بس، واحد من رفقاتي بالسكن مؤخراً همل واجباته، وترك الصحون الوسخة بالمجلى لأيام. هاد الوضع عمل شوية حزازيات بيناتنا. إذا ما حكينا بهي المشكلة علنّي، كانت رح تعمل أجواء مشحونة بالبيت. كرمال هيك، قررنا نعمل اجتماع بالبيت مبارح المسا لنناقش المشكلة بروقان. شرحنا كيف المطبخ المكركب بيأثر على روتين الكل اليومي. هو اعتذر من قلبو وشرح إنه كان تحت ضغط كبير بسبب امتحانات الجامعة. اتفقنا نساعده هالأسبوع، بشرط إنه يمشي عالجدول بالمستقبل. الحكي بصراحة أنقذ صداقتنا وساعدنا نحافظ على أجواء هادية بالبيت.", "vocabulary": ["misunderstandings", "chores", "neglected", "tension", "hostile"]}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (147, 1, 'reading', 'B1', 'lesson', 'University or Vocational Training', '{"text": "Many young people in Europe face a difficult choice between attending university or starting a vocational training program, known as an ''Ausbildung'' in Germany. I have been studying computer science at a technical university for two semesters. University lectures require a lot of self-discipline, as professors expect you to do extensive research independently. If you prefer practical experience, an Ausbildung might be a better option because it combines classroom learning with actual on-the-job training. In a vocational program, students can earn a monthly salary while learning a specific trade. If I had chosen that path, I would be working in an IT company right now instead of preparing for theoretical exams. However, I enjoy academic research and want to pursue a master''s degree later. Both paths offer excellent career opportunities in the European job market. The decision ultimately depends on your personal learning style and whether you want to focus more on theory or practice.", "topic": "school system", "passage": "Many young people in Europe face a difficult choice between attending university or starting a vocational training program, known as an ''Ausbildung'' in Germany. I have been studying computer science at a technical university for two semesters. University lectures require a lot of self-discipline, as professors expect you to do extensive research independently. If you prefer practical experience, an Ausbildung might be a better option because it combines classroom learning with actual on-the-job training. In a vocational program, students can earn a monthly salary while learning a specific trade. If I had chosen that path, I would be working in an IT company right now instead of preparing for theoretical exams. However, I enjoy academic research and want to pursue a master''s degree later. Both paths offer excellent career opportunities in the European job market. The decision ultimately depends on your personal learning style and whether you want to focus more on theory or practice.", "text_ar": "شباب كتار بأوروبا بيواجهوا خيار صعب بين إنهم يروحوا عالجامعة أو يبلشوا برنامج تدريب مهني، يلي بيسموه بألمانيا ''أوسبيلدونغ''. صرلي عم ادرس هندسة كمبيوتر بجامعة تقنية لفصلين دافورين. المحاضرات بالجامعة بدها التزام ذاتي كبير، لأن الدكاترة بيتوقعوا منك تعمل أبحاث موسعة لحالك. إذا بتفضل الخبرة العملية، الأوسبيلدونغ ممكن يكون خيار أحسن لأنه بيجمع بين الدراسة بالصف والتدريب الحقيقي بالشغل. ببرنامج التدريب المهني، الطلاب بيقدروا يطلعوا راتب شهري وهم عم يتعلموا مصلحة معينة. لو اخترت هاد الطريق، كنت عم اشتغل بشركة تكنولوجيا هلق بدل ما اعد جهز للامتحانات النظرية. بس أنا بحب البحث الأكاديمي وبدي كمل ماستر بعدين. الطريقين بيعطوا فرص عمل بتجنن بسوق الشغل الأوروبي. القرار بالنهاية بيعتمد على طريقة دراستك وإذا بدك تركز ع النظري أو العملي.", "title_ar": "الجامعة أو التدريب المهني", "questions": [{"id": "q1", "stem": "What is an advantage of an ''Ausbildung'' mentioned in the text?", "choices": ["It requires more self-discipline than university", "It focuses purely on theoretical exams", "It allows students to earn a salary while learning", "It guarantees a master''s degree immediately"], "correct_index": 2}], "passage_ar": "شباب كتار بأوروبا بيواجهوا خيار صعب بين إنهم يروحوا عالجامعة أو يبلشوا برنامج تدريب مهني، يلي بيسموه بألمانيا ''أوسبيلدونغ''. صرلي عم ادرس هندسة كمبيوتر بجامعة تقنية لفصلين دافورين. المحاضرات بالجامعة بدها التزام ذاتي كبير، لأن الدكاترة بيتوقعوا منك تعمل أبحاث موسعة لحالك. إذا بتفضل الخبرة العملية، الأوسبيلدونغ ممكن يكون خيار أحسن لأنه بيجمع بين الدراسة بالصف والتدريب الحقيقي بالشغل. ببرنامج التدريب المهني، الطلاب بيقدروا يطلعوا راتب شهري وهم عم يتعلموا مصلحة معينة. لو اخترت هاد الطريق، كنت عم اشتغل بشركة تكنولوجيا هلق بدل ما اعد جهز للامتحانات النظرية. بس أنا بحب البحث الأكاديمي وبدي كمل ماستر بعدين. الطريقين بيعطوا فرص عمل بتجنن بسوق الشغل الأوروبي. القرار بالنهاية بيعتمد على طريقة دراستك وإذا بدك تركز ع النظري أو العملي.", "vocabulary": ["vocational", "semesters", "self-discipline", "theoretical", "career"]}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (148, 1, 'reading', 'B1', 'lesson', 'A Visit to the Immigration Office', '{"text": "Dealing with bureaucracy can be one of the most stressful parts of living abroad. Last month, I realized that my student visa was expiring soon, so I had to book an appointment with the immigration office, or ''Ausländerbehörde''. I have already gathered all the necessary documents, such as my university enrollment certificate, health insurance confirmation, and proof of sufficient funds in my blocked bank account. If any of these documents were missing, the officer would reject my application immediately. The appointment was scheduled for early yesterday morning. I was quite anxious while waiting in the corridor. When my number was called, the officer reviewed my paperwork carefully. She asked me a few questions about my studies and how long I intend to stay. Fortunately, everything was in perfect order. She told me that my new residence permit would be ready in six weeks. I felt an immense sense of relief after leaving the building.", "topic": "bureaucracy", "passage": "Dealing with bureaucracy can be one of the most stressful parts of living abroad. Last month, I realized that my student visa was expiring soon, so I had to book an appointment with the immigration office, or ''Ausländerbehörde''. I have already gathered all the necessary documents, such as my university enrollment certificate, health insurance confirmation, and proof of sufficient funds in my blocked bank account. If any of these documents were missing, the officer would reject my application immediately. The appointment was scheduled for early yesterday morning. I was quite anxious while waiting in the corridor. When my number was called, the officer reviewed my paperwork carefully. She asked me a few questions about my studies and how long I intend to stay. Fortunately, everything was in perfect order. She told me that my new residence permit would be ready in six weeks. I felt an immense sense of relief after leaving the building.", "text_ar": "التعامل مع المعاملات الرسمية ممكن يكون من أكتر الشغلات يلي بتبكك بالعيشة برا. الشهر الماضي، انتبهت إنه فيزا الطالب تبعي رح تخلص ومدتها قريبة، كرمال هيك كان لازم احجز موعد بمكتب الإقامة، أو ''الأوسلندريهوردي''. أنا أصلاً جمعت كل الأوراق المطلوبة، متل شهادة التسجيل بالجامعة، تأكيد التأمين الصحي، وإثبات وجود مصاري كافية بحسابي البنكي المقفل. لو كانت أي ورقة من هدول ناقصة، الموظفة كانت رح ترفض الطلب تبعي فوراً. الموعد كان مأصل الصبح بكير مبارح. كنت كتير متوتر وأنا عم استنى بالممر. لما نادوا رقمي، الموظفة دققت بأوراقي بكل عناية. سألتني كم سؤال عن دراستي وقديش ناوي اتم هون. لحسن الحظ، كل شي كان تمام التمام. قالتلي إنه إقامتي الجديدة رح تكون جاهزة خلال ست أسابيع. حسيت براحة بتبكي بعد ما طلعت من البناية.", "title_ar": "زيارة لمكتب الإقامة", "questions": [{"id": "q1", "stem": "How long will it take for the new residence permit to be ready?", "choices": ["Immediately", "Yesterday morning", "One month", "Six weeks"], "correct_index": 3}], "passage_ar": "التعامل مع المعاملات الرسمية ممكن يكون من أكتر الشغلات يلي بتبكك بالعيشة برا. الشهر الماضي، انتبهت إنه فيزا الطالب تبعي رح تخلص ومدتها قريبة، كرمال هيك كان لازم احجز موعد بمكتب الإقامة، أو ''الأوسلندريهوردي''. أنا أصلاً جمعت كل الأوراق المطلوبة، متل شهادة التسجيل بالجامعة، تأكيد التأمين الصحي، وإثبات وجود مصاري كافية بحسابي البنكي المقفل. لو كانت أي ورقة من هدول ناقصة، الموظفة كانت رح ترفض الطلب تبعي فوراً. الموعد كان مأصل الصبح بكير مبارح. كنت كتير متوتر وأنا عم استنى بالممر. لما نادوا رقمي، الموظفة دققت بأوراقي بكل عناية. سألتني كم سؤال عن دراستي وقديش ناوي اتم هون. لحسن الحظ، كل شي كان تمام التمام. قالتلي إنه إقامتي الجديدة رح تكون جاهزة خلال ست أسابيع. حسيت براحة بتبكي بعد ما طلعت من البناية.", "vocabulary": ["bureaucracy", "expiring", "enrollment", "anxious", "relief"]}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (149, 1, 'reading', 'B1', 'lesson', 'Punctuality and Quiet Hours', '{"text": "Understanding cultural differences is essential for a smooth integration into any new society. When I first arrived in Germany, I had to learn about specific social rules that are highly respected here. For instance, punctuality is extremely important; if you have an appointment at three o''clock, you should arrive five minutes early. If you are going to be late, you must call and inform the person beforehand. Another important concept is ''Ruhezeit'', which means quiet hours. On Sundays and every evening after ten o''clock, people are expected to keep noise to a minimum. This means you cannot vacuum your flat or play loud music. If you make too much noise, your neighbors have the right to complain. At first, these rules seemed a bit strict to me compared to life back home. However, I have noticed that they help create a peaceful and organized environment where everyone respects each other''s privacy.", "topic": "cultural differences", "passage": "Understanding cultural differences is essential for a smooth integration into any new society. When I first arrived in Germany, I had to learn about specific social rules that are highly respected here. For instance, punctuality is extremely important; if you have an appointment at three o''clock, you should arrive five minutes early. If you are going to be late, you must call and inform the person beforehand. Another important concept is ''Ruhezeit'', which means quiet hours. On Sundays and every evening after ten o''clock, people are expected to keep noise to a minimum. This means you cannot vacuum your flat or play loud music. If you make too much noise, your neighbors have the right to complain. At first, these rules seemed a bit strict to me compared to life back home. However, I have noticed that they help create a peaceful and organized environment where everyone respects each other''s privacy.", "text_ar": "فهم الفروقات الثقافية أساسي عشان تتأقلم بسلاسة بأي مجتمع جديد. أول ما وصلت ع ألمانيا، كان لازم اتعلم قواعد اجتماعية معينة ومحترمة كتير هون. مثلاً, الالتزام بالوقت مهم بشكل بيموّت؛ إذا عندك موعد الساعة تلاتة، لازم توصل قبل بخمس دقائق. إذا رح تتأخر، لازم تتصل وتخبر الشخص قبل بوقت. في مفهوم تاني مهم وهو ''الروهيتسايت'' (Ruhezeit)، يعني وقت الهدوء. يوم الأحد وكل يوم المسا بعد الساعة عشرة، متوقع من الناس يخلوا الصوت واطي ع الآخر. هاد بيعني ما فيك تشغل مكنسة الكهربا بشقتك أو تشغل أغاني عالية. إذا عملت ضجة زيادة، جيرانك من حقهم يشتكوا. بالبدايه، هي القواعد حسيتها ناشفة شوي مقارنة بالحياة ببلدنا. بس لاحظت إنها بتساعد بعمل بيئة هادية ومنظمة ومحترمة لخصوصية الكل.", "title_ar": "الالتزام بالوقت وأوقات الهدوء", "questions": [{"id": "q1", "stem": "What does the concept of ''Ruhezeit'' mean for residents?", "choices": ["They are expected to keep noise to a minimum during specific hours", "They must vacuum their flats on Sundays", "They must arrive five minutes early to appointments", "They have the right to play loud music after ten o''clock"], "correct_index": 0}], "passage_ar": "فهم الفروقات الثقافية أساسي عشان تتأقلم بسلاسة بأي مجتمع جديد. أول ما وصلت ع ألمانيا، كان لازم اتعلم قواعد اجتماعية معينة ومحترمة كتير هون. مثلاً, الالتزام بالوقت مهم بشكل بيموّت؛ إذا عندك موعد الساعة تلاتة، لازم توصل قبل بخمس دقائق. إذا رح تتأخر، لازم تتصل وتخبر الشخص قبل بوقت. في مفهوم تاني مهم وهو ''الروهيتسايت'' (Ruhezeit)، يعني وقت الهدوء. يوم الأحد وكل يوم المسا بعد الساعة عشرة، متوقع من الناس يخلوا الصوت واطي ع الآخر. هاد بيعني ما فيك تشغل مكنسة الكهربا بشقتك أو تشغل أغاني عالية. إذا عملت ضجة زيادة، جيرانك من حقهم يشتكوا. بالبدايه، هي القواعد حسيتها ناشفة شوي مقارنة بالحياة ببلدنا. بس لاحظت إنها بتساعد بعمل بيئة هادية ومنظمة ومحترمة لخصوصية الكل.", "vocabulary": ["integration", "punctuality", "beforehand", "minimum", "privacy"]}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (150, 1, 'reading', 'B1', 'lesson', 'The Local Public Library', '{"text": "The local public library has become one of my favorite places in the city since I moved here. It is located in a beautiful historical building near the city center. I have recently registered for a membership card, which costs only ten euros per year for students. If you have a card, you can borrow books, movies, and even laptop computers for free. The library has multiple floors with quiet study areas, comfortable armchairs, and fast internet access. I usually go there three times a week to study for my exams and read English novels. If I need a specific book that is not available, the staff can order it from another city branch. I find it much easier to concentrate there than in my noisy shared apartment. It is also a great place to meet other students and participate in cultural events or language exchange groups that are organized regularly.", "topic": "daily city life", "passage": "The local public library has become one of my favorite places in the city since I moved here. It is located in a beautiful historical building near the city center. I have recently registered for a membership card, which costs only ten euros per year for students. If you have a card, you can borrow books, movies, and even laptop computers for free. The library has multiple floors with quiet study areas, comfortable armchairs, and fast internet access. I usually go there three times a week to study for my exams and read English novels. If I need a specific book that is not available, the staff can order it from another city branch. I find it much easier to concentrate there than in my noisy shared apartment. It is also a great place to meet other students and participate in cultural events or language exchange groups that are organized regularly.", "text_ar": "المكتبة العامة المحلية صارت من أكتر الأماكن المفضلة عندي بالمدينة من وقت ما نقلت لهون. هي موجودة ببناية تاريخية بتجنن قريب من مركز المدينة. مؤخراً سجلت عشان أعمل كرت عضوية، يلي بيكلف بس عشرة يورو بالسنة للطلاب. إذا عندك الكرت، فيك تستعير كتب، وأفلام، وحتى كمبيوترات لابتوب ببلاش. المكتبة فيها كذا طابق وفيها مناطق دراسة هادية، وكراسي مريحة، وإنترنت سريع. أنا بالعادي بروح لهنيك تلات مرات بالأسبوع لأدرس لامتحاناتي واقرأ روايات إنكليزي. إذا بدي كتاب معين ومو موجود، الموظفين فيهم يطلبوه من فرع تاني بالمدينة. بلاقي الدراسة هنيك أسهل بكثير من التركيز بشقتي المشتركة يلي فيها عجقة وصوت. وكمان هي مكان كتير حلو لتلتقي بطلاب تانيين وتشارك بفعاليات ثقافية أو مجموعات تبادل لغات يلي بتتنظم كل فترة.", "title_ar": "المكتبة العامة المحلية", "questions": [{"id": "q1", "stem": "How much does a library membership card cost per year for students?", "choices": ["It is completely free", "Ten euros", "Three euros", "Forty euros"], "correct_index": 1}], "passage_ar": "المكتبة العامة المحلية صارت من أكتر الأماكن المفضلة عندي بالمدينة من وقت ما نقلت لهون. هي موجودة ببناية تاريخية بتجنن قريب من مركز المدينة. مؤخراً سجلت عشان أعمل كرت عضوية، يلي بيكلف بس عشرة يورو بالسنة للطلاب. إذا عندك الكرت، فيك تستعير كتب، وأفلام، وحتى كمبيوترات لابتوب ببلاش. المكتبة فيها كذا طابق وفيها مناطق دراسة هادية، وكراسي مريحة، وإنترنت سريع. أنا بالعادي بروح لهنيك تلات مرات بالأسبوع لأدرس لامتحاناتي واقرأ روايات إنكليزي. إذا بدي كتاب معين ومو موجود، الموظفين فيهم يطلبوه من فرع تاني بالمدينة. بلاقي الدراسة هنيك أسهل بكثير من التركيز بشقتي المشتركة يلي فيها عجقة وصوت. وكمان هي مكان كتير حلو لتلتقي بطلاب تانيين وتشارك بفعاليات ثقافية أو مجموعات تبادل لغات يلي بتتنظم كل فترة.", "vocabulary": ["historical", "borrow", "multiple", "concentrate", "participate"]}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (151, 1, 'reading', 'B2', 'lesson', 'Integrating into the Professional Sphere', '{"text": "The professional integration of international graduates into the European labor market has become a pivotal topic for both economic stability and cultural diversity. While many corporate sectors report critical shortages of skilled labor, highly qualified individuals from non-European countries frequently encounter substantial hurdles during their initial job search. It is often argued by economists that unrecognized academic qualifications and bureaucratic delays constitute the primary barriers to successful workforce placement. To mitigate this pressing issue, specialized mentoring programs have been introduced across various federal states. These initiatives, which are typically funded by regional chambers of commerce, aim to connect skilled candidates with potential employers through targeted networking events. Furthermore, recent adjustments to immigration policies have been implemented, which are expected to facilitate a more streamlined path toward acquiring professional residence permits. If these legislative changes had been adopted a decade ago, the current economic bottleneck might have been partially averted. Nonetheless, international candidates are still strongly encouraged to attain advanced language proficiencies, as daily corporate communication remains predominantly localized. Ultimately, bridging the gap between global talent and systemic demand requires a concerted, long-term effort from corporate leaders and administrative bodies alike.", "topic": "career", "passage": "The professional integration of international graduates into the European labor market has become a pivotal topic for both economic stability and cultural diversity. While many corporate sectors report critical shortages of skilled labor, highly qualified individuals from non-European countries frequently encounter substantial hurdles during their initial job search. It is often argued by economists that unrecognized academic qualifications and bureaucratic delays constitute the primary barriers to successful workforce placement. To mitigate this pressing issue, specialized mentoring programs have been introduced across various federal states. These initiatives, which are typically funded by regional chambers of commerce, aim to connect skilled candidates with potential employers through targeted networking events. Furthermore, recent adjustments to immigration policies have been implemented, which are expected to facilitate a more streamlined path toward acquiring professional residence permits. If these legislative changes had been adopted a decade ago, the current economic bottleneck might have been partially averted. Nonetheless, international candidates are still strongly encouraged to attain advanced language proficiencies, as daily corporate communication remains predominantly localized. Ultimately, bridging the gap between global talent and systemic demand requires a concerted, long-term effort from corporate leaders and administrative bodies alike.", "text_ar": "الاندماج المهني للخريجين الأجانب بسوق الشغل الأوروبي صار موضوع أساسي ومحوري لضمان الاستقرار الاقتصادي والتنوع الثقافي سوا. ومع إنه في قطاعات شركات كتيرة عم تشكي من نقص حاد بالأيدي العاملة الماهرة، بس الأفراد المؤهلين بشكل عالي من دول برا أوروبا عم يواجهوا دايماً عقبات كبيرة بأول رحلة تدوير إلهم على شغل. خبراء الاقتصاد عم يقولوا دايماً إنه الشهادات الأكاديمية يلي مو معترف عليها والتأخير بالمعاملات الرسمية هنن العائق الأساسي بوش التوظيف الناجح. وعشان يخففوا من هي المشكلة المستعجلة، بلشوا يطرحوا برامج توجيهية متخصصة بكذا ولاية. هي المبادرات، يلي بالعادي بتمولها غرف التجارة الإقليمية، بتهدف لتوصيل المرشحين المهرة مع أصحاب الشغل المحتملين من خلال فعاليات تعارف وتشبيك مدروسة. وكمان هلق، صار في تعديلات جديدة بقوانين الهجرة بلشوا يطبقوها، ومتوقع منها تسهل طريق أسرع وأوضح ليحصل الواحد على إقامات عمل مهنية. لو هي التغييرات التشريعية اعتمدوها من شي عشر سنين، كان يمكن أزمة النقص الاقتصادي الحالية تخف شوي. ومع هيك، لساتهم عم ينصحوا المرشحين الأجانب بقوة إنهم يوصلوا لمستويات متقدمة باللغة، لأنه التواصل اليومي بالشركات لساته عم يعتمد بشكل أساسي على اللغة المحلية. بالنهاية، تكسير الفجوة بين المواهب العالمية ومتطلبات النظام بدها جهد مشترك وطويل الأمد من مدراء الشركات والدوائر الإدارية على حد سواء.", "title_ar": "الاندماج بالمجال المهني", "questions": [{"id": "q1", "stem": "According to the text, what do economists identify as a primary barrier to employment for international graduates?", "choices": ["Unrecognized qualifications and bureaucratic delays", "A lack of interest from regional chambers of commerce", "The rapid shift toward automated corporate communication", "An oversupply of skilled domestic labor"], "correct_index": 0}], "passage_ar": "الاندماج المهني للخريجين الأجانب بسوق الشغل الأوروبي صار موضوع أساسي ومحوري لضمان الاستقرار الاقتصادي والتنوع الثقافي سوا. ومع إنه في قطاعات شركات كتيرة عم تشكي من نقص حاد بالأيدي العاملة الماهرة، بس الأفراد المؤهلين بشكل عالي من دول برا أوروبا عم يواجهوا دايماً عقبات كبيرة بأول رحلة تدوير إلهم على شغل. خبراء الاقتصاد عم يقولوا دايماً إنه الشهادات الأكاديمية يلي مو معترف عليها والتأخير بالمعاملات الرسمية هنن العائق الأساسي بوش التوظيف الناجح. وعشان يخففوا من هي المشكلة المستعجلة، بلشوا يطرحوا برامج توجيهية متخصصة بكذا ولاية. هي المبادرات، يلي بالعادي بتمولها غرف التجارة الإقليمية، بتهدف لتوصيل المرشحين المهرة مع أصحاب الشغل المحتملين من خلال فعاليات تعارف وتشبيك مدروسة. وكمان هلق، صار في تعديلات جديدة بقوانين الهجرة بلشوا يطبقوها، ومتوقع منها تسهل طريق أسرع وأوضح ليحصل الواحد على إقامات عمل مهنية. لو هي التغييرات التشريعية اعتمدوها من شي عشر سنين، كان يمكن أزمة النقص الاقتصادي الحالية تخف شوي. ومع هيك، لساتهم عم ينصحوا المرشحين الأجانب بقوة إنهم يوصلوا لمستويات متقدمة باللغة، لأنه التواصل اليومي بالشركات لساته عم يعتمد بشكل أساسي على اللغة المحلية. بالنهاية، تكسير الفجوة بين المواهب العالمية ومتطلبات النظام بدها جهد مشترك وطويل الأمد من مدراء الشركات والدوائر الإدارية على حد سواء.", "vocabulary": ["integration", "hurdles", "mitigate", "streamlined", "bottleneck"]}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (152, 1, 'reading', 'B2', 'lesson', 'The Evolution of Sustainable Urban Mobility', '{"text": "In recent years, major European metropolitan areas have undergone a significant transformation regarding their public transport infrastructure. In response to mounting environmental concerns and severe traffic congestion, city planners have prioritized sustainable urban mobility over traditional automobile dependency. Comprehensive networks of bicycle lanes have been constructed, and subsidized transit tickets have been introduced to incentivize residents to utilize trains and buses. Consequently, private car ownership in urban centers has gradually declined as commuting via public networks is increasingly perceived as a more efficient alternative. However, this transition has not been entirely seamless, as local municipalities frequently face budget deficits while upgrading ancient subway systems. It has been reported that infrastructure extensions often experience delays due to rigid environmental regulations and rigorous safety assessments. Had municipal councils allocated more substantial resources to technological innovation earlier, the integration of autonomous electric shuttles could have been completed by now. As urban populations continue to expand, the long-term viability of these cities will depend heavily on the continuous optimization of public transit schedules and the expansion of zero-emission zones.", "topic": "public transport", "passage": "In recent years, major European metropolitan areas have undergone a significant transformation regarding their public transport infrastructure. In response to mounting environmental concerns and severe traffic congestion, city planners have prioritized sustainable urban mobility over traditional automobile dependency. Comprehensive networks of bicycle lanes have been constructed, and subsidized transit tickets have been introduced to incentivize residents to utilize trains and buses. Consequently, private car ownership in urban centers has gradually declined as commuting via public networks is increasingly perceived as a more efficient alternative. However, this transition has not been entirely seamless, as local municipalities frequently face budget deficits while upgrading ancient subway systems. It has been reported that infrastructure extensions often experience delays due to rigid environmental regulations and rigorous safety assessments. Had municipal councils allocated more substantial resources to technological innovation earlier, the integration of autonomous electric shuttles could have been completed by now. As urban populations continue to expand, the long-term viability of these cities will depend heavily on the continuous optimization of public transit schedules and the expansion of zero-emission zones.", "text_ar": "بالسنين الأخيرة، شهدت المناطق الحضرية الكبيرة بأوروبا تحول كتير كبير ببنيتها التحتية للمواصلات العامة. وكتعويض عن المخاوف البيئية يلي عم تزيد وعجقات السير الخانقة، حطوا مخططي المدن الأولوية لوسائل النقل الحضري المستدام على حساب الاعتماد التقليدي على السيارات الخاصة. تم بناء شبكات شاملة لمسارات البسكليتات، وطرحوا تكتات مدعومة للمواصلات عشان يشجعوا السكان يستخدموا القطارات والباصات. وبناءً على هاد الشي، ملكية السيارات الخاصة بمركز المدن عم تنزل شوي شوي كرمال المشاوير عبر شبكات النقل العامة صارت تنشاف أكتر كبديل فعال وعملي. بس هاد التحول ما كان خالي من المشاكل بنوب، لأنه البلديات المحلية عم تواجه دايماً عجز بالميزانية وهي عم تحدث أنظمة المترو القديمة كتير. وطلعت تقارير عم تقول إنه توسيع البنية التحتية عم يتعرض لتأخيرات بسبب القوانين البيئية الناشفة وتدقيق إجراءات السلامة الصارمة. لو مجالس البلديات خصصت موارد أكبر للابتكار التكنولوجي من قبل، كان ممكن دمج باصات النقل الكهربائية ذاتية القيادة يخلص هلق. ومع استمرار التوسع السكاني بالمدن، رح يعتمد نجاح هي المدن على المدى الطويل بشكل كبير على التحديث المستمر لمواعيد النقل العام وتوسيع مناطق خالية من الانبعاثات.", "title_ar": "تطور وسائل النقل الحضري المستدام", "questions": [{"id": "q1", "stem": "What is mentioned as a major cause for delays in extending transit infrastructure?", "choices": ["A total lack of interest from the urban population", "Rigid environmental regulations and safety assessments", "The complete replacement of subway systems with cars", "Cheap transit tickets causing massive overcrowding"], "correct_index": 1}], "passage_ar": "بالسنين الأخيرة، شهدت المناطق الحضرية الكبيرة بأوروبا تحول كتير كبير ببنيتها التحتية للمواصلات العامة. وكتعويض عن المخاوف البيئية يلي عم تزيد وعجقات السير الخانقة، حطوا مخططي المدن الأولوية لوسائل النقل الحضري المستدام على حساب الاعتماد التقليدي على السيارات الخاصة. تم بناء شبكات شاملة لمسارات البسكليتات، وطرحوا تكتات مدعومة للمواصلات عشان يشجعوا السكان يستخدموا القطارات والباصات. وبناءً على هاد الشي، ملكية السيارات الخاصة بمركز المدن عم تنزل شوي شوي كرمال المشاوير عبر شبكات النقل العامة صارت تنشاف أكتر كبديل فعال وعملي. بس هاد التحول ما كان خالي من المشاكل بنوب، لأنه البلديات المحلية عم تواجه دايماً عجز بالميزانية وهي عم تحدث أنظمة المترو القديمة كتير. وطلعت تقارير عم تقول إنه توسيع البنية التحتية عم يتعرض لتأخيرات بسبب القوانين البيئية الناشفة وتدقيق إجراءات السلامة الصارمة. لو مجالس البلديات خصصت موارد أكبر للابتكار التكنولوجي من قبل، كان ممكن دمج باصات النقل الكهربائية ذاتية القيادة يخلص هلق. ومع استمرار التوسع السكاني بالمدن، رح يعتمد نجاح هي المدن على المدى الطويل بشكل كبير على التحديث المستمر لمواعيد النقل العام وتوسيع مناطق خالية من الانبعاثات.", "vocabulary": ["transformation", "incentivize", "seamless", "deficits", "optimization"]}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (153, 1, 'reading', 'B2', 'lesson', 'The Mechanics of the Dual Education System', '{"text": "Germany''s dual education system is widely celebrated internationally for its efficiency in aligning academic training with practical corporate requirements. Through this framework, vocational students split their time between a specialized vocational school and an actual company, ensuring that the skills acquired are immediately applicable in a real-world setting. This system is heavily supported by both corporate entities and federal labor agencies, which recognize the economic benefits of cultivating a highly specialized workforce. Critics, however, point out that the system occasionally forces teenagers to commit to a specific career path too early in their development, potentially limiting future academic flexibility. It is frequently noted by educational researchers that students who choose this route gain financial independence much sooner than university students, as they receive a standardized stipend throughout their training. If the dual model were more easily adaptable to rapidly changing tech sectors, it would serve as an even more flawless blueprint for global educational reform. As industries become increasingly automated, the curriculum of vocational schools is being revised extensively to include advanced digital competencies, ensuring that graduates remain highly competitive.", "topic": "education systems", "passage": "Germany''s dual education system is widely celebrated internationally for its efficiency in aligning academic training with practical corporate requirements. Through this framework, vocational students split their time between a specialized vocational school and an actual company, ensuring that the skills acquired are immediately applicable in a real-world setting. This system is heavily supported by both corporate entities and federal labor agencies, which recognize the economic benefits of cultivating a highly specialized workforce. Critics, however, point out that the system occasionally forces teenagers to commit to a specific career path too early in their development, potentially limiting future academic flexibility. It is frequently noted by educational researchers that students who choose this route gain financial independence much sooner than university students, as they receive a standardized stipend throughout their training. If the dual model were more easily adaptable to rapidly changing tech sectors, it would serve as an even more flawless blueprint for global educational reform. As industries become increasingly automated, the curriculum of vocational schools is being revised extensively to include advanced digital competencies, ensuring that graduates remain highly competitive.", "text_ar": "نظام التعليم المزدوج بألمانيا مشهور كتير على مستوى العالم بسبب كفاءته بربط الدراسة الأكاديمية مع المتطلبات العملية للشركات. ومن خلال هاد السيستم، طلاب التدريب المهني بيقسموا وقتهم بين مدرسة مهنية متخصصة وشركة حقيقية، وهاد الشي بيضمن إنه المهارات يلي عم يتعلموها يطبقوها فوراً على أرض الواقع. هاد النظام مدعوم بقوة من الشركات والمؤسسات ومن وكالات العمل الفيدرالية سوا، لأنهم بيعرفوا الفوائد الاقتصادية لتجهيز أيدي عاملة متخصصة بشكل عالي. بس المنتقدين عم يضلوا يوضحوا إنه هاد النظام أوقات بيجبر المراهقين يلتزموا بطريق مهني معين بوقت كتير بكير من حياتهم، وهاد الشي ممكن يقلل من مرونتهم الأكاديمية بالمستقبل. باحثين بمجال التعليم عم يذكروا دايماً إنه الطلاب يلي بيختاروا هاد الطريق بيحصلوا على استقلال مادي بوقت أبكر بكثير من طلاب الجامعة، كرمال بيجيهم راتب شهري ثابت طول فترة التدريب. لو كان هاد النموذج المزدوج بيتأقلم بشكل أسهل مع قطاعات التكنولوجيا يلي عم تتغير بسرعة، كان رح يكون نسخة مثالية أكتر لإصلاح التعليم العالمي. ومع تحول الصناعات للأتمتة هلق، عم يتم تعديل المناهج بالمدارس المهنية بشكل موسع لتشمل مهارات رقمية متقدمة، عشان يضمنوا إنه الخريجين يضلوا عم ينافسوا بقوة.", "title_ar": "آلية نظام التعليم المزدوج", "questions": [{"id": "q1", "stem": "What potential drawback of the dual education system is highlighted by critics?", "choices": ["It fails to provide any financial support to students", "It completely excludes digital competencies from the curriculum", "It may pressure students into choosing a career path too early", "It is heavily rejected by federal labor agencies"], "correct_index": 2}], "passage_ar": "نظام التعليم المزدوج بألمانيا مشهور كتير على مستوى العالم بسبب كفاءته بربط الدراسة الأكاديمية مع المتطلبات العملية للشركات. ومن خلال هاد السيستم، طلاب التدريب المهني بيقسموا وقتهم بين مدرسة مهنية متخصصة وشركة حقيقية، وهاد الشي بيضمن إنه المهارات يلي عم يتعلموها يطبقوها فوراً على أرض الواقع. هاد النظام مدعوم بقوة من الشركات والمؤسسات ومن وكالات العمل الفيدرالية سوا، لأنهم بيعرفوا الفوائد الاقتصادية لتجهيز أيدي عاملة متخصصة بشكل عالي. بس المنتقدين عم يضلوا يوضحوا إنه هاد النظام أوقات بيجبر المراهقين يلتزموا بطريق مهني معين بوقت كتير بكير من حياتهم، وهاد الشي ممكن يقلل من مرونتهم الأكاديمية بالمستقبل. باحثين بمجال التعليم عم يذكروا دايماً إنه الطلاب يلي بيختاروا هاد الطريق بيحصلوا على استقلال مادي بوقت أبكر بكثير من طلاب الجامعة، كرمال بيجيهم راتب شهري ثابت طول فترة التدريب. لو كان هاد النموذج المزدوج بيتأقلم بشكل أسهل مع قطاعات التكنولوجيا يلي عم تتغير بسرعة، كان رح يكون نسخة مثالية أكتر لإصلاح التعليم العالمي. ومع تحول الصناعات للأتمتة هلق، عم يتم تعديل المناهج بالمدارس المهنية بشكل موسع لتشمل مهارات رقمية متقدمة، عشان يضمنوا إنه الخريجين يضلوا عم ينافسوا بقوة.", "vocabulary": ["aligning", "cultivating", "flexibility", "stipend", "revised"]}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (154, 1, 'reading', 'B2', 'lesson', 'Digital Patient Records and Ethical Boundaries', '{"text": "The implementation of standardized digital patient records across European healthcare systems has sparked an intense debate concerning data protection and medical ethics. Proponents of digitalization argue that centralized electronic networks enable doctors to access vital medical histories instantly, thereby preventing dangerous medication errors and optimizing emergency treatments. It has been proven that when critical patient diagnostics are shared efficiently between specialists, hospital response times decrease significantly. On the other hand, privacy advocates express grave concerns regarding the vulnerability of these digital repositories to cyberattacks and unauthorized corporate surveillance. They emphasize that sensitive medical records must be safeguarded with advanced encryption methods to prevent insurance corporations from exploiting personal vulnerabilities. If stricter regulations had been established prior to the digital transition, public trust in these electronic health systems would be noticeably higher today. As artificial intelligence is increasingly integrated into medical diagnostics, the boundary between automated medical efficiency and human patient confidentiality remains highly contested. Healthcare administrators are now forced to navigate these ethical complexities while maintaining clinical standards.", "topic": "healthcare", "passage": "The implementation of standardized digital patient records across European healthcare systems has sparked an intense debate concerning data protection and medical ethics. Proponents of digitalization argue that centralized electronic networks enable doctors to access vital medical histories instantly, thereby preventing dangerous medication errors and optimizing emergency treatments. It has been proven that when critical patient diagnostics are shared efficiently between specialists, hospital response times decrease significantly. On the other hand, privacy advocates express grave concerns regarding the vulnerability of these digital repositories to cyberattacks and unauthorized corporate surveillance. They emphasize that sensitive medical records must be safeguarded with advanced encryption methods to prevent insurance corporations from exploiting personal vulnerabilities. If stricter regulations had been established prior to the digital transition, public trust in these electronic health systems would be noticeably higher today. As artificial intelligence is increasingly integrated into medical diagnostics, the boundary between automated medical efficiency and human patient confidentiality remains highly contested. Healthcare administrators are now forced to navigate these ethical complexities while maintaining clinical standards.", "text_ar": "تطبيق السجلات الرقمية الموحدة للمرضى بأنظمة الرعاية الصحية الأوروبية عمل نقاش حاد بخصوص حماية البيانات والأخلاق الطبية. المؤيدين للتحول الرقمي عم يقولوا إنه الشبكات الإلكترونية المركزية بتخلي الدكاترة يوصلوا لتاريخ المريض الطبي والمهم بلحظة، وهاد بيمنع أغلاط الأدوية الخطيرة وبيحسن العلاجات الإسعافية. وتم إثبات إنه لما تتشارك تشخيصات المرضى الحساسة بفعالية بين الأطباء المتخصصين، وقت استجابة المستشفيات بينزل بشكل كبير. ومن جهة تانية، المدافعين عن الخصوصية عم يبدوا مخاوف حقيقية بخصوص ضعف هي المستودعات الرقمية قدام الهجمات الإلكترونية ومراقبة الشركات يلي مو مصرح فيها. وعم يشددوا إنه السجلات الطبية الحساسة لازم يحموها بطرق تشفير متقدمة عشان يمنعوا شركات التأمين من استغلال نقاط الضعف الشخصية للمرضى. لو حطوا قوانين أشد قبل ما يبلشوا بالتحول الرقمي، كانت ثقة الناس بهي الأنظمة الصحية الإلكترونية رح تكون أعلى بكتير اليوم. ومع زيادة دمج الذكاء الاصطناعي بالتشخيص الطبي هلق، لساته الخط الفاصل بين الكفاءة الطبية المؤتمتة وسرية المريض البشري عليه خلاف كبير. ومدراء الرعاية الصحية هلق مجبورين يمشوا بين هي التعقيدات الأخلاقية وهم عم يحافظوا ع المعايير الطبية بنفس الوقت.", "title_ar": "السجلات الرقمية للمرضى والحدود الأخلاقية", "questions": [{"id": "q1", "stem": "What do privacy advocates fear regarding centralized digital patient records?", "choices": ["A decrease in the efficiency of emergency medical treatments", "That hospital response times will increase dramatically", "A total elimination of artificial intelligence in hospitals", "The vulnerability of sensitive data to cyberattacks and exploitation"], "correct_index": 3}], "passage_ar": "تطبيق السجلات الرقمية الموحدة للمرضى بأنظمة الرعاية الصحية الأوروبية عمل نقاش حاد بخصوص حماية البيانات والأخلاق الطبية. المؤيدين للتحول الرقمي عم يقولوا إنه الشبكات الإلكترونية المركزية بتخلي الدكاترة يوصلوا لتاريخ المريض الطبي والمهم بلحظة، وهاد بيمنع أغلاط الأدوية الخطيرة وبيحسن العلاجات الإسعافية. وتم إثبات إنه لما تتشارك تشخيصات المرضى الحساسة بفعالية بين الأطباء المتخصصين، وقت استجابة المستشفيات بينزل بشكل كبير. ومن جهة تانية، المدافعين عن الخصوصية عم يبدوا مخاوف حقيقية بخصوص ضعف هي المستودعات الرقمية قدام الهجمات الإلكترونية ومراقبة الشركات يلي مو مصرح فيها. وعم يشددوا إنه السجلات الطبية الحساسة لازم يحموها بطرق تشفير متقدمة عشان يمنعوا شركات التأمين من استغلال نقاط الضعف الشخصية للمرضى. لو حطوا قوانين أشد قبل ما يبلشوا بالتحول الرقمي، كانت ثقة الناس بهي الأنظمة الصحية الإلكترونية رح تكون أعلى بكتير اليوم. ومع زيادة دمج الذكاء الاصطناعي بالتشخيص الطبي هلق، لساته الخط الفاصل بين الكفاءة الطبية المؤتمتة وسرية المريض البشري عليه خلاف كبير. ومدراء الرعاية الصحية هلق مجبورين يمشوا بين هي التعقيدات الأخلاقية وهم عم يحافظوا ع المعايير الطبية بنفس الوقت.", "vocabulary": ["proponents", "vulnerability", "surveillance", "safeguarded", "confidentiality"]}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (155, 1, 'reading', 'B2', 'lesson', 'The Administrative Maze of Social Integration', '{"text": "For many newly arrived individuals in Western Europe, navigating the complex administrative bureaucracy can feel like wandering through an endless maze. To access social benefits, secure accommodation, or obtain local work authorizations, immigrants must submit numerous official documents to various independent municipal offices. This decentralized process is frequently exacerbated by language barriers, as administrative paperwork is rarely translated into foreign languages due to legal constraints. Sociologists observe that the stress of handling this paperwork often hinders the initial psychological integration of migrants, who instead spend months worrying about legal residency status. Recently, several progressive cities have initiated digital platforms designed to centralize these bureaucratic procedures into a single portal. If these intuitive digital solutions had been developed earlier, the immense administrative backlog at physical migration offices could have been managed more effectively. Until these modern systems are fully integrated across all municipalities, applicants are advised to seek guidance from non-profit counseling organizations, which provide invaluable assistance in deciphering legal terminology and filling out applications.", "topic": "bureaucracy", "passage": "For many newly arrived individuals in Western Europe, navigating the complex administrative bureaucracy can feel like wandering through an endless maze. To access social benefits, secure accommodation, or obtain local work authorizations, immigrants must submit numerous official documents to various independent municipal offices. This decentralized process is frequently exacerbated by language barriers, as administrative paperwork is rarely translated into foreign languages due to legal constraints. Sociologists observe that the stress of handling this paperwork often hinders the initial psychological integration of migrants, who instead spend months worrying about legal residency status. Recently, several progressive cities have initiated digital platforms designed to centralize these bureaucratic procedures into a single portal. If these intuitive digital solutions had been developed earlier, the immense administrative backlog at physical migration offices could have been managed more effectively. Until these modern systems are fully integrated across all municipalities, applicants are advised to seek guidance from non-profit counseling organizations, which provide invaluable assistance in deciphering legal terminology and filling out applications.", "text_ar": "بالنسبة لكتير من الناس يلي واصلين جديد ع أوروبا الغربية، التعامل مع المعاملات الإدارية المعقدة ممكن يخليهم يحسوا حالهم ضايعين بمتاهة ماله نهاية. وعشان يوصلوا للمساعدات الاجتماعية، أو يأمنوا سكن، أو يأخذوا تصاريح شغل محلية، لازم المهاجرين يقدموا أوراق رسمية كتيرة لدوائر بلدية مختلفة ومستقلة عن بعضها. هي العملية اللامركزية كتير أوقات بتزيد صعوبتها بسبب عائق اللغة، لأنه الأوراق الرسمية الإدارية بنادر لتترجم للغات أجنبية بسبب شروط قانونية ناشفة. علماء الاجتماع عم يلاحظوا إنه الضغط النفسي لتجهيز هي الأوراق بيعطل أوقات الاندماج النفسي الأولاني للمهاجرين، يلي بيقضوا شهور وهم عم يفضلوا يقلقوا على وضع إقامتهم القانونية. ومؤخراً، بلشت كذا مدينة متطورة تفتح منصات ديجيتال مصممة لتجمع هي الإجراءات البيروقراطية كلها ببوابة وحدة. لو هي الحلول الرقمية السهلة طوروها من قبل، كان ممكن ضغط الأوراق المتراكم الكبير بمكاتب الهجرة الحقيقية يتيسر بشكل فعال أكتر. ولحد ما تطبق هي الأنظمة الحديثة بكل البلديات، عم ينصحوا المتقدمين يطلبوا مساعدة من منظمات استشارية غير ربحية، يلي بتقدم عون ما بيتقدر بتمن بفك الرموز والمصطلحات القانونية وتعبئة الطلبات.", "title_ar": "متاهة المعاملات الإدارية للاندماج الاجتماعي", "questions": [{"id": "q1", "stem": "What is identified by sociologists as a negative consequence of bureaucratic stress on migrants?", "choices": ["It hinders their initial psychological social integration", "It completely stops them from seeking non-profit counseling", "It forces municipalities to translate all forms into foreign languages", "It automatically guarantees their legal residency status"], "correct_index": 0}], "passage_ar": "بالنسبة لكتير من الناس يلي واصلين جديد ع أوروبا الغربية، التعامل مع المعاملات الإدارية المعقدة ممكن يخليهم يحسوا حالهم ضايعين بمتاهة ماله نهاية. وعشان يوصلوا للمساعدات الاجتماعية، أو يأمنوا سكن، أو يأخذوا تصاريح شغل محلية، لازم المهاجرين يقدموا أوراق رسمية كتيرة لدوائر بلدية مختلفة ومستقلة عن بعضها. هي العملية اللامركزية كتير أوقات بتزيد صعوبتها بسبب عائق اللغة، لأنه الأوراق الرسمية الإدارية بنادر لتترجم للغات أجنبية بسبب شروط قانونية ناشفة. علماء الاجتماع عم يلاحظوا إنه الضغط النفسي لتجهيز هي الأوراق بيعطل أوقات الاندماج النفسي الأولاني للمهاجرين، يلي بيقضوا شهور وهم عم يفضلوا يقلقوا على وضع إقامتهم القانونية. ومؤخراً، بلشت كذا مدينة متطورة تفتح منصات ديجيتال مصممة لتجمع هي الإجراءات البيروقراطية كلها ببوابة وحدة. لو هي الحلول الرقمية السهلة طوروها من قبل، كان ممكن ضغط الأوراق المتراكم الكبير بمكاتب الهجرة الحقيقية يتيسر بشكل فعال أكتر. ولحد ما تطبق هي الأنظمة الحديثة بكل البلديات، عم ينصحوا المتقدمين يطلبوا مساعدة من منظمات استشارية غير ربحية، يلي بتقدم عون ما بيتقدر بتمن بفك الرموز والمصطلحات القانونية وتعبئة الطلبات.", "vocabulary": ["bureaucracy", "exacerbated", "hinders", "portal", "deciphering"]}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (156, 1, 'reading', 'B2', 'lesson', 'Feierabend and the Boundary of Leisure', '{"text": "The traditional German cultural concept of ''Feierabend'' represents the distinct separation between professional obligations and personal leisure time. Historically, it designated the period of rest following a long day of agricultural or industrial labor, during which all work-related activities ceased completely. Today, this practice is highly protected by labor unions and corporate regulations, which recognize that clear boundaries prevent professional burnout and enhance productivity. However, with the rise of remote work and mobile corporate applications, maintaining this cultural boundary has become increasingly challenging for modern employees. It is often argued by psychologists that the constant availability via email prevents individuals from full, undisturbed relaxation, thereby leading to heightened stress levels. If remote work frameworks included mandatory digital disconnection clauses, the psychological integrity of ''Feierabend'' would be preserved more effectively. As corporate dynamics evolve, some progressive European companies have started disabling internal email servers during late evening hours, ensuring that their employees can enjoy uninterrupted personal time with their families.", "topic": "cultural differences", "passage": "The traditional German cultural concept of ''Feierabend'' represents the distinct separation between professional obligations and personal leisure time. Historically, it designated the period of rest following a long day of agricultural or industrial labor, during which all work-related activities ceased completely. Today, this practice is highly protected by labor unions and corporate regulations, which recognize that clear boundaries prevent professional burnout and enhance productivity. However, with the rise of remote work and mobile corporate applications, maintaining this cultural boundary has become increasingly challenging for modern employees. It is often argued by psychologists that the constant availability via email prevents individuals from full, undisturbed relaxation, thereby leading to heightened stress levels. If remote work frameworks included mandatory digital disconnection clauses, the psychological integrity of ''Feierabend'' would be preserved more effectively. As corporate dynamics evolve, some progressive European companies have started disabling internal email servers during late evening hours, ensuring that their employees can enjoy uninterrupted personal time with their families.", "text_ar": "المفهوم الثقافي التقليدي بألمانيا لـ ''الفايرآبند'' (Feierabend) بيمثل الفصل الواضح بين التزامات الشغل ووقت الراحة الشخصي. وتاريخياً، كان هاد المفهوم بيحدد فترة الراحة يلي بتيجي بعد يوم طويل من الشغل بالزراعة أو الصناعة، ويلي فيها كل الأنشطة المتعلقة بالشغل بتوقف تماماً. واليوم، هاد العرف محمي بقوة من نقابات العمال وقوانين الشركات، يلي بتعرف إنه الحدود الواضحة بتمنع الاحتراق المهني وبتزيد الإنتاجية. بس مع طلع الشغل عن بعد وتطبيقات الشركات ع الموبايل، الحفاظ على هي الحدود الثقافية صار فيه تحدي كبير للموظفين هلق. علماء النفس عم يقولوا دايماً إنه الرد المستمر ع الإيميلات بيمنع الواحد إنه يفصل تماماً ليرتاح، وهاد الشي بيؤدي لزيادة مستويات التوتر. لو كانت أطر الشغل عن بعد بتشمل بنود إجبارية لفصل النت والاتصال الرقمي، كانت القيمة النفسية لـ ''الفايرآبند'' انحمت بشكل فعال أكتر. ومع تطور حركات الشركات، بلشت بعض الشركات الأوروبية المتطورة توقف سيرفرات الإيميلات الداخلية بمتأخر الليل، لتضمن إنه موظفيها يقدروا يستمتعوا بوقتهم الشخصي من دون أي إزعاج مع عيلاتهم.", "title_ar": "وقت الفراغ المقدس (الفايرآبند) وحدود الراحة", "questions": [{"id": "q1", "stem": "What has made maintaining the traditional boundary of ''Feierabend'' more difficult recently?", "choices": ["The strict interventions implemented by corporate labor unions", "The rise of remote work and continuous digital communication", "A massive decrease in personal interest regarding leisure time", "The expansion of agricultural and industrial working shifts"], "correct_index": 1}], "passage_ar": "المفهوم الثقافي التقليدي بألمانيا لـ ''الفايرآبند'' (Feierabend) بيمثل الفصل الواضح بين التزامات الشغل ووقت الراحة الشخصي. وتاريخياً، كان هاد المفهوم بيحدد فترة الراحة يلي بتيجي بعد يوم طويل من الشغل بالزراعة أو الصناعة، ويلي فيها كل الأنشطة المتعلقة بالشغل بتوقف تماماً. واليوم، هاد العرف محمي بقوة من نقابات العمال وقوانين الشركات، يلي بتعرف إنه الحدود الواضحة بتمنع الاحتراق المهني وبتزيد الإنتاجية. بس مع طلع الشغل عن بعد وتطبيقات الشركات ع الموبايل، الحفاظ على هي الحدود الثقافية صار فيه تحدي كبير للموظفين هلق. علماء النفس عم يقولوا دايماً إنه الرد المستمر ع الإيميلات بيمنع الواحد إنه يفصل تماماً ليرتاح، وهاد الشي بيؤدي لزيادة مستويات التوتر. لو كانت أطر الشغل عن بعد بتشمل بنود إجبارية لفصل النت والاتصال الرقمي، كانت القيمة النفسية لـ ''الفايرآبند'' انحمت بشكل فعال أكتر. ومع تطور حركات الشركات، بلشت بعض الشركات الأوروبية المتطورة توقف سيرفرات الإيميلات الداخلية بمتأخر الليل، لتضمن إنه موظفيها يقدروا يستمتعوا بوقتهم الشخصي من دون أي إزعاج مع عيلاتهم.", "vocabulary": ["obligations", "ceased", "burnout", "detached", "preserved"]}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (157, 1, 'reading', 'B2', 'lesson', 'Urban Green Infrastructure and Climate Change', '{"text": "Urban green infrastructure is increasingly recognized by climatologists as an indispensable asset in mitigating the adverse impacts of global climate change. Metropolises worldwide are expanding their parks, constructing green roofs, and planting extensive urban forests to combat the phenomenon known as the urban heat island effect. These green areas function as natural cooling mechanisms, absorbing solar radiation and significantly reducing surface temperatures in densely built environments. Environmental reports indicate that without these deliberate ecological interventions, summer temperatures in heavily concreted city centers would skyrocket to unlivable levels. Furthermore, urban vegetation plays a critical role in managing stormwater during extreme weather events, absorbing excessive rainfall and reducing the pressure on ancient sewage infrastructure. Had city administrations ignored these sustainable architecture solutions, urban flooding would have caused extensive structural damage during recent torrential storms. As global temperatures continue to fluctuate, the continuous investment in urban green spaces will remain a fundamental pillar of modern sustainable urban planning and public health preservation.", "topic": "global issues", "passage": "Urban green infrastructure is increasingly recognized by climatologists as an indispensable asset in mitigating the adverse impacts of global climate change. Metropolises worldwide are expanding their parks, constructing green roofs, and planting extensive urban forests to combat the phenomenon known as the urban heat island effect. These green areas function as natural cooling mechanisms, absorbing solar radiation and significantly reducing surface temperatures in densely built environments. Environmental reports indicate that without these deliberate ecological interventions, summer temperatures in heavily concreted city centers would skyrocket to unlivable levels. Furthermore, urban vegetation plays a critical role in managing stormwater during extreme weather events, absorbing excessive rainfall and reducing the pressure on ancient sewage infrastructure. Had city administrations ignored these sustainable architecture solutions, urban flooding would have caused extensive structural damage during recent torrential storms. As global temperatures continue to fluctuate, the continuous investment in urban green spaces will remain a fundamental pillar of modern sustainable urban planning and public health preservation.", "text_ar": "البنية التحتية الخضراء بالمدن عم يعترفوا فيها علماء المناخ أكتر وأكتر كعنصر ما فينا نستغني عنه للتخفيف من الآثار السيئة للتغير المناخي العالمي. المدن الكبيرة بكل العالم عم توسع حدائقها، وعم تبني أسطح خضرا، وتزرع غابات حضرية واسعة عشان تحارب الظاهرة المعروفة باسم تأثير الجزر الحرارية بالمدن. هي المناطق الخضرا بتشتغل متل آليات تبريد طبيعية، بتمتص الإشعاع الشمسي وبتنزل درجات حرارة الأسطح بشكل كبير بالأماكن المبنية بكثافة. التقارير البيئية عم تشير إنه بلا هي التدخلات البيئية المدروسة، كانت درجات الحرارة بالصيف بمراكز المدن المليانة بيتون رح تطير لمستويات ما تندحر. وكمان، الغطاء النباتي بالمدن بيلعب دور أساسي بتصريف مي المطر خلال الطقس القاسي، لأنه بيمتص مياه الأمطار الزيادة وبيخفف الضغط عن شبكات الصرف الصحي القديمة. لو كانت إدارات المدن هملت هي الحلول المعمارية المستدامة، كانت فيضانات المدن رح تعمل أضرار هيكلية كبيرة خلال العواصف المطرية القوية الأخيرة. ومع استمرار تقلب درجات الحرارة العالمية، رح يضل الاستثمار المستمر بالمساحات الخضراء بالمدن عمود أساسي للتخطيط الحضري المستدام الحديث وحماية الصحة العامة.", "title_ar": "البنية التحتية الخضراء بالمدن والتغير المناخي", "questions": [{"id": "q1", "stem": "According to the passage, how does urban vegetation assist cities during extreme weather events?", "choices": ["By increasing surface temperatures via solar absorption", "By completely replacing ancient sewage infrastructure systems", "By absorbing excessive rainfall and reducing sewage pressure", "By transforming concrete structures into agricultural fields"], "correct_index": 2}], "passage_ar": "البنية التحتية الخضراء بالمدن عم يعترفوا فيها علماء المناخ أكتر وأكتر كعنصر ما فينا نستغني عنه للتخفيف من الآثار السيئة للتغير المناخي العالمي. المدن الكبيرة بكل العالم عم توسع حدائقها، وعم تبني أسطح خضرا، وتزرع غابات حضرية واسعة عشان تحارب الظاهرة المعروفة باسم تأثير الجزر الحرارية بالمدن. هي المناطق الخضرا بتشتغل متل آليات تبريد طبيعية، بتمتص الإشعاع الشمسي وبتنزل درجات حرارة الأسطح بشكل كبير بالأماكن المبنية بكثافة. التقارير البيئية عم تشير إنه بلا هي التدخلات البيئية المدروسة، كانت درجات الحرارة بالصيف بمراكز المدن المليانة بيتون رح تطير لمستويات ما تندحر. وكمان، الغطاء النباتي بالمدن بيلعب دور أساسي بتصريف مي المطر خلال الطقس القاسي، لأنه بيمتص مياه الأمطار الزيادة وبيخفف الضغط عن شبكات الصرف الصحي القديمة. لو كانت إدارات المدن هملت هي الحلول المعمارية المستدامة، كانت فيضانات المدن رح تعمل أضرار هيكلية كبيرة خلال العواصف المطرية القوية الأخيرة. ومع استمرار تقلب درجات الحرارة العالمية، رح يضل الاستثمار المستمر بالمساحات الخضراء بالمدن عمود أساسي للتخطيط الحضري المستدام الحديث وحماية الصحة العامة.", "vocabulary": ["indispensable", "phenomenon", "deliberate", "torrential", "fluctuate"]}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (158, 1, 'reading', 'B2', 'lesson', 'Anti-Discrimination Laws in Corporate Hiring', '{"text": "The implementation of the General Equal Treatment Act in Germany has transformed corporate hiring processes, aiming to prevent discrimination based on gender, ethnicity, or background. Under this legal framework, human resource departments are required to standardize their selection criteria to ensure absolute objectivity throughout the evaluation process. For instance, application processes have been modified so that interviewers are discouraged from asking personal questions regarding family planning or religious beliefs. Despite these rigorous legal protections, many international applicants still report subtle biases during their corporate evaluation stages. It is frequently observed by researchers that candidates with foreign-sounding names receive fewer interview invitations, even when their professional qualifications perfectly match the job profile. If anonymized application procedures were universally mandated across all industrial sectors, these unconscious biases would be reduced significantly. As corporate social responsibility becomes a priority, forward-thinking organizations are implementing diversity training for their management teams, recognizing that inclusive workplaces exhibit higher employee satisfaction and innovation.", "topic": "job applications", "passage": "The implementation of the General Equal Treatment Act in Germany has transformed corporate hiring processes, aiming to prevent discrimination based on gender, ethnicity, or background. Under this legal framework, human resource departments are required to standardize their selection criteria to ensure absolute objectivity throughout the evaluation process. For instance, application processes have been modified so that interviewers are discouraged from asking personal questions regarding family planning or religious beliefs. Despite these rigorous legal protections, many international applicants still report subtle biases during their corporate evaluation stages. It is frequently observed by researchers that candidates with foreign-sounding names receive fewer interview invitations, even when their professional qualifications perfectly match the job profile. If anonymized application procedures were universally mandated across all industrial sectors, these unconscious biases would be reduced significantly. As corporate social responsibility becomes a priority, forward-thinking organizations are implementing diversity training for their management teams, recognizing that inclusive workplaces exhibit higher employee satisfaction and innovation.", "text_ar": "تطبيق قانون المساواة العام بألمانيا غير عمليات التوظيف بالشركات، بهدف منع التمييز القائم على الجنس، أو العرق، أو الخلفية الاجتماعية. وتحت هاد الإطار القانوني، أقسام الموارد البشرية صارت مجبورة توحد معايير الاختيار تبعها لتضمن موضوعية كاملة طول فترة عملية التقييم. مثلاً، تعدلت إجراءات التقديم لدرجة إنه صار ممنوع أو مو منصح للمقابلين يسألوا أسئلة شخصية بتخص التخطيط للعيلة أو المعتقدات الدينية. ومع وجود هي الحمايات القانونية الصارمة، لساتهم كتير من المتقدمين الأجانب عم يبلغوا عن انحيازات مبطنة خلال مراحل تقييمهم بالشركات. الباحثين عم يلاحظوا دايماً إنه المرشحين يلي أسماءهم بتبين أجنبية عم تجيهم دعوات أقل للمقابلات، حتى لو كانت مؤهلاتهم المهنية بتطابق تماماً مواصفات الشغل. لو كانت إجراءات التقديم المخفية (بلا أسماء) مفروضة بشكل عام بكل القطاعات الصناعية، كان هاد الانحياز اللاواعي رح يقل بشكل كبير. ومع صيرورة المسؤولية الاجتماعية للشركات أولوية، بلشت المؤسسات يلي بتفكر لقدام تطبق تدريبات التنوع لفرق الإدارة تبعها، كرمال بيعرفوا إنه أماكن الشغل الشاملة للكل بتظهر رضا وابتكار أعلى عند الموظفين.", "title_ar": "قوانين مناهضة التمييز بتوظيف الشركات", "questions": [{"id": "q1", "stem": "What measure does the text suggest would significantly reduce unconscious biases in corporate hiring?", "choices": ["Allowing interviewers to ask unrestricted personal questions", "Excluding professional qualifications from the job profile", "Completely eliminating human resource departments", "Universally mandating anonymized application procedures"], "correct_index": 3}], "passage_ar": "تطبيق قانون المساواة العام بألمانيا غير عمليات التوظيف بالشركات، بهدف منع التمييز القائم على الجنس، أو العرق، أو الخلفية الاجتماعية. وتحت هاد الإطار القانوني، أقسام الموارد البشرية صارت مجبورة توحد معايير الاختيار تبعها لتضمن موضوعية كاملة طول فترة عملية التقييم. مثلاً، تعدلت إجراءات التقديم لدرجة إنه صار ممنوع أو مو منصح للمقابلين يسألوا أسئلة شخصية بتخص التخطيط للعيلة أو المعتقدات الدينية. ومع وجود هي الحمايات القانونية الصارمة، لساتهم كتير من المتقدمين الأجانب عم يبلغوا عن انحيازات مبطنة خلال مراحل تقييمهم بالشركات. الباحثين عم يلاحظوا دايماً إنه المرشحين يلي أسماءهم بتبين أجنبية عم تجيهم دعوات أقل للمقابلات، حتى لو كانت مؤهلاتهم المهنية بتطابق تماماً مواصفات الشغل. لو كانت إجراءات التقديم المخفية (بلا أسماء) مفروضة بشكل عام بكل القطاعات الصناعية، كان هاد الانحياز اللاواعي رح يقل بشكل كبير. ومع صيرورة المسؤولية الاجتماعية للشركات أولوية، بلشت المؤسسات يلي بتفكر لقدام تطبق تدريبات التنوع لفرق الإدارة تبعها، كرمال بيعرفوا إنه أماكن الشغل الشاملة للكل بتظهر رضا وابتكار أعلى عند الموظفين.", "vocabulary": ["discrimination", "criteria", "biases", "anonymized", "inclusive"]}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (159, 1, 'reading', 'B2', 'lesson', 'The Role of Community Centers in Civic Inclusion', '{"text": "Local community centers across European cities play an invaluable role in fostering social cohesion and accelerating the linguistic integration of newly arrived immigrants. These neighborhood institutions, which are frequently operated by a mixture of municipal staff and volunteers, offer free language cafes, legal advice clinics, and cultural exchange workshops. By providing a safe space for intercultural dialogue, these centers help dismantle mutual prejudices that often arise between local populations and immigrant communities. Sociological studies demonstrate that migrants who regularly participate in these community activities exhibit a much stronger sense of belonging and civic engagement. If these community initiatives were to receive permanent federal funding instead of temporary regional grants, their capacity to expand vital educational programs would be secured. Until substantial structural changes are made, these centers will continue to rely on the dedication of local citizens who contribute their time to build an inclusive society where diversity is celebrated as an asset.", "topic": "integration", "passage": "Local community centers across European cities play an invaluable role in fostering social cohesion and accelerating the linguistic integration of newly arrived immigrants. These neighborhood institutions, which are frequently operated by a mixture of municipal staff and volunteers, offer free language cafes, legal advice clinics, and cultural exchange workshops. By providing a safe space for intercultural dialogue, these centers help dismantle mutual prejudices that often arise between local populations and immigrant communities. Sociological studies demonstrate that migrants who regularly participate in these community activities exhibit a much stronger sense of belonging and civic engagement. If these community initiatives were to receive permanent federal funding instead of temporary regional grants, their capacity to expand vital educational programs would be secured. Until substantial structural changes are made, these centers will continue to rely on the dedication of local citizens who contribute their time to build an inclusive society where diversity is celebrated as an asset.", "text_ar": "المراكز المجتمعية المحلية بالمدن الأوروبية بتلعب دور ما بيتقدر بتمن بتعزيز التماسك الاجتماعي وتسريع الاندماج اللغوي للمهاجرين الجداد. هي المؤسسات تبع الأحياء، يلي بيشغلها بالعادة خليط من موظفي البلدية والمتطوعين، بتقدم كافيهات لغة ببلاش، وعيادات استشارات قانونية، وورشات لتبادل الثقافات. ومن خلال تأمين مكان آمن للحوار بين الثقافات، هي المراكز بتساعد بكسر الأحكام المسبقة المتبادلة يلي أوقات بتطلع بين السكان المحليين ومجتمعات المهاجرين. الدراسات السوسيولوجية عم توضح إنه المهاجرين يلي بيشاركوا بانتظام بهي الأنشطة المجتمعية بيظهر عندهم شعور أقوى بكثير بالانتماء والمشاركة المدنية. لو كانت هي المبادرات المجتمعية بتأخذ تمويل حكومي دائم بدل المنح الإقليمية المؤقتة، كانت قدرتهم على توسيع البرامج التعليمية المهمة رح تكون مضمونة. ولحد ما يصير في تغييرات هيكلية حقيقية، رح تضل هي المراكز عم تعتمد على تفاني المواطنين المحليين يلي عم يقدموا من وقتهم ليبنوا مجتمع شامل للكل بيحتفل بالتنوع كعنصر قوة.", "title_ar": "دور المراكز المجتمعية بالاندماج المدني", "questions": [{"id": "q1", "stem": "What does the text state is a result of regular participation in community center activities for migrants?", "choices": ["A stronger sense of belonging and civic engagement", "An increase in mutual prejudices against local populations", "An immediate acquisition of permanent federal funding", "A total rejection of free language cafes and workshops"], "correct_index": 0}], "passage_ar": "المراكز المجتمعية المحلية بالمدن الأوروبية بتلعب دور ما بيتقدر بتمن بتعزيز التماسك الاجتماعي وتسريع الاندماج اللغوي للمهاجرين الجداد. هي المؤسسات تبع الأحياء، يلي بيشغلها بالعادة خليط من موظفي البلدية والمتطوعين، بتقدم كافيهات لغة ببلاش، وعيادات استشارات قانونية، وورشات لتبادل الثقافات. ومن خلال تأمين مكان آمن للحوار بين الثقافات، هي المراكز بتساعد بكسر الأحكام المسبقة المتبادلة يلي أوقات بتطلع بين السكان المحليين ومجتمعات المهاجرين. الدراسات السوسيولوجية عم توضح إنه المهاجرين يلي بيشاركوا بانتظام بهي الأنشطة المجتمعية بيظهر عندهم شعور أقوى بكثير بالانتماء والمشاركة المدنية. لو كانت هي المبادرات المجتمعية بتأخذ تمويل حكومي دائم بدل المنح الإقليمية المؤقتة، كانت قدرتهم على توسيع البرامج التعليمية المهمة رح تكون مضمونة. ولحد ما يصير في تغييرات هيكلية حقيقية، رح تضل هي المراكز عم تعتمد على تفاني المواطنين المحليين يلي عم يقدموا من وقتهم ليبنوا مجتمع شامل للكل بيحتفل بالتنوع كعنصر قوة.", "vocabulary": ["cohesion", "prejudices", "demonstrate", "belonging", "grants"]}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (160, 1, 'reading', 'B2', 'lesson', 'Demographic Shifts and Corporate Adaptations', '{"text": "The aging demographic profile of Western Europe is forcing corporate enterprises to radically reconsider their workforce management strategies and training structures. As a substantial portion of experienced employees approaches retirement age, companies are facing an unprecedented loss of institutional knowledge and technical expertise. To counter this impending deficit, human resource departments are developing innovative lifelong learning programs aimed at keeping older workers integrated while simultaneously training younger recruits. It is frequently asserted by labor analysts that traditional, rigid retirement frameworks are no longer sustainable under current demographic conditions. If corporations had invested more comprehensively in knowledge-transfer frameworks earlier, the transition between generational workforces would be proceeding far more smoothly today. Consequently, businesses are also adapting their physical workplaces, introducing ergonomic modifications to accommodate an older demographic. The ultimate success of these corporate adaptations will depend on fostering a workplace culture that values intergenerational collaboration, ensuring that the unique strengths of both younger and older employees are utilized effectively.", "topic": "society", "passage": "The aging demographic profile of Western Europe is forcing corporate enterprises to radically reconsider their workforce management strategies and training structures. As a substantial portion of experienced employees approaches retirement age, companies are facing an unprecedented loss of institutional knowledge and technical expertise. To counter this impending deficit, human resource departments are developing innovative lifelong learning programs aimed at keeping older workers integrated while simultaneously training younger recruits. It is frequently asserted by labor analysts that traditional, rigid retirement frameworks are no longer sustainable under current demographic conditions. If corporations had invested more comprehensively in knowledge-transfer frameworks earlier, the transition between generational workforces would be proceeding far more smoothly today. Consequently, businesses are also adapting their physical workplaces, introducing ergonomic modifications to accommodate an older demographic. The ultimate success of these corporate adaptations will depend on fostering a workplace culture that values intergenerational collaboration, ensuring that the unique strengths of both younger and older employees are utilized effectively.", "text_ar": "التحول الديموغرافي المتمثل بشيخوخة السكان بأوروبا الغربية عم يجبر الشركات والمؤسسات إنها تعيد التفكير جذرياً باستراتيجيات إدارة العمال وهياكل التدريب تبعها. ومع اقتراب جزء كبير من الموظفين الخبراء من عمر التقاعد، الشركات عم تواجه خسارة مسبوقة للمعلومات المؤسساتية والخبرات التقنية. وعشان يواجهوا هاد النقص الجايه، أقسام الموارد البشرية عم تطور برامج مبتكرة للتعليم المستمر مدى الحياة، بتهدف لتخلي العمال الكبار بالسن مندمجين وبنفس الوقت يدربوا الموظفين الجداد الأصغر بالعمر. محللين العمال عم يؤكدوا دايماً إنه أطر التقاعد الناشفة والتقليدية ما عاد فيها تستمر بظل الظروف الديموغرافية الحالية. لو كانت الشركات استثمرت بشكل أوسع بأنظمة نقل المعرفة من قبل، كان انتقال الشغل بين الأجيال عم يمشي بسلاسة أكتر بكثير اليوم. وبناءً على هاد الشي، الشركات كمان عم تعدل أماكن الشغل الحقيقية، وعم تدخل تغييرات مريحة وصحية لتناسب الموظفين الكبار بالسن. النجاح النهائي لهي التأقلمات بالشركات رح يعتمد على تعزيز ثقافة بمكان الشغل بتقدر التعاون بين الأجيال، لتضمن إنه نقاط القوة الفريدة للموظفين الشباب والكبار يتم استخدامها بفعالية.", "title_ar": "التحولات الديموغرافية وتأقلم الشركات", "questions": [{"id": "q1", "stem": "What major challenge are companies facing as experienced employees reach retirement age?", "choices": ["A massive oversupply of traditional retirement funding", "An unprecedented loss of institutional knowledge and expertise", "The sudden refusal of younger recruits to learn digital skills", "An immediate drop in corporate tax obligations across the region"], "correct_index": 1}], "passage_ar": "التحول الديموغرافي المتمثل بشيخوخة السكان بأوروبا الغربية عم يجبر الشركات والمؤسسات إنها تعيد التفكير جذرياً باستراتيجيات إدارة العمال وهياكل التدريب تبعها. ومع اقتراب جزء كبير من الموظفين الخبراء من عمر التقاعد، الشركات عم تواجه خسارة مسبوقة للمعلومات المؤسساتية والخبرات التقنية. وعشان يواجهوا هاد النقص الجايه، أقسام الموارد البشرية عم تطور برامج مبتكرة للتعليم المستمر مدى الحياة، بتهدف لتخلي العمال الكبار بالسن مندمجين وبنفس الوقت يدربوا الموظفين الجداد الأصغر بالعمر. محللين العمال عم يؤكدوا دايماً إنه أطر التقاعد الناشفة والتقليدية ما عاد فيها تستمر بظل الظروف الديموغرافية الحالية. لو كانت الشركات استثمرت بشكل أوسع بأنظمة نقل المعرفة من قبل، كان انتقال الشغل بين الأجيال عم يمشي بسلاسة أكتر بكثير اليوم. وبناءً على هاد الشي، الشركات كمان عم تعدل أماكن الشغل الحقيقية، وعم تدخل تغييرات مريحة وصحية لتناسب الموظفين الكبار بالسن. النجاح النهائي لهي التأقلمات بالشركات رح يعتمد على تعزيز ثقافة بمكان الشغل بتقدر التعاون بين الأجيال، لتضمن إنه نقاط القوة الفريدة للموظفين الشباب والكبار يتم استخدامها بفعالية.", "vocabulary": ["demographic", "unprecedented", "impending", "asserted", "intergenerational"]}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (175, 1, 'reading', 'C2', 'lesson', 'Federalist Frictions in Climate Mitigation Policies', '{"text": "The operationalization of supranational climate mitigation policies within heavily federalized European constitutional frameworks frequently reveals deep structural frictions between centralized mandates and regional statutory autonomy. When the European Union issues aggressive decarbonization directives, the ultimate implementation of these statutory laws relies on complex administrative multi-level governance systems, nowhere more pronounced than within the German federal structure. In this framework, federal states (Länder) possess substantial constitutional authority over regional economic planning, energy infrastructure regulation, and natural resource allocation. This decentralization creates an institutional tug-of-war, as regional administrations frequently seek to protect localized industrial sectors from the economic disruption associated with rapid ecological transitions. For instance, regions dependent on heavy manufacturing or automotive industries routinely utilize their legislative leverage to delay or dilute national carbon reduction targets, citing immediate concerns regarding labor market destabilization and regional economic decline. Constitutional scholars observe that this structural friction is often exacerbated by legal ambiguity concerning the boundary of federal versus regional jurisdiction over sustainable architecture subsidies and grid expansion projects. Had central administrations established more binding consensus mechanisms prior to enacting legislative overhauls, the integration of renewable energy networks would have proceeded with substantially fewer judicial challenges. Until these constitutional boundaries are calibrated through legal precedents, climate governance will remain a contested arena where ecological necessity continuously clashes with the entrenched mechanics of federalist distribution.", "topic": "policy debate", "passage": "The operationalization of supranational climate mitigation policies within heavily federalized European constitutional frameworks frequently reveals deep structural frictions between centralized mandates and regional statutory autonomy. When the European Union issues aggressive decarbonization directives, the ultimate implementation of these statutory laws relies on complex administrative multi-level governance systems, nowhere more pronounced than within the German federal structure. In this framework, federal states (Länder) possess substantial constitutional authority over regional economic planning, energy infrastructure regulation, and natural resource allocation. This decentralization creates an institutional tug-of-war, as regional administrations frequently seek to protect localized industrial sectors from the economic disruption associated with rapid ecological transitions. For instance, regions dependent on heavy manufacturing or automotive industries routinely utilize their legislative leverage to delay or dilute national carbon reduction targets, citing immediate concerns regarding labor market destabilization and regional economic decline. Constitutional scholars observe that this structural friction is often exacerbated by legal ambiguity concerning the boundary of federal versus regional jurisdiction over sustainable architecture subsidies and grid expansion projects. Had central administrations established more binding consensus mechanisms prior to enacting legislative overhauls, the integration of renewable energy networks would have proceeded with substantially fewer judicial challenges. Until these constitutional boundaries are calibrated through legal precedents, climate governance will remain a contested arena where ecological necessity continuously clashes with the entrenched mechanics of federalist distribution.", "text_ar": "تطبيق سياسات التخفيف من التغير المناخي العابرة للدول بقلب الأطر الدستورية الفيدرالية القوية بأوروبا دايماً بيكشف عن احتكاكات هيكلية عميقة بين الأوامر المركزية والاستقلالية القانونية والإقليمية. ولما الاتحاد الأوروبي يصدر توجيهات قوية لإزالة الكربون، التطبيق النهائي لهي القوانين التشريعية بيعتمد على أنظمة حوكمة معقدة ومتعددة المستويات، وما في مكان بتظهر فيه هي القصة أوضح من الهيكل الفيدرالي الألماني. وتحت هاد السيستم، الولايات الفيدرالية (Länder) بتملك سلطة دستورية كبيرة على التخطيط الاقتصادي الإقليمي، وتنظيم البنية التحتية للطاقة، وتوزيع الموارد الطبيعية. هاد التوزيع اللامركزي بيعمل حبل شد بين المؤسسات، لأنه الإدارات الإقليمية دايماً بتحاول تحمي القطاعات الصناعية المحلية من الهزة الاقتصادية المرتبطة بالتحول البيئي السريع. مثلاً، المناطق يلي بتعتمد ع الصناعات الثقيلة أو صناعة السيارات بتستخدم دايماً قدرتها التشريعية لتأخر أو تخفف أهداف تقليل الكربون الوطنية، وبتحجج بمخاوف مباشرة بتخص ضرب استقرار سوق العمل والتراجع الاقتصادي الإقليمي. باحثين بالقانون الدستوري عم يلاحظوا إنه هاد الاحتكاك الهيكلي كتير أوقات بيزيد بسبب الغموض القانوني يلي بيخص الحدود بين صلاحيات الحكومة المركزية والولايات على دعم العمارة المستدامة ومشاريع توسيع شبكات الطاقة. لو كانت الإدارات المركزية عملت آليات إجماع إلزامية أكتر قبل ما تقر التعديلات التشريعية، كان دمج شبكات الطاقة المتجددة مشي بتحديات قضائية أقل بكثير. ولحد ما تتدقق هي الحدود الدستورية عبر أحكام قانونية سابقة، رح تضل حوكمة المناخ ساحة صراع عم تتصادم فيها الضرورة البيئية بشكل مستمر مع آليات التوزيع الفيدرالية المزروعة بالسيستم.", "title_ar": "الاحتكاكات الفيدرالية بسياسات التخفيف من التغير المناخي", "questions": [{"id": "q1", "stem": "What primary factor complicates the implementation of centralized climate directives in a federal system like Germany?", "choices": ["The regional constitutional authority over economic planning and energy infrastructure regulation.", "The total legal invalidation of supranational carbon reduction directives by the European Union.", "The absolute consensus among all industrial sectors to immediately eliminate manufacturing.", "A comprehensive structural lack of natural resource allocation tools at the municipal level."], "correct_index": 0}], "passage_ar": "تطبيق سياسات التخفيف من التغير المناخي العابرة للدول بقلب الأطر الدستورية الفيدرالية القوية بأوروبا دايماً بيكشف عن احتكاكات هيكلية عميقة بين الأوامر المركزية والاستقلالية القانونية والإقليمية. ولما الاتحاد الأوروبي يصدر توجيهات قوية لإزالة الكربون، التطبيق النهائي لهي القوانين التشريعية بيعتمد على أنظمة حوكمة معقدة ومتعددة المستويات، وما في مكان بتظهر فيه هي القصة أوضح من الهيكل الفيدرالي الألماني. وتحت هاد السيستم، الولايات الفيدرالية (Länder) بتملك سلطة دستورية كبيرة على التخطيط الاقتصادي الإقليمي، وتنظيم البنية التحتية للطاقة، وتوزيع الموارد الطبيعية. هاد التوزيع اللامركزي بيعمل حبل شد بين المؤسسات، لأنه الإدارات الإقليمية دايماً بتحاول تحمي القطاعات الصناعية المحلية من الهزة الاقتصادية المرتبطة بالتحول البيئي السريع. مثلاً، المناطق يلي بتعتمد ع الصناعات الثقيلة أو صناعة السيارات بتستخدم دايماً قدرتها التشريعية لتأخر أو تخفف أهداف تقليل الكربون الوطنية، وبتحجج بمخاوف مباشرة بتخص ضرب استقرار سوق العمل والتراجع الاقتصادي الإقليمي. باحثين بالقانون الدستوري عم يلاحظوا إنه هاد الاحتكاك الهيكلي كتير أوقات بيزيد بسبب الغموض القانوني يلي بيخص الحدود بين صلاحيات الحكومة المركزية والولايات على دعم العمارة المستدامة ومشاريع توسيع شبكات الطاقة. لو كانت الإدارات المركزية عملت آليات إجماع إلزامية أكتر قبل ما تقر التعديلات التشريعية، كان دمج شبكات الطاقة المتجددة مشي بتحديات قضائية أقل بكثير. ولحد ما تتدقق هي الحدود الدستورية عبر أحكام قانونية سابقة، رح تضل حوكمة المناخ ساحة صراع عم تتصادم فيها الضرورة البيئية بشكل مستمر مع آليات التوزيع الفيدرالية المزروعة بالسيستم.", "vocabulary": ["operationalization", "supranational", "decarbonization", "dilute", "precedents"]}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (176, 1, 'reading', 'C2', 'lesson', 'The Epistemic Dissonance of Cross-Cultural Corporate Assimilation', '{"text": "The integration of diverse global workforces within the distinct institutional landscape of Rhineland capitalism frequently precipitates a complex form of epistemic dissonance, altering standard communication protocols and organizational behavior. In multinational corporate environments throughout Central Europe, corporate governance is traditionally predicated on consensus-driven deliberation, high-context statutory documentation, and a meticulous separation between professional execution and personal identification. When international professional candidates, trained within divergent communicative and organizational paradigms, enter this systemic matrix, linguistic proficiency alone proves insufficient to guarantee successful integration. Cross-cultural communication experts observe that structural friction points often manifest not during explicit legal disputes, but during localized corporate rituals—such as feedback evaluations, project presentations, and consensus-building meetings. For instance, the high reliance on direct, unvarnished critique characteristic of central European corporate communication can be perceived by international employees as deeply destabilizing or personally hostile, thereby eroding psychological safety. Conversely, localized managers often misinterpret indirect communication styles or relational problem-solving approaches as a lack of professional transparency or intellectual autonomy. This mutual misattunement demonstrates that corporate assimilation requires more than superficial sensitivity training; it necessitates a comprehensive re-engineering of communication channels that explicitly validates communicative diversity as a cognitive asset. Until corporate leadership teams move beyond superficial diversity metrics, the latent intellectual capital of global talent will remain structurally constrained by localized behavioral models.", "topic": "cross-cultural communication", "passage": "The integration of diverse global workforces within the distinct institutional landscape of Rhineland capitalism frequently precipitates a complex form of epistemic dissonance, altering standard communication protocols and organizational behavior. In multinational corporate environments throughout Central Europe, corporate governance is traditionally predicated on consensus-driven deliberation, high-context statutory documentation, and a meticulous separation between professional execution and personal identification. When international professional candidates, trained within divergent communicative and organizational paradigms, enter this systemic matrix, linguistic proficiency alone proves insufficient to guarantee successful integration. Cross-cultural communication experts observe that structural friction points often manifest not during explicit legal disputes, but during localized corporate rituals—such as feedback evaluations, project presentations, and consensus-building meetings. For instance, the high reliance on direct, unvarnished critique characteristic of central European corporate communication can be perceived by international employees as deeply destabilizing or personally hostile, thereby eroding psychological safety. Conversely, localized managers often misinterpret indirect communication styles or relational problem-solving approaches as a lack of professional transparency or intellectual autonomy. This mutual misattunement demonstrates that corporate assimilation requires more than superficial sensitivity training; it necessitates a comprehensive re-engineering of communication channels that explicitly validates communicative diversity as a cognitive asset. Until corporate leadership teams move beyond superficial diversity metrics, the latent intellectual capital of global talent will remain structurally constrained by localized behavioral models.", "text_ar": "دمج الأيدي العاملة العالمية المتنوعة بقلب مشهد المؤسسات الفريد لرأسمالية راينلاند كتير أوقات بيعمل نوع معقد من التنافر المعرفي، وبيغير بروتوكولات التواصل المعتادة والسلوك التنظيمي بالشركات. ببيئات الشركات متعددة الجنسيات بوسط أوروبا، الحوكمة بالشركات قايمة تاريخياً على المداولات القائمة ع الإجماع، والتوثيق القانوني الدقيق، والفصل الحذر بين الأداء المهني والهوية الشخصية. ولما يدخلوا الموظفين الأجانب المحترفين، يلي اتدربوا بأنظمة تواصل ومؤسسات مختلفة تماماً، ع هي المصفوفة الممنهجة، إتقان اللغة لحاله عم يثبت إنه ما بيكفي لتضمن اندماج ناجح. خبراء التواصل بين الثقافات عم يلاحظوا إنه نقط الاحتكاك الهيكلي كتير أوقات ما بتظهر بالخلافات القانونية الواضحة، بل خلال طقوس الشركات المحلية—متل تقييمات الأداء، وعروض المشاريع، واجتماعات بناء الإجماع. مثلاً، الاعتماد الكبير ع النقد المباشر والناشف بوضوح يلي بيميز تواصل الشركات بوسط أوروبا ممكن يشوفوه الموظفين الأجانب كشي بيبكك كتير أو عدائي بشكل شخصي، وهاد بيأكل الأمان النفسي عندهم. وبالمقابل، المدراء المحليين كتير أوقات بيفسروا غلط طرق التواصل غير المباشرة أو أساليب حل المشاكل القائمة ع العلاقات على أساس إنها نقص بالشفافية المهنية أو ضعف بالاستقلال الفكري. هاد عدم الانسجام المتبادل بيوضح إنه التأقلم بالشركات بده أكتر من مجرد تدريبات سطحية ع الحساسية الثقافية؛ بده إعادة هندسة شاملة لقنوات التواصل بتعترف بوضوح بالتنوع التواصلي كميزة فكرية حقيقية. ولحد ما فرق قيادات الشركات تتخطى معايير التنوع السطحية، رح يضل رأس المال الفكري المخفي للمواهب العالمية مقيد هيكلياً بنماذج سلوكية محلية ضيقة.", "title_ar": "التنافر المعرفي بالاندماج الثقافي للشركات", "questions": [{"id": "q1", "stem": "According to the text, what often causes international employees to feel destabilized in Central European corporate environments?", "choices": ["The total legal complete absence of consensus-driven deliberation metrics.", "The high reliance on direct, unvarnished critique during communication rituals.", "An absolute operational requirement to eliminate high-context statutory documentation.", "The explicit mandate forcing them to undergo technical linguistic proficiency examinations."], "correct_index": 1}], "passage_ar": "دمج الأيدي العاملة العالمية المتنوعة بقلب مشهد المؤسسات الفريد لرأسمالية راينلاند كتير أوقات بيعمل نوع معقد من التنافر المعرفي، وبيغير بروتوكولات التواصل المعتادة والسلوك التنظيمي بالشركات. ببيئات الشركات متعددة الجنسيات بوسط أوروبا، الحوكمة بالشركات قايمة تاريخياً على المداولات القائمة ع الإجماع، والتوثيق القانوني الدقيق، والفصل الحذر بين الأداء المهني والهوية الشخصية. ولما يدخلوا الموظفين الأجانب المحترفين، يلي اتدربوا بأنظمة تواصل ومؤسسات مختلفة تماماً، ع هي المصفوفة الممنهجة، إتقان اللغة لحاله عم يثبت إنه ما بيكفي لتضمن اندماج ناجح. خبراء التواصل بين الثقافات عم يلاحظوا إنه نقط الاحتكاك الهيكلي كتير أوقات ما بتظهر بالخلافات القانونية الواضحة، بل خلال طقوس الشركات المحلية—متل تقييمات الأداء، وعروض المشاريع، واجتماعات بناء الإجماع. مثلاً، الاعتماد الكبير ع النقد المباشر والناشف بوضوح يلي بيميز تواصل الشركات بوسط أوروبا ممكن يشوفوه الموظفين الأجانب كشي بيبكك كتير أو عدائي بشكل شخصي، وهاد بيأكل الأمان النفسي عندهم. وبالمقابل، المدراء المحليين كتير أوقات بيفسروا غلط طرق التواصل غير المباشرة أو أساليب حل المشاكل القائمة ع العلاقات على أساس إنها نقص بالشفافية المهنية أو ضعف بالاستقلال الفكري. هاد عدم الانسجام المتبادل بيوضح إنه التأقلم بالشركات بده أكتر من مجرد تدريبات سطحية ع الحساسية الثقافية؛ بده إعادة هندسة شاملة لقنوات التواصل بتعترف بوضوح بالتنوع التواصلي كميزة فكرية حقيقية. ولحد ما فرق قيادات الشركات تتخطى معايير التنوع السطحية، رح يضل رأس المال الفكري المخفي للمواهب العالمية مقيد هيكلياً بنماذج سلوكية محلية ضيقة.", "vocabulary": ["dissonance", "predicated", "unvarnished", "misattunement", "latent"]}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (177, 1, 'reading', 'C2', 'lesson', 'Deconstructing the Degrowth Paradigm', '{"text": "As the escalating ecological crises expose the systemic limitations of carbon capitalism, the academic discourse surrounding ecological economics has increasingly centered on the radical degrowth paradigm. This macro-economic theory challenges the foundational axiom of contemporary economics: the assumption that infinite Gross Domestic Product (GDP) expansion is compatible with finite planetary boundaries. Degrowth proponents argue that contemporary strategies for eco-modernism, such as green capitalism and decoupling, constitute an environmental illusion. They maintain that absolute decoupling—the mathematical insulation of economic expansion from total resource extraction and environmental degradation—has never occurred at the scale or velocity required to avert climate destabilization. Instead, the degrowth framework advocates for a deliberate, planned contraction of material and energy throughput in wealthy nations, fundamentally restructuring society to prioritize human well-being and ecological health over capital accumulation. Critics, however, aggressively contend that such a deliberate contraction would induce immediate macroeconomic chaos, resulting in catastrophic unemployment rates, public revenue collapses, and intense geopolitical vulnerability. They assert that without the financial surplus generated by conventional economic growth, funding advanced science research and sustainable infrastructure transformations becomes fiscally impossible. This intellectual impasse highlights the fundamental systemic dilemma of the anthropocene: whether modern democratic societies can successfully re-engineer their socio-economic institutions away from growth dependency without triggering systemic collapse, or whether they will remain bound to an expansionist paradigm until ecological boundary collapses enforce an unplanned contraction.", "topic": "economics", "passage": "As the escalating ecological crises expose the systemic limitations of carbon capitalism, the academic discourse surrounding ecological economics has increasingly centered on the radical degrowth paradigm. This macro-economic theory challenges the foundational axiom of contemporary economics: the assumption that infinite Gross Domestic Product (GDP) expansion is compatible with finite planetary boundaries. Degrowth proponents argue that contemporary strategies for eco-modernism, such as green capitalism and decoupling, constitute an environmental illusion. They maintain that absolute decoupling—the mathematical insulation of economic expansion from total resource extraction and environmental degradation—has never occurred at the scale or velocity required to avert climate destabilization. Instead, the degrowth framework advocates for a deliberate, planned contraction of material and energy throughput in wealthy nations, fundamentally restructuring society to prioritize human well-being and ecological health over capital accumulation. Critics, however, aggressively contend that such a deliberate contraction would induce immediate macroeconomic chaos, resulting in catastrophic unemployment rates, public revenue collapses, and intense geopolitical vulnerability. They assert that without the financial surplus generated by conventional economic growth, funding advanced science research and sustainable infrastructure transformations becomes fiscally impossible. This intellectual impasse highlights the fundamental systemic dilemma of the anthropocene: whether modern democratic societies can successfully re-engineer their socio-economic institutions away from growth dependency without triggering systemic collapse, or whether they will remain bound to an expansionist paradigm until ecological boundary collapses enforce an unplanned contraction.", "text_ar": "مع استمرار الأزمات البيئية المتصاعدة بكشف الحدود الهيكلية لرأسمالية الكربون، صار النقاش الأكاديمي المحيط بالاقتصاد البيئي يركز أكتر وأكتر على نموذج تراجع النمو (Degrowth) الجذري. هي النظرية بالاقتصاد الكلي عم تتحدى البديهية الأساسية للاقتصاد المعاصر: يعني الافتراض بأنه التوسع اللانهائي للناتج المحلي الإجمالي (GDP) بيتوافق مع الحدود المتناهية للكوكب. المؤيدين لتراجع النمو عم يقولوا إنه الاستراتيجيات المعاصرة للتحديث البيئي، متل الرأسمالية الخضراء وفصل المسارات (Decoupling)، هي مجرد وهم بيئي. وعم يؤكدوا إنه الفصل المطلق—يعني عزل التوسع الاقتصادي رياضياً وحسابياً عن استخراج الموارد الكلي والتدهور البيئي—ما صار بنوب بالحجم أو السرعة المطلوبة لتجنب ضرب الاستقرار المناخي. بدال هاد الشي، إطار تراجع النمو بيدعو لانكماش مدروس ومخطط له باستهلاك المواد والطاقة بالدول الغنية، وإعادة هيكلة المجتمع من الجذور لتحط الأولوية لسلامة البشر والصحة البيئية على حساب تجميع رأس المال. بس المنتقدين عم يجادلوا بقوة إنه هاد الانكماش المدروس رح يعمل فوضى فورية بالاقتصاد الكلي، وبيؤدي لمعدلات بطالة كارثية، وانهيار بإيرادات الدولة، وضعف جيوسياسي حاد. وعم يؤكدوا إنه بلا الفائض المادي يلي بيطلعه النمو الاقتصادي التقليدي، رح يصير تمويل أبحاث العلوم المتقدمة وتحولات البنية التحتية المستدامة مستحيل مالياً. هاد الطريق المسدود بالفكر عم يوضح المعضلة الممنهجة الأساسية لعصرنا: هل فيهم المجتمعات الديمقراطية الحديثة يعيدوا هندسة مؤسساتهم الاقتصادية والاجتماعية بعيداً عن التبعية للنمو من دون ما يعملوا انهيار شامل بالسيستم، ولا رح نضل مربوطين بنموذج توسعي لحد ما انهيارات الحدود البيئية تفرض علينا انكماش عشوائي ومو محسبين إله؟", "title_ar": "تفكيك نموذج تراجع النمو الاقتصادي", "questions": [{"id": "q1", "stem": "What is the primary argument made by degrowth proponents against green capitalism strategies?", "choices": ["They assert that economic expansion can be easily insulated from resource consumption globally.", "They claim that conventional growth automatically eliminates geopolitical vulnerabilities for smaller economies.", "They maintain that absolute decoupling at the necessary scale and velocity is an environmental illusion.", "They argue that material throughput must be accelerated to protect public revenue systems."], "correct_index": 2}], "passage_ar": "مع استمرار الأزمات البيئية المتصاعدة بكشف الحدود الهيكلية لرأسمالية الكربون، صار النقاش الأكاديمي المحيط بالاقتصاد البيئي يركز أكتر وأكتر على نموذج تراجع النمو (Degrowth) الجذري. هي النظرية بالاقتصاد الكلي عم تتحدى البديهية الأساسية للاقتصاد المعاصر: يعني الافتراض بأنه التوسع اللانهائي للناتج المحلي الإجمالي (GDP) بيتوافق مع الحدود المتناهية للكوكب. المؤيدين لتراجع النمو عم يقولوا إنه الاستراتيجيات المعاصرة للتحديث البيئي، متل الرأسمالية الخضراء وفصل المسارات (Decoupling)، هي مجرد وهم بيئي. وعم يؤكدوا إنه الفصل المطلق—يعني عزل التوسع الاقتصادي رياضياً وحسابياً عن استخراج الموارد الكلي والتدهور البيئي—ما صار بنوب بالحجم أو السرعة المطلوبة لتجنب ضرب الاستقرار المناخي. بدال هاد الشي، إطار تراجع النمو بيدعو لانكماش مدروس ومخطط له باستهلاك المواد والطاقة بالدول الغنية، وإعادة هيكلة المجتمع من الجذور لتحط الأولوية لسلامة البشر والصحة البيئية على حساب تجميع رأس المال. بس المنتقدين عم يجادلوا بقوة إنه هاد الانكماش المدروس رح يعمل فوضى فورية بالاقتصاد الكلي، وبيؤدي لمعدلات بطالة كارثية، وانهيار بإيرادات الدولة، وضعف جيوسياسي حاد. وعم يؤكدوا إنه بلا الفائض المادي يلي بيطلعه النمو الاقتصادي التقليدي، رح يصير تمويل أبحاث العلوم المتقدمة وتحولات البنية التحتية المستدامة مستحيل مالياً. هاد الطريق المسدود بالفكر عم يوضح المعضلة الممنهجة الأساسية لعصرنا: هل فيهم المجتمعات الديمقراطية الحديثة يعيدوا هندسة مؤسساتهم الاقتصادية والاجتماعية بعيداً عن التبعية للنمو من دون ما يعملوا انهيار شامل بالسيستم، ولا رح نضل مربوطين بنموذج توسعي لحد ما انهيارات الحدود البيئية تفرض علينا انكماش عشوائي ومو محسبين إله؟", "vocabulary": ["axiom", "decoupling", "throughput", "impasse", "anthropocene"]}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (178, 1, 'reading', 'C2', 'lesson', 'Neural Interfaces and the Sanctity of Cognitive Liberty', '{"text": "The rapid clinical maturation of brain-computer interfaces (BCIs) and neuroprosthetics has transcended the domain of restorative medicine, projecting society into a challenging bioethical frontier centered on the sanctity of cognitive liberty. Modern neurotechnologies, which utilize advanced machine-learning algorithms to decode neural signals and translate mental processes into computational commands, offer revolutionary therapeutic solutions for individuals with severe motor impairments. However, as corporate enterprises aggressively invest in consumer-grade neural interfaces designed to enhance cognitive efficiency, optimize attention metrics, or facilitate direct digital communication, the boundary of personal identity and mental privacy becomes profoundly vulnerable. Bioethicists warn that the commercialization of neural data introduces unprecedented opportunities for algorithmic corporate surveillance, enabling corporations or state entities to monitor individual emotional states, subconscious cognitive preferences, and neural responses directly from the cerebral cortex. This capacity for neural monitoring introduces a fundamental epistemic threat to individual autonomy; when corporate data streams can access and manipulate cognitive processes before they even register in conscious human awareness, the concept of free will becomes compromised. Furthermore, the integration of algorithmic feedback loops that directly stimulate neural pathways to alter mood or behavior risks eroding the very boundary of individual agency, transforming human subjects into semi-automated nodes within decentralized digital networks. This systemic vulnerability necessitates a rigorous jurisdictional evolution: legal scholars contend that conventional human rights frameworks are completely inadequate to handle neurotechnological intrusion, demanding the immediate codification of specific ''neurorights'' designed to protect cognitive liberty, mental privacy, and psychological continuity from predatory commercial exploitation.", "topic": "ethics", "passage": "The rapid clinical maturation of brain-computer interfaces (BCIs) and neuroprosthetics has transcended the domain of restorative medicine, projecting society into a challenging bioethical frontier centered on the sanctity of cognitive liberty. Modern neurotechnologies, which utilize advanced machine-learning algorithms to decode neural signals and translate mental processes into computational commands, offer revolutionary therapeutic solutions for individuals with severe motor impairments. However, as corporate enterprises aggressively invest in consumer-grade neural interfaces designed to enhance cognitive efficiency, optimize attention metrics, or facilitate direct digital communication, the boundary of personal identity and mental privacy becomes profoundly vulnerable. Bioethicists warn that the commercialization of neural data introduces unprecedented opportunities for algorithmic corporate surveillance, enabling corporations or state entities to monitor individual emotional states, subconscious cognitive preferences, and neural responses directly from the cerebral cortex. This capacity for neural monitoring introduces a fundamental epistemic threat to individual autonomy; when corporate data streams can access and manipulate cognitive processes before they even register in conscious human awareness, the concept of free will becomes compromised. Furthermore, the integration of algorithmic feedback loops that directly stimulate neural pathways to alter mood or behavior risks eroding the very boundary of individual agency, transforming human subjects into semi-automated nodes within decentralized digital networks. This systemic vulnerability necessitates a rigorous jurisdictional evolution: legal scholars contend that conventional human rights frameworks are completely inadequate to handle neurotechnological intrusion, demanding the immediate codification of specific ''neurorights'' designed to protect cognitive liberty, mental privacy, and psychological continuity from predatory commercial exploitation.", "text_ar": "النضوج الطبي السريع لواجهات الدماغ والكمبيوتر (BCIs) والأطراف الاصطناعية العصبية تخطى مجال الطب الترميمي، وعم يرمي المجتمع بوش جبهة جديدة ومعقدة من الأخلاق الحيوية بتمحور حول قدسية الحرية الإدراكية والكرامة الفكرية. التكنولوجيات العصبية الحديثة، يلي عم تستخدم خوارزميات تعلم آلي متطورة لتفك تشفير الإشارات العصبية وتحول العمليات العقلية لأوامر حسابية، عم تقدم حلول علاجية ثورية للأشخاص يلي عندهم مشاكل حركية خطيرة. بس مع استثمار الشركات بقوة بواجهات عصبية مخصصة للمستهلكين العاديين، ومصممة لترفع الكفاءة الإدراكية، أو تحسن معايير الانتباه، أو تسهل التواصل الرقمي المباشر، صار الخط الفاصل للهوية الشخصية والخصوصية العقلية بمهب الريح وضعيف كتير. خبراء الأخلاق الحيوية عم يحذروا إنه تحويل البيانات العصبية لبضاعة تجارية بيفتح أبواب مسبوقة للمراقبة الخوارزمية من قبل الشركات، وهاد بيسمح للشركات أو جهات الدولة تراقب الحالات العاطفية للأفراد، وتفضيلاتهم الفكرية اللاواعية، واستجاباتهم العصبية مباشرة من القشرة المخية. وهي القدرة على المراقبة العصبية بتعمل تهديد معرفي أساسي للاستقلال الفردية؛ لما تصير تدفقات بيانات الشركات قادرة توصل وتتلاعب بالعمليات الإدراكية قبل ما تظهر بوعي الإنسان البشري أصلاً، بصير مفهوم الإرادة الحرة بخطر. وكمان، دمج حلقات التغذية الراجعة الخوارزمية يلي بتحفز المسارات العصبية مباشرة لتغير المزاج أو السلوك عم يخاطر بأكل حدود الإرادة الفردية، ويحول البشر لعقد مؤتمتة جزئياً بقلب شبكات رقمية لامركزية. هاد الضعف الهيكلي بيفضل يطلب تطور قانوني حازم: باحثين بالقانون عم يؤكدوا إنه أطر حقوق الإنسان التقليدية ماله كافية بنوب للتعامل مع التدخل التكنولوجي العصبي، وعم يطالبوا بالتدوين الفوري لـ ''حقوق عصبية'' محددة مصممة لتحمي الحرية الإدراكية، والخصوصية العقلية، والاستمرارية النفسية من الاستغلال التجاري الجشع.", "title_ar": "الواجهات العصبية وقدسية الحرية الإدراكية", "questions": [{"id": "q1", "stem": "What primary bioethical risk is identified with the commercialization of consumer-grade neural interfaces?", "choices": ["The permanent degradation of advanced machine-learning algorithms within clinical infrastructure.", "The complete replacement of decentralized digital networks with low-context motor impairment therapies.", "An absolute physical breakdown of the human cerebral cortex due to superconducting refrigerators.", "The vulnerability of personal identity and mental privacy to corporate surveillance and manipulation."], "correct_index": 3}], "passage_ar": "النضوج الطبي السريع لواجهات الدماغ والكمبيوتر (BCIs) والأطراف الاصطناعية العصبية تخطى مجال الطب الترميمي، وعم يرمي المجتمع بوش جبهة جديدة ومعقدة من الأخلاق الحيوية بتمحور حول قدسية الحرية الإدراكية والكرامة الفكرية. التكنولوجيات العصبية الحديثة، يلي عم تستخدم خوارزميات تعلم آلي متطورة لتفك تشفير الإشارات العصبية وتحول العمليات العقلية لأوامر حسابية، عم تقدم حلول علاجية ثورية للأشخاص يلي عندهم مشاكل حركية خطيرة. بس مع استثمار الشركات بقوة بواجهات عصبية مخصصة للمستهلكين العاديين، ومصممة لترفع الكفاءة الإدراكية، أو تحسن معايير الانتباه، أو تسهل التواصل الرقمي المباشر، صار الخط الفاصل للهوية الشخصية والخصوصية العقلية بمهب الريح وضعيف كتير. خبراء الأخلاق الحيوية عم يحذروا إنه تحويل البيانات العصبية لبضاعة تجارية بيفتح أبواب مسبوقة للمراقبة الخوارزمية من قبل الشركات، وهاد بيسمح للشركات أو جهات الدولة تراقب الحالات العاطفية للأفراد، وتفضيلاتهم الفكرية اللاواعية، واستجاباتهم العصبية مباشرة من القشرة المخية. وهي القدرة على المراقبة العصبية بتعمل تهديد معرفي أساسي للاستقلال الفردية؛ لما تصير تدفقات بيانات الشركات قادرة توصل وتتلاعب بالعمليات الإدراكية قبل ما تظهر بوعي الإنسان البشري أصلاً، بصير مفهوم الإرادة الحرة بخطر. وكمان، دمج حلقات التغذية الراجعة الخوارزمية يلي بتحفز المسارات العصبية مباشرة لتغير المزاج أو السلوك عم يخاطر بأكل حدود الإرادة الفردية، ويحول البشر لعقد مؤتمتة جزئياً بقلب شبكات رقمية لامركزية. هاد الضعف الهيكلي بيفضل يطلب تطور قانوني حازم: باحثين بالقانون عم يؤكدوا إنه أطر حقوق الإنسان التقليدية ماله كافية بنوب للتعامل مع التدخل التكنولوجي العصبي، وعم يطالبوا بالتدوين الفوري لـ ''حقوق عصبية'' محددة مصممة لتحمي الحرية الإدراكية، والخصوصية العقلية، والاستمرارية النفسية من الاستغلال التجاري الجشع.", "vocabulary": ["maturation", "prosthetics", "surveillance", "autonomy", "codification"]}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (179, 1, 'reading', 'C2', 'lesson', 'Sovereign AI Infrastructure and Regulatory Overreach', '{"text": "The ongoing policy debate surrounding the regulation of foundational artificial intelligence architectures within Europe illustrates the fundamental systemic tension between technological sovereignty and legislative overreach. As transnational technology corporations solidify their monopolistic hegemony over large-scale generative models and computational infrastructure, European regulatory bodies have introduced comprehensive legal frameworks, such as the EU AI Act, to mitigate existential risks and preserve data privacy. This pioneering legislation utilizes a risk-based tier system, mandating absolute architectural transparency, algorithmic auditing, and strict copyright compliance for high-risk deployments. Proponents of this centralized regulatory approach assert that strict statutory boundaries are essential to shield citizens from automated discrimination, systemic disinformation, and corporate data exploitation. However, a growing faction of technology strategists, open-source advocates, and digital economists contends that this rigid legislative paradigm inadvertently sabotages regional innovation, creating insurmountable bureaucratic hurdles for local start-ups and independent research frameworks. They argue that by imposing criminal liabilities and expensive compliance protocols on open-source software development, the state effectively centralizes technological control into the hands of a few dominant American and Asian tech conglomerates who possess the capital to navigate administrative compliance. Consequently, this dynamic could result in an ironic geopolitical outcome: a legislative framework designed to guarantee digital autonomy might solidify Europe’s technological dependency on foreign proprietary platforms. Moving forward, policymakers face the complex task of calibrating enforcement mechanisms so that ethical guardrails protect civic space without completely freezing the domestic capital investment necessary to construct sovereign, locally adapted computational infrastructure.", "topic": "policy debate", "passage": "The ongoing policy debate surrounding the regulation of foundational artificial intelligence architectures within Europe illustrates the fundamental systemic tension between technological sovereignty and legislative overreach. As transnational technology corporations solidify their monopolistic hegemony over large-scale generative models and computational infrastructure, European regulatory bodies have introduced comprehensive legal frameworks, such as the EU AI Act, to mitigate existential risks and preserve data privacy. This pioneering legislation utilizes a risk-based tier system, mandating absolute architectural transparency, algorithmic auditing, and strict copyright compliance for high-risk deployments. Proponents of this centralized regulatory approach assert that strict statutory boundaries are essential to shield citizens from automated discrimination, systemic disinformation, and corporate data exploitation. However, a growing faction of technology strategists, open-source advocates, and digital economists contends that this rigid legislative paradigm inadvertently sabotages regional innovation, creating insurmountable bureaucratic hurdles for local start-ups and independent research frameworks. They argue that by imposing criminal liabilities and expensive compliance protocols on open-source software development, the state effectively centralizes technological control into the hands of a few dominant American and Asian tech conglomerates who possess the capital to navigate administrative compliance. Consequently, this dynamic could result in an ironic geopolitical outcome: a legislative framework designed to guarantee digital autonomy might solidify Europe’s technological dependency on foreign proprietary platforms. Moving forward, policymakers face the complex task of calibrating enforcement mechanisms so that ethical guardrails protect civic space without completely freezing the domestic capital investment necessary to construct sovereign, locally adapted computational infrastructure.", "text_ar": "النقاش السياسي المستمر المحيط بتنظيم بنى الذكاء الاصطناعي الأساسية بأوروبا عم يوضح التوتر الممنهج والأساسي بين السيادة التكنولوجية والتغول التنظيمي القانوني. ومع تثبيت شركات التكنولوجيا عابرة القارات لهيمنتها الاحتكارية على النماذج التوليدية ضخمة الحجم والبنية التحتية الحسابية، طرحت الهيئات التنظيمية الأوروبية أطراً قانونية شاملة، متل قانون الذكاء الاصطناعي الأوروبي (EU AI Act)، للتخفيف من المخاطر الوجودية وحماية خصوصية البيانات. هاد التشريع الرائد بيستخدم سيستم طبقات قائم ع المخاطر، وبيفرض شفافية كاملة بالبنية، وتدقيقاً خوارزمياً، وامتثالاً صارماً لحقوق النشر بالاستخدامات عالية الخطورة. المؤيدين لهاد الأسلوب الرقابي المركزي عم يؤكدوا إنه الحدود القانونية الصارمة أساسية لحماية المواطنين من التمييز المؤتمت، والتضليل الممنهج، واستغلال الشركات للبيانات. بس في مجموعة عم تكبر من استراتيجيي التكنولوجيا، والمدافعين عن المصادر المفتوحة، وعلماء الاقتصاد الرقمي عم يقولوا إنه هاد النموذج التشريعي الناشف عم يخرب من دون ما يقصد الابتكار الإقليمي، وعم يعمل عوائق بيروقراطية ما بتتخطى بوش الشركات الناشئة المحلية وأطر الأبحاث المستقلة. وعم يجادلوا إنه فرض مسؤوليات جنائية وبروتوكولات امتثال غالية كتير على تطوير البرمجيات مفتوحة المصدر عم يخلي الدولة تثبت وتمركز التحكم التكنولوجي بإيدين كم عائلة شركات تكنولوجية أميركية وآسيوية مهيمنة بتملك المال لتخلص هي المعاملات الإدارية. وبناءً على هاد الشي، هي الحركية ممكن تؤدي لنتيجة جيوسياسية فيها سخرية: يعني إطار تشريعي تصمم ليضمن الاستقلال الرقمي ممكن يثبت ويؤكد تبعية أوروبا التكنولوجية لمنصات أجنبية مملوكة لشركات برّانية. وإذا طلعنا لـ قدام، صناع القرار عم يواجهوا المهمة المعقدة لمعايرة آليات التطبيق كرمال تضمن الحمايات الأخلاقية صيانة الفضاء المدني من دون ما تجمد بالكامل استثمار الرساميل المحلية الضرورية لبناء بنية تحتية حسابية سيادية ومعدلة محلياً.", "title_ar": "بنية الذكاء الاصطناعي السيادية والتغول التنظيمي القانوني", "questions": [{"id": "q1", "stem": "What ironic geopolitical outcome do critics of the EU AI Act fear might occur?", "choices": ["That rigid legislation meant to guarantee digital autonomy will solidify dependency on foreign platforms.", "The total legal complete elimination of copyright compliance across open-source software platforms.", "An immediate migration of transnational tech conglomerates to central European municipal hubs.", "The absolute centralization of domestic capital investments into small local start-ups."], "correct_index": 0}], "passage_ar": "النقاش السياسي المستمر المحيط بتنظيم بنى الذكاء الاصطناعي الأساسية بأوروبا عم يوضح التوتر الممنهج والأساسي بين السيادة التكنولوجية والتغول التنظيمي القانوني. ومع تثبيت شركات التكنولوجيا عابرة القارات لهيمنتها الاحتكارية على النماذج التوليدية ضخمة الحجم والبنية التحتية الحسابية، طرحت الهيئات التنظيمية الأوروبية أطراً قانونية شاملة، متل قانون الذكاء الاصطناعي الأوروبي (EU AI Act)، للتخفيف من المخاطر الوجودية وحماية خصوصية البيانات. هاد التشريع الرائد بيستخدم سيستم طبقات قائم ع المخاطر، وبيفرض شفافية كاملة بالبنية، وتدقيقاً خوارزمياً، وامتثالاً صارماً لحقوق النشر بالاستخدامات عالية الخطورة. المؤيدين لهاد الأسلوب الرقابي المركزي عم يؤكدوا إنه الحدود القانونية الصارمة أساسية لحماية المواطنين من التمييز المؤتمت، والتضليل الممنهج، واستغلال الشركات للبيانات. بس في مجموعة عم تكبر من استراتيجيي التكنولوجيا، والمدافعين عن المصادر المفتوحة، وعلماء الاقتصاد الرقمي عم يقولوا إنه هاد النموذج التشريعي الناشف عم يخرب من دون ما يقصد الابتكار الإقليمي، وعم يعمل عوائق بيروقراطية ما بتتخطى بوش الشركات الناشئة المحلية وأطر الأبحاث المستقلة. وعم يجادلوا إنه فرض مسؤوليات جنائية وبروتوكولات امتثال غالية كتير على تطوير البرمجيات مفتوحة المصدر عم يخلي الدولة تثبت وتمركز التحكم التكنولوجي بإيدين كم عائلة شركات تكنولوجية أميركية وآسيوية مهيمنة بتملك المال لتخلص هي المعاملات الإدارية. وبناءً على هاد الشي، هي الحركية ممكن تؤدي لنتيجة جيوسياسية فيها سخرية: يعني إطار تشريعي تصمم ليضمن الاستقلال الرقمي ممكن يثبت ويؤكد تبعية أوروبا التكنولوجية لمنصات أجنبية مملوكة لشركات برّانية. وإذا طلعنا لـ قدام، صناع القرار عم يواجهوا المهمة المعقدة لمعايرة آليات التطبيق كرمال تضمن الحمايات الأخلاقية صيانة الفضاء المدني من دون ما تجمد بالكامل استثمار الرساميل المحلية الضرورية لبناء بنية تحتية حسابية سيادية ومعدلة محلياً.", "vocabulary": ["hegemony", "auditing", "insurmountable", "liabilities", "conglomerates"]}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (180, 1, 'reading', 'C2', 'lesson', 'Linguistic Drift and Polyphonic Identity Synthesis', '{"text": "The long-term sociolinguistic evolution of second-generation diasporic communities within Western European metropolises offers a fascinating study in linguistic drift and polyphonic identity synthesis. Within these urban spaces, young individuals continuously navigate a dense communicative ecosystem, synthesizing the syntactic structures of their heritage languages—such as Syrian Arabic—with the morphology and lexicon of their host societies'' standard tongues, like German or English. Rather than representing a corrupted or incomplete mastery of either idiom, contemporary sociolinguists interpret this fluid code-switching and hybrid speech production as the emergence of a sophisticated third space. This linguistic hybridity functions as an active strategy for individual and collective agency, allowing youth to construct a localized, syncretic identity that consciously resists both majoritarian cultural erasure and the rigid traditionalism of diasporic enclaves. Through the subversion of standard monolingual registers, these speakers develop a rich polyphonic repertoire that serves as an expressive medium for their unique existential positionality. However, the institutional recognition of these hybrid communication models remains a highly contested domain within formal education and employment spheres. National pedagogical institutions routinely prioritize standardized language competence as the absolute metric for socio-economic mobility, pathologizing hybrid structures as indicators of linguistic deficit or cognitive confusion. This institutional rigidity creates an intellectual impasse: while the lived reality of multicultural urban centers requires flexible, multifaceted communicative adaptability, systemic evaluation mechanisms remain bound to an antiquated monolingual ideology. Ultimately, dismantling these systemic biases requires an epistemological shift that validates polyphonic hybridity not as a deficit, but as a form of socio-cultural capital essential for cross-cultural communication.", "topic": "cross-cultural communication", "passage": "The long-term sociolinguistic evolution of second-generation diasporic communities within Western European metropolises offers a fascinating study in linguistic drift and polyphonic identity synthesis. Within these urban spaces, young individuals continuously navigate a dense communicative ecosystem, synthesizing the syntactic structures of their heritage languages—such as Syrian Arabic—with the morphology and lexicon of their host societies'' standard tongues, like German or English. Rather than representing a corrupted or incomplete mastery of either idiom, contemporary sociolinguists interpret this fluid code-switching and hybrid speech production as the emergence of a sophisticated third space. This linguistic hybridity functions as an active strategy for individual and collective agency, allowing youth to construct a localized, syncretic identity that consciously resists both majoritarian cultural erasure and the rigid traditionalism of diasporic enclaves. Through the subversion of standard monolingual registers, these speakers develop a rich polyphonic repertoire that serves as an expressive medium for their unique existential positionality. However, the institutional recognition of these hybrid communication models remains a highly contested domain within formal education and employment spheres. National pedagogical institutions routinely prioritize standardized language competence as the absolute metric for socio-economic mobility, pathologizing hybrid structures as indicators of linguistic deficit or cognitive confusion. This institutional rigidity creates an intellectual impasse: while the lived reality of multicultural urban centers requires flexible, multifaceted communicative adaptability, systemic evaluation mechanisms remain bound to an antiquated monolingual ideology. Ultimately, dismantling these systemic biases requires an epistemological shift that validates polyphonic hybridity not as a deficit, but as a form of socio-cultural capital essential for cross-cultural communication.", "text_ar": "التطور اللغوي والاجتماعي على المدى الطويل لمجتمعات الجيل الثاني من المغتربين بقلب المدن الأوروبية الغربية الكبيرة بيقدم دراسة بتجنن بالانزياح اللغوي وتركيب الهوية متعددة الأصوات. وبقلب هي المساحات الحضرية، الشباب عم يمشوا بشكل مستمر ببيئة تواصل كثيفة، وعم يدمجوا التراكيب النحوية للغاتهم الأصلية—متل العربي السوري—مع الصرف والمفردات للغات المجتمعات المضيفة المعيارية، متل الألماني أو الإنكليزي. وبدل ما ينشاف هاد الشي كإتقان مشوه أو ناقص لأي من اللغتين، علماء اللغة الاجتماعيين المعاصرين عم يفسروا هاد التبديل المرن بين اللغات وإنتاج الكلام الهجين على أساس إنه ظهور لـ مساحة تالتة متطورة وذكية. هاد الهجين اللغوي بيشتغل كاستراتيجية نشطة للإرادة الفردية والجماعية، وبيسمح للشباب يبنوا هوية محلية مخلطة بتقاوم بوعي المحو الثقافي من الأغلبية وكمان الجمود التقليدي الناشف بقلب تجمعات المغتربين المنغلقة. ومن خلال قلب أنظمة اللغة الوحدة المعيارية، هدول المتحدثين عم يطوروا مخزون لغوي متعدد الأصوات بيشتغل كوسيط تعبيري لوضعهم الوجودي الفريد. بس الاعتراف المؤسساتي بنماذج التواصل الهجينة هي عم يضل مجال عليه خلاف كبير بقطاعات التعليم الرسمي والشغل. المؤسسات التعليمية الوطنية عم تحط الأولوية دايماً لكفاءة اللغة الموحدة كمعيار مطلق للحركة الاجتماعية والاقتصادية، وعم تعامل التراكيب الهجينة كحالة مرضية وكمؤشر على النقص اللغوي أو التشتت الفكري. هاد الجمود المؤسساتي بيعمل طريق مسدود بالفكر: بالوقت يلي الواقع المعاش بالمراكز الحضرية متعددة الثقافات بيطلب مرونة وقدرة على التأقلم التواصلي متعدد الجوانب، آليات التقييم الممنهجة لساتها مربوطة بأيديولوجية اللغة الوحدة الموديل قديم كتير. بالنهاية، تكسير هي الانحيازات بقلب السيستم بده تحول معرفي بيعترف بالهجين متعدد الأصوات ماله عيب ونقص، بل كنوع من رأس المال الاجتماعي والثقافي الأساسي للتواصل بين الثقافات هلق.", "title_ar": "الانزياح اللغوي وتركيب الهوية متعددة الأصوات", "questions": [{"id": "q1", "stem": "How do contemporary sociolinguists primarily evaluate fluid code-switching and hybrid speech production among diasporic youth?", "choices": ["As a corrupted and incomplete mastery of host languages that limits socio-economic mobility directly.", "As the emergence of a sophisticated third space and an active strategy for individual and collective agency.", "As a clear cognitive indicator of structural linguistic deficit and absolute mental confusion.", "As a direct structural violation of the standard language registers mandated by national institutions."], "correct_index": 1}], "passage_ar": "التطور اللغوي والاجتماعي على المدى الطويل لمجتمعات الجيل الثاني من المغتربين بقلب المدن الأوروبية الغربية الكبيرة بيقدم دراسة بتجنن بالانزياح اللغوي وتركيب الهوية متعددة الأصوات. وبقلب هي المساحات الحضرية، الشباب عم يمشوا بشكل مستمر ببيئة تواصل كثيفة، وعم يدمجوا التراكيب النحوية للغاتهم الأصلية—متل العربي السوري—مع الصرف والمفردات للغات المجتمعات المضيفة المعيارية، متل الألماني أو الإنكليزي. وبدل ما ينشاف هاد الشي كإتقان مشوه أو ناقص لأي من اللغتين، علماء اللغة الاجتماعيين المعاصرين عم يفسروا هاد التبديل المرن بين اللغات وإنتاج الكلام الهجين على أساس إنه ظهور لـ مساحة تالتة متطورة وذكية. هاد الهجين اللغوي بيشتغل كاستراتيجية نشطة للإرادة الفردية والجماعية، وبيسمح للشباب يبنوا هوية محلية مخلطة بتقاوم بوعي المحو الثقافي من الأغلبية وكمان الجمود التقليدي الناشف بقلب تجمعات المغتربين المنغلقة. ومن خلال قلب أنظمة اللغة الوحدة المعيارية، هدول المتحدثين عم يطوروا مخزون لغوي متعدد الأصوات بيشتغل كوسيط تعبيري لوضعهم الوجودي الفريد. بس الاعتراف المؤسساتي بنماذج التواصل الهجينة هي عم يضل مجال عليه خلاف كبير بقطاعات التعليم الرسمي والشغل. المؤسسات التعليمية الوطنية عم تحط الأولوية دايماً لكفاءة اللغة الموحدة كمعيار مطلق للحركة الاجتماعية والاقتصادية، وعم تعامل التراكيب الهجينة كحالة مرضية وكمؤشر على النقص اللغوي أو التشتت الفكري. هاد الجمود المؤسساتي بيعمل طريق مسدود بالفكر: بالوقت يلي الواقع المعاش بالمراكز الحضرية متعددة الثقافات بيطلب مرونة وقدرة على التأقلم التواصلي متعدد الجوانب، آليات التقييم الممنهجة لساتها مربوطة بأيديولوجية اللغة الوحدة الموديل قديم كتير. بالنهاية، تكسير هي الانحيازات بقلب السيستم بده تحول معرفي بيعترف بالهجين متعدد الأصوات ماله عيب ونقص، بل كنوع من رأس المال الاجتماعي والثقافي الأساسي للتواصل بين الثقافات هلق.", "vocabulary": ["drift", "polyphonic", "syncretic", "enclaves", "pathologizing"]}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (181, 1, 'listening', 'A1', 'lesson', 'Meeting a New Classmate', '{"topic": "self-introduction", "title_ar": "التقاء برفيقة صف جديدة", "questions": [{"id": "q1", "stem": "Where is Maya from originally?", "choices": ["Syria", "Germany", "Berlin", "Frankfurt"], "correct_index": 0}], "situation": "A student introduces herself on the first day of an English class in Berlin.", "vocabulary": ["name", "live", "student", "speak", "meet"], "instructions": "A student introduces herself on the first day of an English class in Berlin.", "situation_ar": "طالبة عم تعرف عن حالها بأول يوم بصف الإنكليزي ببرلين.", "audio_transcript": "Hello! My name is Maya. I am from Homs, Syria. Now, I live in Berlin, Germany. I am twenty-two years old. I am a new student here. I speak Arabic and a little English. Nice to meet you all!"}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (182, 1, 'listening', 'A1', 'lesson', 'Talking About Family', '{"topic": "family", "title_ar": "عم نحكي عن العيلة", "questions": [{"id": "q1", "stem": "How old is the speaker''s brother?", "choices": ["Twenty-six years old", "Ten years old", "Three years old", "Seven years old"], "correct_index": 1}], "situation": "A young man is showing a picture of his family to his German flatmate.", "vocabulary": ["photo", "family", "father", "mother", "brother"], "instructions": "A young man is showing a picture of his family to his German flatmate.", "situation_ar": "شاب عم يفرجي صورة عيلته لرفيقه ألماني بالسكن.", "audio_transcript": "Look at this photo, Max. This is my family in Damascus. Here is my father. He is a tall man. This is my mother. She has green eyes. I have one small brother. He is ten. I miss them very much."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (183, 1, 'listening', 'A1', 'lesson', 'My Small Flat', '{"topic": "home", "title_ar": "شقتي الصغيرة", "questions": [{"id": "q1", "stem": "Who does the speaker share the kitchen with?", "choices": ["His mother", "A friendly doctor", "Two German students", "Nobody"], "correct_index": 2}], "situation": "An international student describes his room in a shared apartment over the phone.", "vocabulary": ["room", "clean", "quiet", "bed", "share"], "instructions": "An international student describes his room in a shared apartment over the phone.", "situation_ar": "طالب مغترب عم يوصف غرفته بشقة مشتركة ع التلفون.", "audio_transcript": "Hi Mom! My new room is small. It is clean and quiet. I have a white bed and a big desk. The kitchen is nice. I share it with two German students. They are very friendly. I like it here."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (184, 1, 'listening', 'A1', 'lesson', 'Morning in the City', '{"topic": "daily routine", "title_ar": "الصبح بالمدينة", "questions": [{"id": "q1", "stem": "What does the girl drink in the morning?", "choices": ["Hot coffee", "Black tea", "Cold water", "Warm milk"], "correct_index": 3}], "situation": "A girl explains what she does every morning before going to school.", "vocabulary": ["morning", "drink", "walk", "train", "early"], "instructions": "A girl explains what she does every morning before going to school.", "situation_ar": "بنت عم تشرح شو عم تعمل كل يوم الصبح قبل ما تروح عالمدرسة.", "audio_transcript": "I get up at six o''clock every morning. I drink warm milk. Then, I walk to the train station. I take the red train at seven. I arrive at my school early. My class starts at eight o''clock."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (185, 1, 'listening', 'A1', 'lesson', 'Buying Breakfast', '{"topic": "food", "title_ar": "عم اشتري فطور", "questions": [{"id": "q1", "stem": "How much does the customer''s food cost?", "choices": ["Four euros", "Five euros", "Two euros", "Eight euros"], "correct_index": 0}], "situation": "A customer orders some food at a local German bakery.", "vocabulary": ["fresh", "bread", "sweet", "cake", "bakery"], "instructions": "A customer orders some food at a local German bakery.", "situation_ar": "زبون عم يطلب أكل بفرن محلي بألمانيا.", "audio_transcript": "Good morning! I want some fresh bread, please. Yes, the brown bread. I also want one sweet apple cake. How much is it? Four euros? The bakery is clean. Here is five euros. Thank you very much! I love this place."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (186, 1, 'listening', 'A1', 'lesson', 'Buying a Train Ticket', '{"topic": "numbers", "title_ar": "شرا تكت قطار", "questions": [{"id": "q1", "stem": "What is the cost of one train ticket?", "choices": ["Thirty euros", "Thirteen euros", "Twenty-six euros", "Two euros"], "correct_index": 1}], "situation": "A student asks a transit worker for ticket prices at a train station in Munich.", "vocabulary": ["ticket", "cheap", "total", "train", "fast"], "instructions": "A student asks a transit worker for ticket prices at a train station in Munich.", "situation_ar": "طالب عم يسأل موظف مواصلات عن أسعار التكتات بمحطة القطار بميونيخ.", "audio_transcript": "Excuse me! I need a ticket to Munich, please. Is it cheap? Oh, it is thirteen euros. Okay. I need two tickets for my friends. That is twenty-six euros total. Here is thirty euros. The train is fast. I am happy."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (187, 1, 'listening', 'A1', 'lesson', 'Asking for the Bus', '{"topic": "public transport", "title_ar": "عم اسأل عن الباص", "questions": [{"id": "q1", "stem": "Which bus number must the speaker take?", "choices": ["Bus number ten", "The blue bus", "Bus number nine", "Bus number seven"], "correct_index": 2}], "situation": "A lost commuter asks someone about the bus route to the city center.", "vocabulary": ["blue", "bus", "center", "understand", "station"], "instructions": "A lost commuter asks someone about the bus route to the city center.", "situation_ar": "واحد ضايع عم يسأل حدا عن طريق الباص لمركز المدينة.", "audio_transcript": "Hello! Does the blue bus go to the city center? Oh, it does not? Okay, I understand. I must take bus number nine. Does it arrive at ten o''clock? Yes? Great! The station is near. I see it now. Thank you!"}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (354, 1, 'speaking', 'C2', 'speaking_prompt', 'The Geopolitical Scramble for Quantum Sovereignty', '{"topic": "advanced science", "prompt": "Discuss the geopolitical and macroeconomic implications of fault-tolerant quantum computing scales. Analyze how quantum capabilities invalidate public-key encryption infrastructure (RSA) and evaluate the material constraints shaping technocratic blocs.", "title_ar": "السباق الجيوسياسي على السيادة الكمية", "prompt_ar": "ناقش العواقب الجيوسياسية والاقتصادية الكبيرة لقرب الوصول لحوسبة كمية قادرة على تصحيح الأخطاء. حلل شلون هي القدرات الكمية عم تطير وتلغي أنظمة التشفير التقليدية (RSA)، وقيم شروط المواد النادرة يلي عم تقسم العالم لتكتلات تكنوقراطية هلق.", "min_seconds": 120, "question_type": "discuss", "example_answer": "The impending technical realization of fault-tolerant quantum computing architectures at scale has ignited an aggressive international race for quantum sovereignty, fundamentally redefining the parameters of macroeconomic stability and national security. Unlike conventional semiconductor innovations, which merely deliver incremental upgrades to computational velocity, quantum architecture leverages superposition and entanglement to execute complex calculations at speeds that completely invalidate existing cryptographic standards. The primary geopolitical threat centers directly upon the absolute vulnerability of current public-key encryption infrastructure, specifically RSA algorithms, which safeguard global financial transactions, state intelligence networks, and critical industrial utilities. A sovereign state that achieves mathematical supremacy via a scalable quantum system would possess the asymmetric capacity to decrypt legacy data retroactively, thereby entirely neutralizing the strategic intelligence shields of foreign adversaries. Recognizing this systemic risk, European research institutes and regulatory frameworks are accelerating the development of post-quantum cryptography (PQC) standards to fortify critical digital infrastructure before decryption capabilities fully materialize. However, the transition to quantum-resistant ecosystems is profoundly complicated by the sheer material scarcity of essential components, such as high-purity superconducting materials and specialized dilution refrigeration hardware. Consequently, the geopolitical landscape is splintering into competitive technocratic blocs, with major global powers implementing aggressive export controls on quantum hardware and intellectual capital to prevent strategic spillover. This intense imperative forces smaller economies to navigate complex technological dependencies, demonstrating that future geopolitical autonomy will depend heavily upon a nation''s internal capacity to sustain a localized quantum infrastructure, independent of transnational supply chains."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (355, 1, 'speaking', 'C2', 'speaking_prompt', 'Federalist Friction in Decarbonization Policies', '{"topic": "policy debate", "prompt": "Evaluate how supranational environmental mandates create structural friction within federalized constitutional frameworks. Discuss the institutional tug-of-war over natural resource allocation and how regional legislative leverage delays transition timelines.", "title_ar": "الاحتكاك الفيدرالي بسياسات إزالة الكربون", "prompt_ar": "قيم شلون الأوامر البيئية الأوروبية العابرة للدول عم تعمل احتكاك هيكلي وقانوني بقلب الأنظمة الدستورية الفيدرالية هلق. شو رأيك بحبل الشد بين المؤسسات على توزيع الموارد، وشلون عم تستغل الولايات الإقليمية قدرتها التشريعية لتأخر خطط التحول؟", "min_seconds": 120, "question_type": "opinion", "example_answer": "The operationalization of supranational climate mitigation policies within heavily federalized European constitutional frameworks frequently reveals deep structural frictions between centralized mandates and regional statutory autonomy. When the European Union issues aggressive decarbonization directives, the ultimate implementation of these statutory laws relies upon complex administrative multi-level governance systems, nowhere more pronounced than within the German federal structure. In this framework, regional states (Länder) possess substantial constitutional authority over regional economic planning, energy infrastructure regulation, and natural resource allocation. This decentralization inevitably generates an institutional tug-of-war, as regional administrations frequently seek to protect localized industrial sectors from the economic disruption associated with rapid ecological transitions. For instance, regions dependent upon heavy manufacturing or automotive industries routinely utilize their legislative leverage to systematically delay or dilute national carbon reduction targets, citing immediate concerns regarding labor market destabilization and regional economic decline. Constitutional scholars observe that this structural friction is often exacerbated by profound legal ambiguity concerning the precise boundary of federal versus regional jurisdiction over sustainable architecture subsidies and grid expansion projects. Had central administrations established more binding consensus mechanisms prior to enacting legislative overhauls, the integration of renewable energy networks would have proceeded with substantially fewer judicial challenges. Until these constitutional boundaries are calibrated through clear legal precedents, climate governance will remain a bitterly contested arena where ecological necessity continuously clashes with the entrenched mechanics of federalist distribution."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (356, 1, 'speaking', 'C2', 'speaking_prompt', 'Epistemic Dissonance in Corporate Assimilation', '{"topic": "cross-cultural communication", "prompt": "Discuss the communicative and organizational misattunement that occurs when diverse global workforces integrate into consensus-driven corporate systems. Analyze the impact of unvarnished direct critique on psychological safety.", "title_ar": "التنافر المعرفي بالاندماج بقلب الشركات", "prompt_ar": "ناقش عدم الانسجام التواصلي والتنظيمي يلي عم يصير لما تندمج أيدي عاملة عالمية ومتنوعة بقلب أنظمة الشركات القائمة ع الإجماع هلق. شو تأثير النقد المباشر والناشف بوضوح ع الأمان النفسي للموظف الأجنبي؟", "min_seconds": 120, "question_type": "discuss", "example_answer": "The integration of diverse global workforces within the distinct institutional landscape of Rhineland capitalism frequently precipitates a complex form of epistemic dissonance, radically altering standard communication protocols and organizational behavior. In multinational corporate environments throughout Central Europe, corporate governance is traditionally predicated upon consensus-driven deliberation, high-context statutory documentation, and a meticulous separation between professional execution and personal identification. When international professional candidates, trained within entirely divergent communicative and organizational paradigms, enter this systemic matrix, linguistic proficiency alone proves completely insufficient to guarantee successful integration. Cross-cultural communication experts observe that structural friction points often manifest not during explicit legal disputes, but during localized corporate rituals—such as performance feedback evaluations, project presentations, and consensus-building meetings. For instance, the high reliance upon direct, unvarnished critique characteristic of central European corporate communication can be perceived by international employees as deeply destabilizing or personally hostile, thereby rapidly eroding psychological safety. Conversely, localized managers often misinterpret indirect communication styles or relational problem-solving approaches as a distinct lack of professional transparency or intellectual autonomy. This mutual misattunement demonstrates that corporate assimilation requires far more than superficial sensitivity training; it necessitates a comprehensive re-engineering of communication channels that explicitly validates communicative diversity as a cognitive asset. Until corporate leadership teams move beyond superficial diversity metrics, the latent intellectual capital of global talent will remain structurally constrained by localized behavioral models."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (188, 1, 'listening', 'A1', 'lesson', 'Going to the Park', '{"topic": "daily city life", "title_ar": "مشوار عالجنينة", "questions": [{"id": "q1", "stem": "What animal does the speaker''s friend have at the park?", "choices": ["A white cat", "A green bird", "No animal", "A black dog"], "correct_index": 3}], "situation": "Two friends talk about going outside on a sunny afternoon in Hamburg.", "vocabulary": ["weather", "beautiful", "park", "walk", "dog"], "instructions": "Two friends talk about going outside on a sunny afternoon in Hamburg.", "situation_ar": "رفقات اثنين عم يحكوا عن مشوار لبرّا بعد الظهر بيوم مشمس بهامبورغ.", "audio_transcript": "The weather is very beautiful today. Let us go to the green park. We can walk for one hour. I want to see the trees and flowers. My friend Ahmad is there. He has a black dog. Come on! I love sunny days."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (189, 1, 'listening', 'A1', 'lesson', 'Lunch at the Cafe', '{"topic": "food", "title_ar": "الغدا بالقهوة", "questions": [{"id": "q1", "stem": "What drink does the customer order after finding out there is no juice?", "choices": ["Cold water", "Hot coffee", "White milk", "Black tea"], "correct_index": 0}], "situation": "A worker talks to a waiter about ordering lunch during a short afternoon break.", "vocabulary": ["hungry", "chicken", "salad", "orange", "water"], "instructions": "A worker talks to a waiter about ordering lunch during a short afternoon break.", "situation_ar": "موظف عم يحكي مع غرسون عن طلب الغدا خلال استراحة قصيرة بعد الظهر.", "audio_transcript": "Hello! I am hungry. I want a small chicken salad, please. Do you have fresh orange juice? No? Okay, give me cold water. How much is the salad? Six euros? That is very cheap. Here is the money. Thank you very much!"}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (190, 1, 'listening', 'A1', 'lesson', 'Welcome to the Shared Flat', '{"topic": "self-introduction", "title_ar": "أهلاً فيك بالشقة المشتركة", "questions": [{"id": "q1", "stem": "What time does the household eat dinner together?", "choices": ["At six o''clock", "At seven o''clock", "At eight o''clock", "At nine o''clock"], "correct_index": 1}], "situation": "A German resident welcomes a new Syrian flatmate into their house.", "vocabulary": ["welcome", "live", "brother", "room", "dinner"], "instructions": "A German resident welcomes a new Syrian flatmate into their house.", "situation_ar": "ساكن ألماني عم يرحب برفيقه الجديد السوري بالبيت.", "audio_transcript": "Welcome to our flat, Rami! My name is Jonas. I am twenty-six years old. I live here with my brother. This is your new room. It has a big window. We eat dinner together at seven. Make yourself at home! Enjoy your stay!"}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (191, 1, 'listening', 'A2', 'lesson', 'Returning a Winter Coat', '{"topic": "shopping", "title_ar": "ترجيع جاكيت شتوي", "questions": [{"id": "q1", "stem": "Why is the customer returning the winter coat?", "choices": ["It is too small", "It is the wrong color", "It has a broken button", "It was too expensive"], "correct_index": 0}], "situation": "A customer is explaining to a store assistant why they need to return an item.", "vocabulary": ["bought", "return", "realized", "receipt", "refund"], "instructions": "A customer is explaining to a store assistant why they need to return an item.", "situation_ar": "زبون عم يشرح لموظف بالمحل ليش بده يرجع قطعة ثياب.", "audio_transcript": "Hello. I bought this black winter coat yesterday afternoon, but I need to return it. When I got home, I realized the size was completely wrong. It is too small for me, and I cannot close the buttons properly. I am currently looking for a bigger one, but your store does not have any left in stock. Here is my receipt. Can I get a full refund in cash, please?"}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (192, 1, 'listening', 'A2', 'lesson', 'Missing the Subway Train', '{"topic": "transport", "title_ar": "راحت عليّ تروحة المترو", "questions": [{"id": "q1", "stem": "Where is the speaker waiting right now?", "choices": ["At the cafe entrance", "On platform three", "In a taxi", "Inside a restaurant"], "correct_index": 1}], "situation": "A student calls their friend because they are going to be late due to transport issues.", "vocabulary": ["late", "running", "station", "platform", "entrance"], "instructions": "A student calls their friend because they are going to be late due to transport issues.", "situation_ar": "طالب عم يتصل برفيقه لأنه رح يتأخر بسبب مشكلة بالمواصلات.", "audio_transcript": "Hey Jonas, it is Ahmad. I am calling to tell you that I will be late for our meeting. I was running to the subway station, but the train left exactly one minute before I arrived. The next train is coming in fifteen minutes, so I am waiting on platform three right now. I am really sorry about this. Please wait for me at the cafe entrance."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (193, 1, 'listening', 'A2', 'lesson', 'Planning a Weekend Picnic', '{"topic": "weather", "title_ar": "عم نخطط لسيران بالعطلة", "questions": [{"id": "q1", "stem": "What will the weather be like tomorrow morning?", "choices": ["Cold and raining heavily", "Very dark and windy", "Beautiful, warm, and sunny", "Snowy and cold"], "correct_index": 2}], "situation": "Two people are listening to a local weather forecast on the radio to plan their weekend.", "vocabulary": ["weather", "report", "changing", "rising", "picnic"], "instructions": "Two people are listening to a local weather forecast on the radio to plan their weekend.", "situation_ar": "شخصين عم يسمعوا النشرة الجوية ع الراديو كرمال يخططوا لسيران بالعطلة.", "audio_transcript": "Good morning! Here is your weekend weather report for Munich. Today, it is raining heavily, and the temperature is only twelve degrees. However, the weather is changing tonight. Tomorrow morning will be beautiful, warm, and sunny. Temperatures are rising to twenty-five degrees. It is the perfect day for a picnic in the park or a bicycle ride by the lake. Enjoy your weekend!"}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (194, 1, 'listening', 'A2', 'lesson', 'Joining a Photography Class', '{"topic": "hobbies", "title_ar": "التسجيل بصف تصوير", "questions": [{"id": "q1", "stem": "Where does the photography class take place?", "choices": ["At a famous museum", "In a big school", "In a digital camera shop", "At the community center"], "correct_index": 3}], "situation": "A woman tells her colleague about her new weekend hobby at a community center.", "vocabulary": ["interesting", "course", "community", "professional", "museum"], "instructions": "A woman tells her colleague about her new weekend hobby at a community center.", "situation_ar": "مرّة عم تخبر رفيقتها بالشغل عن هوايتها الجديدة بالعطلة بمركز مجتمعي.", "audio_transcript": "I started an interesting photography class last Saturday. The course is held at the community center near my apartment. We learned how to use a digital camera properly to take beautiful pictures of nature. Our teacher is a professional photographer who traveled all around Europe. Next weekend, our class is visiting a famous museum downtown to look at old photographs. I am really enjoying this new hobby."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (357, 1, 'speaking', 'C2', 'speaking_prompt', 'Deconstructing the Degrowth Paradigm', '{"topic": "economics", "prompt": "Evaluate the theoretical validity of the degrowth paradigm in ecological economics. Critique the absolute decoupling hypothesis within carbon capitalism, and confront critics who assert that planned material contraction causes macroeconomic collapse.", "title_ar": "تفكيك نموذج تراجع النمو الاقتصادي", "prompt_ar": "قيم الصلاحية النظرية لنموذج تراجع النمو (Degrowth) بالاقتصاد البيئي هلق. انتقد فرضية الفصل المطلق بقلب رأسمالية الكربون، وواجه المنتقدين يلي عم يقولوا إن الانكماش المادي المخطط له بيعمل فوضى وانهيار فوري بالاقتصاد الكلي.", "min_seconds": 120, "question_type": "opinion", "example_answer": "As escalating ecological crises systematically expose the inherent structural limitations of carbon capitalism, the academic discourse surrounding ecological economics has increasingly centered on the radical degrowth paradigm. This macro-economic theory fundamentally challenges the core foundational axiom of contemporary economics: the unvetted assumption that infinite Gross Domestic Product (GDP) expansion is physically compatible with finite planetary biophysical boundaries. Degrowth proponents convincingly argue that contemporary corporate strategies for eco-modernism, such as green capitalism and decoupling, constitute a dangerous environmental illusion. They maintain that absolute decoupling—the mathematical insulation of economic expansion from total resource extraction and environmental degradation—has never actually occurred at the scale or velocity required to avert catastrophic climate destabilization. Instead, the degrowth framework advocates for a deliberate, planned contraction of material and energy throughput in wealthy nations, fundamentally restructuring social institutions to prioritize human well-being and ecological health over capital accumulation. Critics, however, aggressively contend that such a deliberate contraction would induce immediate macroeconomic chaos, resulting in catastrophic unemployment rates, public revenue collapses, and intense geopolitical vulnerability. They assert that without the financial surplus continuously generated by conventional economic growth, funding advanced scientific research and sustainable infrastructure transformations becomes fiscally impossible. This intellectual impasse highlights the fundamental systemic dilemma of the anthropocene: whether modern democratic societies can successfully re-engineer their socio-economic institutions away from growth dependency without triggering a complete systemic collapse, or whether they will remain bound to an expansionist paradigm until ecological boundary collapses enforce an unplanned contraction."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (195, 1, 'listening', 'A2', 'lesson', 'A New Syrian Restaurant', '{"topic": "neighborhood", "title_ar": "مطعم سوري جديد", "questions": [{"id": "q1", "stem": "When did the new Syrian restaurant open?", "choices": ["Last Tuesday night", "Yesterday evening", "Next week", "Last Sunday morning"], "correct_index": 0}], "situation": "A resident talks to his neighbor about a new dining option in their neighborhood.", "vocabulary": ["opened", "pharmacy", "delicious", "reasonable", "extremely"], "instructions": "A resident talks to his neighbor about a new dining option in their neighborhood.", "situation_ar": "ساكن عم يحكي مع جاره عن مطعم جديد فتح بحارتهم.", "audio_transcript": "Hi Sarah, did you see the new Syrian restaurant down the street? It opened last Tuesday night, right next to the pharmacy. My roommates and I went there yesterday evening for dinner. We ordered delicious chicken shawarma, fresh hummus, and hot falafel. The food was excellent, and the prices were very reasonable. The staff were extremely friendly too. We should definitely go there together next week."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (196, 1, 'listening', 'A2', 'lesson', 'Registering for a Course', '{"topic": "school", "title_ar": "التسجيل بكورس مسائي", "questions": [{"id": "q1", "stem": "On which days does the evening course meet?", "choices": ["Tuesdays and Thursdays", "Mondays and Wednesdays", "Every Saturday morning", "Fridays and Sundays"], "correct_index": 1}], "situation": "A student is asking the school secretary for information about evening classes.", "vocabulary": ["register", "attend", "intermediate", "meets", "application"], "instructions": "A student is asking the school secretary for information about evening classes.", "situation_ar": "طالب عم يسأل سكرتيرة المدرسة عن معلومات بتخص كورسات المسا.", "audio_transcript": "Hello, I want to register for the evening English course, please. I work during the day, so I can only attend lessons after five o''clock. Are there any spaces left in the intermediate level? The secretary said the class meets twice a week, on Mondays and Wednesdays. It costs eighty euros per month. I need to fill out this yellow application form now."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (197, 1, 'listening', 'A2', 'lesson', 'Lost Wallet at the Supermarket', '{"topic": "daily city life", "title_ar": "ضياع الجزدان بالسوبرماركت", "questions": [{"id": "q1", "stem": "What was the speaker doing when he realized his wallet was missing?", "choices": ["Buying fresh vegetables", "Walking to the train station", "Paying the cashier", "Filling out a yellow form"], "correct_index": 2}], "situation": "A man speaks to a security guard at a supermarket about a lost item.", "vocabulary": ["lost", "wallet", "reached", "cashier", "contains"], "instructions": "A man speaks to a security guard at a supermarket about a lost item.", "situation_ar": "زلمة عم يحكي مع حارس الأمن بالسوبرماركت عن غرض ضايع منه.", "audio_transcript": "Excuse me, I need some help. I think I lost my small brown wallet in this supermarket. I was buying some fresh vegetables and bread twenty minutes ago. When I reached the cashier to pay, my wallet was gone. It contains my student identity card, my health insurance card, and about thirty euros in cash. Did anyone find it?"}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (198, 1, 'listening', 'A2', 'lesson', 'Extending a Parking Permit', '{"topic": "bureaucracy", "title_ar": "تمديد ورقة صف السيارات", "questions": [{"id": "q1", "stem": "Why is Samer calling the city office?", "choices": ["To pay a parking fine", "To buy a new bicycle", "To rent a flat downtown", "To extend his parking permit"], "correct_index": 3}], "situation": "A resident calls the local city office to ask about renewing a document.", "vocabulary": ["extend", "permit", "expires", "upload", "convenient"], "instructions": "A resident calls the local city office to ask about renewing a document.", "situation_ar": "ساكن عم يتصل بمكتب البلدية كرمال يسأل عن تجديد ورقة رسمية.", "audio_transcript": "Good morning. My name is Samer, and I live in the city center. I need to extend my residential parking permit because it expires next week. Can I complete this process online through your website, or must I visit the city hall in person? The clerk explained that I can upload my rental contract online, and the new permit costs thirty euros yearly. That is very convenient."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (199, 1, 'listening', 'A2', 'lesson', 'Changing a Medical Appointment', '{"topic": "healthcare", "title_ar": "تغيير موعد الدكتور", "questions": [{"id": "q1", "stem": "Why can''t Maya attend her appointment tomorrow morning?", "choices": ["She has a university exam", "She must work flexible hours", "She lost her health card", "She went to Munich by train"], "correct_index": 0}], "situation": "A patient calls a medical clinic to reschedule an appointment.", "vocabulary": ["appointment", "unfortunately", "important", "possible", "stomachache"], "instructions": "A patient calls a medical clinic to reschedule an appointment.", "situation_ar": "مريض عم يتصل بالعيادة الطبية كرمال يغير موعده.", "audio_transcript": "Hello, this is Maya. I have a medical appointment with Doctor Müller tomorrow morning at nine o''clock. Unfortunately, I cannot come because I have an important university exam at the same time. Is it possible to change my appointment to Thursday afternoon? I have a bad stomachache, so I really need to see the doctor this week if possible."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (200, 1, 'listening', 'A2', 'lesson', 'Arranging a Meeting Location', '{"topic": "daily city life", "title_ar": "الاتفاق عمكان الشوفة", "questions": [{"id": "q1", "stem": "Where do the friends decide to meet instead of the park?", "choices": ["At the train platform", "Inside the bookstore in the mall", "At a new Syrian restaurant", "Near the local pharmacy"], "correct_index": 1}], "situation": "A man leaves a voice message for his friend about where to meet in the city.", "vocabulary": ["arriving", "journey", "planned", "opposite", "bookstore"], "instructions": "A man leaves a voice message for his friend about where to meet in the city.", "situation_ar": "زلمة عم يترك رسالة صوتية لرفيقه عن مكان الشوفة بالمدينة.", "audio_transcript": "Hey Rami, I am arriving at the central station right now. The train journey was very comfortable. Since it is raining heavily outside, let us not meet at the green park as we planned. Instead, I am walking to the big shopping mall opposite the station. I am waiting for you inside the bookstore on the ground floor. See you soon!"}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (246, 1, 'writing', 'A1', 'writing_prompt', 'Taking the Bus to School', '{"topic": "public transport", "prompt": "Write about how you travel to your language school. What color is the bus or train? Is the ticket cheap?", "title_ar": "ركوب الباص عالمدرسة", "min_words": 30, "prompt_ar": "اكتب كيف عم تروح عمدرستك تبع اللغة. شو لون الباص أو المترو؟ هل التكت رخيص؟", "min_sentences": 3, "example_answer": "Every morning, I take the blue bus to school. The bus is always on time. The ticket costs three euros. It is very cheap. I love public transport here."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (358, 1, 'speaking', 'C2', 'speaking_prompt', 'Neural Interfaces and Cognitive Liberty', '{"topic": "ethics", "prompt": "Discuss the bioethical and biopolitical threats that consumer-grade brain-computer interfaces (BCIs) pose to mental privacy. Formulate a legal argument for the immediate codification of unique ''neurorights'' to shield individual autonomy.", "title_ar": "الواجهات العصبية والحرية الإدراكية", "prompt_ar": "ناقش التهديدات الأخلاقية والسياسية الحيوية يلي عم تشكلها واجهات الدماغ والكمبيوتر التجارية ع الخصوصية العقلية هلق. ابنِ حجة قانونية واضحة للتدوين الفوري لـ ''حقوق عصبية'' فريدة لتحمي استقلالية الشخص الفكرية.", "min_seconds": 120, "question_type": "discuss", "example_answer": "The rapid clinical maturation of brain-computer interfaces (BCIs) and neuroprosthetics has officially transcended the traditional domain of restorative medicine, projecting modern society into a challenging bioethical frontier centered on the sanctity of cognitive liberty. Modern neurotechnologies, which utilize advanced machine-learning algorithms to decode neural signals and translate mental processes into computational commands, offer revolutionary therapeutic solutions for individuals with severe motor impairments. However, as corporate enterprises aggressively invest in consumer-grade neural interfaces designed to enhance cognitive efficiency, optimize attention metrics, or facilitate direct digital communication, the boundary of personal identity and mental privacy becomes profoundly vulnerable. Bioethicists warn that the commercialization of neural data introduces unprecedented opportunities for invasive algorithmic corporate surveillance, enabling corporations or state entities to monitor individual emotional states, subconscious cognitive preferences, and neural responses directly from the cerebral cortex. This capacity for neural monitoring introduces a fundamental epistemic threat to individual autonomy; when corporate data streams can access and manipulate cognitive processes before they even register in conscious human awareness, the very concept of free will becomes compromised. Furthermore, the integration of algorithmic feedback loops that directly stimulate neural pathways to alter mood or behavior risks eroding the boundary of individual agency, transforming human subjects into semi-automated nodes within decentralized digital networks. This systemic vulnerability necessitates a rigorous jurisdictional evolution: legal scholars contend that conventional human rights frameworks are completely inadequate to handle neurotechnological intrusion, demanding the immediate codification of specific ''neurorights'' designed to protect cognitive liberty, mental privacy, and psychological continuity from predatory commercial exploitation."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (201, 1, 'listening', 'B1', 'lesson', 'Preparing for a Mock Interview', '{"topic": "job applications", "title_ar": "التحضير لمقابلة عمل تجريبية", "questions": [{"id": "q1", "stem": "What will the speaker say if he is asked about his weaknesses?", "choices": ["He focuses too much on details but is improving time management.", "He cannot handle stressful situations at work.", "He forgot to bring his certificates and updated CV.", "He does not want to work flexible hours on weekends."], "correct_index": 0}], "situation": "A student tells his friend how he is preparing for an upcoming practice job interview.", "vocabulary": ["mock interview", "anxious", "advisor", "weaknesses", "expenses"], "instructions": "A student tells his friend how he is preparing for an upcoming practice job interview.", "situation_ar": "شاب عم يحكي لرفيقه شو عم يعمل مشان يجهز لمقابلة الشغل التجريبية تبعه بكرا.", "audio_transcript": "Hi Zein, I spent the entire evening preparing for my mock interview tomorrow at the language center. If I had practiced more last week, I wouldn''t feel this anxious right now. My advisor told me that they might ask about how I handle stressful situations at work. I have already updated my CV and printed out my certificates. I''ve also prepared some questions about the company''s training programs. If they ask about my weaknesses, I''ll say that I am sometimes too focused on details, but I am learning to manage my time better. I really need to get a part-time job soon to help with my living expenses here. Wish me luck!"}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (202, 1, 'listening', 'B1', 'lesson', 'The Challenge of Waste Sorting', '{"topic": "environment", "title_ar": "تحدي فرز الزبالة", "questions": [{"id": "q1", "stem": "What consequence did the landlord mention if the city finds mixed trash?", "choices": ["The resident must leave the apartment immediately.", "The entire building could receive a financial fine.", "The blue paper bin will be removed from the property.", "The flatmate will have to sort all the bottles alone."], "correct_index": 1}], "situation": "An international resident explains a recycling mistake to his friend and shares what his landlord said.", "vocabulary": ["recycling", "landlord", "fine", "packaging", "scraps"], "instructions": "An international resident explains a recycling mistake to his friend and shares what his landlord said.", "situation_ar": "طالب عم يشرح لرفيقه بالسكن المشكلة يلي صارت معه مع صاحب البناية بسبب فرز الزبالة.", "audio_transcript": "Honestly, I have been living in Hamburg for three months now, but I still find the local recycling system quite confusing. Yesterday, my landlord noticed that I had accidentally thrown some plastic containers into the blue paper bin. He wasn''t angry, but he explained that if the city finds mixed trash, the whole building could get a fine. He told me that plastic packaging belongs in the yellow bags, while food scraps should go into the organic waste bin. I have tried my best to follow these guidelines since then. If my flatmate hadn''t helped me sort the bottles this morning, I would have made another mistake. It takes time to build these habits."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (203, 1, 'listening', 'B1', 'lesson', 'Booking a Holiday Ticket', '{"topic": "travel", "title_ar": "حجز تكت للعطلة", "questions": [{"id": "q1", "stem": "Why does the speaker want to buy the train tickets today?", "choices": ["Because the train leaves exactly at nine tonight.", "Because the free onboard internet is only available today.", "To get a significant discount before prices double.", "To change the travel destination from Munich to Frankfurt."], "correct_index": 2}], "situation": "A young man calls his classmate to invite him on a weekend train journey and discusses ticket availability.", "vocabulary": ["significant", "discount", "affordable", "budget", "journey"], "instructions": "A young man calls his classmate to invite him on a weekend train journey and discusses ticket availability.", "situation_ar": "واحد عم يتصل برفيقه ليعزمه ع رحلة ويقله يحجزوا التكتات هلق مشان الرخص.", "audio_transcript": "Hello, I am calling to see if you would like to join us on a trip to Frankfurt next weekend. I have just checked the train tickets online, and if we buy them today, we will get a significant discount. If we wait until Friday, the prices will definitely double. I have been looking for an affordable option because my budget is tight this month. The train leaves at nine in the morning and takes around four hours. There is free internet on board, so we could even watch a movie during the journey. Let me know by tonight if you can come, so I can book all the seats together."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (204, 1, 'listening', 'B1', 'lesson', 'Getting a Health Insurance Card', '{"topic": "health", "title_ar": "طلعت كرت التأمين الصحي", "questions": [{"id": "q1", "stem": "What step does the speaker plan to take now that she has her physical card?", "choices": ["Submit a new digital photo to the medical clinic.", "Wait another three weeks to see if she develops a fever.", "Cancel her appointment because healthcare is too expensive.", "Register with a local English-speaking general practitioner."], "correct_index": 3}], "situation": "A woman leaves a voice message for her friend about receiving her medical insurance document.", "vocabulary": ["received", "submitted", "practitioner", "severe", "relief"], "instructions": "A woman leaves a voice message for her friend about receiving her medical insurance document.", "situation_ar": "بنت عم تخبر رفيقتها بمسج صوتي إنها استلمت كرت الصحة الجديد وتبعت شو لازم تعمل هلق.", "audio_transcript": "Hi Selma, I finally received my new health insurance card in the mail today. I have been waiting for it for over three weeks, and I was getting a bit worried. If I hadn''t submitted the digital photo online last Monday, it probably would have taken even longer. Now that I have the physical card, I should register with a local general practitioner near our neighborhood. My friend recommended a very kind doctor who speaks excellent English. If I ever feel sick or develop a severe fever, I can just call them for an appointment. It''s a huge relief to have this sorted out because healthcare without insurance is incredibly expensive here."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (247, 1, 'writing', 'A1', 'writing_prompt', 'My German Class in Numbers', '{"topic": "numbers", "prompt": "Write about the numbers in your classroom. How many students are there? How many men, women, and books do you see?", "title_ar": "صف الألماني تبعي بالأرقام", "min_words": 30, "prompt_ar": "اكتب عن الأرقام بصفك. كم طالب وطالبة فيه؟ كم زلمة ومرّة وكم كتاب شايف؟", "min_sentences": 3, "example_answer": "My class is big. We have twelve international students. There are four men and eight women. We have fifteen new books on the tables. Our class starts at nine."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (359, 1, 'speaking', 'C2', 'speaking_prompt', 'The EU AI Act Paradox', '{"topic": "policy debate", "prompt": "Evaluate the systemic paradox embedded within centralized AI legislation like the EU AI Act. Address how rigid risk-based compliance frameworks designed to protect civic spaces might inadvertently freeze domestic innovation and create foreign dependencies.", "title_ar": "تناقض قانون الذكاء الاصطناعي الأوروبي", "prompt_ar": "قيم التناقض الممنهج والواضح بقلب قوانين الذكاء الاصطناعي المركزية متل قانون الذكاء الاصطناعي الأوروبي هلق. شلون عم تتسبب أطر الامتثال الصارمة القائمة ع المخاطر بتجميد الابتكار المحلي وعمل تبعية لشركات أجنبية بلا ما تقصد؟", "min_seconds": 120, "question_type": "opinion", "example_answer": "The ongoing policy debate surrounding the statutory regulation of foundational artificial intelligence architectures within Europe illustrates a fundamental systemic tension between technological sovereignty and legislative overreach. As transnational technology corporations solidify their monopolistic hegemony over large-scale generative models and computational infrastructure, European regulatory bodies have introduced comprehensive legal frameworks, such as the EU AI Act, to mitigate existential risks and preserve data privacy. This pioneering legislation utilizes a risk-based tier system, mandating absolute architectural transparency, algorithmic auditing, and strict copyright compliance for high-risk deployments. Proponents of this centralized regulatory approach assert that strict statutory boundaries are essential to shield citizens from automated discrimination, systemic disinformation, and corporate data exploitation. However, a growing faction of technology strategists, open-source advocates, and digital economists contends that this rigid legislative paradigm inadvertently sabotages regional innovation, creating insurmountable bureaucratic hurdles for local start-ups and independent research frameworks. They argue that by imposing criminal liabilities and expensive compliance protocols on open-source software development, the state effectively centralizes technological control into the hands of a few dominant foreign tech conglomerates who possess the capital to navigate administrative compliance effortlessly. Consequently, this dynamic could result in an ironic geopolitical outcome: a legislative framework explicitly designed to guarantee digital autonomy might solidify Europe’s technological dependency on foreign proprietary platforms. Moving forward, policymakers face the complex task of calibrating enforcement mechanisms so that ethical guardrails protect civic space without completely freezing the domestic capital investment necessary to construct sovereign, locally adapted computational infrastructure."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (360, 1, 'speaking', 'C2', 'speaking_prompt', 'Linguistic Drift and Polyphonic Identity', '{"topic": "cross-cultural communication", "prompt": "Describe the sociolinguistic evolution of second-generation diasporic communities in urban spaces. Analyze how fluid code-switching serves as a sophisticated third space for agency, and critique the institutional pathologization of these hybrid structures.", "title_ar": "الانزياح اللغوي والهوية متعددة الأصوات", "prompt_ar": "اوصف التطور اللغوي والاجتماعي لمجتمعات الجيل الثاني من المغتربين بالمساحات الحضرية هلق. حلل شلون عم يشتغل التبديل اللغوي المرن كمساحة تالتة متطورة للتعبير عن الإرادة، وانتقد التعامل المرضي والسلبي للمؤسسات مع هي الهياكل الهجينة.", "min_seconds": 120, "question_type": "describe", "example_answer": "The long-term sociolinguistic evolution of second-generation diasporic communities within Western European metropolises offers a fascinating study in linguistic drift and polyphonic identity synthesis. Within these urban spaces, young individuals continuously navigate a dense communicative ecosystem, synthesizing the syntactic structures of their heritage languages—such as Syrian Arabic—with the morphology and lexicon of their host societies'' standard tongues, like German or English. Rather than representing a corrupted or incomplete mastery of either idiom, contemporary sociolinguists interpret this fluid code-switching and hybrid speech production as the emergence of a sophisticated third space. This linguistic hybridity functions as an active strategy for individual and collective agency, allowing youth to construct a localized, syncretic identity that consciously resists both majoritarian cultural erasure and the rigid traditionalism of diasporic enclaves. Through the subversion of standard monolingual registers, these speakers develop a rich polyphonic repertoire that serves as an expressive medium for their unique existential positionality. However, the institutional recognition of these hybrid communication models remains a highly contested domain within formal education and employment spheres. National pedagogical institutions routinely prioritize standardized language competence as the absolute, non-negotiable metric for socio-economic mobility, pathologizing hybrid structures as indicators of linguistic deficit or cognitive confusion. This institutional rigidity creates an intellectual impasse: while the lived reality of multicultural urban centers requires flexible, multifaceted communicative adaptability, systemic evaluation mechanisms remain bound to an antiquated monolingual ideology. Ultimately, dismantling these systemic biases requires an epistemological shift that validates polyphonic hybridity not as a deficit, but as a form of valuable socio-cultural capital essential for cross-cultural communication."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (366, 1, 'reading', 'C2', 'lesson', 'Navigating the Unspoken Rules: A Newcomer''s Journey', '{"source": "ai_nightly", "passage": "Seldom had she encountered a community quite so steeped in unspoken rituals as this bustling metropolis. Were it not for the kindness of a few neighbours, she might have found herself perpetually adrift, misinterpreting gestures, and inadvertently breaching social etiquette. Little did she know, when she first arrived, that the seemingly simple act of inviting someone for coffee carried a subtext of commitment far weightier than a casual offer. It was imperative that she adapt, lest she remain an outsider looking in, forever grappling with the subtle currents of local interaction. The nuances of local humour, for instance, often hinged on historical anecdotes or regional rivalries, making their apprehension a formidable task. She often wished it were easier to grasp the intricate tapestry of their social fabric, a fabric woven with threads of tradition and contemporary adaptation. Had she understood earlier the profound significance of seemingly trivial exchanges, she would have approached initial interactions with far more circumspection. It was not merely about language; rather, it was the unspoken lexicon of social dynamics that proved most formidable. She had to learn to read between the lines, to discern the subtle cues that dictated everything from queuing manners to the appropriate timing for a house visit. Never before had she felt such an acute sense of the depth of cultural embeddedness. Only then, she surmised, could she truly begin to belong, to move beyond merely existing within the city''s confines to genuinely thriving and contributing. One must, after all, pull one''s weight, and this often entailed mastering the unwritten rules of community engagement. Lest anyone think otherwise, this was a process demanding immense patience and an open mind, a veritable baptism of fire.", "title_ar": "كيف تتأقلم مع القواعد غير المعلنة: رحلة وافد جديد", "questions": [{"stem": "What is the primary challenge the newcomer faces in the new city, according to the passage?", "choices": ["Learning the local language and its dialects.", "Understanding the city''s complex transportation system.", "Deciphering the unspoken social rules and cultural nuances.", "Finding affordable housing and employment opportunities."], "correct_index": 2}, {"stem": "Which of the following best describes the phrase \"baptism of fire\" as used in the passage?", "choices": ["A religious ceremony for new members of the community.", "A difficult and challenging experience that tests one''s abilities.", "A literal experience involving heat or fire.", "A celebratory event marking successful integration."], "correct_index": 1}], "passage_ar": "نادراً ما كانت قد صادفت مجتمعاً غارقاً في طقوس غير معلنة مثل هالمدينة الصاخبة. لو ما كانت لطافة كم جار، كانت ممكن تلاقي حالها تايهة على طول، عم تفهم الإيماءات غلط، وعم تخالف الآداب الاجتماعية من غير قصد. شو كانت بتعرف لما وصلت أول مرة، إنو دعوة بسيطة لشرب قهوة بتحمل معنى التزام أعمق بكتير من مجرد عرض عادي. كان لازم عليها تتأقلم، مشان ما تضل غريبة عم تتفرج من برا، وعم تتصارع مع التيارات الخفية للتفاعل المحلي. الفروقات الدقيقة بالفكاهة المحلية، مثلاً، غالباً ما كانت بتعتمد على حكايات تاريخية أو منافسات إقليمية، وهالشي خلى فهمها مهمة صعبة كتير. كانت بتتمنى لو كان أسهل عليها تفهم النسيج المعقد للمجتمع تبعن، نسيج منسوج بخيوط التقاليد والتكيف المعاصر. لو كانت فهمت قبل هيك الأهمية العميقة للتبادلات اللي بتبين تافهة، كانت تعاملت مع التفاعلات الأولية بحذر أكتر بكتير. ما كان الموضوع بس عن اللغة؛ بالأحرى، كان القاموس غير المنطوق للديناميكيات الاجتماعية هو اللي أثبت إنو الأصعب. كان لازم تتعلم تقرأ ما بين السطور، لتكتشف الإشارات الدقيقة اللي بتحدد كل شي، من آداب الدور بالطوابير لأي وقت مناسب لزيارة بيت. ولا مرة قبل هيك حست بهالعمق الكبير للاندماج الثقافي. بس وقتها، استنتجت، ممكن تبلش تنتمي عنجد، لتتجاوز مجرد الوجود ضمن حدود المدينة، لتزدهر وتساهم عن حق. لازم الواحد، بالنهاية، يتحمل مسؤوليتو، وهالشي غالباً بيتضمن إتقان القواعد غير المكتوبة للمشاركة المجتمعية. مشان ما حدا يفكر غير هيك، كانت هالعملية بتتطلب صبر هائل وعقل منفتح، وهاد اختبار حقيقي.", "generated_at": "2026-06-23T23:44:04.186353+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (205, 1, 'listening', 'B1', 'lesson', 'Setting Up Home Internet', '{"topic": "technology", "title_ar": "تركيب إنترنت بالبيت", "questions": [{"id": "q1", "stem": "Why did the roommates experience a delay in getting their internet setup?", "choices": ["The company failed to send the activation code on time.", "The technician lost the kitchen table password.", "They spent all their money on extra mobile data.", "They were busy studying online for two whole weeks."], "correct_index": 0}], "situation": "A tenant calls his roommate to inform him that the internet service is being installed.", "vocabulary": ["technician", "router", "activation", "connection", "interruptions"], "instructions": "A tenant calls his roommate to inform him that the internet service is being installed.", "situation_ar": "ساكن عم يتصل برفيقه بالسكن ليخبره إنه موظف الشركة إجا وأخيراً عم يركب النت.", "audio_transcript": "Hi Kareem, I''m just calling to let you know that the technician has finally arrived to set up our home internet router. I''ve been using my mobile data for the past two weeks, and I have already spent a lot of money on extra gigabytes. If the company had sent the activation code on time, we would have had internet last week. The technician says it will take about half an hour to test the connection speed. Once it''s ready, we will be able to stream videos and study online without any interruptions. I will write down the new Wi-Fi password and leave it on the kitchen table for you."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (206, 1, 'listening', 'B1', 'lesson', 'Discussing Flat Rules', '{"topic": "relationships", "title_ar": "نقاش عن قواعد الشقة", "questions": [{"id": "q1", "stem": "What is the speaker worried might happen if the shared areas stay messy?", "choices": ["Samer will fail his upcoming university exams.", "The landlord might complain during the next inspection.", "They will have to buy new empty boxes for the hallway.", "The kitchen schedule will be extended until the weekend."], "correct_index": 1}], "situation": "A roommate confronts his flatmate about neglecting his shared household cleaning chores.", "vocabulary": ["routine", "counter", "schedule", "tension", "inspection"], "instructions": "A roommate confronts his flatmate about neglecting his shared household cleaning chores.", "situation_ar": "شاب عم يحكي مع رفيقه بالسكن بجدية مشان قصة النظافة والترتيب بالبيت.", "audio_transcript": "Listen, Samer, we need to have a quick chat about our flat''s cleaning routine. I''ve noticed that the kitchen counter hasn''t been wiped for a few days, and there are several empty boxes in the hallway. We agreed on a strict schedule when we moved in, and if everyone doesn''t do their part, it creates a lot of unnecessary tension. I know you''ve been extremely busy with your university exams lately, but it only takes ten minutes to wash your dishes. If we don''t keep the shared areas clean, our landlord might complain during the next inspection. Let''s try to fix this before the weekend, okay?"}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (207, 1, 'listening', 'B1', 'lesson', 'Choosing an Apprenticeship', '{"topic": "school system", "title_ar": "اختيار التدريب المهني", "questions": [{"id": "q1", "stem": "Why does Tareq prefer the vocational training program over a university degree?", "choices": ["He wants to avoid moving to the city of Stuttgart.", "His father forced him to look for a monthly salary immediately.", "He prefers hands-on, practical experience over purely academic study.", "The career counselor advised him to quit studying computer science."], "correct_index": 2}], "situation": "A speaker talks about his cousin''s dilemma between choosing university or vocational training.", "vocabulary": ["career", "vocational", "apprenticeship", "salary", "counselor"], "instructions": "A speaker talks about his cousin''s dilemma between choosing university or vocational training.", "situation_ar": "واحد عم يحكي عن ابن عمه يلي عم يفكر يعمل أوسبيلدونغ ومحتار بينه وبين الجامعة.", "audio_transcript": "My cousin Tareq has been thinking about his career options since he finished his language course. He was planning to apply for a computer science degree at university, but now he is considering a vocational training program instead. He found a great apprenticeship at an IT company in Stuttgart. If he chooses the Ausbildung, he will be able to earn a monthly salary while learning practical skills on the job. His father believes that university offers better long-term opportunities, but Tareq prefers hands-on experience. If he gets accepted, he would start training this September. It''s a difficult decision, and he has been talking to a career counselor to weigh the pros and cons."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (208, 1, 'listening', 'B1', 'lesson', 'Extending the Residence Permit', '{"topic": "bureaucracy", "title_ar": "تمديد الإقامة بمكتب الأجانب", "questions": [{"id": "q1", "stem": "What did the officer give the speaker because the card takes six weeks to print?", "choices": ["A completely new university enrollment letter.", "An immediate extension of three additional months.", "A bank statement showing sufficient funds.", "A temporary document to use in the meantime."], "correct_index": 3}], "situation": "A student describes his experience renewing his visa at the local migration office.", "vocabulary": ["immigration", "extension", "examined", "statements", "temporary"], "instructions": "A student describes his experience renewing his visa at the local migration office.", "situation_ar": "طالب عم يوصف لرفيقه العجقة والضغط يلي عاشه اليوم الصبح بمكتب الإقامة.", "audio_transcript": "I had a very stressful morning at the immigration office today. My current residence permit is due to expire next month, so I had to request an extension. If I hadn''t booked the appointment three months in advance, I wouldn''t have found an available slot before the deadline. The officer examined all my documents carefully, including my bank statements and university enrollment letter. Luckily, everything was in perfect order, but she said the actual card takes six weeks to be printed. She gave me a temporary document to use in the meantime. If you need to renew your visa soon, you should definitely start gathering your paperwork immediately."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (248, 1, 'writing', 'A1', 'writing_prompt', 'A Cold Winter Day', '{"topic": "weather", "prompt": "Write about the weather today in your city. Is it cold or hot? What clothes do you wear outside?", "title_ar": "يوم شتي بارد", "min_words": 30, "prompt_ar": "اكتب عن الجو اليوم بمدينتك. هل هو بارد ولا شوب؟ شو عم تلبس ثياب برّا؟", "min_sentences": 3, "example_answer": "The winter here is very cold. The sky is dark grey today. It is raining outside. I wear my heavy black coat and boots. I carry a yellow umbrella."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (249, 1, 'writing', 'A1', 'writing_prompt', 'My Favorite Cafe', '{"topic": "daily city life", "prompt": "Write about your favorite cafe in the city. Where is it? What do you order there and who do you talk to?", "title_ar": "قهوتي المفضلة", "min_words": 30, "prompt_ar": "اكتب عن قهوتك المفضلة بالمدينة. وين صايرة؟ شو عم تطلب هنيك ومع مين عم تحكي؟", "min_sentences": 3, "example_answer": "I go to a small cafe near my flat. It is very beautiful. I order hot coffee and a sweet cake. I talk to my Syrian friend, Ahmad."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (209, 1, 'listening', 'B1', 'lesson', 'Understanding Sunday Quiet Hours', '{"topic": "cultural differences", "title_ar": "فهم ساعات الهدوء يوم الأحد", "questions": [{"id": "q1", "stem": "What happened when the speaker started using an electric drill last Sunday?", "choices": ["His neighbor knocked on the door and explained the quiet hours rule.", "The landlord arrived to help him hang the shelves.", "The other residents called the police to issue a major fine.", "His drill broke down within the first five minutes of use."], "correct_index": 0}], "situation": "A recent migrant shares an incident where he accidentally violated a local neighborhood rule.", "vocabulary": ["strict", "shelves", "prohibited", "warned", "relaxation"], "instructions": "A recent migrant shares an incident where he accidentally violated a local neighborhood rule.", "situation_ar": "مغترب عم يحكي لرفيقه عن قصة صارت معه يوم الأحد لما استخدم الحفارة بالبيت.", "audio_transcript": "When I first moved to Germany, I didn''t know about the strict rules regarding Sunday quiet hours, which locals call Ruhetag. Last Sunday morning, I decided to hang some shelves in my room and started using an electric drill. Within five minutes, my neighbor knocked on the door and politely explained that loud noises are prohibited on Sundays. He said that if I continued drilling, the other residents might get upset or even call the landlord. I apologized immediately and put my tools away. If he hadn''t warned me, I would have broken the community rules without realizing it. Now I understand that Sundays are meant entirely for quiet relaxation."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (210, 1, 'listening', 'B1', 'lesson', 'Contesting a Transit Fine', '{"topic": "public transport", "title_ar": "الاعتراض على مخالفة مواصلات", "questions": [{"id": "q1", "stem": "How can the speaker reduce his transit fine from sixty euros to seven euros?", "choices": ["By buying a completely new monthly pass from the tram inspector.", "By bringing his valid monthly ticket to the transit office within a week.", "By explaining to the landlord that he forgot it inside the flat.", "By waiting tomorrow morning until the bureaucracy rules change."], "correct_index": 1}], "situation": "A commuter explains how he received a public transit fine because he forgot his valid monthly pass.", "vocabulary": ["monthly", "inspector", "produce", "reduce", "annoying"], "instructions": "A commuter explains how he received a public transit fine because he forgot his valid monthly pass.", "situation_ar": "راكب عم يشرح شو صار معه بالترام لما نسي تكت الشهر وأكل مخالفة.", "audio_transcript": "You won''t believe what happened to me on the tram yesterday. I bought a monthly transit ticket last week, but I forgot to carry it with me when I left the apartment. During the journey, a ticket inspector boarded the tram and asked to see my pass. Since I couldn''t produce it, he gave me a regular sixty-euro fine. He explained that if I take my valid monthly ticket to the transit office within a week, they will reduce the fine to just seven euros. I am planning to go there tomorrow morning to sort this out. If I had been more careful, I would have avoided this annoying bureaucracy."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (211, 1, 'listening', 'B2', 'lesson', 'Adapting to Direct Corporate Feedback', '{"topic": "career", "title_ar": "التأقلم مع النقد المباشر بالشركات", "questions": [{"id": "q1", "stem": "Why do some international employees misunderstand constructive criticism in this company?", "choices": ["Because they are unaccustomed to the blunt delivery of corporate critique.", "Because the feedback seminars have been canceled for the upcoming quarter.", "Because human resources refuses to handle their scheduling constraints.", "Because software engineers prefer indirect training modules over workshops."], "correct_index": 0}], "situation": "A corporate manager addresses her team about challenges faced by international employees adjusting to regional communication styles.", "vocabulary": ["integration", "hurdles", "misconstrued", "mitigate", "mandatory"], "instructions": "A corporate manager addresses her team about challenges faced by international employees adjusting to regional communication styles.", "situation_ar": "مسؤولة بالشركة عم تحكي باجتماع عن الصعوبات يلي عم يواجهوها الموظفين الأجانب الجداد ليتأقلموا مع طريقة النقد المباشر بالشغل.", "audio_transcript": "Hi everyone. I wanted to touch base regarding the professional integration seminars scheduled for the upcoming quarter. It has been reported by several team leads that many of our international software engineers are encountering substantial hurdles when adapting to our direct feedback loop. In our corporate culture, constructive criticism is typically delivered quite bluntly, which can easily be misconstrued as personal hostility by employees who are accustomed to a more indirect communication style. To mitigate this issue, a specialized interpersonal workshop is being introduced next week. Had we implemented these cross-cultural modules during the initial onboarding phase, a great deal of team friction might have been averted entirely. Attendance is going to be mandatory for all project managers, as we actively aim to foster an inclusive environment where cognitive diversity is valued. If you have any unavoidable scheduling constraints, please notify the human resources department by tomorrow afternoon."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (212, 1, 'listening', 'B2', 'lesson', 'Debating Public Transit Ticket Subsidies', '{"topic": "public transport", "title_ar": "نقاش ببلدية المدينة عن دعم تكتات المواصلات", "questions": [{"id": "q1", "stem": "What main argument is raised by opposition members against the transit subsidy?", "choices": ["They claim that traffic congestion in the city center has increased significantly.", "They argue it is financially unsustainable without adjusting fares by income.", "They believe federal grants should be utilized to ban private automobiles entirely.", "They state that ancient subway networks do not require any physical maintenance."], "correct_index": 1}], "situation": "A city council member speaks at a public hearing regarding the financial challenges of public transit subsidies.", "vocabulary": ["optimization", "incentivize", "deficits", "unsustainable", "bottleneck"], "instructions": "A city council member speaks at a public hearing regarding the financial challenges of public transit subsidies.", "situation_ar": "جلسة بمجلس البلدية عم يتناقشوا فيها عن نجاح التكتات المدعومة والمشاكل المادية يلي عم تواجهها شبكة المترو.", "audio_transcript": "Good evening, fellow citizens. Tonight''s city council session focuses on the proposed optimization of our urban mobility infrastructure. As you know, the subsidized monthly transit pass, which was introduced last year to incentivize residents to utilize trains and buses rather than private automobiles, has been a tremendous success. Consequently, traffic congestion in the city center has dropped by approximately twenty percent. However, local municipalities are currently facing severe budget deficits due to the skyrocketing costs of maintaining and upgrading our ancient subway networks. It has been argued by opposition members that continuing this massive subsidy is fiscally unsustainable unless fare structures are adjusted based on income brackets. Had municipal councils successfully secured more substantial federal grants prior to launching the initiative, this structural bottleneck could have been avoided. We are now opening the floor for an open public debate, and your active participation is highly encouraged."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (250, 1, 'writing', 'A1', 'writing_prompt', 'Email to a New Flatmate', '{"topic": "self-introduction", "prompt": "Write a short email to your new flatmate before you move in. Greet them, state your age, your hobbies, and what language you speak.", "title_ar": "إيميل لرفيق سكن جديد", "min_words": 30, "prompt_ar": "اكتب إيميل قصير لرفيق سكنك الجديد قبل ما تنقل. سلم عليه، وقله قديش عمرك، شو هواياتك، وشو اللغة يلي بتحكيها.", "min_sentences": 3, "example_answer": "Hello Jonas! I am your new flatmate. I am twenty-five years old. I speak Arabic and English. I like football and hot coffee. See you on Sunday morning!"}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (367, 1, 'reading', 'C2', 'lesson', 'The Interdisciplinary Imperative: A Holistic Approach to Knowledge', '{"source": "ai_nightly", "passage": "The contemporary academic landscape often champions an interdisciplinary approach, positing that a holistic understanding of complex phenomena is only truly attainable when diverse fields converge. Were it not for the insights gleaned from sociology, for instance, a purely economic analysis of poverty might fail to apprehend the intricate web of social determinants. Seldom do scholars operating solely within the confines of a single discipline manage to fully elucidate the multifaceted nature of societal challenges. It is imperative that researchers cultivate a nuanced epistemological flexibility, allowing them to transcend traditional boundaries. Little did many realize in bygone eras that the fragmentation of knowledge into rigid silos could inadvertently obscure profound connections. To assert that one discipline holds the sole key to truth would be to commit a disservice to intellectual inquiry itself. One might argue, indeed, that the most groundbreaking advancements have invariably emerged from the fertile ground where seemingly disparate ideas cross-pollinate. The question is not merely ''what do we know?'' but ''how do we know it across various lenses?'' Had we always confined ourselves to established paradigms, countless innovations, both scientific and philosophical, would assuredly never have seen the light of day. This demands a readiness to engage with disparate methodologies and terminologies, a willingness to be discomfited by unfamiliar perspectives. Such an approach, while challenging, ultimately enriches the collective human endeavour to comprehend the world in its bewildering complexity. Lest we forget, the pursuit of knowledge is an ongoing, evolving dialogue, not a static monologue.", "title_ar": "ضرورة التخصصات المتعددة: مقاربة شاملة للمعرفة", "questions": [{"stem": "What is the central argument for the interdisciplinary approach in academia?", "choices": ["It allows scholars to specialize deeply in one area.", "It simplifies complex phenomena by isolating variables.", "It provides a holistic understanding by integrating diverse fields.", "It reduces the need for extensive research and collaboration."], "correct_index": 2}, {"stem": "The passage suggests that a \"nuanced epistemological flexibility\" is crucial for researchers. What does this phrase imply?", "choices": ["The ability to adhere strictly to one''s own disciplinary methods.", "The capacity to adapt one''s understanding of knowledge and how it''s acquired across different fields.", "A preference for quantitative research methods over qualitative ones.", "The skill of communicating complex ideas to a non-academic audience."], "correct_index": 1}], "passage_ar": "المشهد الأكاديمي المعاصر غالباً ما بيدعم المقاربة متعددة التخصصات، مفترضاً إنو الفهم الشامل للظواهر المعقدة بيتحقق بس لما تتلاقى المجالات المتنوعة. لو ما كانت الأفكار المستخلصة من علم الاجتماع، مثلاً، ممكن تحليل اقتصادي بحت للفقر يفشل بفهم الشبكة المعقدة للمحددات الاجتماعية. نادراً ما يتمكن الباحثون اللي بيشتغلوا ضمن حدود تخصص واحد بس من توضيح الطبيعة المتعددة الأوجه للتحديات المجتمعية بشكل كامل. من الضروري إنو الباحثين ينموا مرونة معرفية دقيقة، تسمحلن يتجاوزوا الحدود التقليدية. شو كان بيعرف كتير ناس بالعهود الماضية إنو تجزئة المعرفة لسياجات جامدة ممكن تخفي روابط عميقة من غير قصد. إنو الواحد يدعي إنو تخصص واحد بيحمل المفتاح الوحيد للحقيقة، هاد بيعتبر إجحاف بحق البحث الفكري نفسه. ممكن الواحد يجادل، بالفعل، إنو أهم الإنجازات الرائدة ظهرت دائماً من الأرض الخصبة اللي بتتلاقح فيها الأفكار اللي بتبين متباعدة. السؤال مو بس ''شو بنعرف؟'' بس ''شلون بنعرف من خلال عدسات مختلفة؟'' لو كنا دايماً حصرنا حالنا ضمن النماذج الراسخة، أكيد كتير ابتكارات، علمية وفلسفية، ما كانت رح تشوف النور أبداً. هاد بيتطلب استعداد للانخراط بمنهجيات ومصطلحات متباينة، رغبة بالانزعاج من وجهات النظر غير المألوفة. هيك مقاربة، مع إنها صعبة، بس بالنهاية بتغني المسعى الإنساني الجماعي لفهم العالم بتعقيده المحير. مشان ما ننسى، السعي ورا المعرفة هو حوار مستمر ومتطور، مو مونولوج ثابت.", "generated_at": "2026-06-23T23:44:04.187351+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (213, 1, 'listening', 'B2', 'lesson', 'The Housing Scarcity Crisis', '{"topic": "current events", "title_ar": "أزمة السكن وغلاء الآجارات بالمدن", "questions": [{"id": "q1", "stem": "According to opponents, what is a negative effect of rigid rent control regulations?", "choices": ["They automatically increase the socio-economic diversity of metropolitan areas.", "They force the housing ministry to expand social programs immediately.", "They inadvertently discourage private developers from building new housing units.", "They eliminate speculative real estate investments within a single decade."], "correct_index": 2}], "situation": "A news anchor delivers a report on the economic and social impacts of the urban housing shortage.", "vocabulary": ["acute", "speculative", "interventions", "inadvertently", "mitigated"], "instructions": "A news anchor delivers a report on the economic and social impacts of the urban housing shortage.", "situation_ar": "تقرير إخباري ع التلفزيون عم يحكي عن أزمة قلة البيوت الرخيصة والآجارات يلي شعلت بالمدن الكبيرة وتأثيرها ع الطلاب.", "audio_transcript": "Welcome back to the Evening Report. Today, we examine the growing social unrest surrounding the acute shortage of affordable housing options in major metropolitan areas across the country. As monthly rental prices continue to skyrocket due to speculative real estate investment and rapid demographic shifts, young professionals and international students find themselves priced out of the residential market entirely. Sociologists have warned that if immediate legislative interventions, such as stricter rent caps, are not implemented by the government, our urban centers risk losing their socio-economic diversity. These rent control measures are currently being fiercely debated in parliament, with opponents claiming that rigid regulations inadvertently discourage private developers from constructing new residential units. Had the housing ministry invested more comprehensively in social housing programs over the past decade, this systemic crisis might have been partially mitigated. Next, we will speak live with a local housing advocate who outlines potential community-driven solutions."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (214, 1, 'listening', 'B2', 'lesson', 'Transitioning to Digital Registration', '{"topic": "bureaucracy", "title_ar": "التحول الرقمي بمعاملات مكتب الإقامة", "questions": [{"id": "q1", "stem": "What concern do non-profit counseling organizations have regarding the new paperless portal?", "choices": ["It will significantly increase the existing administrative backlog for staff members.", "It prevents applicants from uploading official rental contracts and certificates.", "It requires case workers to cancel the upcoming training session on Friday.", "It might create technological barriers for vulnerable migrants lacking digital literacy."], "correct_index": 3}], "situation": "An administrative director briefs office staff on the implementation of a new digital portal for immigrants.", "vocabulary": ["directive", "backlog", "streamlined", "vulnerable", "glitches"], "instructions": "An administrative director briefs office staff on the implementation of a new digital portal for immigrants.", "situation_ar": "توجيه رسمي بمكتب الأجانب عم يشرحوا فيه كيف رح تتحول المعاملات كلها أونلاين والمشاكل يلي ممكن تواجه الكبار بالعمر.", "audio_transcript": "Attention all staff members of the municipal integration office. This morning, an official directive was issued regarding the upcoming transition to our centralized digital registration portal. As you are well aware, our physical migration offices have been completely overwhelmed by an immense administrative backlog for several consecutive months. By shifting to an entirely paperless system, international applicants will be enabled to upload their rental contracts, employment verification certificates, and passport documents directly from their homes. This streamlined process is explicitly expected to reduce waiting times by up to fifty percent. However, serious concerns have been raised by non-profit counseling organizations regarding potential technological barriers for vulnerable migrants who lack advanced digital literacy. Had this administrative software been thoroughly vetted by cross-cultural usability experts earlier, some of these systemic technical glitches could have been eliminated. A mandatory training session will be held this Friday afternoon to ensure all case workers can navigate the new interface effortlessly."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (215, 1, 'listening', 'B2', 'lesson', 'Urban Green Infrastructure Benefits', '{"topic": "global issues", "title_ar": "المساحات الخضراء بالمدن ومواجهة الشوب", "questions": [{"id": "q1", "stem": "What occurs during the phenomenon known as the urban heat island effect?", "choices": ["Concrete surfaces absorb solar radiation, causing localized temperatures to skyrocket.", "Abandoned industrial yards are automatically converted into sustainable architecture.", "Energy-intensive air conditioning systems drop urban temperatures to hazardous levels.", "Municipal councils establish zero-emission zones across major European parks."], "correct_index": 0}], "situation": "A university professor introduces a lecture topic on architectural solutions to the urban heat island effect.", "vocabulary": ["indispensable", "phenomenon", "mandates", "deliberate", "hazardous"], "instructions": "A university professor introduces a lecture topic on architectural solutions to the urban heat island effect.", "situation_ar": "أستاذ بالجامعة عم يعطي محاضرة عن كيف الحدائق والأسطح الخضرا بتساعد بتبريد المدن بظاهرة الجزر الحرارية بالصيف.", "audio_transcript": "Good morning, everyone. In today''s seminar on sustainable urban architecture, we will analyze how metropolitan green infrastructure serves as an indispensable asset in mitigating global climate change. Densely built urban centers frequently suffer from the urban heat island effect, a phenomenon where concrete surfaces absorb solar radiation, causing localized temperatures to skyrocket during summer months. To combat this pressing environmental challenge, city planners are increasingly converting abandoned industrial yards into public parks and enforcing strict green roof mandates for all new commercial developments. Recent environmental assessments indicate that without these deliberate ecological interventions, peak summer temperatures in major European cities would quickly rise to hazardous levels. Had municipal councils prioritized these sustainable planning models twenty years ago, our current reliance on energy-intensive air conditioning systems would be significantly lower. We will now divide into small analytical groups to review a detailed case study focusing on the zero-emission zones that were recently established in Copenhagen."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (216, 1, 'listening', 'B2', 'lesson', 'The Multi-Track Secondary School Debate', '{"topic": "education systems", "title_ar": "النقاش حول نظام المدارس وتقسيم الطلاب بكير", "questions": [{"id": "q1", "stem": "According to the speaker, why are international children disproportionately kept away from university tracks?", "choices": ["Because vocational training programs require highly integrated primary school tracking.", "Because early linguistic barriers affect their placement in the multi-track system.", "Because federal states uniformly implemented comprehensive educational reforms a decade ago.", "Because academic symposiums discourage flexible enrollment structures in secondary schools."], "correct_index": 1}], "situation": "An educational researcher presents an analysis of academic tracking structures to a committee.", "vocabulary": ["framework", "proponents", "mobility", "disproportionately", "disparity"], "instructions": "An educational researcher presents an analysis of academic tracking structures to a committee.", "situation_ar": "باحث عم يحكي بندوة تعليمية عن سلبيات تقسيم الطلاب بمسارات مختلفة بعمر صغير وتأثير هاد الشي ع أولاد المهاجرين.", "audio_transcript": "Hello, colleagues. I''d like to share some insights from our recent educational research symposium regarding the multi-track secondary school system. As you know, under this traditional framework, children are typically sorted into different academic paths at a relatively early age based on their primary school performance. While proponents argue that this dual structure effectively cultivates a highly specialized workforce by separating academic tracking from vocational training, critics fiercely point out that it severely limits socio-economic mobility. It is frequently asserted by sociologists that children from international backgrounds are disproportionately directed away from university-bound tracks due to early linguistic barriers. If the secondary school curriculum were more integrated and flexible, students would be allowed to pivot between academic and practical streams much later in their personal development. Had these comprehensive educational reforms been implemented uniformly across all federal states a decade ago, the current disparity in higher education enrollment would be far less pronounced. Let''s discuss how this affects our local language integration initiatives."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (251, 1, 'writing', 'A2', 'writing_prompt', 'Buying a Used Bicycle', '{"topic": "shopping", "prompt": "Write an email to a person selling a used bicycle online. Ask about the price, the condition of the brakes, and when you can see it.", "title_ar": "شرا بسكليت مستعملة", "min_words": 50, "prompt_ar": "اكتب إيميل لشخص عم يبيع بسكليت مستعملة أونلاين. اسألو عن السعر، وعن حالة الفرامل، وإيمتى فيك تشوفها.", "min_sentences": 5, "example_answer": "Hello, I saw your advertisement on the website. I want to buy your green bicycle for my university trips. Is the price still fifty euros? How is the condition of the brakes? I am free on Tuesday evening. Can I come to see it at six o''clock?"}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (217, 1, 'listening', 'B2', 'lesson', 'Civic Engagement and Social Integration', '{"topic": "culture", "title_ar": "دور الشغل التطوعي بدمج المهاجرين", "questions": [{"id": "q1", "stem": "What is a major benefit of migrant participation in volunteer programs mentioned in the text?", "choices": ["It eliminates the necessity for federal funding in grassroots community centers.", "It helps residents organize the upcoming winter bazaar schedule without managers.", "It builds a significantly stronger sense of belonging and civic responsibility.", "It allows neighborhood institutions to avoid operating free language clinics."], "correct_index": 2}], "situation": "A community coordinator briefs local volunteers about the social impact of neighborhood integration programs.", "vocabulary": ["facilitating", "prejudices", "dismantled", "belonging", "cohesion"], "instructions": "A community coordinator briefs local volunteers about the social impact of neighborhood integration programs.", "situation_ar": "اجتماع بمركز مجتمعي عم يحكوا فيه عن أهمية التطوع لتسهيل اندماج العالم الجداد وكسر الأحكام المسبقة بالحارة.", "audio_transcript": "Hi everyone, thank you for attending the community volunteer briefing. Tonight, we are discussing the vital role of civic engagement in facilitating the long-term social integration of newly arrived residents. In our society, community centers are heavily reliant on volunteer networks to operate free language cafes, legal advice clinics, and cross-cultural workshops. These neighborhood institutions provide an invaluable safe space where mutual prejudices can be dismantled through open dialogue. It has been demonstrated by recent sociological studies that migrants who actively participate in these volunteer programs exhibit a significantly stronger sense of belonging and civic responsibility. If federal funding were granted permanently to these grassroots initiatives, their capacity to offer advanced educational modules would be secured. Had our organization ignored the value of civic networking during the previous migration wave, our neighborhood cohesion would be noticeably weaker today. We appreciate your dedication and would like to walk you through the volunteer schedule for the upcoming winter bazaar."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (218, 1, 'listening', 'B2', 'lesson', 'Digital Health Records and Privacy Boundaries', '{"topic": "healthcare", "title_ar": "السجلات الطبية الديجيتال وسرية بيانات المريض", "questions": [{"id": "q1", "stem": "Why do privacy advocates express grave concerns regarding the new centralized database?", "choices": ["Because it prevents medical specialists from accessing diagnostic records during emergencies.", "Because it causes frequent medication errors due to complex encryption keys.", "Because the health ministry requires medical staff to log out of their terminals.", "Because the database is vulnerable to cyberattacks and unauthorized corporate surveillance."], "correct_index": 3}], "situation": "A clinical supervisor updates healthcare workers on data security regulations for electronic health systems.", "vocabulary": ["mandatory", "vulnerability", "surveillance", "safeguarded", "confidentiality"], "instructions": "A clinical supervisor updates healthcare workers on data security regulations for electronic health systems.", "situation_ar": "مسؤول بعيادة طبية عم يوجه الدكاترة والممرضات عن نظام السجلات الرقمية الجديد ومخاوف حماية الخصوصية من الهجمات الإلكترونية.", "audio_transcript": "Good morning, medical staff. I need your undivided attention regarding the mandatory implementation of the standardized digital patient records system across our clinic network. While this electronic transformation is heavily supported by hospital administrators because it enables specialists to access vital medical histories instantly, thereby preventing dangerous medication errors, it has sparked an intense debate regarding data protection. Privacy advocates have expressed grave concerns about the vulnerability of these centralized databases to sophisticated cyberattacks and unauthorized corporate surveillance. They emphasize that sensitive diagnostic records must be safeguarded using advanced encryption keys. If stricter legal frameworks had been established by the health ministry prior to this digital transition, public skepticism would be noticeably lower today. As doctors and nurses, we are required to maintain strict patient confidentiality while utilizing these new automated interfaces. Please ensure that you log out of your terminals immediately after completing each patient evaluation."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (219, 1, 'listening', 'B2', 'lesson', 'Algorithmic Bias in Recruitment Software', '{"topic": "job applications", "title_ar": "التحيز المخفي بخوارزميات توظيف الشركات", "questions": [{"id": "q1", "stem": "Why does automated screening software frequently filter out qualified international candidates?", "choices": ["Because the algorithms are trained on historical datasets that reflect existing corporate imbalances.", "Because employment laws universally mandate expensive compliance protocols for start-ups.", "Because human resource specialists refuse to audit the selection criteria manually.", "Because tech companies design software specifically to create recruitment bottlenecks."], "correct_index": 0}], "situation": "A human resources expert delivers a lecture on structural discrimination embedded in automated hiring systems.", "vocabulary": ["screening", "replicate", "anonymized", "mandated", "equitable"], "instructions": "A human resources expert delivers a lecture on structural discrimination embedded in automated hiring systems.", "situation_ar": "ندوة للموارد البشرية عم تناقش كيف برامج التوظيف المؤتمتة أوقات بتظلم المتقدمين الأجانب بسبب الأسماء أو الخلفية التعليمية.", "audio_transcript": "Welcome to today''s corporate human resources seminar. Our main topic focuses on the ethical challenges of utilizing automated screening software during the initial job application stages. While these advanced algorithms are marketed by tech companies as objective tools designed to eliminate human bias from the hiring process, studies indicate they often replicate systemic discrimination. Because the software is trained on historical datasets that reflect existing corporate imbalances, candidates with foreign-sounding names or non-traditional educational backgrounds are frequently filtered out automatically. If anonymized application procedures were universally mandated by employment laws, these unconscious structural biases would be reduced significantly. Had our corporate board implemented rigorous diversity training for our software development teams earlier, our current recruitment bottleneck might have been avoided entirely. Moving forward, human resource specialists must critically audit algorithmic recommendations to ensure our selection criteria remain fully inclusive and equitable for all qualified global talent."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (220, 1, 'listening', 'B2', 'lesson', 'New Municipal Utility and Waste Regulations', '{"topic": "bureaucracy", "title_ar": "قوانين البلدية الجديدة لفرز الزبالة والكهربا", "questions": [{"id": "q1", "stem": "What penalty will occur if residents repeatedly fail to separate their household waste?", "choices": ["The district council will stop distributing bilingual informational pamphlets.", "Financial penalties will be issued to the entire residential building.", "Smart sensors will be removed from all blue and green containers entirely.", "The federal government will cancel the mandatory energy efficiency audits."], "correct_index": 1}], "situation": "A neighborhood representative reads a community announcement regarding strict environmental compliance rules.", "vocabulary": ["compliance", "rigorous", "protocols", "penalties", "inevitably"], "instructions": "A neighborhood representative reads a community announcement regarding strict environmental compliance rules.", "situation_ar": "إعلان رسمي من مؤسسة السكن بالبلدية عم ينبهوا فيه السكان من غرامات مالية إذا ما فرزوا الزبالة منيح والتزموا بقوانين البيئة.", "audio_transcript": "Hello residents, this is an official announcement from the municipal housing authority regarding the updated regulations for public utility consumption and household waste disposal. Due to strict new environmental compliance laws enacted by the federal government, all residential complexes are now subject to rigorous energy efficiency audits. Additionally, our neighborhood recycling protocols have been modified to enforce absolute waste separation. Bins are monitored via smart sensors, and financial penalties will be issued to the entire building if non-recyclable materials are repeatedly discovered in the blue or green containers. If tenants fail to comply with these strict guidelines, communal maintenance fees will inevitably increase next year. Had these eco-friendly waste management strategies been adopted by our district council a decade ago, our current carbon offset targets would have already been achieved successfully. We highly encourage you to review the bilingual informational pamphlets that were distributed to your mailboxes yesterday morning."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (221, 1, 'listening', 'C1', 'lesson', 'Overhauling the Postgraduate Research Framework', '{"topic": "academic research", "title_ar": "تعديل نظام أبحاث الدراسات العليا", "questions": [{"id": "q1", "stem": "What does the speaker identify as the primary cause of discouragement for doctoral candidates pursuing cross-disciplinary research?", "choices": ["The compartmentalization of funding within traditional departmental silos based on historical metrics.", "A comprehensive structural complete absence of interest in global crises among modern university senates.", "The rapid, unvetted complete elimination of legal administrative pathways for international scholars.", "A total mandate requiring all permanent endowments to be spent on basic linguistic refinement."], "correct_index": 0}], "situation": "A university dean delivers a speech to faculty members regarding structural changes to postgraduate funding and research frameworks.", "vocabulary": ["inertia", "compartmentalized", "silos", "endowments", "viability"], "instructions": "A university dean delivers a speech to faculty members regarding structural changes to postgraduate funding and research frameworks.", "situation_ar": "عميد جامعة عم يلقي خطاب قدام أعضاء الهيئة التدريسية عن التغييرات الهيكلية بتمويل الدراسات العليا وأطر الأبحاث.", "audio_transcript": "Good morning, fellow researchers. Today, I''d like to address the structural inertia currently impeding our postgraduate departments. Seldom have we seen such profound reluctance to adopt interdisciplinary methodologies, despite clear evidence that contemporary global crises require a radical synthesis of distinct academic fields. In our current framework, research funding remains predominantly compartmentalized within traditional departmental silos, which inadvertently discourages doctoral candidates from embarking on speculative, cross-disciplinary ventures. It is precisely this institutional friction that has prompted the university senate to overhaul our doctoral curriculum. Were funding bodies to establish permanent endowments specifically earmarked for interdisciplinary laboratories, the pace of scientific innovation would accelerate exponentially. Furthermore, international scholars often bear the brunt of these systemic inefficiencies, navigating not only pedagogical adjustments but also an incredibly dense web of academic bureaucracy. To counteract this, we are pioneering integrated hubs that combine linguistic refinement with targeted professional cultivation. Ultimately, our long-term viability as a premier research institution hinges entirely upon our capacity to dismantle these antiquated barriers, establishing an ecosystem where cognitive diversity is actively celebrated as the cornerstone of intellectual progress. I will now take your questions regarding the allocation metrics."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (222, 1, 'listening', 'C1', 'lesson', 'The Fragmentation of Contemporary Public Discourse', '{"topic": "media literacy", "title_ar": "انقسام النقاش العام بالوقت الحالي", "questions": [{"id": "q1", "stem": "According to the speaker, what is the ultimate driver behind corporate platforms prioritizing sensationalized content?", "choices": ["A legislative mandate to enforce media literacy frameworks uniformly across European demographics.", "A business model focused entirely on maximizing screen time to increase advertising revenue.", "An ideological commitment to help individual citizens deconstruct systemic political biases.", "The complete replacement of public-key encryption protocols with proprietary digital tools."], "correct_index": 1}], "situation": "A media analyst discusses the societal impacts of algorithmic content curation during a panel discussion broadcast.", "vocabulary": ["epistemological", "curation", "partisan", "pervasive", "curtailed"], "instructions": "A media analyst discusses the societal impacts of algorithmic content curation during a panel discussion broadcast.", "situation_ar": "محلل إعلامي عم يناقش التأثيرات المجتمعية لتوجيه المحتوى عبر الخوارزميات خلال برنامج ندوة إذاعي.", "audio_transcript": "Welcome back to our weekly media symposium. Tonight, we''re unpacking how the contemporary digital landscape has precipitated an unprecedented epistemological crisis, altering the fundamental mechanisms through which public audiences consume information. In an environment dominated by automated algorithmic curation, corporate platforms systematically prioritize highly sensationalized, divisive content. Why? Because their business model relies entirely on maximizing user screen time to drive advertising revenue, completely detached from factual accuracy. Consequently, the public sphere has fractured into hyper-partisan echo chambers, wherein citizens are continuously exposed to perspectives that reinforce existing cognitive biases. It is this pervasive manipulation that undermines democratic discourse, rendering constructive consensus virtually unachievable. To counteract this destabilizing trend, educational specialists strongly advocate for the universal implementation of comprehensive media literacy frameworks. Such modern curricula must transcend elementary fact-checking techniques, focusing instead on equipping individual citizens with the analytical tools necessary to deconstruct systemic media bias and identify sophisticated digital manipulations. Were European regulatory bodies to enforce more stringent oversight on proprietary corporate algorithms, the proliferation of malicious disinformation could be substantively curtailed. However, legislation alone remains insufficient; individual cognitive resilience must be meticulously cultivated through continuous critical inquiry across all societal demographics."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (223, 1, 'listening', 'C1', 'lesson', 'Re-engineering Corporate Ecosystems for Circularity', '{"topic": "business strategy", "title_ar": "إعادة هندسة أنظمة الشركات للاقتصاد الدائري", "questions": [{"id": "q1", "stem": "What primary operational shift must corporations execute to successfully adopt circular economic frameworks?", "choices": ["They must focus exclusively on generating short-term quarterly returns for conventional investment markets.", "They must implement superficial adjustments while maintaining the conventional manufacturing paradigm.", "They must comprehensively re-engineer their entire ecosystem and cultivate relationships based on stewardship.", "They must increase their reliance on volatile raw material markets to expand physical ownership metrics."], "correct_index": 2}], "situation": "A business consultant delivers a strategic briefing to corporate executives about the shift from linear to circular business models.", "vocabulary": ["fragility", "modular", "inception", "stewardship", "obsolescence"], "instructions": "A business consultant delivers a strategic briefing to corporate executives about the shift from linear to circular business models.", "situation_ar": "مستشار شركات عم يقدم توجيه استراتيجي لمدراء تنفيذيين عن التحول من النماذج الخطية للدائرية.", "audio_transcript": "Good afternoon, colleagues. As supply chain vulnerabilities continue to expose the inherent fragility of linear economies, forward-thinking European enterprises must accelerate their transition toward circular business strategies. The conventional manufacturing paradigm has generated catastrophic ecological consequences while increasingly exposing our organizations to highly volatile raw material markets. In contrast, circular economic frameworks prioritize systemic regeneration, designing products to be entirely modular, easily repairable, and fundamentally recyclable from their inception. Adopting these sustainable models requires not merely superficial adjustments to operational processes, but a comprehensive re-engineering of the entire corporate ecosystem. Not only must we reinvent our physical manufacturing methodologies, but we must also cultivate entirely new customer relationships predicated on product stewardship rather than outright material ownership. What complicates this corporate transition is the short-term financial pressure exerted by conventional investment markets, which frequently demand immediate quarterly returns at the expense of long-term ecological viability. Had financial institutions integrated comprehensive environmental ESG metrics into their core valuation frameworks sooner, the corporate adoption of circularity would be vastly more advanced today. Moving forward, businesses that fail to integrate these sustainable paradigms risk institutional obsolescence as regulatory compliance standards tighten globally."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (224, 1, 'listening', 'C1', 'lesson', 'The Legal Nuances of Transnational Data Privacy', '{"topic": "law", "title_ar": "التفاصيل القانونية لسرية البيانات عبر الحدود", "questions": [{"id": "q1", "stem": "What negative consequence of transnational legislative texts on ordinary citizens is highlighted by the speaker?", "choices": ["They completely eliminate the legal right of cross-border commerce within all member states.", "They force local jurisdictions to fund bilingual legal clinics using regional security mandates.", "They automatically subject ordinary citizens to predatory corporate surveillance networks without appeal.", "The complex nominalization within the texts frequently obscures the practical application of their rights."], "correct_index": 3}], "situation": "A legal scholar gives a presentation at a jurisprudence conference regarding the conflict between centralized EU data laws and local court agility.", "vocabulary": ["harmonization", "jurisprudence", "jurisdictions", "nominalization", "intricate"], "instructions": "A legal scholar gives a presentation at a jurisprudence conference regarding the conflict between centralized EU data laws and local court agility.", "situation_ar": "باحث قانوني عم يقدم عرض بمؤتمر أحكام القضائية عن الصراع بين قوانين البيانات الأوروبية ومرونة المحاكم المحلية.", "audio_transcript": "Good evening, legal professionals. The evolution of trans-European statutory frameworks represents a continuous negotiation between jurisdictional harmonization and the preservation of national individual autonomy. As member states increasingly integrate their administrative systems to facilitate cross-border commerce, the tension between centralized European regulations and localized statutory traditions becomes highly pronounced. Nowhere is this delicate balance more fiercely contested than in the domain of data privacy jurisprudence, where the enforcement of standardized protections frequently conflicts with regional security mandates. Legal scholars observe that while centralized regulations provide an essential shield against predatory corporate surveillance, they occasionally restrict the administrative agility of local judicial bodies. It is this institutional friction that necessitates a sophisticated calibration of our legal mechanisms. What remains problematic is the complex nominalization embedded within transnational legislative texts, which frequently obscures the immediate practical application of statutory rights for ordinary citizens. Were local jurisdictions to establish dedicated, bilingual legal clinics, the accessibility of trans-European judicial pathways would be significantly enhanced. Not only must legal professionals master these intricate administrative networks, but they must also develop a profound sensitivity to the localized cultural contexts that continuously inform statutory interpretations."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (225, 1, 'listening', 'C1', 'lesson', 'Spatial Architecture and Collective Memory', '{"topic": "philosophy", "title_ar": "العمارة المكانية والذاكرة الجماعية", "questions": [{"id": "q1", "stem": "What practical paradigm does the speaker propose to reconcile historical preservation with modern commercial utility?", "choices": ["A sustainable structural and practical framework known as adaptive reuse.", "The complete demolition of ancient historic quarters to expand high-density development zones.", "The systematic replacement of collective memory with homogenized corporate architecture structures.", "Allowing modern real estate markets to operate entirely free from municipal legislative mandates."], "correct_index": 0}], "situation": "A philosophy professor lectures postgraduate students on the existential value of preserving old buildings amidst modern real estate pressure.", "vocabulary": ["ontological", "remnants", "proliferation", "lucrative", "continuity"], "instructions": "A philosophy professor lectures postgraduate students on the existential value of preserving old buildings amidst modern real estate pressure.", "situation_ar": "أستاذ فلسفة عم يعطي محاضرة لطلاب الدراسات العليا عن القيمة الوجودية للحفاظ ع البنايات القديمة قدام ضغط العقارات.", "audio_transcript": "Welcome to today''s seminar on urban philosophy. The conceptual framework surrounding urban preservation has shifted from simple aesthetic appreciation to a rigorous investigation into the ontological value of architectural heritage. Contemporary philosophical discourse posits that historical buildings are not merely decorative remnants of bygone eras, but vital spatial structures that activate human consciousness and ground communal identity. In an age characterized by hyper-rapid urbanization and the proliferation of homogenized corporate architecture, ancient structures offer a tangible link to collective memory. It is this profound grounding capacity that renders preservation efforts culturally essential. However, the operationalization of preservation principles within modern real estate markets remains highly problematic. Urban planners frequently confront intense commercial pressure to demolish historic quarters in favor of high-density, economically lucrative developments. What is desperately needed is a philosophical framework that synthesizes historical preservation with functional modern utility, a paradigm often referred to as adaptive reuse. Not only does the adaptive reuse of historic buildings conserve precious material resources, but it also maintains the architectural continuity of urban landscapes. Were municipal councils to enforce strict legislative mandates protecting spatial heritage from speculative development, cities would retain their unique historical character."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (226, 1, 'listening', 'C1', 'lesson', 'Strategic Sovereignty in the Critical Minerals Market', '{"topic": "geopolitics", "title_ar": "السيادة الاستراتيجية بسوق المعادن الحساسة", "questions": [{"id": "q1", "stem": "According to the analysis, what constitutes a major vulnerability for European strategic independence during the green transition?", "choices": ["Its total administrative inability to rewrite standard international trade agreements.", "Its heavy reliance on foreign nations for extracting and processing rare earth elements.", "The complete elimination of solar, wind, and hydrogen infrastructures across central Europe.", "An absolute surplus of domestic mining and recycling frameworks within member states."], "correct_index": 1}], "situation": "A geopolitical analyst briefs government officials on how the shift to renewable energy changes global power balances and creates vulnerabilities for Europe.", "vocabulary": ["realignment", "leverage", "sovereignty", "indispensable", "nuanced"], "instructions": "A geopolitical analyst briefs government officials on how the shift to renewable energy changes global power balances and creates vulnerabilities for Europe.", "situation_ar": "محلل جيوسياسي عم يقدم توجيه لمسؤولين حكوميين عن كيف التحول للطاقة المتجددة عم يغير موازين القوى العالمية وبيعمل ثغرات لأوروبا.", "audio_transcript": "Good evening, ladies and gentlemen. The global transition away from fossil fuels is orchestrating a profound geopolitical realignment, challenging established international power dynamics and redefining the strategic value of geographical territories. For decades, international relations were heavily dominated by the protection of hydrocarbon supply chains, with resource-rich nations exercising immense diplomatic leverage. However, the rapid proliferation of renewable energy technologies—particularly solar, wind, and hydrogen infrastructures—is shifting power toward nations that control critical mineral supply chains and advanced manufacturing technologies. Not only do these technological advancements alter resource dependencies, but they also rewrite international trade agreements. It is this systemic shift that forces European policymakers to rethink their regional sovereignty strategies. What remains a critical vulnerability for Europe is its heavy reliance on foreign nations for the extraction and processing of rare earth elements, which are indispensable for producing electric batteries and wind turbines. Were the European Union to establish decentralized domestic mining and recycling frameworks, its strategic independence would be significantly strengthened. Furthermore, the economic destabilization of traditional petrostates could induce regional conflicts, necessitating a highly nuanced diplomatic approach to resource realignment."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (227, 1, 'listening', 'C1', 'lesson', 'Deconstructing the Monolingual Bias in Education', '{"topic": "academic research", "title_ar": "تفكيك الانحياز للغة الوحدة بالتعليم", "questions": [{"id": "q1", "stem": "How does the speaker believe educational systems should view code-switching and multilingual practices?", "choices": ["As clear indicators of incomplete language acquisition and cognitive confusion.", "As systemic violations of standard registers that must be penalized in professional exams.", "As genuine cognitive assets and a potent form of beneficial cultural capital.", "As historical remnants of linear migration patterns that are obsolete in modern schools."], "correct_index": 2}], "situation": "A sociolinguist delivers a university lecture criticizing how official school systems penalize hybrid language styles used by immigrant students.", "vocabulary": ["hybridity", "pedagogical", "rigidity", "adherence", "repertoires"], "instructions": "A sociolinguist delivers a university lecture criticizing how official school systems penalize hybrid language styles used by immigrant students.", "situation_ar": "عالم لغة اجتماعي عم يعطي محاضرة بالجامعة عم ينتقد فيها كيف السيستم التعليمي الرسمي بيخالف طرق الحكي المختلطة للطلاب المهاجرين.", "audio_transcript": "Hello, everyone. Academic research into migrant communities in Western Europe has increasingly focused on the concept of linguistic hybridity and its direct correlation with socio-cultural capital. Traditional pedagogical perspectives often treated the emergence of mixed linguistic codes—such as blending Arabic syntactic structures with German vocabulary—as a severe deficit indicating incomplete language acquisition. However, contemporary sociolinguistic frameworks completely deconstruct this outdated narrative, demonstrating that linguistic hybridity represents a highly sophisticated communicative competence. It is this multi-layered linguistic flexibility that allows individuals to navigate distinct cultural spheres fluidly, maximizing their social network opportunities. What complicates the academic valuation of these linguistic skills is the institutional rigidity of official educational systems, which continue to demand strict adherence to monolingual standard registers during professional examinations. Were school curricula to validate code-switching and multilingual practices as genuine cognitive assets, the educational achievements of international students would improve substantially. Sociologists emphasize that linguistic flexibility functions as a potent form of cultural capital, empowering individuals to challenge systemic marginalization. Ultimately, fostering an inclusive educational ecosystem requires a definitive shift away from monolingual biases, embracing instead the rich communicative repertoires that characterize modern diverse urban populations."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (228, 1, 'listening', 'C1', 'lesson', 'Epistemological Resilience in Digital Spaces', '{"topic": "media literacy", "title_ar": "المناعة الفكرية بالفضاء الرقمي", "questions": [{"id": "q1", "stem": "What step does the speaker claim is necessary beyond legislative intervention to preserve democratic integrity online?", "choices": ["The total elimination of data sovereignty laws across all regional regulatory institutions.", "Allowing automated feedback loops to freely analyze individual behavioral data arrays.", "Enforcing strict monolingual standard registers across all corporate platform algorithms.", "A pedagogical overhaul that positions algorithmic literacy as a core civic competence."], "correct_index": 3}], "situation": "A professor addresses a seminar on media studies, explaining how automated online platforms exploit psychological triggers to shape public awareness.", "vocabulary": ["pervasive", "protocols", "oblivious", "sovereignty", "skepticism"], "instructions": "A professor addresses a seminar on media studies, explaining how automated online platforms exploit psychological triggers to shape public awareness.", "situation_ar": "أستاذ عم يوجه ندوة عن الدراسات الإعلامية، عم يشرح فيها كيف المنصات أونلاين بتستغل المحفزات النفسية لتوجيه وعي الناس.", "audio_transcript": "Good morning, students. The pervasive influence of algorithmic curation on digital information networks has structurally transformed the nature of public discourse, presenting unprecedented challenges to media literacy. Contemporary data platforms leverage complex machine-learning protocols to analyze vast arrays of individual behavioral data, thereby predicting and delivering content customized to maximize screen time. This automated feedback loop inherently capitalizes on psychological triggers, systematically amplifying sensationalized or divisive narratives. It is this underlying commercial architecture that distorts collective consciousness, creating deeply polarized societal factions. Media researchers note that the standard consumer remains largely oblivious to the invisible mechanisms shaping their digital environment, frequently confusing curated feeds with objective reality. Were regulatory institutions to mandate algorithmic transparency and enforce data sovereignty laws, citizens would regain a degree of cognitive agency over their digital consumption. However, mitigating this systemic crisis demands more than legislative intervention; it requires a pedagogical overhaul that positions algorithmic literacy as a core civic competence. Ultimately, preserving democratic integrity in the digital era depends on our collective ability to cultivate critical skepticism toward the automated systems that filter our shared socio-political reality."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (229, 1, 'listening', 'C1', 'lesson', 'Navigating Middle Management Resistance to Agility', '{"topic": "business strategy", "title_ar": "التعامل مع مقاومة الإدارة الوسطى للمرونة", "questions": [{"id": "q1", "stem": "According to the speaker, why does middle management frequently resist the application of agile methodologies?", "choices": ["Because decentralized frameworks fundamentally challenge their institutional authority.", "Because agile tools force them to expand hierarchical command structures permanently.", "Because they prefer to decouple performance evaluations from static long-term planning cycles.", "Because cross-functional teams cause hyper-accelerated technological disruptions in stable markets."], "correct_index": 0}], "situation": "A corporate restructuring specialist presents a strategic analysis to a board of directors regarding corporate agility transitions.", "vocabulary": ["inertia", "hierarchical", "obsolete", "entrenched", "decouple"], "instructions": "A corporate restructuring specialist presents a strategic analysis to a board of directors regarding corporate agility transitions.", "situation_ar": "إخصائي إعادة هيكلة الشركات عم يقدم تحليل استراتيجي لمجلس الإدارة عن التحول نحو المرونة الإدارية ومقاومة الموظفين.", "audio_transcript": "Good morning, executive board members. The application of agile methodologies within traditionally bureaucratic European corporate structures has emerged as a core business strategy to combat institutional inertia. Historically, corporate enterprises operating in stable markets relied on hierarchical command structures and extensive, long-term planning cycles. However, the contemporary commercial landscape, characterized by hyper-accelerated technological disruptions and volatile consumer demands, has rendered these static models obsolete. To remain competitive, organizations are forced to decentralize decision-making authority, organizing internal workforces into cross-functional, autonomous teams. It is this operational restructuring that facilitates rapid iteration and continuous adaptation to market shifts. What frequently sabotages these organizational transformations is the entrenched psychological resistance from middle management, whose institutional authority is fundamentally challenged by decentralized frameworks. Corporate analysts emphasize that unless leadership teams actively cultivate an organizational culture that views failure as an essential learning metric, structural agility remains completely unattainable. Were corporate entities to decouple performance evaluations from rigid, short-term targets, employee innovation would flourish. Ultimately, dismantling institutional inertia requires a profound philosophical commitment to continuous evolution, transforming rigid corporations into adaptive ecosystems capable of thriving amidst global market uncertainty."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (230, 1, 'listening', 'C1', 'lesson', 'The Jurisprudence of the Right to Disconnect', '{"topic": "law", "title_ar": "الفقه القانوني للحق بفصل الاتصال بالشغل", "questions": [{"id": "q1", "stem": "What major obstacle to enforcing the ''right to disconnect'' in modern corporate environments is cited by the speaker?", "choices": ["The absolute refusal of international labor bodies to acknowledge psychological burnout.", "The operational fact that global companies frequently function across multiple time zones.", "A comprehensive legal ban prohibiting remote employment models across all European nations.", "The complete disappearance of digital connectivity options outside of official working hours."], "correct_index": 1}], "situation": "A labor lawyer delivers a keynote presentation at a legal conference discussing the enforcement challenges of digital employment laws.", "vocabulary": ["normalization", "blurring", "doctrine", "transnational", "mandates"], "instructions": "A labor lawyer delivers a keynote presentation at a legal conference discussing the enforcement challenges of digital employment laws.", "situation_ar": "محامي قضايا عمالية عم يلقي كلمة بمؤتمر قانوني عم يناقش فيها تحديات تطبيق قوانين الشغل الرقمي وفصل الاتصال.", "audio_transcript": "Good evening, colleagues. The rapid normalization of remote employment models across Europe has necessitated a fundamental re-examination of labor law, specifically regarding individual boundary management. While digital connectivity offers unparalleled flexibility, it simultaneously facilitates a corporate culture of constant availability, systematically blurring the distinction between professional duties and private life. To safeguard employee health, several European nations have pioneered statutory interventions, universally referred to as the ''right to disconnect.'' This legal doctrine establishes that employees are under no obligation to engage with corporate communications outside of official working hours. It is this protective legislation that aims to mitigate the rising incidence of psychological burnout among digital workforces. However, enforcing these statutory boundaries within highly fluid, transnational corporate environments remains immensely complex. Legal experts note that global companies frequently operate across multiple time zones, complicating the application of localized labor regulations. Were international labor bodies to draft unified, enforceable digital employment standards, cross-border exploitation could be effectively neutralized. Ultimately, the successful containment of digital exploitation requires a synchronized strategy that reinforces robust legislative mandates with a profound cultural shift that treats uninterrupted leisure as an absolute human right."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (231, 1, 'listening', 'C2', 'lesson', 'The Fiscal Architecture of the Eurozone', '{"topic": "economics", "title_ar": "الهيكل المالي لمنطقة اليورو", "questions": [{"id": "q1", "stem": "According to the speaker, what primary structural defect continues to undermine the stability of the Eurozone?", "choices": ["The implementation of a unified monetary policy without a corresponding fiscal unification mechanism.", "The absolute legal complete absence of independent export-driven core economies within Central Europe.", "The total elimination of counter-cyclical budgetary options by peripheral nation treasuries.", "An unprecedented surplus of joint sovereign debt instruments favored by wealthier electorates."], "correct_index": 0}], "situation": "A prominent macroeconomic policy debate between international financial analysts during a high-stakes banking summit in Frankfurt.", "vocabulary": ["hamstrung", "asymmetry", "relinquish", "austerity", "disincentivize"], "instructions": "A prominent macroeconomic policy debate between international financial analysts during a high-stakes banking summit in Frankfurt.", "situation_ar": "نقاش سياسي واقتصادي حاد بين محللين ماليين دوليين خلال قمة مصرفية رفيعة المستوى بفرانكفورت.", "audio_transcript": "Look, let''s be entirely honest about the structural architecture of the Eurozone. It''s fundamentally one of the most audacious macroeconomic experiments we''ve ever witnessed, yet here we are, still completely hamstrung by this glaring architectural asymmetry. I mean, you simply cannot implement a unified monetary policy across diverse sovereign states without a corresponding fiscal unification. It defies basic economic logic. When these countries relinquished control over their domestic monetary instruments—specifically their ability to independently manipulate interest rates or devalue their currency to absorb external shocks—they essentially rendered themselves exceptionally vulnerable to asymmetric downturns. And since there''s no centralized Eurozone fiscal treasury capable of executing counter-cyclical budgetary transfers, what happens? Distressed member states are forced to rely almost exclusively on painful internal deflation and incredibly stringent fiscal austerity just to claw back some semblance of international competitiveness. This dynamic is precisely what ignites these devastating socio-economic crises, because the entire burden of structural adjustment falls disproportionately on public infrastructure, social welfare networks, and employment metrics. Now, economists have long argued that a monetary union cannot achieve long-term equilibrium without robust fiscal risk-sharing mechanisms—like a permanent common budget or joint sovereign debt instruments. But let''s look at the political reality. The path toward deeper fiscal integration is bitterly contested by national electorates, polarizing the continent along historical geopolitical fault lines. Wealthier core nations routinely express profound anxiety regarding the moral hazard of subsidizing structurally weaker economies, fearing a permanent transfer union would completely disincentivize necessary domestic reforms. Conversely, peripheral nations quite rightly contend that the current framework systematically favors export-driven core economies, thereby exacerbating structural imbalances across the single market. Ultimately, the survival of the currency union hinges on a political consensus that transcends localized electoral calculations, but whether European leaders possess the statecraft to forge that consensus remains an open question."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (232, 1, 'listening', 'C2', 'lesson', 'Algorithmic Determinism and Moral Agency', '{"topic": "ethics", "title_ar": "الحتمية الخوارزمية والإرادة الأخلاقية", "questions": [{"id": "q1", "stem": "What major legal risk does the speaker associate with the phenomenon of algorithmic determinism?", "choices": ["The total elimination of proprietary machine-learning protocols from administrative datasets.", "The systematic erosion of individualized justice in favor of probabilistic categorization.", "An immediate expansion of transparent human evaluation frameworks across judicial systems.", "The complete replacement of social housing eligibility criteria with mathematical variables."], "correct_index": 1}], "situation": "A keynote speech delivered at a bioethics symposium detailing the systemic erosion of individual justice through judicial predictive analytics.", "vocabulary": ["purging", "reify", "veneer", "recidivism", "absolving"], "instructions": "A keynote speech delivered at a bioethics symposium detailing the systemic erosion of individual justice through judicial predictive analytics.", "situation_ar": "خطاب أساسي بورشة عمل عن الأخلاق الحيوية عم يوضح التأكل الممنهج للعدالة الفردية بسبب تحليلات القضاء التنبؤية.", "audio_transcript": "Now, if we delve into the automated decision-making systems currently proliferating across public administration and judicial frameworks, we confront a profound shift in how modern societies conceptualize moral agency and constitutional rights. Institutions are increasingly relying on complex machine-learning protocols to evaluate everything from recidivism risks in criminal sentencing to eligibility criteria for social housing. Proponents aggressively champion these technologies as emblems of mathematical objectivity, claiming they purge human bias from administrative processes. But let''s look past that veneer of computational neutrality. A rigorous examination reveals that these algorithms frequently reify and obscure systemic discrimination. Why? Because these proprietary models are trained on historical datasets that inherently reflect deeply entrenched societal inequalities. Consequently, their outputs invariably perpetuate those exact disparities, effectively transforming past prejudices into predictive certainty. This phenomenon, which we can call algorithmic determinism, systematically erodes the foundational legal principle of individualized justice, replacing nuanced human evaluation with probabilistic categorization. Furthermore, the opaque, ''black-box'' nature of these advanced protocols creates an epistemic barrier that completely undermines democratic accountability. When a citizen is denied a fundamental right or social benefit based on an automated scoring system, tracing the specific logic behind that decision becomes virtually impossible. This effectively neutralizes the constitutional right to appeal or challenge administrative overreach. We''re facing an urgent legal and bioethical dilemma here. By delegating complex moral and legal evaluations to automated code, society risks entirely absolving human actors of ethical accountability while institutionalizing a form of technocratic governance that prioritizes computational efficiency over human dignity. We need an immediate, robust framework to protect civic spaces before this automated overreach becomes completely irreversible."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (233, 1, 'listening', 'C2', 'lesson', 'Kafkaesque Realities in Modern Transnational Literature', '{"topic": "literature analysis", "title_ar": "الواقع الكافكاوي بالأدب الحديث العابر للحدود", "questions": [{"id": "q1", "stem": "According to the podcast analysis, how does contemporary transnational literature subvert standard migration narratives?", "choices": ["By focusing heavily on the rapid and successful linear assimilation of corporate candidates.", "By completely eliminating magical realist elements to maintain historical document accuracy.", "By deploying an aesthetics of estrangement to depict administrative spaces as menacing and arbitrary.", "By validating state integration mandates as transparent structures that prevent psychological trauma."], "correct_index": 2}], "situation": "A literary podcast segment analyzing Kafkaesque structures inside contemporary trans-European migrant novels.", "vocabulary": ["corpus", "estrangement", "oeuvre", "ontological", "subversion"], "instructions": "A literary podcast segment analyzing Kafkaesque structures inside contemporary trans-European migrant novels.", "situation_ar": "حلقة بودكاست أدبي عم تحلل الهياكل الكافكاوية بقلب روايات المهاجرين المعاصرة العابرة لأوروبا.", "audio_transcript": "Welcome back to the channel. Today we''re deep-diving into the contemporary corpus of transnational literature emerging from the European migrant experience, and specifically how it deploys an aesthetics of estrangement to interrogate the labyrinthine structures of state bureaucracy. If you look closely at these texts, you''ll see that modern authors are systematically moving beyond those conventional, linear migration narratives that usually center on simple cultural assimilation or superficial linguistic friction. Instead, these highly sophisticated works articulate a profound existential dislocation by drawing explicit structural parallels to the surreal, menacing architectures found in Franz Kafka’s oeuvre. In these modern narratives, the immigration office, the asylum accommodation center, and the judicial courtroom are transformed into contemporary iterations of Kafka''s The Castle—spaces defined by completely arbitrary regulations, invisible authorities, and seemingly infinite procedural delays. The protagonist''s journey is characterized by a perpetual ontological suspension, where their legal identity, human rights, and very temporal existence are governed by an inaccessible administrative machinery. By utilizing highly stylized prose, fragmented narrative structures, and magical realist disruptions, these authors meticulously deconstruct the deep psychological trauma inflicted by systemic bureaucratic alienation. The text essentially functions as a hermeneutic mirror, reflecting how the modern state utilizes complex paperwork, linguistic mistranslations, and constantly shifting legislative mandates as deliberate instruments of socio-political containment. Consequently, this literary subgenre serves as a brilliant epistemological critique of Western integration discourses, exposing the violence implicit in demands for total cultural compliance. Through the deliberate subversion of standard narrative conventions, transnational literature challenges us to confront the institutional absurdities that reduce human lives to mere administrative files, thereby brilliantly reaffirming the role of the contemporary novel as a vital space for political critique and existential resistance."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (234, 1, 'listening', 'C2', 'lesson', 'The Geopolitics of Quantum Sovereignty', '{"topic": "advanced science", "title_ar": "الجيوسياسة للسيادة الكمية", "questions": [{"id": "q1", "stem": "Why does the speaker state that quantum computing poses an asymmetric intelligence threat to sovereign states?", "choices": ["It permanently damages localized semiconductor manufacturing facilities via dilution refrigerators.", "It forces smaller economies to completely eliminate transnational supply chain configurations.", "It mandates the immediate universal application of obsolete cryptographic standards globally.", "It grants the capacity to retroactively decrypt legacy data protected by current public-key encryption."], "correct_index": 3}], "situation": "A national security panel addressing the imminent systemic vulnerability of standard RSA encryption infrastructures.", "vocabulary": ["fault-tolerant", "entanglement", "retroactively", "fortify", "spillover"], "instructions": "A national security panel addressing the imminent systemic vulnerability of standard RSA encryption infrastructures.", "situation_ar": "جلسة للأمن القومي عم تناقش الضعف الهيكلي القريب لبنى التشفير التقليدية (RSA).", "audio_transcript": "So, let''s unpack this mad scramble for what''s being dubbed ''quantum sovereignty.'' The impending realization of fault-tolerant quantum computing at scale is orchestrating a profound geopolitical realignment, fundamentally redefining the parameters of macroeconomic stability and state security. Now, unlike conventional semiconductor innovations, which merely offer incremental upgrades to computational velocity, quantum architecture leverages superposition and entanglement to execute complex calculations at speeds that completely invalidate existing cryptographic standards. The primary geopolitical threat centers directly on the vulnerability of current public-key encryption infrastructure, specifically RSA algorithms, which safeguard our global financial transactions, state secrets, and critical industrial networks. I mean, think about it: a sovereign state that achieves mathematical supremacy via a scalable quantum system would possess the asymmetric capacity to decrypt legacy data retroactively. This completely neutralizes the strategic intelligence shields of foreign adversaries. Recognizing this massive systemic risk, European research institutes and regulatory bodies are scrambling to accelerate the development of post-quantum cryptography standards. They want to fortify critical digital infrastructure before these decryption capabilities actually materialize. But here''s the catch—the transition to quantum-resistant ecosystems is profoundly complicated by the sheer material scarcity of essential components, like superconducting materials and highly specialized dilution refrigerators. Consequently, we see the geopolitical landscape splintering into distinct technocratic blocs. Major global powers are implementing aggressive export controls on quantum hardware and intellectual capital to prevent strategic spillover. This strategic imperative forces smaller economies to navigate incredibly complex technological dependencies, demonstrating that future geopolitical autonomy will depend almost entirely on a nation''s capacity to build and sustain a localized quantum infrastructure, independent of transnational supply chains."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (235, 1, 'listening', 'C2', 'lesson', 'Constitutional Impasses in Federal Decarbonization Mandates', '{"topic": "policy debate", "title_ar": "طرق مسدودة بالدستور بخصوص أوامر إزالة الكربون", "questions": [{"id": "q1", "stem": "What institutional factor frequently delays the execution of supranational decarbonization directives in a federalized system?", "choices": ["The legal constitutional authority of federal states over regional infrastructure and resource allocation.", "The absolute elimination of regional economic planning authority by the European Union.", "The uniform implementation of binding consensus mechanisms across all industrial sectors.", "A comprehensive structural lack of sustainable architecture subsidies within municipal councils."], "correct_index": 0}], "situation": "An academic lecture highlighting the jurisdictional friction between supranational climate directives and regional autonomy.", "vocabulary": ["operationalization", "supranational", "decarbonization", "dilute", "precedents"], "instructions": "An academic lecture highlighting the jurisdictional friction between supranational climate directives and regional autonomy.", "situation_ar": "محاضرة أكاديمية عم تسلط الضوء ع الاحتكاك بالصلاحيات بين توجيهات المناخ الأوروبية والاستقلال الإقليمي.", "audio_transcript": "Right, let''s confront the structural frictions that occur when supranational climate mitigation policies are implemented within heavily federalized European constitutional frameworks. We often see a deep conflict between centralized mandates and regional statutory autonomy. When the European Union issues aggressive decarbonization directives, the ultimate execution of these laws relies on incredibly complex, multi-level governance systems, and nowhere is this more pronounced than within the German federal structure. In this specific framework, the federal states, or Länder, possess substantial constitutional authority over regional economic planning, energy infrastructure regulation, and natural resource allocation. This decentralized setup creates an intense institutional tug-of-war. Regional administrations frequently seek to protect their localized industrial sectors from the economic disruption associated with rapid ecological transitions. For instance, regions that are heavily dependent on manufacturing or automotive industries routinely utilize their legislative leverage to systematically delay or dilute national carbon reduction targets, citing immediate, valid concerns regarding labor market destabilization and regional economic decline. Constitutional scholars observe that this friction is frequently exacerbated by immense legal ambiguity concerning the exact boundary of federal versus regional jurisdiction over sustainable architecture subsidies and grid expansion projects. Had central administrations established more binding consensus mechanisms prior to enacting these legislative overhauls, the integration of renewable energy networks would have proceeded with substantially fewer judicial challenges. Until these constitutional boundaries are calibrated through legal precedents, climate governance will remain a highly contested arena where ecological necessity continuously clashes with the entrenched mechanics of federalist distribution."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (236, 1, 'listening', 'C2', 'lesson', 'Epistemic Friction in Rhineland Corporate Assimilation', '{"topic": "cross-cultural communication", "title_ar": "الاحتكاك المعرفي بالاندماج بقلب شركات الراينلاند", "questions": [{"id": "q1", "stem": "What causes mutual misattunement between local managers and international employees according to the speaker?", "choices": ["The complete absence of high-context statutory documentation in central European multinational corporations.", "Different interpretations of direct, unvarnished critique versus indirect communication styles.", "A mandatory legislative requirement forcing corporate leadership teams to adopt superficial metrics.", "The total legal invalidation of linguistic proficiency standards during feedback evaluations."], "correct_index": 1}], "situation": "A corporate workshop breakdown discussing the misattunement between indirect communicative styles and blunt central European feedback.", "vocabulary": ["dissonance", "predicated", "unvarnished", "misattunement", "latent"], "instructions": "A corporate workshop breakdown discussing the misattunement between indirect communicative styles and blunt central European feedback.", "situation_ar": "ورشة عمل بالشركة عم تفكك عدم الانسجام بين طرق التواصل غير المباشرة والنقد المباشر والناشف بوسط أوروبا.", "audio_transcript": "Okay team, let''s talk about the cultural misalignment that''s currently bottlenecking our professional integration seminars. The integration of diverse global workforces within the unique institutional landscape of Rhineland capitalism frequently precipitates a complex form of epistemic dissonance. This fundamentally alters standard communication protocols and organizational behavior. In multinational corporate environments throughout Central Europe, corporate governance is traditionally predicated on consensus-driven deliberation, high-context statutory documentation, and a meticulous separation between professional execution and personal identification. When international professional candidates, who have been trained within entirely divergent communicative and organizational paradigms, enter this systemic matrix, linguistic proficiency alone proves completely insufficient to guarantee successful integration. Cross-cultural communication experts observe that structural friction points often manifest not during explicit legal disputes, but during localized corporate rituals—such as feedback evaluations, project presentations, and consensus-building meetings. For instance, the heavy reliance on direct, unvarnished critique characteristic of central European corporate communication can be perceived by international employees as deeply destabilizing or personally hostile, thereby rapidly eroding psychological safety. Conversely, localized managers often misinterpret indirect communication styles or relational problem-solving approaches as a distinct lack of professional transparency or intellectual autonomy. This mutual misattunement demonstrates that corporate assimilation requires far more than superficial sensitivity training; it necessitates a comprehensive re-engineering of communication channels that explicitly validates communicative diversity as a genuine cognitive asset. Until corporate leadership teams move beyond superficial diversity metrics, the latent intellectual capital of global talent will remain structurally constrained by localized behavioral models."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (237, 1, 'listening', 'C2', 'lesson', 'The Viability of Absolute Decoupling within Degrowth Frameworks', '{"topic": "economics", "title_ar": "مدى نجاح فصل المسارات المطلق بأطر تراجع النمو", "questions": [{"id": "q1", "stem": "What primary argument do critics raise against the deliberate contraction advocated by the degrowth paradigm?", "choices": ["They claim it would mathematically insulate economic expansion from environmental degradation metrics.", "They argue that absolute decoupling has already successfully resolved the environmental illusion.", "They assert it would induce immediate macroeconomic chaos, revenue collapses, and high unemployment.", "They believe it will eliminate the finite planetary boundaries of modern democratic societies."], "correct_index": 2}], "situation": "An environmental economics radio broadcast debating whether infinite GDP expansion is truly compatible with planetary boundaries.", "vocabulary": ["axiom", "decoupling", "throughput", "impasse", "anthropocene"], "instructions": "An environmental economics radio broadcast debating whether infinite GDP expansion is truly compatible with planetary boundaries.", "situation_ar": "برنامج إذاعي عن الاقتصاد البيئي عم يتناقش إذا كان التوسع اللانهائي للناتج الإجمالي بيتوافق فعلاً مع حدود الكوكب.", "audio_transcript": "So, I want to talk about this whole ecological economics debate, specifically the degrowth paradigm, which is gaining serious traction as escalating ecological crises expose the systemic limitations of carbon capitalism. This macroeconomic theory fundamentally challenges the core axiom of contemporary economics: the assumption that infinite Gross Domestic Product expansion is somehow compatible with finite planetary boundaries. Degrowth proponents argue that contemporary strategies for eco-modernism, like green capitalism and decoupling, constitute an environmental illusion. They maintain that absolute decoupling—meaning the mathematical insulation of economic expansion from total resource extraction and environmental degradation—has never actually occurred at the scale or velocity required to avert climate destabilization. Instead, the degrowth framework advocates for a deliberate, planned contraction of material and energy throughput in wealthy nations, fundamentally restructuring society to prioritize human well-being and ecological health over capital accumulation. Now, critics aggressively contend that such a deliberate contraction would induce immediate macroeconomic chaos, resulting in catastrophic unemployment rates, public revenue collapses, and intense geopolitical vulnerability. They assert that without the financial surplus generated by conventional economic growth, funding advanced scientific research and sustainable infrastructure transformations becomes fiscally impossible. This intellectual impasse highlights the fundamental systemic dilemma of the anthropocene: whether modern democratic societies can successfully re-engineer their socio-economic institutions away from growth dependency without triggering a complete systemic collapse, or whether they will remain bound to an expansionist paradigm until ecological boundary collapses enforce an unplanned contraction. It''s a high-stakes debate that we can no longer afford to ignore."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (238, 1, 'listening', 'C2', 'lesson', 'The Biopolitical Implications of Brain-Computer Interfacing', '{"topic": "ethics", "title_ar": "الآثار السياسية والحيوية لواجهات الدماغ والكمبيوتر", "questions": [{"id": "q1", "stem": "Why do legal scholars demand the immediate codification of specific ''neurorights'' according to the speaker?", "choices": ["Because advanced machine-learning algorithms have successfully eliminated all severe motor impairments.", "To encourage corporate enterprises to aggressively expand decentralized digital feedback loop networks.", "To completely eliminate the therapeutic clinical maturation of modern restorative medicine systems.", "Because conventional human rights frameworks are completely inadequate to handle neurotechnological intrusion."], "correct_index": 3}], "situation": "A university round-table discussion examining the legal necessity of formulating neurorights to protect cognitive liberty.", "vocabulary": ["maturation", "prosthetics", "surveillance", "autonomy", "codification"], "instructions": "A university round-table discussion examining the legal necessity of formulating neurorights to protect cognitive liberty.", "situation_ar": "نقاش طاولة مستديرة بالجامعة عم يدرس الضرورة القانونية لصياغة حقوق عصبية تحمي الحرية الإدراكية.", "audio_transcript": "Alright, let''s push past the clinical hype surrounding brain-computer interfaces and neuroprosthetics. The rapid clinical maturation of these systems has officially transcended the domain of restorative medicine, projecting our society into a challenging bioethical frontier centered on the sanctity of cognitive liberty. Modern neurotechnologies utilize advanced machine-learning algorithms to decode neural signals and translate mental processes into computational commands, offering revolutionary therapeutic solutions for individuals with severe motor impairments. However, as corporate enterprises aggressively invest in consumer-grade neural interfaces designed to enhance cognitive efficiency, optimize attention metrics, or facilitate direct digital communication, the boundary of personal identity and mental privacy becomes profoundly vulnerable. Bioethicists warn that the commercialization of neural data introduces unprecedented opportunities for algorithmic corporate surveillance, enabling corporations or state entities to monitor individual emotional states, subconscious cognitive preferences, and neural responses directly from the cerebral cortex. This capacity for neural monitoring introduces a fundamental epistemic threat to individual autonomy. When corporate data streams can access and manipulate cognitive processes before they even register in conscious human awareness, the very concept of free will becomes compromised. Furthermore, the integration of algorithmic feedback loops that directly stimulate neural pathways to alter mood or behavior risks eroding the boundary of individual agency, transforming human subjects into semi-automated nodes within decentralized digital networks. This systemic vulnerability necessitates a rigorous jurisdictional evolution. Legal scholars contend that conventional human rights frameworks are completely inadequate to handle neurotechnological intrusion, demanding the immediate codification of specific ''neurorights'' designed to protect cognitive liberty, mental privacy, and psychological continuity from predatory commercial exploitation."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (239, 1, 'listening', 'C2', 'lesson', 'The EU AI Act and Transnational Technological Hegemony', '{"topic": "policy debate", "title_ar": "قانون الذكاء الاصطناعي الأوروبي والهيمنة التكنولوجية", "questions": [{"id": "q1", "stem": "What ironic geopolitical outcome do critics of the European artificial intelligence regulations anticipate?", "choices": ["A framework intended to guarantee digital autonomy might solidify technological dependency on foreign platforms.", "Local start-ups will completely eliminate foreign proprietary platforms from the computational infrastructure.", "Transnational tech conglomerates will voluntarily surrender their monopolistic hegemony over large-scale models.", "The state will automatically fund all open-source software development to avoid criminal liabilities."], "correct_index": 0}], "situation": "A technology strategy symposium investigating how rigorous legislative overreach inadvertently favors foreign tech conglomerates.", "vocabulary": ["hegemony", "auditing", "insurmountable", "liabilities", "conglomerates"], "instructions": "A technology strategy symposium investigating how rigorous legislative overreach inadvertently favors foreign tech conglomerates.", "situation_ar": "ندوة لاستراتيجيات التكنولوجيا عم تبحث كيف التغول التنظيمي والقانوني الصارم ممكن يدعم شركات التكنولوجيا الأجنبية بلا ما يقصد.", "audio_transcript": "Look, the ongoing debate regarding the EU AI Act highlights a profound paradox. While it''s designed to regulate foundational artificial intelligence architectures within Europe, it illustrates the fundamental systemic tension between technological sovereignty and legislative overreach. As transnational technology corporations solidify their monopolistic hegemony over large-scale generative models and computational infrastructure, European regulatory bodies have introduced comprehensive legal frameworks to mitigate existential risks and preserve data privacy. This pioneering legislation utilizes a risk-based tier system, mandating absolute architectural transparency, algorithmic auditing, and strict copyright compliance for high-risk deployments. Proponents assert that these strict statutory boundaries are essential to shield citizens from automated discrimination, systemic disinformation, and corporate data exploitation. However, a growing faction of technology strategists, open-source advocates, and digital economists contends that this rigid legislative paradigm inadvertently sabotages regional innovation, creating insurmountable bureaucratic hurdles for local start-ups and independent research frameworks. They argue that by imposing criminal liabilities and expensive compliance protocols on open-source software development, the state effectively centralizes technological control into the hands of a few dominant foreign tech conglomerates who possess the capital to navigate administrative compliance effortlessly. Consequently, this dynamic could result in an ironic geopolitical outcome: a legislative framework explicitly designed to guarantee digital autonomy might solidify Europe’s technological dependency on foreign proprietary platforms. Moving forward, policymakers face the complex task of calibrating enforcement mechanisms so that ethical guardrails protect civic space without completely freezing the domestic capital investment necessary to construct sovereign, locally adapted computational infrastructure."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (240, 1, 'listening', 'C2', 'lesson', 'Polyphonic Identity Synthesis and Monolingual Pedagogical Rigidity', '{"topic": "cross-cultural communication", "title_ar": "تركيب الهوية متعددة الأصوات والجمود التعليمي للغة الوحدة", "questions": [{"id": "q1", "stem": "How do national pedagogical institutions evaluate fluid code-switching among multicultural youth according to the lecturer?", "choices": ["They celebrate it as a sophisticated third space and a valuable form of socio-cultural capital.", "They pathologize hybrid structures as indicators of linguistic deficit or cognitive confusion.", "They actively utilize it as the absolute metric for socio-economic mobility and employment.", "They mandate its universal integration across all formal cross-cultural communication channels."], "correct_index": 1}], "situation": "A sociolinguistic lecture exploring how institutional evaluation mechanisms pathologize fluid code-switching among diasporic youth.", "vocabulary": ["drift", "polyphonic", "syncretic", "enclaves", "pathologizing"], "instructions": "A sociolinguistic lecture exploring how institutional evaluation mechanisms pathologize fluid code-switching among diasporic youth.", "situation_ar": "محاضرة بعلم اللغة الاجتماعي عم تستكشف كيف آليات التقييم بالمؤسسات عم تتعامل مع التبديل اللغوي المرن كمشكلة وعيب عند شباب المغتربين.", "audio_transcript": "To wrap up today''s sociolinguistic seminar, I want to focus on linguistic drift and polyphonic identity synthesis, specifically within the long-term evolution of second-generation diasporic communities in Western European metropolises. Within these urban spaces, young individuals continuously navigate a dense communicative ecosystem, synthesizing the syntactic structures of their heritage languages—such as Syrian Arabic—with the morphology and lexicon of their host societies'' standard tongues, like German or English. Rather than representing a corrupted or incomplete mastery of either idiom, contemporary sociolinguists interpret this fluid code-switching and hybrid speech production as the emergence of a sophisticated third space. This linguistic hybridity functions as an active strategy for individual and collective agency, allowing youth to construct a localized, syncretic identity that consciously resists both majoritarian cultural erasure and the rigid traditionalism of diasporic enclaves. Through the subversion of standard monolingual registers, these speakers develop a rich polyphonic repertoire that serves as an expressive medium for their unique existential positionality. However, the institutional recognition of these hybrid communication models remains a highly contested domain within formal education and employment spheres. National pedagogical institutions routinely prioritize standardized language competence as the absolute metric for socio-economic mobility, pathologizing hybrid structures as indicators of linguistic deficit or cognitive confusion. This institutional rigidity creates an intellectual impasse: while the lived reality of multicultural urban centers requires flexible, multifaceted communicative adaptability, systemic evaluation mechanisms remain bound to an antiquated monolingual ideology. Ultimately, dismantling these systemic biases requires an epistemological shift that validates polyphonic hybridity not as a deficit, but as a form of valuable socio-cultural capital essential for cross-cultural communication."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (241, 1, 'writing', 'A1', 'writing_prompt', 'Introducing Yourself to Your Classmate', '{"topic": "self-introduction", "prompt": "Write a message to a new classmate. Tell them your name, your country, your age, and where you live now in Germany.", "title_ar": "تعريف عن حالك لرفيقك بالصف", "min_words": 30, "prompt_ar": "اكتب رسالة لرفيقك الجديد بالصف. قله شو اسمك، من أي بلد أنت، قديش عمرك، ووين عايش هلق بألمانيا.", "min_sentences": 3, "example_answer": "Hello! My name is Rami. I am from Syria. I am twenty-six years old. Now, I live in Frankfurt, Germany. I am a student here. Nice to meet you!"}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (242, 1, 'writing', 'A1', 'writing_prompt', 'Describing Your Family', '{"topic": "family", "prompt": "Write about your family. Talk about your parents, your brothers, or your sisters. Where do they live?", "title_ar": "عم توصف عيلتك", "min_words": 30, "prompt_ar": "اكتب عن عيلتك. احكي عن أبوك وأمك، أو أخواتك الشباب والبنات. وين هنن عايشين؟", "min_sentences": 3, "example_answer": "My family is nice. I have a father and a mother. I have one brother. His name is Ali. They live in Damascus, Syria. I love my family very much."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (243, 1, 'writing', 'A1', 'writing_prompt', 'My New Apartment in Hamburg', '{"topic": "home", "prompt": "Write about your new apartment in Germany. Describe your room and what color it is. Do you like it?", "title_ar": "شقتي الجديدة بهامبورغ", "min_words": 30, "prompt_ar": "اكتب عن شقتك الجديدة بألمانيا. اوصف غرفتك وشو لونها. عاجبتك؟", "min_sentences": 3, "example_answer": "I have a new apartment in Hamburg. My room is small and clean. The walls are white. I have a big brown desk. I like my new home every day."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (244, 1, 'writing', 'A1', 'writing_prompt', 'My Morning Routine', '{"topic": "daily routine", "prompt": "Write about what you do every morning. What time do you wake up? What do you eat or drink?", "title_ar": "روتيني الصباحي", "min_words": 30, "prompt_ar": "اكتب شو عم تعمل كل يوم الصبح. بأي ساعة بتفيق؟ شو بتاكل أو بتشرب؟", "min_sentences": 3, "example_answer": "Every morning, I wake up at seven o''clock. I drink hot black tea. I eat warm bread with cheese. Then, I go to my language school. I walk there."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (245, 1, 'writing', 'A1', 'writing_prompt', 'Shopping for Dinner', '{"topic": "food", "prompt": "Write about your trip to the supermarket. What food do you need to buy for dinner tonight? How much does it cost?", "title_ar": "عم اتسوق للعشا", "min_words": 30, "prompt_ar": "اكتب عن مشوارك على السوبرماركت. شو بدك تشتري أكل للعشا الليلة؟ قديش حقه؟", "min_sentences": 3, "example_answer": "Today, I go to the big supermarket. I buy fresh chicken and yellow rice. I buy five red tomatoes. The food costs ten euros. I cook dinner for my friends."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (252, 1, 'writing', 'A2', 'writing_prompt', 'An Unfortunate Train Delay', '{"topic": "transport", "prompt": "Write a message to your friend. Explain why you are late because of a train delay and where they should wait for you.", "title_ar": "تأخير بالقطار صار معي", "min_words": 50, "prompt_ar": "اكتب مسج لرفيقك. اشرحلو ليش عم تتأخر بسبب تأخير بالقطار، ووين لازم يستناك.", "min_sentences": 5, "example_answer": "Hi Jonas, I am very sorry but I will be late for our meeting today. I arrived at the huge central station at eight o''clock, but my train is delayed. The next train is coming in twenty minutes. Please wait for me inside the warm coffee shop near the entrance. See you soon!"}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (253, 1, 'writing', 'A2', 'writing_prompt', 'My Plan for a Sunny Weekend', '{"topic": "weather", "prompt": "Write a short paragraph about your plans for a warm, sunny weekend. Where are you going and what are you doing there?", "title_ar": "خطتي لعطلة نهاية الأسبوع المشمسة", "min_words": 50, "prompt_ar": "اكتب مقطع قصير عن خططك لعطلة نهاية أسبوع دافية ومشمسة. وين رايح وشو بدك تعمل هنيك؟", "min_sentences": 5, "example_answer": "The weather forecast says tomorrow will be very sunny and warm. My friends and I want to go to a beautiful lake near Frankfurt. We are planning to swim in the cool water and eat strawberry ice cream. Then, we will ride our bicycles in the park. I am very excited about the weekend."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (254, 1, 'writing', 'A2', 'writing_prompt', 'Joining a Local Sports Club', '{"topic": "hobbies", "prompt": "Write an email to a local football club. Express your interest in joining, ask about the student membership price, and when training sessions start.", "title_ar": "التسجيل بنادي رياضي محلي", "min_words": 50, "prompt_ar": "اكتب إيميل لنادي فوتبول محلي. قلهن إنك حابب تسجل معهم، واسألهن عن سعر اشتراك الطلاب، وإيمتى بتبلش حصص التدريب.", "min_sentences": 5, "example_answer": "Hello, my name is Ahmad and I love playing football. I decided to join your local sports club this month. Can you tell me the price of the student membership? When do your training sessions start during the week? I am free every Thursday evening after school. Thank you!"}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (255, 1, 'writing', 'A2', 'writing_prompt', 'An Invitation to My Neighbors', '{"topic": "neighborhood", "prompt": "Write a note to invite your new neighbors for tea in your apartment. Tell them when to come and what cake you are preparing.", "title_ar": "عزيمة لجيراني", "min_words": 50, "prompt_ar": "اكتب ورقة صغيرة لتعزم جيرانك الجداد ع الشاي بشقتك. قلهن إيمتى يجوا وشو الكيك يلي عم تجهزو.", "min_sentences": 5, "example_answer": "Dear neighbors, welcome to our apartment building! I want to invite you to have tea at my flat next Sunday evening. We can sit in my living room and talk. I am baking a delicious homemade chocolate cake for you. Please come at five o''clock. See you then!"}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (256, 1, 'writing', 'A2', 'writing_prompt', 'My First Week at Language School', '{"topic": "school", "prompt": "Write a letter to your family in Syria about your first week at the language school in Germany. Mention your teacher and classmates.", "title_ar": "أول أسبوع بمدرسة اللغة", "min_words": 50, "prompt_ar": "اكتب رسالة لعيلتك بسوريا عن أول أسبوع إلك بمدرسة اللغة بألمانيا. احكي عن آنستك ورفقاتك يلي بالصف.", "min_sentences": 5, "example_answer": "Dear family, my first week at the language school was very good. I was quite nervous on Monday, but now I feel confident. Our teacher, Miss Sarah, is very kind and professional. My classmates come from different countries like Spain and Brazil. We practice speaking English together every morning. I miss you!"}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (257, 1, 'writing', 'A2', 'writing_prompt', 'Registering My New Address', '{"topic": "bureaucracy", "prompt": "Write an email to the local city hall. Ask about the documents required to register your new apartment address and the opening hours.", "title_ar": "تسجيل عنوان السكن الجديد تبعي", "min_words": 50, "prompt_ar": "اكتب إيميل لبلدية المدينة المحلية. اسأل عن الأوراق المطلوبة لتسجيل عنوان شقتك الجديدة وعن أوقات الدوام.", "min_sentences": 5, "example_answer": "Hello, I recently moved to a new flat in Stuttgart. I need to register my home address at the city hall this week. What documents do I need to bring to the appointment? Can I upload my rental contract online? Also, what are your opening hours on Wednesday? Thank you for your help."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (258, 1, 'writing', 'A2', 'writing_prompt', 'An Email to the Doctor''s Clinic', '{"topic": "healthcare", "prompt": "Write an email to a medical clinic to change your doctor''s appointment. Explain why you cannot come tomorrow and ask for a new time.", "title_ar": "إيميل لعيادة الدكتور", "min_words": 50, "prompt_ar": "اكتب إيميل للعيادة الطبية مشان تغير موعد الدكتور. اشرحلن ليش ما فيك تجي بكرا واسألن عن موعد جديد.", "min_sentences": 5, "example_answer": "Hello, this is Maya. I have a medical appointment with Doctor Müller tomorrow morning at nine o''clock. Unfortunately, I cannot come because I have an important university exam at that time. Is it possible to change my appointment to Thursday afternoon? I have a bad cough and need some medicine."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (259, 1, 'writing', 'A2', 'writing_prompt', 'Returning a Broken Item', '{"topic": "shopping", "prompt": "Write a message to an online store customer service. Explain that the winter coat you bought yesterday is too small and ask for a cash refund.", "title_ar": "ترجيع غرض مكسور", "min_words": 50, "prompt_ar": "اكتب مسج لخدمة زباين محل أونلاين. اشرحلن إنه الجاكيت الشتوي يلي اشتريتو مبارح كتير صغير، واسألن عن ترجيع المصاري كاش.", "min_sentences": 5, "example_answer": "Hello, I bought a black winter coat from your website yesterday afternoon. When I got home, I realized the size was completely wrong. The coat is too small for me and I cannot close the buttons. Your store does not have a bigger size. Can I get a full cash refund?"}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (260, 1, 'writing', 'A2', 'writing_prompt', 'A Visit to the Local Library', '{"topic": "daily city life", "prompt": "Write a blog post about your visit to the local public library. Describe the building, what you can borrow, and why you like studying there.", "title_ar": "زيارة للمكتبة العامة المحلية", "min_words": 50, "prompt_ar": "اكتب بوست لمدونة عن زيارتك للمكتبة العامة المحلية. اوصف البناية، شو فيك تستعير منها، وليش بتحب تدرس هنيك.", "min_sentences": 5, "example_answer": "Yesterday, I visited the local public library near the city center. The building is very large and modern. If you have a membership card, you can borrow interesting books and movies. I like studying there because the rooms are quiet and the internet is fast. It is a wonderful place."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (261, 1, 'writing', 'B1', 'writing_prompt', 'Applying for a Part-Time Job', '{"topic": "work", "prompt": "Write a formal email to a logistics company in Frankfurt applying for a part-time job as a customer service assistant. Mention your previous experience and your availability on weekends.", "title_ar": "التقديم على شغل بارت تايم", "min_words": 80, "prompt_ar": "اكتب إيميل رسمي لشركة لوجستية بفرانكفورت مشان تقدم على شغل بارت تايم كمساعد بخدمة الزباين. اذكر خبرتك القديمة وقدرتك ع الشغل بعطلة نهاية الأسبوع.", "min_sentences": 6, "example_answer": "Dear Hiring Manager, I am writing to express my interest in the part-time customer service position at your company in Frankfurt. I recently completed my language course, and I am currently studying at the university. I have previous experience in customer service because I worked in a busy cafe for one year. If you offer me this position, I would be able to handle flexible working hours. I am fully available to work on weekends and evenings. Attached are my certificates and resume. I look forward to hearing from you. Sincerely, Rami."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (262, 1, 'writing', 'B1', 'writing_prompt', 'Explaining the Recycling System', '{"topic": "environment", "prompt": "Write an email to your new roommate from Syria explaining the local waste sorting rules in Germany. Describe the different colored bins and explain the concept of ''Pfand''.", "title_ar": "شرح نظام إعادة التدوير", "min_words": 80, "prompt_ar": "اكتب إيميل لرفيقك السكن الجديد يلي جاي من سوريا عم تشرحلو فيه قواعد فرز الزبالة بألمانيا. اوصف الحاويات الملونة واشرحلو شو يعني الـ ''بفاند''.", "min_sentences": 6, "example_answer": "Hi Ahmad, I hope you are settling in well. I want to explain the local recycling system in our flat because it is quite strict here. We sort our trash into different colored bins. The blue bin is for paper, the yellow bag is for plastic packaging, and the brown bin is for organic waste. Also, remember that most plastic bottles have a deposit called ''Pfand''. If you return these empty bottles to the supermarket machine, you will get your extra money back. Please don''t mix them up. Let''s talk more tonight!"}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (263, 1, 'writing', 'B1', 'writing_prompt', 'Planning a Train Journey across Europe', '{"topic": "travel", "prompt": "Write an email to a friend proposing a holiday trip using the high-speed ICE train. Explain why booking early is beneficial and describe what the train offers on board.", "title_ar": "التخطيط لرحلة بالقطار عبر أوروبا", "min_words": 80, "prompt_ar": "اكتب إيميل لرفيقك عم تقترح عليه رحلة بالعطلة باستعمال قطار الـ ICE السريع. اشرحلو ليش الحجز البكير منيح والخدمات يلي بيقدمها القطار جواه.", "min_sentences": 6, "example_answer": "Dear Selma, I am planning a holiday trip to Paris for next month, and I would love it if you joined me. I have been checking the high-speed ICE train tickets online today. If we book our tickets two weeks in advance, we will secure a very cheap price. The journey takes around four hours, and the train is incredibly modern. It offers free Wi-Fi and a comfortable onboard bistro where we can buy warm food. Let me know by tomorrow if you can come!"}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (264, 1, 'writing', 'B1', 'writing_prompt', 'Booking a Dentist Appointment', '{"topic": "health", "prompt": "Write a formal letter or email to your health insurance company. Explain that you had a severe toothache, visited a local dentist for an emergency filling, and request them to confirm coverage for the costs.", "title_ar": "حجز موعد عند دكتور السنان", "min_words": 80, "prompt_ar": "اكتب رسالة أو إيميل رسمي لشركة التأمين الصحي تبعك. اشرحلن إنه جاك وجع سنين قوي، ورحت لعند دكتور سنان محلي كرمال حشوة إسعافية، واطلبن منهم يأكدوا تغطية التكاليف.", "min_sentences": 6, "example_answer": "Dear Sir or Madam, I am writing to submit a request regarding my dental treatment expenses. Last week, I developed a severe toothache that kept me awake all night. Because it was an emergency, I visited a local dentist immediately. She discovered a cavity and gave me a filling. The procedure was completely painless, but I had to show my health insurance card. I am writing to confirm that my public insurance covers the total cost of this treatment. I look forward to your confirmation. Sincerely, Maya."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (265, 1, 'writing', 'B1', 'writing_prompt', 'Complaining About Internet Delays', '{"topic": "technology", "prompt": "Write an email to your internet service provider. Complain about the delay in receiving your activation code, describe how it impacts your online studies, and request a technician to visit immediately.", "title_ar": "شكوى على تأخير تركيب الإنترنت", "min_words": 80, "prompt_ar": "اكتب إيميل لشركة تزويد الإنترنت تبعك. اشتكي من التأخير باستلام كود التفعيل، واشرح كيف هاد الشي عم يأثر على دراستك أونلاين، واطلبن يبعتوا موظف فني فوراً.", "min_sentences": 6, "example_answer": "Dear Customer Service, I am writing to complain about the delay in setting up our home internet connection. We ordered the service two weeks ago, but we have not received our activation router code yet. Because of this issue, I have spent a lot of money on extra mobile data. Furthermore, it directly impacts my online university studies because I cannot access the portal without interruptions. I request you to activate our line or send a technician to our flat immediately. Yours faithfully, Tareq."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (266, 1, 'writing', 'B1', 'writing_prompt', 'Resolving Flatmate Conflicts', '{"topic": "relationships", "prompt": "Write a message to your roommate addressing a conflict about household chores. Explain why leaving dirty dishes in the sink causes tension and suggest a house meeting to update the cleaning schedule.", "title_ar": "حل الخلافات بين رفقات السكن", "min_words": 80, "prompt_ar": "اكتب مسج لرفيقك بالسكن عم تحكي فيه عن مشكلة بتخص شغل البيت. اشرحلو ليش ترك الصحون الوسخة بالمجلى عم يعمل حزازيات واقترح عليه تعملوا اجتماع بالبيت لتحدثوا جدول التنظيف.", "min_sentences": 6, "example_answer": "Hi Samer, I think we need to have a quick chat about our flat rules because there is some tension lately. I noticed that you have neglected your cleaning duties this week, leaving dirty dishes in the kitchen sink for days. I know you are under a lot of stress due to university exams, but a messy kitchen affects everyone''s daily routine. If we don''t address this openly, it will create a hostile environment. Let''s hold a short house meeting tonight to fix this schedule."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (267, 1, 'writing', 'B1', 'writing_prompt', 'Choosing Between University and Ausbildung', '{"topic": "school system", "prompt": "Write an essay or a blog post discussing the choices young people face between attending university or starting a vocational training program (Ausbildung). Give your opinion on the advantages of practical experience.", "title_ar": "الاختيار بين الجامعة والأوسبيلدونغ", "min_words": 80, "prompt_ar": "اكتب مقال أو بوست لمدونة عم تناقش فيه الخيارات يلي بيواجهوها الشباب بين إنهم يروحوا عالجامعة أو يبلشوا برنامج تدريب مهني (أوسبيلدونغ). اعطي رأيك عن ميزات الخبرة العملية.", "min_sentences": 6, "example_answer": "Many young people in Germany face a difficult decision after finishing school. They must choose between attending a traditional university or starting a vocational training program, known as an Ausbildung. If you prefer practical experience, an Ausbildung is an excellent option because it combines classroom learning with actual on-the-job training. Furthermore, vocational students can earn a monthly salary while learning a trade. On the other hand, university lectures require more self-discipline and theoretical research. In my opinion, both paths offer wonderful career opportunities depending on your style."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (268, 1, 'writing', 'B1', 'writing_prompt', 'Requesting a Visa Extension', '{"topic": "bureaucracy", "prompt": "Write a formal letter to the local immigration office (Ausländerbehörde) requesting an extension for your student residence permit. Mention the documents you have gathered, such as your blocked bank account proof.", "title_ar": "طلب تمديد الفيزا", "min_words": 80, "prompt_ar": "اكتب رسالة رسمية لمكتب الإقامة والأجانب المحلي عم تطلب فيها تمديد إقامة الطالب تبعك. اذكر الأوراق يلي جمعتها، متل إثبات الحساب البنكي المقفل.", "min_sentences": 6, "example_answer": "To the Immigration Office, I am writing to formally request an extension for my student residence permit. My current visa is expiring next month, so I have gathered all the necessary application paperwork. I have enclosed my university enrollment certificate, my current health insurance confirmation, and proof of sufficient funds in my blocked bank account. If you require any additional documents, please let me know. I hope we can arrange an appointment soon because I intend to continue my studies here. Sincerely, Samer."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (269, 1, 'writing', 'B1', 'writing_prompt', 'Adapting to Local Social Rules', '{"topic": "cultural differences", "prompt": "Write a letter to a friend in Syria describing two important social rules you learned in Germany: punctuality for appointments and quiet hours (Ruhezeit) on Sundays. Explain how you adapted to them.", "title_ar": "التأقلم مع القواعد الاجتماعية المحلية", "min_words": 80, "prompt_ar": "اكتب رسالة لرفيقك بسوريا عم توصفلو فيها قاعدتين اجتماعيتين مهمين تعلمتهم بألمانيا: الالتزام بالوقت بالمواعيد وساعات الهدوء يوم الأحد. اشرحلو كيف تأقلمت معهم.", "min_sentences": 6, "example_answer": "Hi Fadi, I want to tell you about some interesting cultural differences I noticed since I moved to Germany. First, punctuality is extremely important; if you have an appointment, you must always arrive five minutes early. Second, there is a concept called ''Ruhezeit'' or quiet hours. On Sundays and every evening after ten o''clock, people must keep noise to a minimum. At first, these social rules seemed very strict to me, but now I understand they help create a peaceful environment."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (270, 1, 'writing', 'B1', 'writing_prompt', 'Appealing a Public Transport Fine', '{"topic": "daily city life", "prompt": "Write an email to the public transport authority appealing a fine you received on the tram. Explain that you possess a valid monthly subscription but had accidentally left it inside your apartment.", "title_ar": "الاعتراض على مخالفة مواصلات", "min_words": 80, "prompt_ar": "اكتب إيميل لمؤسسة المواصلات العامة عم تعترض فيه على مخالفة أكلتها بالترام. اشرحلن إنك بتملك اشتراك شهري نظامي بس نسيته بالغلط جوّات شقتك.", "min_sentences": 6, "example_answer": "Dear Customer Support, I am writing to contest a public transit fine that I received on the tram yesterday afternoon. The ticket inspector gave me a sixty-euro penalty because I could not show my pass. However, I actually possess a valid monthly subscription ticket, but I had accidentally left it on my kitchen table. The inspector explained that if I bring my valid ticket to your main office within a week, you will reduce the fine to seven euros. Please review my attached documents."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (271, 1, 'writing', 'B2', 'writing_prompt', 'Cover Letter for a Professional Internship', '{"topic": "job applications", "prompt": "Write a formal cover letter applying for a marketing internship at a multinational firm in Munich. Explain how your academic background aligns with their requirements and discuss your long-term career goals.", "title_ar": "رسالة تغطية لتدريب مهني", "min_words": 120, "prompt_ar": "اكتب رسالة تغطية رسمية عم تقدم فيها على تدريب مهني بمجال الماركتنغ بشركة متعددة الجنسيات بميونيخ. اشرح كيف دراستك وعلمك بيتناسبوا مع طلباتهم واحكي عن أهدافك بالشغل على المدى الطويل.", "min_sentences": 8, "example_answer": "Dear Hiring Manager, I am writing to formally apply for the marketing internship position at your Munich office. As a current business administration student specializing in digital media, my academic background perfectly aligns with your corporate requirements. Throughout my studies, I have developed extensive analytical skills and managed several university campaigns. I am highly motivated to contribute to your upcoming global initiatives while enhancing my practical knowledge. This opportunity is critical for my long-term career goals, as I aim to establish myself within the European corporate sphere. If I am selected, I am fully prepared to adapt to your flexible working hours and handle complex market research projects. Thank you for considering my application. Sincerely, Ahmad."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (305, 1, 'speaking', 'A1', 'speaking_prompt', 'Your Favorite Fruit', '{"topic": "food", "prompt": "What is your favorite fruit? Do you like red apples or green bananas? Why do you like it?", "title_ar": "فاكهتك المفضلة", "prompt_ar": "شو هي فاكهتك المفضلة؟ بتحب التفاح الأحمر ولا الموز الأخضر؟ وليش بتحبها؟", "min_seconds": 20, "question_type": "opinion", "example_answer": "My favorite fruit is the red apple. I like red apples because they are very sweet and fresh. I eat one apple every day."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (272, 1, 'writing', 'B2', 'writing_prompt', 'Essay on Sustainable Urban Transport', '{"topic": "public transport", "prompt": "Write an essay discussing the benefits and challenges of shifting from private cars to public transit systems in major cities. Analyze how ticket subsidies can incentivize citizens and prevent traffic congestion.", "title_ar": "مقال عن وسائل النقل الحضري المستدام", "min_words": 120, "prompt_ar": "اكتب مقال عم تناقش فيه ميزات وتحديات التحول من السيارات الخاصة لشبكات النقل العام بالمدن الكبيرة. حلل كيف دعم التكتات ممكن يشجع العالم يركبوا باصات ومترو ويخفف من عجقات السير كرمال البيئة.", "min_sentences": 8, "example_answer": "In recent years, many European metropolitan areas have prioritized sustainable urban mobility to combat severe traffic congestion and environmental concerns. Shifting from private automobiles to public transit systems offers tremendous benefits, such as reducing global carbon emissions and optimizing daily city commuting. However, this transition is not entirely seamless, as local municipalities frequently face budget deficits while expanding ancient subway networks. To incentivize residents, subsidized monthly tickets have been introduced, making public transport an affordable and attractive alternative for everyone. In my opinion, if corporate leaders and city planners cooperate to enhance transit frequencies, car ownership will gradually decline. Ultimately, the long-term viability of modern cities depends heavily on continuous investment in clean infrastructure."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (273, 1, 'writing', 'B2', 'writing_prompt', 'Analyzing the Dual Education System', '{"topic": "education systems", "prompt": "Write a response to an educational forum analyzing the advantages and potential drawbacks of Germany''s dual education system (Ausbildung). Discuss whether sorting students early limits future academic flexibility.", "title_ar": "تحليل نظام التعليم المزدوج", "min_words": 120, "prompt_ar": "اكتب رد لمنتدى تعليمي عم تحلل فيه ميزات وسلبيات نظام التعليم المزدوج (الأوسبيلدونغ) بألمانيا. ناقش إذا كان تقسيم الطلاب بمسارات مختلفة بعمر صغير بيقيد مرونتهم الأكاديمية بالمستقبل.", "min_sentences": 8, "example_answer": "Germany''s dual education system, widely celebrated as the Ausbildung framework, effectively aligns academic training with practical corporate requirements. Through this structure, vocational students split their time between specialized schools and actual companies, ensuring that acquired skills are immediately applicable. One major advantage is that students gain financial independence early because they receive a standardized stipend throughout their training. However, critics point out that this system occasionally forces teenagers to commit to a specific career path too early in their development, potentially limiting future academic flexibility. In my view, while the early specialization helps cultivate a highly professional workforce, educational ministries must introduce more flexible transition pathways. This structural optimization would allow graduates to pivot into higher university education later if their career interests evolve."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (274, 1, 'writing', 'B2', 'writing_prompt', 'Debating Digital Patient Records', '{"topic": "healthcare", "prompt": "Write a formal letter to a local health committee expressing your opinion on the implementation of centralized digital patient records. Address data protection concerns and discuss whether automated efficiency compromises confidentiality.", "title_ar": "نقاش عن السجلات الرقمية للمرضى", "min_words": 120, "prompt_ar": "اكتب رسالة رسمية للجنة صحية محلية عم تبدي فيها رأيك عن تطبيق السجلات الرقمية المركزية للمرضى. احكي عن مخاوف حماية البيانات وناقش إذا كانت الكفاءة المؤتمتة بتمس سرية وخصوصية المرضى.", "min_sentences": 8, "example_answer": "Dear Members of the Health Committee, I am writing to share my perspectives regarding the implementation of standardized digital patient records across our regional healthcare system. Proponents of digitalization rightly argue that centralized electronic networks enable medical specialists to access vital histories instantly, thereby preventing dangerous medication errors. However, privacy advocates express grave concerns regarding the vulnerability of these digital repositories to cyberattacks and unauthorized surveillance. It is essential that sensitive diagnostics are safeguarded with advanced encryption methods to maintain absolute patient confidentiality. In my opinion, automated clinical efficiency should never compromise individual privacy rights. If the health ministry had established stricter regulations prior to this digital transition, public trust would be noticeably higher today. Therefore, I highly recommend implementing independent data security audits to protect citizen trust. Sincerely, Maya."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (275, 1, 'writing', 'B2', 'writing_prompt', 'Critiquing Digital Bureaucracy Portals', '{"topic": "bureaucracy", "prompt": "Write an article for a student magazine critiquing the transition of migration offices to paperless online portals. Discuss how this affects administrative backlogs and its impact on vulnerable migrants with low digital literacy.", "title_ar": "نقد منصات المعاملات الرسمية الديجيتال", "min_words": 120, "prompt_ar": "اكتب مقال لمجلة طلابية عم تنتقد فيه تحول مكاتب الإقامة والاجانب لمنصات ديجيتال بلا أوراق. ناقش كيف هاد الشي بيأثر ع تراكم المعاملات وتأثيره ع المهاجرين يلي ما عندهم خبرة بالكمبيوتر والنت.", "min_sentences": 8, "example_answer": "The recent administrative transition toward centralized digital registration portals at migration offices has sparked significant debate among integration experts. On one hand, shifting to paperless online systems is expected to streamline procedures and reduce the immense administrative backlog at physical buildings. Applicants can now upload rental contracts and passport documents directly from their homes, which optimizes efficiency. On the other hand, non-profit counseling organizations warn that these digital solutions create insurmountable hurdles for vulnerable migrants who lack advanced technological literacy. If administrative software is implemented without cross-cultural usability testing, it inadvertently hinders the initial social integration of newcomers. To mitigate this pressing issue, municipal councils must provide hybrid options, maintaining in-person support desks alongside modern digital interfaces to ensure equitable access for all residents."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (306, 1, 'speaking', 'A1', 'speaking_prompt', 'Counting Students in Class', '{"topic": "numbers", "prompt": "Talk about the numbers in your language class. How many students are there? How many men and women do you see?", "title_ar": "عدّ الطلاب بالصف", "prompt_ar": "احكي عن الأرقام بصف اللغة تبعك. كم طالب وطالبة فيه؟ كم زلمة ومرّة شايف؟", "min_seconds": 20, "question_type": "describe", "example_answer": "My class is big. There are ten students in the room. We have four men and six women. We have twelve new books."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (276, 1, 'writing', 'B2', 'writing_prompt', 'The Cultural Significance of Feierabend', '{"topic": "cultural differences", "prompt": "Write an essay explaining the German cultural concept of ''Feierabend'' and how remote work challenges this traditional boundary between career obligations and personal leisure time. Suggest corporate ways to protect it.", "title_ar": "الأهمية الثقافية لوقت الراحة", "min_words": 120, "prompt_ar": "اكتب مقال عم تشرح فيه المفهوم الثقافي الألماني لـ ''الفايرآبند'' (Feierabend) وكيف الشغل عن بعد عم يتحدى هاد الخط الفاصل بين التزامات الشغل ووقت الراحة الشخصي. اقترح طرق للشركات عشان تحميه.", "min_sentences": 8, "example_answer": "The traditional German cultural concept of Feierabend represents a distinct and highly respected boundary between professional obligations and personal leisure time. Historically, it designated a period of complete rest following agricultural or industrial labor, which is essential for preventing professional burnout and enhancing daily productivity. However, with the contemporary rise of remote work and mobile corporate applications, maintaining this cultural boundary has become increasingly challenging for modern employees. Psychologists observe that constant digital availability via corporate email prevents individuals from full, undisturbed relaxation, leading to heightened stress levels across society. In my view, forward-thinking organizations must establish mandatory digital disconnection clauses within their employment contracts. Disabling internal messaging servers during late evening hours ensures that employees can enjoy uninterrupted personal time with their families, thereby preserving psychological integrity."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (277, 1, 'writing', 'B2', 'writing_prompt', 'Report on Urban Green Infrastructure', '{"topic": "global issues", "prompt": "Write a formal report for a neighborhood council advocating for the expansion of urban green infrastructure. Explain how parks and green roofs combat the urban heat island effect and manage torrential rainfall.", "title_ar": "تقرير عن البنية التحتية الخضراء بالمدن", "min_words": 120, "prompt_ar": "اكتب تقرير رسمي لمجلس الحارة عم تطالب فيه بتوسيع البنية التحتية الخضراء بالمدينة. اشرح كيف الحدائق والأسطح الخضرا بتحارب ظاهرة الجزر الحرارية بالمدن وبتصرف مياه الأمطار القوية والفيضانات.", "min_sentences": 8, "example_answer": "To the Neighborhood Council Members, I am submitting this formal report to strongly advocate for the continuous expansion of urban green infrastructure across our district. Climatologists increasingly recognize that expanding public parks and constructing green roofs are indispensable strategies for mitigating the adverse impacts of climate change. Densely built environments frequently suffer from the urban heat island effect, where concrete surfaces absorb solar radiation, causing summer temperatures to skyrocket. Deliberate ecological interventions, such as planting extensive urban forests, function as natural cooling mechanisms and significantly reduce surface temperatures. Furthermore, urban vegetation plays a critical role in managing stormwater during extreme weather events, reducing pressure on our ancient sewage infrastructure. Investing in these sustainable architectural models will safeguard public health and preserve our neighborhood''s long-term viability. Sincerely, Samer."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (278, 1, 'writing', 'B2', 'writing_prompt', 'Letter on Anti-Discrimination Hiring Laws', '{"topic": "job applications", "prompt": "Write an opinion piece for a business blog analyzing the effectiveness of anti-discrimination laws in corporate hiring. Discuss whether anonymized application procedures should be mandated universally to eliminate biases.", "title_ar": "رسالة عن قوانين مناهضة التمييز بالتوظيف", "min_words": 120, "prompt_ar": "اكتب مقال رأي لمدونة أعمال عم تحلل فيه كفاءة قوانين مناهضة التمييز بتوظيف الشركات. ناقش إذا كان لازم يفرضوا التقديم المخفي (بلا أسماء وبلا صور) بشكل عام بكل مكان عشان نقضي ع الانحيازات اللاواعية.", "min_sentences": 8, "example_answer": "The implementation of the General Equal Treatment Act has structurally transformed corporate hiring processes, aiming to prevent discrimination based on gender or ethnicity. Under this legal framework, human resource departments standardized selection criteria to ensure absolute objectivity throughout evaluation stages. Despite these rigorous protections, many international applicants still report subtle biases during recruitment, as candidates with foreign-sounding names frequently receive fewer interview invitations. In my opinion, anonymized application procedures should be universally mandated across all industrial sectors to eliminate these unconscious barriers. If corporations remove personal details like names, ages, and photographs from initial resumes, recruiters will focus purely on professional qualifications. Inclusive workplaces exhibit higher employee satisfaction and innovation, proving that diversity is a substantial corporate asset that must be protected legally."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (279, 1, 'writing', 'B2', 'writing_prompt', 'The Role of Community Centers in Inclusion', '{"topic": "integration", "prompt": "Write a proposal for a municipal grant describing how local community centers accelerate social cohesion and language integration. Detail how volunteer-led initiatives like language cafes dismantle mutual prejudices.", "title_ar": "دور المراكز المجتمعية بالاندماج المدني", "min_words": 120, "prompt_ar": "اكتب مقترح لمنحة بلدية عم توصف فيه كيف المراكز المجتمعية المحلية بتعزز التماسك الاجتماعي والاندماج اللغوي للناس الجداد. اشرح بالتفصيل كيف المبادرات التطوعية متل كافيهات اللغة بتكسر الأحكام المسبقة المتبادلة.", "min_sentences": 8, "example_answer": "Dear Municipal Selection Committee, I am writing to submit a funding proposal designed to accelerate the social integration of newly arrived immigrants within our city. Local community centers play an invaluable role in fostering social cohesion by providing free language cafes, legal advice clinics, and cross-cultural workshops. These neighborhood institutions serve as safe spaces for intercultural dialogue, helping to dismantle mutual prejudices that often arise between local populations and immigrant groups. Sociological studies demonstrate that migrants who regularly participate in these civic activities exhibit a much stronger sense of belonging and community engagement. If our grassroots initiative receives permanent municipal grants, our capacity to expand vital educational programs will be secured. Fostering an inclusive society requires continuous structural support for these dedicated volunteer networks. Sincerely, Zein."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (280, 1, 'writing', 'B2', 'writing_prompt', 'Addressing the Demographic Shift', '{"topic": "society", "prompt": "Write an essay examining how the aging population in Western Europe forces corporate enterprises to adapt their workforce management strategies. Discuss the value of lifelong learning programs and intergenerational collaboration.", "title_ar": "مواجهة التحول الديموغرافي بالشركات", "min_words": 120, "prompt_ar": "اكتب مقال عم تدرس فيه كيف شيخوخة السكان بأوروبا الغربية عم تجبر الشركات والمؤسسات تغير استراتيجيات إدارة العمال تبعها. ناقش أهمية برامج التعليم مدى الحياة والتعاون بين الأجيال الشابة والكبيرة بالشغل.", "min_sentences": 8, "example_answer": "The aging demographic profile of Western Europe is currently forcing corporate enterprises to radically reconsider their workforce management strategies and training structures. As a substantial portion of experienced employees approaches retirement age, companies face an unprecedented loss of institutional knowledge and technical expertise. To counter this impending deficit, human resource departments are developing innovative lifelong learning programs aimed at keeping older workers integrated while simultaneously training younger recruits. Labor analysts assert that traditional, rigid retirement frameworks are no longer sustainable under current demographic conditions. Consequently, businesses must adapt their physical workplaces, introducing ergonomic modifications to accommodate older workers. The ultimate success of these corporate adaptations depends on fostering an organizational culture that values intergenerational collaboration, ensuring that the unique strengths of both demographics are utilized effectively."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (281, 1, 'writing', 'C1', 'writing_prompt', 'The Interdisciplinary Dilemma in Higher Education', '{"topic": "academic research", "prompt": "Write a critical essay discussing the structural challenges of implementing interdisciplinary research within modern European higher education frameworks. Address institutional inertia, funding allocation metrics, and pedagogical friction points.", "title_ar": "المعضلة المشتركة بين التخصصات بالتعليم العالي", "min_words": 180, "prompt_ar": "اكتب مقال نقدي عم تناقش فيه التحديات الهيكلية لتطبيق الأبحاث العابرة للتخصصات بأنظمة التعليم العالي الأوروبي الحديثة. احكي عن الجمود المؤسساتي، معايير توزيع التمويل، ونقاط الاحتكاك بطرق التعليم.", "min_sentences": 10, "example_answer": "Seldom have we witnessed a more profound transformation within contemporary higher education than the integration of interdisciplinary methodologies into traditional research frameworks. However, despite clear evidence that global crises demand a radical synthesis of distinct disciplines, severe structural inertia remains embedded within academic systems. Financial resources continue to be distributed based on historical departmental prestige and narrow disciplinary metrics, thereby inadvertently discouraging younger scholars from speculative ventures. To rectify this institutional paralysis, funding bodies must establish permanent endowments specifically earmarked for collaborative research hubs. Furthermore, international doctoral candidates often bear the brunt of these systemic friction points, navigating complex pedagogical adjustments alongside dense academic bureaucracy. Progressive universities are pioneering integrated support centers that synthesize linguistic refinement with professional development to mitigate these challenges. Ultimately, the long-term viability of academic institutions hinges entirely upon their capacity to dismantle antiquated departmental boundaries. Only by fostering an environment where cognitive diversity is celebrated can universities cultivate the intellectual agility necessary for global advancement."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (282, 1, 'writing', 'C1', 'writing_prompt', 'Deconstructing Algorithmic Echo Chambers', '{"topic": "media literacy", "prompt": "Write a formal analysis concerning the epistemological crisis precipitated by algorithmic content curation on digital corporate platforms. Suggest comprehensive media literacy strategies to cultivate individual cognitive resilience.", "title_ar": "تفكيك غرف الصدى الخوارزمية", "min_words": 180, "prompt_ar": "اكتب تحليل رسمي بخصوص الأزمة المعرفية يلي عملتها الخوارزميات وتوجيه المحتوى بالمنصات الرقمية الكبيرة. اقترح خطط تعليمية شاملة للتربية الإعلامية لبناء مناعة فكرية عند الشخص.", "min_sentences": 10, "example_answer": "The contemporary digital landscape has precipitated an unprecedented epistemological crisis, fundamentally altering how public audiences consume and evaluate socio-political information. Driven by algorithmic curation, corporate digital platforms systematically prioritize sensationalized content designed to maximize user screen time rather than factual accuracy. Consequently, the public sphere has fragmented into hyper-partisan echo chambers that reinforce existing cognitive biases and manipulate consensus. To counteract this destabilizing societal trend, educational specialists strongly advocate for the universal implementation of media literacy frameworks. Such curricula must transcend elementary fact-checking techniques, focusing instead on equipping citizens with advanced analytical tools to deconstruct systemic media bias. Not only do these digital loops distort public perception, but they also systematically erode public trust in governance institutions. Were regulatory bodies to enforce more stringent oversight on corporate data algorithms, the proliferation of disinformation could be substantively curtailed. Until then, individual cognitive resilience must be meticulously cultivated through continuous critical inquiry across all demographics. Restoring democratic integrity requires a synchronized approach that synthesizes government regulation with unwavering public media education."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (283, 1, 'writing', 'C1', 'writing_prompt', 'The Paradox of Circular Economic Business Strategies', '{"topic": "business strategy", "prompt": "Write a strategic business proposal advocating for the integration of circular economic frameworks in traditional manufacturing firms. Address short-term financial pressures and the transition toward product stewardship.", "title_ar": "تناقض استراتيجيات الاقتصاد الدائري بالشركات", "min_words": 180, "prompt_ar": "اكتب مقترح استراتيجي للشركات عم تطالب فيه بدمج أطر الاقتصاد الدائري بمصانع الإنتاج التقليدية، واحكي عن كيفية مواجهة الضغوطات المادية قصيرة الأمد والتحول نحو المسؤولية عن رعاية المنتج.", "min_sentences": 10, "example_answer": "As global supply chain vulnerabilities continue to expose the fragility of linear economies, manufacturing corporations must accelerate their transition toward circular business strategies. The conventional manufacturing paradigm generates catastrophic ecological consequences while continuously exposing enterprises to highly volatile raw material markets. In contrast, circular economic frameworks prioritize systemic regeneration, designing products to be entirely modular and recyclable from inception. Adopting this sustainable blueprint requires a comprehensive re-engineering of the corporate ecosystem rather than superficial operational adjustments. Not only must enterprises reinvent their physical manufacturing methodologies, but they must also cultivate customer relationships predicated on stewardship. What complicates this corporate transformation is the immense financial pressure exerted by investment markets demanding immediate quarterly returns. Had financial institutions integrated comprehensive environmental ESG metrics into valuation models sooner, the corporate adoption of circularity would be vastly more advanced. Moving forward, businesses failing to integrate these sustainable paradigms risk institutional obsolescence as compliance regulations tighten globally. Embracing product stewardship represents an absolute commercial imperative for navigating modern macroeconomic uncertainty."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (284, 1, 'writing', 'C1', 'writing_prompt', 'Transnational Privacy Jurisprudence and Local Autonomy', '{"topic": "law", "prompt": "Write a legal memorandum analyzing the institutional friction between trans-European data privacy harmonization and localized statutory traditions. Discuss the implications for individual autonomy and judicial agility.", "title_ar": "أحكام خصوصية البيانات العابرة للدول والاستقلالية المحلية", "min_words": 180, "prompt_ar": "اكتب مذكرة قانونية عم تحلل فيها الاحتكاك بين توحيد قوانين سرية البيانات الأوروبية والتقاليد القانونية المحلية. ناقش عواقب هاد الشي ع الاستقلالية الفردية والمرونة القضائية.", "min_sentences": 10, "example_answer": "The evolution of trans-European legal frameworks represents a continuous negotiation between jurisdictional harmonization and the preservation of national individual autonomy. As member states integrate administrative systems to facilitate cross-border commerce, the tension between centralized regulations and localized statutory traditions becomes highly pronounced. Nowhere is this balance more fiercely contested than in data privacy jurisprudence, where standardized protections conflict with regional security mandates. Legal scholars observe that while centralized regulations provide an essential shield against corporate surveillance, they occasionally restrict judicial agility. It is this structural friction that necessitates a sophisticated, continuous calibration of legal enforcement mechanisms. What remains highly problematic is the complex nominalization embedded in legislative texts, obscuring practical application for ordinary citizens. Were local jurisdictions to establish dedicated bilingual clinics, the accessibility of trans-European judicial pathways would be significantly enhanced. Not only must legal professionals master these intricate networks, but they must also develop cultural sensitivity toward localized interpretations. Ultimately, trans-European legitimacy depends upon guaranteeing collective integration without eroding fundamental constitutional protections."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (285, 1, 'writing', 'C1', 'writing_prompt', 'The Ontological Value of Architectural Conservation', '{"topic": "philosophy", "prompt": "Write a philosophical critique examining the ontological value of architectural heritage within modernized urban landscapes. Advocate for the paradigm of adaptive reuse over speculative commercial development.", "title_ar": "القيمة الوجودية للحفاظ على المعمار التاريخي", "min_words": 180, "prompt_ar": "اكتب نقد فلسفي عم تدرس فيه القيمة الوجودية للإرث المعماري بالمدن الحديثة. طالب بالاعتماد على نموذج إعادة الاستخدام التكيفي بوش مشاريع التطوير العقاري والمضاربات التجارية.", "min_sentences": 10, "example_answer": "The conceptual framework surrounding urban preservation has shifted from simple aesthetic appreciation to an investigation into the ontological value of architectural heritage. Contemporary philosophical discourse posits that historical buildings are vital spatial structures that activate human consciousness and ground communal identity. In an age characterized by hyper-rapid urbanization and homogenized corporate architecture, ancient structures offer a tangible link to collective memory. It is this profound grounding capacity that renders preservation efforts culturally and existentially essential. However, the operationalization of preservation principles within modern real estate markets remains highly problematic due to commercial pressure. Urban planners frequently confront intense commercial demands to demolish historic quarters in favor of high-density, economically lucrative developments. What is desperately needed is a philosophical framework that synthesizes historical preservation with functional modern utility through adaptive reuse. Not only does adaptive reuse conserve material resources, but it also maintains the architectural continuity of urban landscapes. Were municipal councils to enforce strict legislative mandates protecting spatial heritage, cities would retain their unique character. Ultimately, architectural survival depends on valuing spaces for existential enrichment rather than pure speculation."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (286, 1, 'writing', 'C1', 'writing_prompt', 'Geopolitical Realignment in Post-Carbon Markets', '{"topic": "geopolitics", "prompt": "Write a policy paper evaluating the geopolitical realignment generated by the transition to renewable energy infrastructures. Address Europe''s strategic vulnerability regarding rare earth mineral extraction.", "title_ar": "إعادة التموضع الجيوسياسي بأسواق ما بعد الكربون", "min_words": 180, "prompt_ar": "اكتب ورقة سياسات عم تقيم فيها التحولات الجيوسياسية الناتجة عن الانتقال لتكنولوجيا الطاقة المتجددة. احكي عن نقطة ضعف أوروبا الاستراتيجية باستخراج المعادن الأرضية النادرة.", "min_sentences": 10, "example_answer": "The global transition away from fossil fuels is orchestrating a profound geopolitical realignment, redefining the strategic value of geographical territories. For decades, international relations were heavily dominated by hydrocarbon supply chains, with resource-rich nations exercising immense diplomatic leverage. However, the rapid proliferation of renewable infrastructures—such as hydrogen, wind, and solar systems—is shifting power toward nations controlling critical mineral chains. Not only do these technological advancements alter resource dependencies, but they also rewrite transnational trade agreements completely. It is this systemic shift that forces European policymakers to rethink their regional sovereignty strategies immediately. What remains a critical vulnerability for Europe is its heavy reliance on foreign nations for rare earth element extraction. Rare earth processing is indispensable for producing electric batteries, clean transit systems, and advanced military wind turbines. Were the European Union to establish decentralized domestic mining and recycling frameworks, its strategic independence would be strengthened. Navigating the resource realignment demands a comprehensive strategy combining environmental sustainability with aggressive technological innovation."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (287, 1, 'writing', 'C1', 'writing_prompt', 'Linguistic Hybridity as Socio-Cultural Capital', '{"topic": "academic research", "prompt": "Write an academic response evaluating how mixed linguistic codes among diasporic youth can be validated as cognitive assets. Critique the institutional rigidity of standard monolingual educational systems.", "title_ar": "الهوية اللغوية الهجينة كرأس مال اجتماعي وثقافي", "min_words": 180, "prompt_ar": "اكتب رد أكاديمي عم تقيم فيه كيف فينا نعتبر الممارسات اللغوية المخلطة عند شباب المغتربين كميزة فكرية حقيقية. انتقد الجمود المؤسساتي بأنظمة التعليم الرسمية يلي بتنحاز للغة الوحدة.", "min_sentences": 10, "example_answer": "Academic research into migrant communities in Western Europe has increasingly focused on linguistic hybridity and its correlation with socio-cultural capital. Traditional pedagogical perspectives often treated mixed linguistic codes—such as blending Arabic syntactic structures with German vocabulary—as a deficit indicating incomplete language acquisition. However, contemporary sociolinguistic frameworks deconstruct this outdated narrative, demonstrating that linguistic hybridity represents a highly sophisticated communicative competence. It is this multi-layered linguistic flexibility that allows individuals to navigate distinct cultural spheres fluidly, maximizing social network opportunities. What complicates the academic valuation of these unique skills is the institutional rigidity of standard educational systems. Examinations continue to demand absolute adherence to monolingual standard registers, penalizing code-switching as a cognitive deficiency. Were school curricula to validate multilingual practices as cognitive assets, the educational achievements of international students would improve. Sociologists emphasize that linguistic flexibility functions as a potent form of cultural capital that challenges systemic marginalization. Fostering an inclusive educational ecosystem requires a shift away from monolingual biases toward rich communicative repertoires."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (288, 1, 'writing', 'C1', 'writing_prompt', 'The Commercial Architecture of Public Disinformation', '{"topic": "media literacy", "prompt": "Write an analytical essay discussing how corporate data platforms utilize machine-learning protocols to manipulate collective consciousness. Analyze the threat this poses to democratic consensus and media literacy.", "title_ar": "البنية التجارية للتضليل الإعلامي العام", "min_words": 180, "prompt_ar": "اكتب مقال تحليلي عم تناقش فيه كيف المنصات الرقمية بتستغل بروتوكولات التعلم الآلي لتتلاعب بالوعي الجماعي. حلل التهديد يلي بيشكله هاد الشي ع الإجماع الديمقراطي والتربية الإعلامية.", "min_sentences": 10, "example_answer": "The pervasive influence of algorithmic curation on digital information networks has structurally transformed the nature of public discourse, threatening democratic stability. Contemporary data platforms leverage complex machine-learning protocols to analyze individual behavioral arrays, delivering content customized to maximize screen time. This automated feedback loop inherently capitalizes on psychological triggers, systematically amplifying sensationalized or divisive narratives for profit. It is this underlying commercial architecture that distorts collective consciousness, creating deeply polarized societal factions globally. Media researchers note that the standard consumer remains largely oblivious to the invisible mechanisms shaping their digital landscape. Not only do corporate algorithms dictate information visibility, but they also fundamentally undermine rational consensus-building processes. Were regulatory institutions to mandate algorithmic transparency and enforce data sovereignty laws, citizens would regain cognitive agency. However, mitigating this systemic crisis demands a pedagogical overhaul that positions algorithmic literacy as a core civic competence. Preserving democratic integrity in the digital era depends on cultivating critical skepticism toward automated filter networks."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (289, 1, 'writing', 'C1', 'writing_prompt', 'Middle Management Resistance to Decentralized Agility', '{"topic": "business strategy", "prompt": "Write a corporate report analyzing the structural and psychological resistance from middle management during corporate transitions to agile frameworks. Suggest leadership metrics to overcome institutional inertia.", "title_ar": "مقاومة الإدارة الوسطى للمرونة اللامركزية", "min_words": 180, "prompt_ar": "اكتب تقرير للشركات عم تحلل فيه المقاومة الهيكلية والنفسية من مدراء منتصف الهرم الوظيفي خلال التحول لأطر العمل المرنة (Agile). اقترح معايير قيادية لتخطّي الجمود المؤسساتي.", "min_sentences": 10, "example_answer": "The application of agile methodologies within traditionally bureaucratic corporate structures has emerged as a core strategy to combat institutional inertia. Historically, corporate enterprises operating in stable markets relied on hierarchical command structures and extensive, long-term planning cycles. However, the contemporary commercial landscape, characterized by hyper-accelerated technological disruptions, has rendered these static models completely obsolete. To remain competitive, organizations are forced to decentralize decision-making authority, organizing internal workforces into cross-functional, autonomous teams. What frequently sabotages these essential transformations is the entrenched psychological resistance from middle management, whose authority is challenged. Corporate analysts emphasize that unless leadership teams cultivate an organizational culture viewing failure as a learning metric, structural agility remains unattainable. Were corporate entities to decouple performance evaluations from rigid, short-term targets, employee innovation would flourish rapidly. Not only must enterprises adopt agile digital tools, but they must also re-engineer communication channels completely. Ultimately, dismantling institutional inertia requires a profound commitment to continuous evolution, transforming rigid corporations into adaptive ecosystems."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (290, 1, 'writing', 'C1', 'writing_prompt', 'Legislating the Remote Work Interface and Burnout', '{"topic": "law", "prompt": "Write a comprehensive legal critique evaluating the enforcement mechanisms of ''right to disconnect'' mandates within fluid, transnational corporate networks operating across time zones.", "title_ar": "تقنين واجهة الشغل عن بعد والاحتراق النفسي", "min_words": 180, "prompt_ar": "اكتب نقد قانوني شامل عم تقيم فيه آليات تطبيق قوانين ''الحق بفصل الاتصال'' ببيئات الشركات المرنة والعابرة للقارات يلي بتشتغل عبر كذا توقيت زمني.", "min_sentences": 10, "example_answer": "The rapid normalization of remote employment models across Europe has necessitated a fundamental re-examination of statutory labor law frameworks. While digital connectivity offers unparalleled flexibility, it simultaneously facilitates a corporate culture of constant availability, blurring professional duties and private life. To safeguard employee health, several European nations have pioneered statutory interventions universally referred to as the right to disconnect. This legal doctrine establishes that employees are under no obligation to engage with corporate communications outside of official hours. It is this protective legislation that aims to mitigate the rising incidence of psychological burnout among digital workforces. However, enforcing these boundaries within fluid, transnational corporate environments remains immensely complex due to cross-border jurisdiction conflicts. Legal experts note that global companies operate across multiple time zones, complicating localized labor regulations. Were international labor bodies to draft unified, enforceable employment standards, digital cross-border exploitation could be effectively neutralized. Successful containment requires a synchronized strategy reinforcing robust legislative mandates with cultural shifts treating leisure as an absolute right."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (291, 1, 'writing', 'C2', 'writing_prompt', 'The Systemic Risks of Fiscal Asymmetry within Monetary Unions', '{"topic": "economics", "prompt": "Write a rigorous macroeconomic analysis evaluating the instability inherent in currency unions that implement a unified monetary policy without a corresponding centralized fiscal treasury. Critically assess the long-term socio-economic consequences of internal deflation and stringent austerity on public infrastructure, and discuss how deep ideological differences between core and peripheral nations create political impasses regarding joint sovereign debt instruments.", "title_ar": "المخاطر الهيكلية لعدم التوازن المالي بقلب الاتحادات النقدية", "min_words": 250, "prompt_ar": "اكتب تحليل دقيق بالاقتصاد الكلي عم تقيم فيه عدم الاستقرار المزروع بقلب الاتحادات النقدية يلي بتطبق سياسة نقدية موحدة من دون ما يكون في وزارة مالية مركزية بتقابلها. قيم بشكل نقدي العواقب الاقتصادية والاجتماعية طويلة الأمد للانكماش الداخلي والتقشف الناشف على البنية التحتية العامة، وناقش كيف الفروقات الفكرية العميقة بين الدول الأساسية والطرفية عم تعمل طرق مسدودة بالسياسة بخصوص أدوات الديون السيادية المشتركة.", "min_sentences": 13, "example_answer": "The historical architecture of the Eurozone inherently embodies a structural asymmetry that continues to destabilize its long-term macroeconomic equilibrium. By executing a thoroughly unified monetary policy without establishing an equivalent centralized fiscal framework, the currency union effectively leaves its sovereign member states exceptionally exposed to asymmetric economic shocks. When sovereign nations voluntarily relinquish control over localized monetary instruments, they strip themselves of the capacity to manipulate interest rates or strategically devalue their currency to mitigate domestic crises. In the conspicuous absence of a central Eurozone treasury authorized to implement counter-cyclical budgetary transfers, distressed economies must rely almost exclusively upon internal deflation and draconian fiscal austerity. Consequently, the severe socio-economic burden of structural adjustment falls disproportionately upon public infrastructure, employment metrics, and vital social safety nets. It is this specific systemic flaw that polarizes the European continent along deeply historical geopolitical and ideological fault lines. Wealthier core nations routinely articulate intense resistance toward a permanent transfer union, fearing the moral hazard of continuously subsidizing structurally weaker jurisdictions. Conversely, peripheral states accurately contend that the current statutory paradigm systematically favors export-driven core economies, thereby structurally reinforcing imbalances across the single market. Never have localized electoral calculations been more at odds with the demands of global macroeconomic integration. Ultimately, the long-term viability of this currency framework hinges not upon temporary administrative stopgaps, but upon a robust political consensus that deliberately prioritizes transnational collective stability over immediate national self-interest. Without such structural reform, the system will remain highly vulnerable to cyclical destabilization."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (292, 1, 'writing', 'C2', 'writing_prompt', 'Algorithmic Determinism, Epistemic Opacity, and the Future of Individualized Justice', '{"topic": "ethics", "prompt": "Write a sophisticated bioethical and legal critique examining the proliferation of automated decision-making protocols within public administration and judicial frameworks. Analyze how training algorithms on historical datasets reifies systemic discrimination, outline how the opaque ''black-box'' nature of these models neutralizes the constitutional right to appeal, and discuss whether delegating complex moral evaluations to code completely absolves human actors of ethical accountability.", "title_ar": "الحتمية الخوارزمية، العتمة المعرفية، ومستقبل العدالة الفردية", "min_words": 250, "prompt_ar": "اكتب نقد قانوني وأخلاقي متطور عم تدرس فيه انتشار بروتوكولات اتخاذ القرار المؤتمتة بقلب الدوائر الحكومية والأطر القضائية. حلل كيف تدريب الخوارزميات على بيانات تاريخية عم يثبت التمييز الممنهج، ووضح كيف طبيعة ''الصندوق الأسود'' المعتمة لهي النماذج عم تعطل الحق الدستوري بالاعتراض، وناقش إذا كان تفويض التقييمات الأخلاقية المعقدة لأكواد برمجية عم يعفي الأشخاص تماماً من المسؤولية الأخلاقية.", "min_sentences": 13, "example_answer": "The contemporary proliferation of automated decision-making architecture within public administration and judicial frameworks marks a profound paradigm shift that threatens the core configuration of individual moral agency and constitutional rights. Utilizing sophisticated predictive analytics and advanced machine-learning protocols, modern state institutions increasingly delegate critical evaluations, such as criminal recidivism scoring and social welfare eligibility, to proprietary algorithms. While vociferous proponents aggressively champion these computational interfaces as pristine emblems of objective neutrality, a more meticulous examination uncovers systemic biases deliberately obscured by a veneer of mathematical infallibility. Because these commercial models are invariably trained on historical datasets that reflect deeply entrenched societal discrimination, their predictive outputs systematically reify and perpetuate those exact structural disparities. This pervasive algorithmic determinism effectively strips legal systems of the foundational principle of individualized justice, substituting nuanced human assessment with reductionist probabilistic categorization. Furthermore, the opaque, unmapped ''black-box'' nature of advanced neural networks creates an insurmountable epistemic barrier that completely undermines public accountability and administrative transparency. When a citizen is denied an essential constitutional benefit via automated profiling, discovering the underlying algorithmic logic becomes virtually impossible, thereby neutralizing the statutory right to legal appeal. Society now faces an unprecedented ethical impasse that cannot be resolved through superficial technical adjustments. By abdicating moral responsibility to automated lines of code, governance structures risk institutionalizing a technocratic apparatus that systematically values computational speed over human dignity. Fostering a just digital society demands the immediate codification of strict guardrails that subordinate automated convenience to fundamental ethical accountability."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (293, 1, 'writing', 'C2', 'writing_prompt', 'Aesthetics of Estrangement: The Kafkaesque Architecture of Modern Transnational Fiction', '{"topic": "literature analysis", "prompt": "Write an advanced literary analysis investigating how the contemporary corpus of European transnational migrant literature deploys an aesthetics of estrangement. Critique the ways modern authors move beyond linear assimilation narratives to expose systemic alienation, and evaluate how transforming administrative spaces into modern versions of Kafka''s ''The Castle'' depicts the psychological trauma of legal residency suspension.", "title_ar": "جماليات الاغتراب: المعمار الكافكاوي بالروايات المعاصرة العابرة للحدود", "min_words": 250, "prompt_ar": "اكتب تحليل أدبي متقدم عم تبحث فيه كيف مجموعة الأدب المعاصر العابر للحدود والمستوحى من تجربة المهاجرين بأوروبا عم تستخدم جماليات الاغتراب. انتقد الطرق يلي عم يتخطى فيها الكتاب المحدثين روايات الاندماج الخطية ليكشفوا عن الاغتراب الممنهج، وقيم كيف تحويل المساحات الإدارية لنسخ حديثة من رواية ''القلعة'' لكافكا عم يصور الصدمة النفسية لتعليق الإقامة القانونية.", "min_sentences": 13, "example_answer": "The contemporary corpus of transnational literature emerging from the European migrant experience elegantly deploys an aesthetics of estrangement to rigorously interrogate the oppressive, labyrinthine structures of state bureaucracy. Rather than adhering to conventional, linear migration narratives that traditionally focus on superficial cultural assimilation or basic linguistic adjustments, these highly sophisticated texts articulate a profound existential dislocation. By drawing explicit structural and thematic parallels to the surreal, menacing spatial architectures found across Franz Kafka’s seminal oeuvre, modern transnational authors masterfully deconstruct the psychological trauma of institutional containment. Within these narratives, the municipal immigration office, the isolated asylum center, and the rigid judicial courtroom are transfigured into contemporary iterations of Kafka''s The Castle. These spaces are fundamentally characterized by arbitrary regulatory shifts, inaccessible authorities, and seemingly infinite procedural delays that suspend human agency. The protagonist''s journey becomes an exhausting exercise in perpetual ontological suspension, wherein their legal identity, human dignity, and temporal existence are governed by an invisible administrative machine. Meticulously utilizing fragmented prose structures, disjointed temporalities, and magical realist disruptions, these authors transform the novel into a potent hermeneutic mirror. This mirror clearly reflects how the modernized state employs complex paperwork and linguistic mistranslations as deliberate instruments of socio-political alienation. Consequently, this literary subgenre serves as a devastating epistemological critique of Western integration discourses by exposing the structural violence embedded within demands for absolute cultural compliance. Through the radical subversion of standard narrative expectations, transnational fiction challenges readers to confront the institutional absurdities that reduce lived human experiences to static administrative files."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (294, 1, 'writing', 'C2', 'writing_prompt', 'The Geopolitical Scramble for Fault-Tolerant Quantum Supremacy', '{"topic": "advanced science", "prompt": "Write a strategic security proposal evaluating the geopolitical realignment triggered by the impending maturation of fault-tolerant quantum computing architectures. Analyze how quantum mechanics invalidates current public-key encryption infrastructures (RSA), evaluate the strategic vulnerabilities this poses to international financial and intelligence shields, and discuss the material constraints of superconducting elements.", "title_ar": "السباق الجيوسياسي على التفوق الكمي القادر على تصحيح الأخطاء", "min_words": 250, "prompt_ar": "اكتب مقترح أمني استراتيجي عم تقيم فيه إعادة التموضع الجيوسياسي الناتج عن قرب نضوج بني الحوسبة الكمية القادرة على تصحيح الأخطاء. حلل كيف ميكانيكا الكم رح تلغي وتطير معايير التشفير التقليدية ذات المفتاح العام (RSA)، وقيم الثغرات الاستراتيجية يلي رح تعملها بهي الكيفية على دروع المال والمخابرات الدولية، وناقش القيود المادية للمواد فائقة التوصيل.", "min_sentences": 13, "example_answer": "The impending technical realization of fault-tolerant quantum computing architectures at scale has precipitated an aggressive global scramble for quantum sovereignty, fundamentally reordering the parameters of international security and macroeconomic stability. Unlike conventional semiconductor breakthroughs, which merely deliver incremental upgrades to computational velocity, quantum processing leverages superposition and entanglement to execute highly complex algorithmic calculations at speeds that completely invalidate contemporary cryptographic paradigms. The most critical strategic risk centers upon the immediate vulnerability of current public-key encryption infrastructures, specifically RSA protocols, which currently safeguard global financial transactions, state intelligence networks, and critical industrial utilities. A sovereign entity that achieves mathematical supremacy via a scalable quantum system would instantly possess the asymmetric capacity to decrypt legacy data retroactively, thereby entirely neutralizing the strategic intelligence shields of global adversaries. Recognizing this systemic threat, European research centers and regulatory frameworks are rapidly accelerating the formulation of post-quantum cryptography (PQC) standards to fortify critical networks before decryption capabilities fully materialize. However, this transition to quantum-resistant ecosystems is profoundly hindered by the severe material scarcity of essential components, such as high-purity superconducting elements and specialized dilution refrigeration hardware. Consequently, the international technological landscape is fracturing into competitive technocratic blocs, characterized by stringent export controls on quantum intellectual capital to prevent strategic spillover. This intense imperative forces smaller nations to navigate dangerous technological dependencies, proving that future geopolitical autonomy will depend upon a country''s internal capacity to sustain independent computational infrastructure. Seldom has a scientific advancement possessed such absolute power to alter the global balance of power."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (295, 1, 'writing', 'C2', 'writing_prompt', 'Multi-Level Governance Jurisdictional Frictions in Supranational Climate Directives', '{"topic": "policy debate", "prompt": "Write an academic policy paper investigating the structural and legal frictions that arise when supranational climate mitigation directives are executed within heavily federalized constitutional systems. Analyze how regional state authority over natural resource allocation generates an institutional tug-of-war, and evaluate how legal ambiguities regarding jurisdictions delay grid expansion projects.", "title_ar": "احتكاكات الصلاحيات بالحوكمة متعددة المستويات بخصوص توجيهات المناخ الأوروبية", "min_words": 250, "prompt_ar": "اكتب ورقة سياسات أكاديمية عم تبحث فيها بالاحتكاكات الهيكلية والقانونية يلي عم تطلع لما تتنفذ توجيهات التخفيف من التغير المناخي الأوروبية بقلب أنظمة دستورية فيدرالية قوية. حلل كيف سلطة الولايات الإقليمية على توزيع الموارد الطبيعية عم تعمل حبل شد بين المؤسسات، وقيم كيف الغموض القانوني بخصوص الصلاحيات عم يخرّب ويأخر مشاريع توسيع شبكات الطاقة.", "min_sentences": 13, "example_answer": "The concrete operationalization of supranational climate mitigation directives within heavily federalized European constitutional frameworks continuously exposes intense structural frictions between centralized ecological mandates and regional statutory autonomy. When the European Union enacts aggressive, sweeping decarbonization timelines, the ultimate execution of these statutory laws relies upon intricate, multi-level administrative structures. Nowhere is this systemic conflict more highly pronounced than within the German federal framework, where regional states, or Länder, retain substantial constitutional jurisdiction over economic planning, energy regulation, and natural resource allocation. This highly decentralized structure inevitably generates a fierce institutional tug-of-war, as regional administrations actively maneuver to shield localized industrial sectors from the severe economic disruptions associated with rapid ecological transitions. For instance, districts heavily dependent upon traditional automotive manufacturing or heavy industries routinely employ their legislative leverage to systematically delay or dilute national carbon reduction targets, citing immediate structural unemployment hazards. Constitutional scholars observe that this operational impasse is continuously exacerbated by systemic legal ambiguity regarding the precise boundaries of federal versus regional authority over sustainable architecture subsidies and grid expansion initiatives. Had central authorities successfully engineered more binding, mandatory consensus mechanisms prior to passing legislative overhauls, the integration of renewable energy grids would have encountered far fewer judicial obstructions. Until these intricate constitutional boundaries are definitively calibrated through judicial precedents, climate governance will remain a bitterly contested arena where ecological survival continuously clashes with the entrenched mechanics of federalist resource distribution."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (296, 1, 'writing', 'C2', 'writing_prompt', 'Epistemic Dissonance and Blunt Critique in Central European Corporate Rituals', '{"topic": "cross-cultural communication", "prompt": "Write a critical report exploring how the integration of diverse global workforces within Central European corporate environments triggers profound epistemic dissonance. Examine the communicative misattunement between unvarnished direct critique and high-context indirect problem-solving, discuss its impact on psychological safety, and propose ways to re-engineer communication channels.", "title_ar": "التنافر المعرفي والنقد الناشف بالطقوس المؤسساتية بوسط أوروبا", "min_words": 250, "prompt_ar": "اكتب تقرير نقدي عم تستكشف فيه كيف دمج الأيدي العاملة العالمية المتنوعة ببيئات الشركات بوسط أوروبا عم يعمل حالة من التنافر المعرفي العميق. ادرس عدم الانسجام التواصلي بين النقد المباشر والناشف بوضوح وحل المشاكل غير المباشر القائم ع السياق العالي، وناقش تأثير هاد الشي ع الأمان النفسي، واقترح طرق لإعادة هندسة قنوات التواصل.", "min_sentences": 13, "example_answer": "The integration of diverse global workforces within the distinct institutional landscape of Central European capitalism frequently precipitates a complex form of epistemic dissonance, radically disrupting standard communication protocols and organizational behavior. Within multinational corporate ecosystems across this region, corporate governance remains traditionally predicated upon consensus-driven deliberation, high-context statutory documentation, and a strict separation between professional execution and personal identity. When international professional candidates, trained within entirely divergent communicative and organizational paradigms, enter this specific matrix, basic linguistic proficiency alone proves fundamentally inadequate to ensure successful alignment. Cross-cultural communication experts observe that structural friction points rarely emerge during explicit legal confrontations, manifesting instead during routine corporate rituals, such as performance feedback evaluations, project presentations, and consensus-building meetings. For example, the institutional reliance upon direct, entirely unvarnished critique characteristic of central European professional communication is frequently perceived by international employees as deeply destabilizing or personally hostile, thereby swiftly eroding psychological safety. Conversely, localized management teams regularly misinterpret indirect communication styles or relational, collaborative problem-solving approaches as a distinct lack of professional transparency or intellectual autonomy. This profound mutual misattunement demonstrates that authentic corporate integration requires far more than superficial diversity sensitivity seminars. What is desperately required is a comprehensive re-engineering of internal corporate communication channels that explicitly validates communicative diversity as a potent cognitive asset. Until leadership teams transcend superficial multicultural metrics, the vast latent intellectual capital of global talent will remain structurally constrained by localized behavioral models."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (297, 1, 'writing', 'C2', 'writing_prompt', 'Deconstructing the Material Throughput Axiom within Ecological Economics', '{"topic": "economics", "prompt": "Write a theoretical essay evaluating the radical degrowth paradigm within modern ecological economics. Formulate a comprehensive critique of the absolute decoupling hypothesis within carbon capitalism, analyze how infinite GDP expansion conflicts with finite planetary boundaries, and confront the critics who claim planned material contraction induces immediate macroeconomic chaos.", "title_ar": "تفكيك بديهية استهلاك المواد بالاقتصاد البيئي", "min_words": 250, "prompt_ar": "اكتب مقال نظري عم تقيم فيه نموذج تراجع النمو (Degrowth) الجذري بقلب الاقتصاد البيئي الحديث. صغ نقد شامل لفرضية فصل المسارات المطلق بقلب رأسمالية الكربون، وحلل كيف التوسع اللانهائي للناتج الإجمالي بيتعارض مع الحدود البيئية المتناهية للكوكب، وواجه المنتقدين يلي عم يقولوا إن الانكماش المادي المخطط له بيعمل فوضى فورية بالاقتصاد الكلي.", "min_sentences": 13, "example_answer": "As escalating ecological crises systematically expose the inherent structural fragility of traditional linear economies, the academic discourse surrounding ecological economics has shifted decisively toward the radical degrowth paradigm. This sophisticated macro-economic theory fundamentally challenges the core axiom of contemporary economics: the assumption that infinite Gross Domestic Product (GDP) expansion is physically compatible with the finite biophysical boundaries of our planet. Degrowth proponents convincingly argue that contemporary corporate strategies for eco-modernism, such as green capitalism and absolute decoupling, constitute a dangerous environmental illusion. They maintain that absolute decoupling—the mathematical insulation of economic expansion from total material resource throughput and environmental degradation—has never occurred at the scale or velocity required to avert catastrophic climate destabilization. Instead, the degrowth framework advocates for a deliberate, democratically planned contraction of material and energy usage in wealthy nations, fundamentally restructuring social institutions to prioritize human well-being over capital accumulation. Critics, however, aggressively contend that such a deliberate economic contraction would induce immediate macroeconomic chaos, resulting in catastrophic unemployment, public revenue collapses, and severe geopolitical vulnerability. They vociferously assert that without the financial surplus continuously generated by conventional economic growth, funding advanced scientific research and sustainable infrastructure transformations becomes fiscally impossible. This profound intellectual impasse highlights the fundamental systemic dilemma of the anthropocene epoch. Modern democratic societies must either successfully re-engineer their socio-economic institutions away from growth dependency without triggering structural collapse, or remain bound to an expansionist paradigm until ecological boundary failures enforce a catastrophic contraction."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (298, 1, 'writing', 'C2', 'writing_prompt', 'The Biopolitical Frontier: Neurotechnology and the Legal Formulation of Neurorights', '{"topic": "ethics", "prompt": "Write a bioethical manifesto investigating the biopolitical threats that consumer-grade brain-computer interfaces pose to individual identity and cognitive liberty. Analyze how commercializing neural data enables predictive corporate surveillance directly from the cerebral cortex, and build a legal argument for the immediate codification of unique ''neurorights'' to protect mental privacy.", "title_ar": "الجبهة السياسية الحيوية: التكنولوجيا العصبية والصياغة القانونية للحقوق العصبية", "min_words": 250, "prompt_ar": "اكتب بيان عن الأخلاق الحيوية عم تبحث فيه بالتهديدات السياسية والحيوية يلي بتشكلها واجهات الدماغ والكمبيوتر المخصصة للمستهلكين على الهوية الشخصية والحرية الإدراكية. حلل كيف تحويل البيانات العصبية لبضاعة بيسمح بمراقبة الشركات التنبؤية مباشرة من القشرة المخية، وابنِ حجة قانونية للتدوين الفوري لـ ''حقوق عصبية'' فريدة تحمي الخصوصية العقلية.", "min_sentences": 13, "example_answer": "The rapid clinical and commercial maturation of advanced brain-computer interfaces (BCIs) and neuroprosthetics has officially transcended the traditional boundaries of restorative medicine, projecting contemporary society into a highly complex bioethical frontier centered on the sanctity of cognitive liberty. Modern neurotechnologies, which utilize sophisticated machine-learning algorithms to decode complex neural signals and translate mental processes into computational commands, offer revolutionary therapeutic choices for individuals suffering from severe motor impairments. However, as corporate enterprises aggressively invest in consumer-grade neural interfaces designed to maximize attention metrics or facilitate direct digital communication, the boundary of personal identity and mental privacy becomes exceptionally vulnerable. Bioethicists warn that the mass commercialization of raw neural data introduces unprecedented opportunities for invasive algorithmic corporate surveillance, enabling corporations or state entities to monitor subconscious cognitive preferences directly from the human cerebral cortex. This unprecedented capacity for neural monitoring introduces a fundamental epistemic threat to individual autonomy. When corporate data streams can access and manipulate cognitive processes before they even register within conscious human awareness, the very concept of free will becomes profoundly compromised. Furthermore, the integration of automated feedback loops that directly stimulate neural pathways to alter mood risks eroding individual agency entirely, transforming human subjects into semi-automated nodes within decentralized networks. This systemic vulnerability necessitates a rapid jurisdictional evolution. Legal scholars contend that conventional human rights frameworks are completely inadequate to handle neurotechnological intrusion, demanding the immediate codification of specific neurorights designed to protect absolute cognitive liberty from predatory commercial exploitation."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (299, 1, 'writing', 'C2', 'writing_prompt', 'The Paradox of the EU AI Act: Balancing Autonomy with Legislative Overreach', '{"topic": "policy debate", "prompt": "Write a political strategy essay exploring the systemic paradox embedded within centralized artificial intelligence legislation like the EU AI Act. Analyze how strict risk-based frameworks designed to prevent data exploitation might inadvertently sabotage regional innovation, impose severe liabilities on open-source software, and increase technological dependency on foreign proprietary conglomerates.", "title_ar": "تناقض قانون الذكاء الاصطناعي الأوروبي: الموازنة بين الاستقلال والتغول التنظيمي", "min_words": 250, "prompt_ar": "اكتب مقال بالاستراتيجية السياسية عم تستكشف فيه التناقض الممنهج المزروع بقلب تشريعات الذكاء الاصطناعي المركزية متل قانون الذكاء الاصطناعي الأوروبي. حلل كيف الأطر الصارمة القائمة على المخاطر والمصممة لمنع استغلال البيانات ممكن تخرب من دون ما تقصد الابتكار الإقليمي، وتفرض مسؤوليات جنائية على البرمجيات مفتوحة المصدر، وتزيد التبعية التكنولوجية للشركات الأجنبية.", "min_sentences": 13, "example_answer": "The intense policy debate surrounding the statutory regulation of foundational artificial intelligence architectures within Europe illustrates a fundamental systemic tension between technological sovereignty and legislative overreach. As transnational technology corporations solidify their monopolistic hegemony over large-scale generative models and critical computational infrastructure, European regulatory bodies have implemented comprehensive legal frameworks, such as the EU AI Act, to mitigate existential risks and preserve data privacy. This pioneering legislation utilizes a rigid, risk-based tier system, mandating absolute architectural transparency, independent algorithmic auditing, and strict copyright compliance for high-risk deployments. Proponents of this centralized regulatory paradigm assert that strict statutory boundaries are essential to shield citizens from automated discrimination, systemic disinformation, and corporate data exploitation. However, an expanding faction of technology strategists, open-source advocates, and digital economists contends that this rigid legislative framework inadvertently sabotages regional innovation, creating insurmountable bureaucratic hurdles for local start-ups and independent research teams. They argue that by imposing severe criminal liabilities and expensive compliance protocols on open-source software development, the state effectively centralizes technological control into the hands of a few dominant foreign tech conglomerates who possess the vast capital required to navigate administrative compliance effortlessly. Consequently, this dynamic could result in an ironic geopolitical outcome, whereby a legislative framework explicitly designed to guarantee digital autonomy instead solidifies Europe’s long-term technological dependency on foreign proprietary platforms. Moving forward, policymakers face the delicate task of calibrating enforcement mechanisms so that ethical guardrails protect civic spaces without freezing domestic capital investments."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (300, 1, 'writing', 'C2', 'writing_prompt', 'Linguistic Drift, Polyphonic Repertoires, and Monolingual Institutional Pathologization', '{"topic": "cross-cultural communication", "prompt": "Write a sociolinguistic dissertation paper investigating the linguistic drift and polyphonic identity synthesis within second-generation diasporic communities in Western European urban spaces. Evaluate how fluid code-switching serves as a sophisticated third space for agency, and critically analyze the institutional pathologization of these hybrid structures by monolingual standard registers.", "title_ar": "الانزياح اللغوي، المخزون متعدد الأصوات والتعامل المرضي للمؤسسات مع اللغة الوحدة", "min_words": 250, "prompt_ar": "اكتب ورقة أطروحة بعلم اللغة الاجتماعي عم تبحث فيها بالانزياح اللغوي وتركيب الهوية متعددة الأصوات بقلب مجتمعات الجيل الثاني من المغتربين بالمساحات الحضرية بأوروبا الغربية. قيم كيف التبديل المرن بين اللغات بيشتغل كمساحة تالتة متطورة للتعبير عن الإرادة، وحلل بشكل نقدي التعامل المرضي للمؤسسات مع هي الهياكل الهجينة من قبل أنظمة اللغة الوحدة.", "min_sentences": 13, "example_answer": "The long-term sociolinguistic evolution of second-generation diasporic communities within Western European metropolises offers a profound study in linguistic drift and polyphonic identity synthesis. Within these dense urban spaces, young individuals continuously navigate a multifaceted communicative ecosystem, fluidly synthesizing the syntactic structures of their heritage languages—such as Syrian Arabic—with the morphology and lexicon of their host societies'' standard tongues, like German or English. Rather than representing a corrupted or incomplete mastery of either idiom, contemporary sociolinguists interpret this fluid code-switching and hybrid speech production as the emergence of a highly sophisticated third space. This linguistic hybridity functions as an active strategy for individual and collective agency, allowing youth to construct a localized, syncretic identity that consciously resists both majoritarian cultural erasure and the rigid traditionalism of diasporic enclaves. Through the deliberate subversion of standard monolingual registers, these speakers develop a rich polyphonic repertoire that serves as an expressive medium for their unique existential positionality. However, the institutional recognition of these hybrid communication models remains a highly contested domain within formal education and employment spheres. National pedagogical institutions routinely prioritize standardized language competence as the absolute, non-negotiable metric for socio-economic mobility, pathologizing hybrid structures as indicators of linguistic deficit or cognitive confusion. This institutional rigidity creates a frustrating intellectual impasse, because while the lived reality of multicultural urban centers requires flexible, multifaceted communicative adaptability, systemic evaluation mechanisms remain bound to an antiquated monolingual ideology. Ultimately, dismantling these systemic biases requires an epistemological shift that validates polyphonic hybridity as a vital form of socio-cultural capital."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (301, 1, 'speaking', 'A1', 'speaking_prompt', 'Introduce Yourself', '{"topic": "self-introduction", "prompt": "Introduce yourself to the class. What is your name? Where are you from and where do you live now?", "title_ar": "تعريف عن حالك", "prompt_ar": "عرفنا عن حالك بالصف. شو اسمك؟ من وين أنت؟ ووين عايش هلق؟", "min_seconds": 20, "question_type": "describe", "example_answer": "Hello. My name is Ahmad. I am from Syria. Now, I live in Berlin, Germany. I am twenty-five years old. I am a student."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (302, 1, 'speaking', 'A1', 'speaking_prompt', 'Your Family Members', '{"topic": "family", "prompt": "Talk about your family. Do you have brothers or sisters? How many brothers or sisters do you have?", "title_ar": "أفراد عيلتك", "prompt_ar": "احكي عن عيلتك. عندك أخوات شباب أو بنات؟ قديش عدد أخواتك؟", "min_seconds": 20, "question_type": "describe", "example_answer": "I have a nice family. I have one brother and two sisters. My father is a doctor. My mother is a teacher. We live together."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (303, 1, 'speaking', 'A1', 'speaking_prompt', 'Describe Your Bedroom', '{"topic": "home", "prompt": "Describe your bedroom in Germany. What is in your room? What color are the walls?", "title_ar": "وصف غرفة نومك", "prompt_ar": "اوصف غرفة نومك بألمانيا. شو في بقلب غرفتك؟ وشو لون الحيطان؟", "min_seconds": 20, "question_type": "describe", "example_answer": "My room is small and clean. It has a white bed. I have a brown desk and a big window. The walls are white."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (304, 1, 'speaking', 'A1', 'speaking_prompt', 'Your Morning Routine', '{"topic": "daily routine", "prompt": "Talk about your morning routine. What time do you wake up? What do you drink or eat every morning?", "title_ar": "روتينك الصباحي", "prompt_ar": "احكي عن روتينك الصباحي. بأي ساعة بتفيق؟ شو بتشرب أو بتاكل كل يوم الصبح؟", "min_seconds": 20, "question_type": "narrate", "example_answer": "Every morning, I wake up at seven o''clock. I drink hot black tea. I eat warm bread with cheese. Then, I go to school."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (307, 1, 'speaking', 'A1', 'speaking_prompt', 'Your Weekend Hobby', '{"topic": "self-introduction", "prompt": "What is your favorite hobby on the weekend? What do you like to do on Saturday afternoon?", "title_ar": "هوايتك بالعطلة", "prompt_ar": "شو هي هوايتك المفضلة بعطلة نهاية الأسبوع؟ شو بتحب تعمل يوم السبت بعد الظهر؟", "min_seconds": 20, "question_type": "describe", "example_answer": "On Saturday afternoon, I do not study at school. I play football with my Syrian friends in the park. Football is my favorite hobby."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (308, 1, 'speaking', 'A1', 'speaking_prompt', 'Describe Your Mother', '{"topic": "family", "prompt": "Talk about your mother. What is her name? What does she look like and where does she live?", "title_ar": "وصف أمك", "prompt_ar": "احكي عن أمك. شو اسمها؟ كيف شكلها ووين عايشة؟", "min_seconds": 20, "question_type": "describe", "example_answer": "My mother is very kind. Her name is Fatima. She has beautiful green eyes and brown hair. She lives in Damascus, Syria now."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (309, 1, 'speaking', 'A1', 'speaking_prompt', 'The Flat''s Shared Kitchen', '{"topic": "home", "prompt": "Describe the shared kitchen in your flat. Is it big or clean? Do you cook dinner there with your flatmates?", "title_ar": "المطبخ المشترك بالشقة", "prompt_ar": "اوصف المطبخ المشترك يلي بشقتك. هل هو كبير أو نضيف؟ عم تطبخ عشا هنيك مع رفقاتك بالسكن؟", "min_seconds": 20, "question_type": "describe", "example_answer": "The kitchen in our flat is clean and big. It has a small table. I cook chicken and rice there every night with my flatmates."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (310, 1, 'speaking', 'A1', 'speaking_prompt', 'Buying Groceries', '{"topic": "food", "prompt": "Talk about shopping for food. What do you buy at the German supermarket? How much money do you pay?", "title_ar": "شرا غراض الأكل", "prompt_ar": "احكي عن شرا الأكل. شو عم تشتري من السوبرماركت الألماني؟ وقديش عم تدفع مصاري؟", "min_seconds": 20, "question_type": "describe", "example_answer": "I go to the supermarket on Friday. I buy fresh white milk, warm bread, and red tomatoes. The food is cheap. I pay ten euros."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (311, 1, 'speaking', 'A2', 'speaking_prompt', 'Buying a New Jacket', '{"topic": "shopping", "prompt": "Talk about the last time you went shopping for clothes. What did you buy and how much did it cost?", "title_ar": "شرا جاكيت جديد", "prompt_ar": "احكي عن آخر مرة رحت فيها تتسوق ثياب. شو اشتريت وقديش كلفك؟", "min_seconds": 30, "question_type": "describe", "example_answer": "Last Saturday, I went to a large shopping mall downtown. I bought a warm black jacket because the weather was freezing. It cost forty euros, which was quite cheap. The shop assistant was very friendly and helpful. I am very happy with my new jacket."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (312, 1, 'speaking', 'A2', 'speaking_prompt', 'A Train Journey', '{"topic": "transport", "prompt": "Tell a story about a train journey you took recently. Where did you go and was it comfortable?", "title_ar": "مشوار بالقطار", "prompt_ar": "احكي قصة عن مشوار بالقطار عملته مؤخراً. وين رحت وهل كان مريح؟", "min_seconds": 30, "question_type": "narrate", "example_answer": "Yesterday morning, I travelled by train from Berlin to Hamburg to visit my friend. I arrived at the station early and bought my ticket from a machine. The journey took two hours, and the train was clean and comfortable. I read a storybook during the trip."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (313, 1, 'speaking', 'A2', 'speaking_prompt', 'My Favorite Season', '{"topic": "weather", "prompt": "What is your favorite season in Germany? Do you like sunny summers or snowy winters? Why?", "title_ar": "فصلي المفضل", "prompt_ar": "شو هو فصلك المفضل بألمانيا؟ بتحب الصيف المشمس ولا الشتا يلي فيه ثلج؟ وليش؟", "min_seconds": 30, "question_type": "opinion", "example_answer": "In my opinion, summer is the best season here. I love warm and sunny days because I can spend time outside. Winters are extremely cold and dark, which I do not like. In summer, my friends and I always swim in the nearby lake."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (314, 1, 'speaking', 'A2', 'speaking_prompt', 'My Weekend Hobby', '{"topic": "hobbies", "prompt": "Describe your favorite hobby. When do you practice it and who do you play with?", "title_ar": "هوايتي بالعطلة", "prompt_ar": "اوصف هوايتك المفضلة. إيمتى بتمارسها ومع مين بتلعب؟", "min_seconds": 30, "question_type": "describe", "example_answer": "My favorite hobby is playing football. I joined a local German sports club last month. We practice together every Thursday evening after school on a big green field. I play with three friendly international students. It is fun and healthy."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (315, 1, 'speaking', 'A2', 'speaking_prompt', 'My New Neighborhood', '{"topic": "neighborhood", "prompt": "Describe the neighborhood where you live now. Are there shops, parks, or restaurants near your flat?", "title_ar": "حارتي الجديدة", "prompt_ar": "اوصف الحارة يلي عايش فيها هلق. في محلات، جناين، أو مطاعم قريب من شقتك؟", "min_seconds": 30, "question_type": "describe", "example_answer": "I live in a beautiful neighborhood near Munich. It is very quiet and clean. There is a large supermarket and a pharmacy down the street. A new Syrian restaurant opened last Tuesday right next to my flat. I love walking in the local park."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (316, 1, 'speaking', 'A2', 'speaking_prompt', 'First Day at School', '{"topic": "school", "prompt": "Talk about your first day at the language institute. How did you feel and who did you meet?", "title_ar": "أول يوم بالمدرسة", "prompt_ar": "احكي عن أول يوم إلك بمعهد اللغة. كيف كنت حاسس ومين التقيت؟", "min_seconds": 30, "question_type": "narrate", "example_answer": "Last Monday, I started my new English course. I was very nervous in the morning because I did not know anyone. I entered the classroom at nine o''clock and met our teacher, Miss Sarah. She gave me a big vocabulary textbook and welcomed me warmly."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (317, 1, 'speaking', 'A2', 'speaking_prompt', 'Buying Used Items Online', '{"topic": "shopping", "prompt": "Do you think buying used items like bicycles online is a good idea? Why or why not?", "title_ar": "شرا غراض مستعملة أونلاين", "prompt_ar": "هل بتظن إنه شرا غراض مستعملة متل البسكليتات أونلاين فكرة منيحة؟ ليش إي وليش لأ؟", "min_seconds": 30, "question_type": "opinion", "example_answer": "I think buying used items online is a great idea. New things are very expensive for international students, so websites help us save money. Yesterday, I bought a good used bicycle for only fifty euros. The brakes work perfectly and it is in excellent condition."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (318, 1, 'speaking', 'A2', 'speaking_prompt', 'Buses Versus Bicycles', '{"topic": "transport", "prompt": "Discuss the differences between traveling by bus and riding a bicycle in the city. Which is better?", "title_ar": "الباصات بوش البسكليتات", "prompt_ar": "ناقش الفروقات بين المشاوير بالباص وركوب البسكليت بالمدينة. أنهي الأحسن؟", "min_seconds": 30, "question_type": "discuss", "example_answer": "Traveling by bus is comfortable when it rains heavily outside because the bus is always warm. However, buying tickets every month costs money. Riding a bicycle is cheaper and healthier, but it is difficult when the weather is cold. I prefer bicycles for short trips."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (319, 1, 'speaking', 'A2', 'speaking_prompt', 'Morning Classes or Evening Classes', '{"topic": "school", "prompt": "Compare morning classes and evening classes at your institute. Which schedule do you prefer?", "title_ar": "صفوف الصبح ولا صفوف المسا", "prompt_ar": "قارن بين صفوف الصبح وصفوف المسا بالمعهد تبعك. أنهي دوام بتفضله؟", "min_seconds": 30, "question_type": "discuss", "example_answer": "Morning classes are excellent because your brain is active and you can study well. However, many students must work during the day. Evening classes allow you to attend lessons after five o''clock. I prefer morning classes because I enjoy studying early with my classmates."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (320, 1, 'speaking', 'A2', 'speaking_prompt', 'Living in a Shared Apartment', '{"topic": "neighborhood", "prompt": "Is it better to live alone or with roommates in a shared apartment? Share your opinion.", "title_ar": "العيشة بشقة مشتركة", "prompt_ar": "هل الأحسن الواحد يعيش لحاله ولا مع رفقات سكن بشقة مشتركة؟ اعطينا رأيك.", "min_seconds": 30, "question_type": "opinion", "example_answer": "In my opinion, living in a shared apartment is much better for newcomers. You can practice languages with your flatmates and make new friends easily. Living alone is very quiet but it can be lonely and expensive. My roommates are polite and we often cook together."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (321, 1, 'speaking', 'B1', 'speaking_prompt', 'Preparing for a Job Interview', '{"topic": "job applications", "prompt": "Describe how you would prepare for an important job interview in Germany. What documents should you bring, and how would you dress to make a good impression?", "title_ar": "التجهيز لمقابلة شغل", "prompt_ar": "اوصف كيف بتجهز حالك لمقابلة شغل مهمة بألمانيا. شو الأوراق يلي لازم تجيبها معك، وكيف لازم تلبس مشان تعطي انطباع منيح؟", "min_seconds": 45, "question_type": "describe", "example_answer": "If I had an important job interview tomorrow, I would prepare by researching the company''s profile online. I have already updated my CV and printed out my university certificates, which I should bring in a neat folder. I would definitely dress formally, wearing a clean suit to make a professional impression. I must also practice answering common questions about my previous customer service experience. If I managed my time well and arrived ten minutes early, I would feel much more confident during the interview."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (322, 1, 'speaking', 'B1', 'speaking_prompt', 'Sorting Waste and Recycling', '{"topic": "environment", "prompt": "Give your opinion on the strict German recycling system. Do you think waste sorting really helps protect the environment, or do you find it too complicated?", "title_ar": "رأيك بفرز الزبالة وإعادة التدوير", "prompt_ar": "شو رأيك بنظام فرز الزبالة الصارم بألمانيا؟ بتظن إنه فرز الزبالة فعلاً عم يساعد بحماية البيئة، ولا شايفه معقد زيادة عن اللزوم؟", "min_seconds": 45, "question_type": "opinion", "example_answer": "In my opinion, the strict recycling system in Germany is excellent, although it seemed quite complicated when I first arrived. I truly believe that sorting waste into different colored bins helps protect our environment because it makes recycling much more efficient. If we didn''t separate plastic packaging from organic waste, we would destroy natural resources. I have learned to appreciate the ''Pfand'' system too, because returning empty bottles to the supermarket ensures that materials are reused properly instead of being thrown away."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (323, 1, 'speaking', 'B1', 'speaking_prompt', 'A Memorable European Journey', '{"topic": "travel", "prompt": "Narrate a story about a memorable trip you took by train or plane within Europe. Where did you go, who were you with, and what did you enjoy the most?", "title_ar": "رحلة ما بتتنسى بأوروبا", "prompt_ar": "احكيلنا قصة عن رحلة ما بتتنسى عملتها بالقطار أو بالطيارة جوّات أوروبا. وين رحت، مع مين كنت، وشو أكتر شي عجبك هنيك؟", "min_seconds": 45, "question_type": "narrate", "example_answer": "Last summer, I took a memorable trip to Munich using the high-speed ICE train. I traveled with my Syrian classmate, and we had booked our tickets early online to get a cheap price. During the smooth journey, we sat by the window, drank hot coffee from the onboard bistro, and watched the beautiful green hills. If the train hadn''t been so fast, we wouldn''t have reached the central station on schedule. I enjoyed exploring the historic city center the most because it was absolutely breathtaking."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (324, 1, 'speaking', 'B1', 'speaking_prompt', 'Visiting a Doctor in Germany', '{"topic": "health", "prompt": "Describe your experience when you visited a medical clinic or a dentist recently. How did you book the appointment, and how did the insurance handle the costs?", "title_ar": "زيارة لعند الدكتور بألمانيا", "prompt_ar": "اوصف تجربتك لما زرت عيادة طبية أو دكتور سنان مؤخراً. كيف حجزت الموعد وكيف التأمين أدار التكاليف؟", "min_seconds": 45, "question_type": "describe", "example_answer": "Recently, I developed a severe toothache that kept me awake all night, so I had to visit a dentist immediately. I called the clinic in the morning, and the receptionist kindly managed to give me an emergency appointment for the afternoon. When I arrived, I showed my public health insurance card at the front desk. The dentist discovered a small cavity and gave me a painless filling. I am very grateful that my mandatory insurance covered the whole cost, so I didn''t pay anything."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (325, 1, 'speaking', 'B1', 'speaking_prompt', 'Smart Homes and Daily Automation', '{"topic": "technology", "prompt": "Discuss the advantages and disadvantages of using smart devices and automated appliances at home. Does technology make our life simpler or more dependent?", "title_ar": "البيوت الذكية والأتمتة اليومية", "prompt_ar": "ناقش ميزات وسلبيات استخدام الأجهزة الذكية والأدوات المؤتمتة بالبيت. هل التكنولوجيا عم تخلي حياتنا أسهل ولا عم تخلينا معتمدين عليها زيادة؟", "min_seconds": 45, "question_type": "discuss", "example_answer": "Using smart devices at home offers several advantages, such as saving time and controlling appliances through your smartphone. For instance, we have installed a smart router that connects our devices seamlessly. However, a major disadvantage is that we become too dependent on automation. If the internet connection went down, we wouldn''t be able to study or access our documents easily. In conclusion, while modern technology makes daily routine simpler, we should ensure we can manage our chores independently without relying purely on devices."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (326, 1, 'speaking', 'B1', 'speaking_prompt', 'Managing Flatmate Conflicts', '{"topic": "relationships", "prompt": "Give your opinion on the best way to handle a conflict with a flatmate who neglects cleaning chores. Would you talk to them directly or call a flat meeting?", "title_ar": "حل المشاكل مع رفقات السكن", "prompt_ar": "شو رأيك بأحسن طريقة لتعالج مشكلة مع رفيقك بالسكن يلي عم يهمل شغل التنظيف؟ بتحكي معه دغري وش بوش ولا بتعمل اجتماع للبيت كله؟", "min_seconds": 45, "question_type": "opinion", "example_answer": "In my opinion, if a flatmate neglects his chores and leaves dirty dishes in the kitchen sink, you should address the issue openly and calmly. Leaving a messy kitchen creates unnecessary tension among roommates. I would prefer to talk to them directly first, explaining how the situation affects everyone''s daily routine. If they continued to ignore the cleaning schedule, I would then call a house meeting to update the rules together. Communicating honestly is the best way to maintain a peaceful friendship at home."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (327, 1, 'speaking', 'B1', 'speaking_prompt', 'University versus Apprenticeship', '{"topic": "school system", "prompt": "Compare studying for a theoretical degree at a university with completing a practical apprenticeship (Ausbildung). Which path is more suitable for your goals?", "title_ar": "الدراسة بالجامعة بوش الأوسبيلدونغ", "prompt_ar": "قارن بين الدراسة لشهادة نظرية بالجامعة وبين عمل تدريب مهني وعملي (أوسبيلدونغ). أنهي طريق شايفه مناسب أكتر لأهدافك المهنية؟", "min_seconds": 45, "question_type": "discuss", "example_answer": "Attending university requires a lot of self-discipline because professors expect extensive theoretical research. On the other hand, starting a vocational training program, or an Ausbildung, combines classroom learning with actual on-the-job experience. A major benefit of an apprenticeship is that you can earn a monthly salary while learning a specific trade. For my personal career goals, I prefer the university path because I enjoy academic research, but I believe both options offer excellent career opportunities in the European market."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (328, 1, 'speaking', 'B1', 'speaking_prompt', 'A Day at the Immigration Office', '{"topic": "bureaucracy", "prompt": "Narrate your experience visiting a German government building or the immigration office (Ausländerbehörde). What happened during your appointment?", "title_ar": "يوم بمكتب الإقامة والأجانب", "prompt_ar": "احكيلنا شو صار معك لما زرت دائرة حكومية ألمانية أو مكتب الإقامة والأجانب (الأوسلندريهوردي). شو صار معك خلال الموعد تبعك؟", "min_seconds": 45, "question_type": "narrate", "example_answer": "Last month, I had a very stressful morning because I needed to renew my student residence permit. I arrived at the immigration office early because my visa was expiring soon. If I hadn''t gathered all my paperwork beforehand, including my blocked bank account statement, the officer would have rejected my application immediately. Luckily, she examined my documents carefully and gave me a temporary permit. I felt an immense sense of relief when I finally left the building with everything sorted out."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (329, 1, 'speaking', 'B1', 'speaking_prompt', 'Punctuality and Social Expectations', '{"topic": "cultural differences", "prompt": "Share your opinion on the cultural importance of punctuality in Germany. How does it compare to your home country, and have you ever experienced an awkward delay?", "title_ar": "الالتزام بالوقت والتوقعات الاجتماعية", "prompt_ar": "عطينا رأيك بالأهمية الثقافية للالتزام بالوقت بألمانيا. كيف بتشوفها مقارنة ببلدنا، وهل شي مرة صار معك موقف بيبكك بسبب التأخير؟", "min_seconds": 45, "question_type": "opinion", "example_answer": "I believe that punctuality is extremely important for a smooth integration into German society. If you have an official appointment, you are expected to arrive five minutes early out of respect. In my home country, social timing is much more flexible, which can sometimes lead to minor misunderstandings here. Once, I accidentally looked at the wrong tram map and arrived twenty minutes late for a meeting. I felt terrible, so I called beforehand to apologize sincerely. Since that day, I always check the schedule twice."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (330, 1, 'speaking', 'B1', 'speaking_prompt', 'Public Transport versus Private Cars', '{"topic": "daily city life", "prompt": "Discuss whether it is better to rely on public transport or own a private car while living in a major European city. Consider costs, convenience, and traffic.", "title_ar": "المواصلات العامة بوش السيارات الخاصة", "prompt_ar": "ناقش إذا كان الأحسن الواحد يعتمد ع المواصلات العامة ولا يملك سيارة خاصة وهو عايش بمدينة أوروبية كبيرة. فكر بالتكاليف، الراحة، وعجقات السير.", "min_seconds": 45, "question_type": "discuss", "example_answer": "Relying on public transport in a big European city is highly efficient because trains and buses are always on time. If you use a monthly pass, it is much cheaper than owning a private car, which requires expensive insurance and parking fees. On the other hand, driving a car offers more personal comfort and privacy, but you frequently face terrible traffic congestion during rush hours. Therefore, I think using the subway or a bicycle is a much better alternative for daily city life."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (362, 1, 'reading', 'B2', 'lesson', 'The Remote Work Debate: Balancing Flexibility and Collaboration', '{"source": "ai_nightly", "passage": "The shift towards remote work has sparked considerable debate globally, with advocates emphasizing its potential benefits. On the one hand, proponents argue that it offers unparalleled flexibility, enabling employees to manage personal commitments more effectively and reducing daily commute stress. Consequently, this could lead to increased job satisfaction and, arguably, higher productivity. Furthermore, businesses might experience reduced overheads by requiring less office space. Nevertheless, critics tend to point out the potential downsides. It seems that a lack of face-to-face interaction might hinder team cohesion and spontaneous collaboration, which are often indispensable for innovation. The analysis shows concerns about maintaining a distinct work-life balance when the office environment is removed. Finding a viable solution that balances these perspectives remains a controversial topic for many organizations, prompting a re-evaluation of traditional work models. In conclusion, while the benefits are clear, the challenges necessitate careful consideration.", "title_ar": "نقاش الشغل عن بُعد: الموازنة بين المرونة والتعاون", "questions": [{"stem": "What is one main argument AGAINST remote work mentioned in the passage?", "choices": ["It leads to increased overheads for businesses.", "It seems to hinder team cohesion and spontaneous collaboration.", "Employees tend to experience more commute stress.", "It offers unparalleled flexibility for personal commitments."], "correct_index": 1}, {"stem": "What does the author suggest about finding a solution to the remote work debate?", "choices": ["It is a simple matter that most organizations have already resolved.", "It requires organizations to completely abandon traditional work models.", "It remains a controversial topic requiring careful consideration of different perspectives.", "The benefits are so clear that challenges are negligible."], "correct_index": 2}], "passage_ar": "التحول نحو الشغل عن بُعد أثار نقاش كبير عالمياً، والمؤيدين عم يأكدوا على فوائده المحتملة. من جهة، المؤيدين عم يحكوا إنو بيوفر مرونة لا مثيل إلها، وبيمكّن الموظفين من إدارة التزاماتهم الشخصية بشكل أحسن ويقلل من توتر التنقل اليومي. وبالتالي، هالشي ممكن يؤدي لزيادة الرضا الوظيفي، ويمكن كمان إنتاجية أعلى. علاوة على ذلك، الشركات ممكن تقلل من تكاليفها التشغيلية لأنو بتحتاج مساحة مكتبية أقل. مع هيك، المنتقدين بيميلوا ليأشروا على السلبيات المحتملة. بيبدو إنو نقص التواصل المباشر ممكن يعيق تماسك الفريق والتعاون العفوي، يللي غالباً بيكونوا ضروريين للابتكار. التحليل بيبين مخاوف حول المحافظة على توازن واضح بين الشغل والحياة لما يتم إزالة بيئة المكتب. إيجاد حل قابل للتطبيق بيوازن بين هدول المنظورين بيضل موضوع جدلي لكثير من الشركات، وهالشي عم يدفع لإعادة تقييم نماذج الشغل التقليدية. وبالختام، بينما الفوائد واضحة، التحديات بتحتاج لدراسة دقيقة.", "generated_at": "2026-06-23T23:42:45.852913+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (363, 1, 'reading', 'B2', 'lesson', 'AI in Education: Prospects and Challenges', '{"source": "ai_nightly", "passage": "The integration of Artificial Intelligence (AI) into educational frameworks has become a focal point of discussion, prompting both optimism and skepticism among educators and policymakers. Many academics have advocated for AI''s potential to personalize learning experiences, asserting that it could tailor content to individual student needs, a concept previously considered unfeasible. Furthermore, a recent report emphasized that AI tools might significantly reduce administrative burdens for teachers, allowing them to concentrate more on pedagogical development. Nevertheless, critics have consistently alleged that AI could exacerbate existing inequalities, particularly concerning access to technology in underserved communities. Some experts have conceded that while AI presents undeniable advantages, its implementation must be carefully managed to avoid unintended consequences. The debate, therefore, centers on how to harness AI''s transformative power responsibly, ensuring it serves as an indispensable asset rather than a controversial disruption.", "title_ar": "الذكاء الاصطناعي بالتعليم: آمال وتحديات", "questions": [{"stem": "What is one potential benefit of AI in education, according to its advocates?", "choices": ["It could lead to increased administrative burdens for teachers.", "It has the potential to personalize learning experiences for students.", "It is likely to exacerbate existing inequalities in technology access.", "It is a controversial disruption that must be avoided."], "correct_index": 1}, {"stem": "What do critics mainly allege about AI''s integration into education?", "choices": ["It promises to create unprecedented pedagogical development opportunities.", "It could disproportionately benefit underserved communities.", "It might worsen existing inequalities, especially regarding technology access.", "It makes individual student needs easier to address without careful management."], "correct_index": 2}], "passage_ar": "دمج الذكاء الاصطناعي (AI) ضمن الأطر التعليمية صار محور نقاش، ومو بس عم يثير تفاؤل، كمان شكوك بين التربويين وصناع السياسات. كتير أكاديميين دعوا لإمكانيات الذكاء الاصطناعي بتخصيص تجارب التعلم، وعم يؤكدوا إنو ممكن يصمم المحتوى حسب احتياجات الطلاب الفردية، وهالشي كان يعتبر مستحيل من قبل. علاوة على ذلك، تقرير جديد أكد إنو أدوات الذكاء الاصطناعي ممكن تقلل بشكل كبير الأعباء الإدارية على المعلمين، وهالشي بيسمحلهم يركزوا أكتر على تطوير طرق التدريس. مع هيك، المنتقدين ادعوا باستمرار إنو الذكاء الاصطناعي ممكن يزيد من عدم المساواة الموجودة، خصوصاً بخصوص الوصول للتكنولوجيا بالمجتمعات المحرومة. بعض الخبراء اعترفوا إنو بينما الذكاء الاصطناعي بيقدم مزايا لا يمكن إنكارها، تنفيذه لازم يدار بعناية لتجنب عواقب غير مقصودة. النقاش، لهيك، بيركز على كيفية تسخير قوة الذكاء الاصطناعي التحويلية بمسؤولية، لضمان إنو يكون ركيزة أساسية لا غنى عنها بدل ما يكون مصدر إرباك جدلي.", "generated_at": "2026-06-23T23:42:45.852913+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (364, 1, 'reading', 'C1', 'lesson', 'The Digital Paradox: Connection and Isolation', '{"source": "ai_nightly", "passage": "The ubiquitous penetration of digital technology into our daily lives presents a paradoxical conundrum. On the one hand, it has undeniably fostered unprecedented levels of global connectivity; seldom has humanity been so interconnected, enabling instantaneous communication across continents. Be that as it may, this pervasive digital presence often engenders a less desirable outcome: a profound sense of isolation and superficiality in real-world interactions. Social media platforms, for instance, while purporting to build communities, can inadvertently cultivate a culture of comparison and inadequacy, thus eroding genuine human connection.\n\nNeedless to say, the implications for mental well-being are substantial. Were we to truly scrutinize the quality of our online interactions, we would likely discover a marked disparity between perceived and actual intimacy. Furthermore, the constant barrage of information, coupled with the pressure to maintain an idealized online persona, contributes to heightened stress levels and a pervasive sense of FOMO (Fear Of Missing Out). On the flip side, proponents argue that digital tools democratize information and empower marginalized voices, facilitating social movements and fostering a global citizenry. Consequently, navigating this complex landscape necessitates a nuanced understanding of both its promises and its inherent perils. Had we foresight, we might have established clearer societal norms for digital engagement from the outset, thereby mitigating some of the contentious issues we face today.", "title_ar": "المفارقة الرقمية: اتصال وعزلة", "questions": [{"stem": "What is the main paradox discussed in the passage regarding digital technology?", "choices": ["It connects people globally but isolates them locally.", "It provides too much information but too little knowledge.", "It is both expensive and widely accessible.", "It helps social movements but harms personal relationships."], "correct_index": 0}, {"stem": "The phrase \"Had we foresight, we might have established clearer societal norms\" primarily suggests:", "choices": ["A wish for better technology development.", "A regret about past decisions regarding digital integration.", "A recommendation for future social media policies.", "A critique of the current generation''s digital habits."], "correct_index": 1}], "passage_ar": "التغلغل الواسع للتكنولوجيا الرقمية بحياتنا اليومية بيقدم لغز متناقض. من جهة، هي بلا شك عززت مستويات غير مسبوقة من الاتصال العالمي؛ نادراً ما كانت البشرية مترابطة لهالدرجة، وهاد سمح بالتواصل الفوري عبر القارات. مع كل هاد، هالتواجد الرقمي المنتشر غالباً ما بيخلق نتيجة مو مرغوبة كتير: إحساس عميق بالعزلة والسطحية بالتفاعلات بالعالم الحقيقي. منصات التواصل الاجتماعي، مثلاً، مع إنها بتدعي إنها بتبني مجتمعات، ممكن بدون قصد تخلق ثقافة مقارنة ونقص، وبالتالي بتضعف الاتصال الإنساني الحقيقي.\n\nغني عن القول، الآثار على الصحة النفسية كبيرة. لو كنا رح نفحص جودة تفاعلاتنا على الإنترنت بشكل جدي، كنا على الأرجح رح نكتشف فرق كبير بين الألفة المتصورة والألفة الحقيقية. بالإضافة لهيك، السيل المستمر من المعلومات، مع الضغط للحفاظ على شخصية مثالية على الإنترنت، بيساهم بزيادة مستويات التوتر وإحساس منتشر بالخوف من فوات الفرص (FOMO). من الناحية التانية، المؤيدون بيجادلوا إنو الأدوات الرقمية بتديمقرط المعلومات وبتعطي صوت للفئات المهمشة، وبتسهل الحركات الاجتماعية وبتعزز المواطنة العالمية. بالتالي، التنقل بهالمنظر المعقد بيتطلب فهم دقيق لوعودها ومخاطرها الكامنة. لو كان عنا بصيرة، كان ممكن نكون حطينا معايير مجتمعية أوضح للمشاركة الرقمية من البداية، وبالتالي نخفف من بعض القضايا الخلافية اللي عم نواجهها هلأ.", "generated_at": "2026-06-23T23:43:21.587355+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (365, 1, 'reading', 'C1', 'lesson', 'Navigating New Horizons: Challenges and Triumphs of Integration', '{"source": "ai_nightly", "passage": "Integration into a new cultural milieu presents a multifaceted array of challenges and opportunities for newcomers. Not only do they often grapple with linguistic barriers and the complexities of new bureaucratic systems, but they also contend with the subtle nuances of social customs and unspoken rules. Be that as it may, their resilience is frequently remarkable; seldom do we encounter individuals who navigate such profound changes with unwavering determination. Had they not possessed such fortitude, the path to establishing a new life would undoubtedly be fraught with insurmountable obstacles.\n\nThe economic landscape, too, poses significant hurdles. Many skilled professionals find their qualifications unrecognized, leading to underemployment or protracted periods of joblessness. On the flip side, their diverse perspectives and unique skill sets can be invaluable assets, enriching the host society and fostering innovation. Consequently, governments and community organizations are increasingly implementing programs designed to mitigate these disparities, though the efficacy of such initiatives remains a contentious topic. Needless to say, successful integration hinges upon a reciprocal effort: the willingness of immigrants to adapt and the commitment of the host society to be inclusive. Were both parties to fully embrace this ethos, the benefits would be manifold, yielding a more vibrant and cohesive societal fabric for all.", "title_ar": "التنقل بآفاق جديدة: تحديات وانتصارات الاندماج", "questions": [{"stem": "What is highlighted as a significant challenge for skilled professionals integrating into a new country?", "choices": ["Lack of community support.", "Unrecognized qualifications leading to underemployment.", "Difficulty in learning the local language quickly.", "High cost of living in the new environment."], "correct_index": 1}, {"stem": "The passage suggests that successful integration primarily depends on:", "choices": ["The government''s ability to create effective programs.", "The financial resources available to new immigrants.", "A mutual commitment from both immigrants and the host society.", "The strength of the immigrant''s family network."], "correct_index": 2}], "passage_ar": "الاندماج ببيئة ثقافية جديدة بيقدم مجموعة متعددة الأوجه من التحديات والفرص للقادمين الجدد. مو بس غالباً ما بيعانوا من حواجز لغوية وتعقيدات الأنظمة البيروقراطية الجديدة، بل بيواجهوا كمان التفاصيل الدقيقة للعادات الاجتماعية والقواعد غير المعلنة. مع كل هاد، مرونتهم غالباً ما بتكون ملفتة؛ نادراً ما بنصادف أفراد بيتكيفوا مع هيك تغييرات عميقة بعزيمة لا تتزعزع. لو ما كانوا بيمتلكوا هيك قوة، كان طريق تأسيس حياة جديدة بلا شك مليان عقبات مستحيلة.\n\nالمشهد الاقتصادي كمان بيطرح عقبات كبيرة. كتير من المهنيين المهرة بيلاقوا مؤهلاتهم مو معترف فيها، وهاد بيؤدي لتوظيف أقل من المستوى المطلوب أو فترات بطالة طويلة. من الناحية التانية، وجهات نظرهم المتنوعة ومجموعات مهاراتهم الفريدة ممكن تكون أصول لا تقدر بثمن، بتغني المجتمع المضيف وبتعزز الابتكار. بالتالي، الحكومات والمنظمات المجتمعية عم بتطبق بشكل متزايد برامج مصممة للتخفيف من هالتباينات، مع إنو فعالية هيك مبادرات بتضل موضوع خلاف. غني عن القول، الاندماج الناجح بيعتمد على جهد متبادل: رغبة المهاجرين بالتكيف والتزام المجتمع المضيف بالشمولية. لو الطرفين تبنوا هالأخلاق بشكل كامل، كانت الفوائد رح تكون متعددة، وبتنتج نسيج مجتمعي أكتر حيوية وتماسك للكل.", "generated_at": "2026-06-23T23:43:21.587355+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (331, 1, 'speaking', 'B2', 'speaking_prompt', 'Adapting to Direct Corporate Feedback', '{"topic": "career", "prompt": "Discuss the challenges international professionals encounter when adapting to a direct corporate feedback culture. How can companies support employees from indirect communication backgrounds?", "title_ar": "التأقلم مع النقد المباشر بالشركات", "prompt_ar": "ناقش التحديات يلي بيواجهوها الموظفين الأجانب لما يضطروا يتأقلموا مع ثقافة النقد المباشر بالشركات. كيف فيها الشركات تدعم الموظفين يلي جايين من خلفيات بتعتمد ع التواصل غير المباشر؟", "min_seconds": 60, "question_type": "discuss", "example_answer": "Adapting to a direct feedback culture can be incredibly challenging for international professionals who are accustomed to indirect communication. In many Central European corporate environments, constructive criticism is delivered quite bluntly, which newcomers might initially misconstrue as personal hostility or a lack of respect. To mitigate this systemic friction, corporate leaders should implement specialized cross-cultural workshops during the initial onboarding phase. These training modules can help clarify that unvarnished critique is meant to optimize performance rather than attack individual capabilities. Furthermore, creating a mentorship framework allows experienced colleagues to guide new recruits, fostering a psychologically safe environment where cognitive diversity is actively valued as a significant corporate asset."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (332, 1, 'speaking', 'B2', 'speaking_prompt', 'Public Transit Ticket Subsidies', '{"topic": "public transport", "prompt": "Express your opinion on whether city municipalities should heavily subsidize public transit tickets. Address how this impacts environmental concerns and municipal budget deficits.", "title_ar": "دعم تكتات المواصلات العامة", "prompt_ar": "عطينا رأيك إذا كان لازم البلديات تدعم تكتات المواصلات العامة بشكل كبير. احكي كيف هاد الشي بيأثر ع المخاوف البيئية وعجز الميزانية بالبلدية.", "min_seconds": 60, "question_type": "opinion", "example_answer": "In my opinion, city municipalities should definitely prioritize the heavy subsidization of public transit tickets. Introducing affordable monthly transit passes is an excellent strategy to incentivize residents to utilize trains and buses instead of private automobiles. This policy directly addresses mounting environmental concerns, drastically reducing traffic congestion and urban carbon emissions. However, we cannot ignore that extensive subsidies frequently lead to severe municipal budget deficits, making it challenging to upgrade ancient subway networks. To balance this structural bottleneck, federal governments should allocate substantial ecological grants to regional councils, ensuring that clean, zero-emission urban mobility infrastructure remains financially sustainable on the long term."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (333, 1, 'speaking', 'B2', 'speaking_prompt', 'The Urban Housing Scarcity', '{"topic": "current events", "prompt": "Describe the current urban housing scarcity in major European cities and its specific socio-economic impacts on international students and young professionals.", "title_ar": "أزمة السكن بالمدن الكبيرة", "prompt_ar": "اوصف أزمة قلة البيوت الحالية بالمدن الأوروبية الكبيرة وتأثيراتها الاقتصادية والاجتماعية المعينة ع الطلاب الأجانب والشباب يلي مبلشين شغل جديد.", "min_seconds": 60, "question_type": "describe", "example_answer": "The acute shortage of affordable accommodation in major metropolitan areas has generated severe social unrest recently. As speculative real estate investments and rapid demographic shifts cause monthly rental prices to skyrocket, young professionals and international students find themselves entirely priced out of the market. This systemic housing scarcity forces individuals to settle for substandard living conditions far from their universities or workplaces, directly disrupting their daily commuting routine. Moreover, the fierce competition for shared flats or ''WGs'' creates immense psychological stress. Without strict government interventions, such as effective rent caps and extensive investments in public social housing, modern urban centers risk losing their cultural and socio-economic diversity entirely."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (334, 1, 'speaking', 'B2', 'speaking_prompt', 'Transitioning to Paperless Bureaucracy', '{"topic": "bureaucracy", "prompt": "Discuss the advantages and disadvantages of converting physical migration offices into centralized digital registration portals. Consider administrative backlogs and technological barriers.", "title_ar": "التحول الرقمي بالمعاملات الرسمية", "prompt_ar": "ناقش ميزات وسلبيات تحويل مكاتب الإقامة والاجانب الحقيقية لمنصات تسجيل رقمية مركزية أونلاين. فكر بتراكم المعاملات وبالعوائق التكنولوجية.", "min_seconds": 60, "question_type": "discuss", "example_answer": "Transitioning to paperless digital bureaucracy portals offers a brilliant solution to the immense administrative backlog currently overwhelming physical migration offices. Streamlining the application process allows international candidates to upload essential rental contracts and passport documents directly from home, substantially reducing waiting times. However, a major disadvantage is that this automated shift creates insurmountable technological barriers for vulnerable migrants who lack advanced digital literacy. If centralized software is implemented without thorough cross-cultural usability testing, it inadvertently hinders the initial social integration of newcomers. Therefore, municipal councils must maintain decentralized in-person support desks alongside modern interfaces to guarantee equitable access for everyone."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (335, 1, 'speaking', 'B2', 'speaking_prompt', 'Capitalizing on Urban Green Spaces', '{"topic": "global issues", "prompt": "State your perspective on whether expanding urban green infrastructure is an indispensable asset for modern cities facing global climate change challenges.", "title_ar": "الاستثمار بالمساحات الخضراء بالمدن", "prompt_ar": "قولنا شو نظرتك ورأيك إذا كان توسيع البنية التحتية الخضراء بالمدن عنصر ما فينا نستغني عنه للمدن الحديثة يلي عم تواجه تحديات التغير المناخي العالمي.", "min_seconds": 60, "question_type": "opinion", "example_answer": "From my perspective, expanding urban green infrastructure is an indispensable asset for combatting global climate change in densely built environments. Metropolises worldwide frequently suffer from the urban heat island effect, where concrete surfaces absorb solar radiation, causing summer temperatures to skyrocket. Implementing deliberate ecological interventions, such as expanding public parks and enforcing strict green roof mandates, functions as a natural cooling mechanism that reduces surface temperatures significantly. Furthermore, urban vegetation plays a critical role in managing stormwater during torrential rainfall, reducing the immense pressure on ancient sewage systems. Investing in these sustainable architecture paradigms is fundamental for preserving public health and ensuring urban structural viability."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (336, 1, 'speaking', 'B2', 'speaking_prompt', 'The Multi-Track School System Debate', '{"topic": "education systems", "prompt": "Analyze the debate surrounding early academic tracking in multi-track secondary school systems. Discuss how this structure affects socio-economic mobility and international students.", "title_ar": "نظام تقسيم الطلاب بالمدارس الثانوية", "prompt_ar": "حلل النقاش الدائر حول تقسيم الطلاب الأكاديمي المبكر بأنظمة المدارس الثانوية متعددة المسارات. ناقش كيف هاد الهيكل بيأثر ع الحركة الاجتماعية والاقتصادية وعلى الطلاب الأجانب.", "min_seconds": 60, "question_type": "discuss", "example_answer": "The debate surrounding early academic tracking in multi-track secondary school systems focuses heavily on equity and specialization. Proponents argue that sorting children early effectively cultivates a highly specialized workforce by separating academic paths from practical vocational training. However, critics fiercely point out that this rigid structure severely limits future socio-economic mobility. Sociologists have proven that international children are disproportionately directed away from university-bound tracks due to early linguistic barriers. If educational ministries introduced a more integrated, flexible secondary curriculum, students would be allowed to pivot between academic streams and apprenticeships much later in their personal development, thereby minimizing the higher education disparity."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (337, 1, 'speaking', 'B2', 'speaking_prompt', 'Civic Engagement and Integration', '{"topic": "culture", "prompt": "Describe how civic engagement and participating in volunteer-led community initiatives can accelerate the linguistic and social integration of newly arrived immigrants.", "title_ar": "دور الشغل التطوعي بالاندماج الاجتماعي", "prompt_ar": "اوصف كيف المشاركة المدنية والانخراط بالمبادرات المجتمعية التطوعية فيها تسرع الاندماج اللغوي والاجتماعي للمهاجرين يلي واصلين جديد.", "min_seconds": 60, "question_type": "describe", "example_answer": "Civic engagement plays an invaluable role in facilitating the long-term social integration of newly arrived immigrants. Neighborhood institutions, such as local community centers, heavily rely on volunteer networks to operate free language cafes, legal advice clinics, and intercultural workshops. These grassroots initiatives provide a safe space where residents can engage in open dialogue, effectively dismantling mutual prejudices and social boundaries. Recent sociological studies demonstrate that migrants who actively participate in these volunteer programs exhibit a significantly stronger sense of belonging and civic responsibility. Fostering an inclusive society requires continuous structural and financial support for these vital civic networks to bridge cultural differences."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (338, 1, 'speaking', 'B2', 'speaking_prompt', 'Privacy Boundaries of Electronic Health Systems', '{"topic": "healthcare", "prompt": "Express your opinion on the mandatory implementation of digital patient records. Do the automated clinical efficiencies outweigh potential vulnerabilities to cyberattacks and surveillance?", "title_ar": "حدود الخصوصية بالسجلات الطبية الرقمية", "prompt_ar": "عطينا رأيك بفرز وتطبيق السجلات الطبية الرقمية الإجبارية. هل الكفاءة الطبية والمؤتمتة بتغلب الثغرات المحتملة قدام الهجمات الإلكترونية والمراقبة؟", "min_seconds": 60, "question_type": "opinion", "example_answer": "In my opinion, while the implementation of standardized digital patient records offers clear automated clinical efficiencies, we must critically evaluate data protection boundaries. Centralized electronic networks undoubtedly optimize emergency treatments by enabling specialists to access vital medical histories instantly, thereby preventing dangerous medication errors. However, privacy advocates express valid, grave concerns regarding the vulnerability of these vast databases to sophisticated cyberattacks and unauthorized corporate surveillance. Sensitive diagnostic records must be safeguarded with advanced encryption to ensure absolute patient confidentiality. Clinical efficiency should never compromise individual privacy rights; hence, health ministries must enforce rigorous security regulations to maintain public trust in digital healthcare systems."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (339, 1, 'speaking', 'B2', 'speaking_prompt', 'Automated Screening in Corporate Hiring', '{"topic": "job applications", "prompt": "Discuss the ethical challenges of utilizing automated screening software during job application stages. How can human resource departments prevent algorithmic discrimination?", "title_ar": "برامج الفرز المؤتمتة بتوظيف الشركات", "prompt_ar": "ناقش التحديات الأخلاقية لاستخدام برامج الفرز المؤتمتة خلال مراحل التقديم على شغل. كيف فيها أقسام الموارد البشرية تمنع التمييز الخوارزمي؟", "min_seconds": 60, "question_type": "discuss", "example_answer": "Utilizing automated screening software during initial job application stages introduces severe ethical challenges that corporate boards must address. Although these algorithms are marketed as objective tools designed to eliminate human bias, they frequently replicate systemic discrimination because they are trained on historical datasets reflecting existing corporate imbalances. Consequently, qualified candidates with foreign-sounding names or non-traditional educational backgrounds are often automatically filtered out. To prevent this recruitment bottleneck, human resource departments must critically audit algorithmic selection criteria. Furthermore, employment laws should mandate anonymized application procedures universally, forcing recruitment systems to focus purely on professional competencies and ensure equitable opportunities for global talent."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (345, 1, 'speaking', 'C1', 'speaking_prompt', 'The Ontological Value of Architectural Heritage', '{"topic": "philosophy", "prompt": "Evaluate the philosophical argument that historical architectural structures possess an ontological value that transcends their speculative real estate commodity worth within modernized urban landscapes.", "title_ar": "القيمة الوجودية للإرث المعماري", "prompt_ar": "قيم الحجة الفلسفية يلي بتقول إنه البنايات المعمارية التاريخية بتملك قيمة وجودية بتتخطى قيمتها التجارية والمادية بأسواق العقارات والمضاربات بقلب المدن الحديثة.", "min_seconds": 90, "question_type": "opinion", "example_answer": "I strongly subscribe to the philosophical notion that historical architecture embodies an irreplaceable ontological value essential for communal identity. In an era dominated by hyper-rapid urbanization and homogenized corporate landscapes, ancient buildings provide a tangible material link to our collective memory. It is this profound grounding capacity that renders preservation efforts culturally imperative. What contemporary city planners must embrace is the paradigm of adaptive reuse, thereby synthesizing historic preservation with functional utility, rather than demolishing historic quarters for high-density, lucrative commercial developments."}', NULL, 4, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (340, 1, 'speaking', 'B2', 'speaking_prompt', 'The Impact of Demographic Shifts on Workplaces', '{"topic": "society", "prompt": "Describe the impact of aging demographics in Western Europe on corporate workforce strategies. Mention the importance of lifelong learning and intergenerational collaboration.", "title_ar": "تأثير التحولات الديموغرافية عأماكن الشغل", "prompt_ar": "اوصف تأثير شيخوخة السكان بأوروبا الغربية على استراتيجيات العمال بالشركات. اذكر أهمية التعليم مدى الحياة والتعاون بين الأجيال المختلفة.", "min_seconds": 60, "question_type": "describe", "example_answer": "The aging demographic profile of Western Europe is currently forcing corporate enterprises to radically restructure their workforce management strategies. As a substantial portion of experienced employees approaches traditional retirement age, industries face an unprecedented loss of institutional knowledge and technical expertise. To counter this impending deficit, human resource departments are developing innovative lifelong learning programs aimed at keeping older workers integrated while simultaneously training younger recruits. Businesses are also implementing ergonomic modifications in the physical workplace to accommodate an older demographic. Ultimately, navigating this structural shift depends on cultivating a workplace culture that highly values intergenerational collaboration, ensuring that generational diversity is celebrated as a productive economic asset."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (341, 1, 'speaking', 'C1', 'speaking_prompt', 'Interdisciplinary Research Paradigm Shifts', '{"topic": "academic research", "prompt": "Discuss the administrative and structural impediments that contemporary academic institutions face when attempting to integrate interdisciplinary research methodologies into traditionally compartmentalized departments.", "title_ar": "تحولات نموذج الأبحاث العابرة للتخصصات", "prompt_ar": "ناقش العوائق الإدارية والهيكلية يلي عم تواجهها المؤسسات الأكاديمية بالوقت الحالي لما تحاول تدمج مناهج الأبحاث العابرة للتخصصات بقلب الأقسام المنعزلة والتقليدية.", "min_seconds": 90, "question_type": "discuss", "example_answer": "What contemporary higher education systems struggle with is the deeply entrenched departmental inertia. Seldom do conventional funding allocation bodies prioritize cross-disciplinary ventures, preferring instead to evaluate speculative projects through rigid, outdated metrics. Consequently, it is this institutional friction that inadvertently stifles academic innovation. To mitigate this systemic bottleneck, progressive European universities are pioneering integrated support structures. Not only do these initiatives streamline the administrative labyrinth, but they also cultivate cognitive diversity as a core intellectual asset, ensuring long-term institutional viability."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (342, 1, 'speaking', 'C1', 'speaking_prompt', 'The Epistemological Impact of Algorithmic Curation', '{"topic": "media literacy", "prompt": "Express your opinion on the societal ramifications of algorithmic content curation on corporate digital platforms, specifically focusing on how it fractures public discourse into hyper-partisan echo chambers.", "title_ar": "التأثير المعرفي للتوجيه الخوارزمي", "prompt_ar": "عطينا رأيك بالعواقب المجتمعية لتوجيه المحتوى عبر الخوارزميات بالمنصات الرقمية الكبيرة، وركز بشكل خاص على كيف عم يقسم النظرة والنقاش العام لغرف صدى منغلقة ومتعصبة كتير.", "min_seconds": 90, "question_type": "opinion", "example_answer": "In my perspective, the pervasive influence of algorithmic curation has precipitated an unprecedented epistemological crisis. Only when European regulatory bodies enforce stringent oversight on these corporate digital platforms will we see a substantive reduction in malicious disinformation. It is the underlying commercial architecture, designed to maximize user engagement at the expense of factual accuracy, that systematically erodes public trust. Therefore, universal implementation of comprehensive media literacy frameworks is not merely advisable but fundamentally mandatory for cultivating cognitive resilience."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (343, 1, 'speaking', 'C1', 'speaking_prompt', 'Implementing Circular Economic Ecosystems', '{"topic": "business strategy", "prompt": "Describe the strategic adjustments a traditional manufacturing corporation must execute to transition effectively from a linear model to a circular economic framework predicated on product stewardship.", "title_ar": "تطبيق أنظمة الاقتصاد الدائري", "prompt_ar": "اوصف التعديلات الاستراتيجية يلي لازم تنفذها شركات الإنتاج التقليدية لتنتقل بشكل فعال من النموذج الخطي لإطار الاقتصاد الدائري القائم على المسؤولية ورعاية المنتج.", "min_seconds": 90, "question_type": "describe", "example_answer": "Transitioning toward a circular economic framework necessitates a comprehensive re-engineering of the entire corporate ecosystem. Rarely can a firm achieve systemic sustainability through superficial operational adjustments alone; rather, products must be designed to be entirely modular and recyclable from their very inception. Furthermore, enterprises are forced to restructure consumer relationships, pivoting from outright asset ownership to long-term stewardship models. Under current macroeconomic conditions, managing short-term quarterly financial pressures while prioritizing long-term ecological viability represents a formidable strategic challenge."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (344, 1, 'speaking', 'C1', 'speaking_prompt', 'The Jurisprudence of the Right to Disconnect', '{"topic": "law", "prompt": "Discuss the legislative complexities of enforcing ''right to disconnect'' mandates within fluid, transnational corporate environments that operate across multiple time zones.", "title_ar": "الفقه القانوني للحق بفصل الاتصال", "prompt_ar": "ناقش التعقيدات التشريعية لتطبيق قوانين ''الحق بفصل الاتصال'' ببيئات الشركات المرنة والعابرة للقارات يلي بتشتغل عبر كذا توقيت زمني.", "min_seconds": 90, "question_type": "discuss", "example_answer": "Enforcing statutory right to disconnect mandates within highly fluid corporate environments represents an intricate jurisdictional puzzle. While digital connectivity offers unprecedented operational flexibility, it simultaneously fosters an insidious culture of constant availability, systematically blurring the boundary between professional duties and personal leisure. Were international labor organizations to establish unified, enforceable employment standards, cross-border exploitation could be effectively neutralized. Ultimately, what legal scholars contend is that localized regulations remain insufficient unless paired with a profound cultural shift that treats uninterrupted rest as an absolute human right."}', NULL, 3, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (351, 1, 'speaking', 'C2', 'speaking_prompt', 'The Fiscal Architecture of the Eurozone', '{"topic": "economics", "prompt": "Critically analyze the macroeconomic stability of a currency union that executes a unified monetary policy without an underlying fiscal unification. Discuss the ramifications of internal deflation on public infrastructure and how ideological divides shape political impasses regarding joint debt instruments.", "title_ar": "الهيكل المالي لمنطقة اليورو", "prompt_ar": "حلل بشكل نقدي الاستقرار المالي الكلي لاتحاد عملة عم يطبق سياسة نقدية موحدة من دون ما يكون في توحيد مالي حقيقي بأساسه. شو رأيك بعواقب الانكماش الداخلي ع البنية التحتية العامة، وشلون عم تشكل الانقسامات الفكرية طرق مسدودة بالسياسة بخصوص أدوات الديون المشتركة هلق؟", "min_seconds": 120, "question_type": "discuss", "example_answer": "The structural architecture of the Eurozone represents an extraordinarily audacious macroeconomic experiment, yet it remains fundamentally hamstrung by a systemic asymmetry: the implementation of a unified monetary policy absent a corresponding fiscal unification. When sovereign states relinquish control over their domestic monetary instruments—specifically the capacity to manipulate interest rates or devalue currency to absorb macroeconomic shocks—they render themselves uniquely vulnerable to asymmetric economic downturns. In the conspicuous absence of a centralized fiscal treasury capable of executing counter-cyclical budgetary transfers, distressed member states are forced to rely almost exclusively upon internal deflation and stringent fiscal austerity to claw back international competitiveness. This structural dynamic frequently ignites severe socio-economic crises, as the burden of adjustment falls disproportionately upon public infrastructure, social welfare networks, and employment metrics. A monetary union cannot achieve long-term equilibrium without robust mechanisms for fiscal risk-sharing, such as a permanent common budget or the issuance of joint sovereign debt instruments. However, the path toward deeper fiscal integration is bitterly contested by national electorates, polarizing the continent along historical geopolitical and ideological fault lines. Wealthier core nations routinely express profound anxiety regarding the moral hazard of subsidizing structurally weaker economies, fearing a permanent transfer union would completely disincentivize domestic structural reforms. Conversely, peripheral nations contend that the current framework systematically favors export-driven core economies, thereby exacerbating structural imbalances across the single market. Ultimately, the survival of the currency union hinges upon a political consensus that transcends localized electoral calculations, demonstrating that macroeconomic integration cannot endure without deep political alignment."}', NULL, 0, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (352, 1, 'speaking', 'C2', 'speaking_prompt', 'Algorithmic Determinism and Individualized Justice', '{"topic": "ethics", "prompt": "Evaluate the ethical implications of proliferating automated decision-making protocols within public administration. Discuss how historical datasets reify discrimination and whether delegating moral evaluations to code completely absolves human actors of accountability.", "title_ar": "الحتمية الخوارزمية والعدالة الفردية", "prompt_ar": "قيم الأبعاد الأخلاقية لانتشار بروتوكولات اتخاذ القرار المؤتمتة بقلب الدوائر الحكومية هلق. شلون عم تشكل البيانات التاريخية أداة لتثبيت التمييز الممنهج، وهل برأيك تفويض التقييمات الأخلاقية المعقدة لأكواد برمجية عم يعفي الأشخاص تماماً من المسؤولية والمحاسبة؟", "min_seconds": 120, "question_type": "opinion", "example_answer": "The contemporary proliferation of automated decision-making systems within public administration and judicial frameworks has catalyzed a profound paradigm shift in how modern societies conceptualize moral agency and constitutional rights. Utilizing predictive analytics and complex machine-learning models, institutions increasingly rely on algorithms to assess variables ranging from recidivism risks in criminal sentencing to eligibility criteria for social housing and welfare distributions. While proponents aggressively champion these technologies as emblems of mathematical objectivity capable of purging human bias from administrative processes, a more meticulous examination uncovers systemic discrimination deliberately reified and obscured under a veneer of computational neutrality. Because these proprietary algorithms are trained on historical datasets that inherently reflect deeply entrenched societal inequalities, their predictive outputs invariably perpetuate those exact structural disparities, transforming past prejudices into predictive certainty. This phenomenon, which can be defined as algorithmic determinism, systematically erodes the foundational legal principle of individualized justice, replacing nuanced human evaluation with reductionist probabilistic categorization. Furthermore, the opaque, unmapped ''black-box'' nature of advanced machine-learning protocols creates an insurmountable epistemic barrier that completely undermines democratic accountability and administrative transparency. When a citizen is denied a fundamental constitutional right or benefit based on an automated scoring system, tracing the specific underlying logic behind that decision becomes virtually impossible, thereby effectively neutralizing the legal right to appeal or challenge administrative overreach. By abdicating complex moral evaluations to automated code, society risks entirely absolving human actors of ethical accountability while institutionalizing a form of technocratic governance that prioritizes computational efficiency over human dignity."}', NULL, 1, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (353, 1, 'speaking', 'C2', 'speaking_prompt', 'Kafkaesque Resonances in Transnational Prose', '{"topic": "literature analysis", "prompt": "Narrate an analysis of how contemporary European transnational literature utilizes an aesthetics of estrangement. Detail how administrative spaces are transformed into modern iterations of Kafka''s ''The Castle'' to depict the psychological trauma of legal suspension.", "title_ar": "الأصداء الكافكاوية بالنثر العابر للحدود", "prompt_ar": "احكيلنا تحليل مفصل عن شلون الأدب المعاصر العابر للحدود بأوروبا عم يستخدم جماليات الاغتراب هلق. وضح شلون عم تتحول المساحات الإدارية لنسخ حديثة من رواية ''القلعة'' لكافكا لتصوّر الصدمة النفسية لحالة التعليق القانوني للإقامة.", "min_seconds": 120, "question_type": "narrate", "example_answer": "The contemporary corpus of transnational literature emerging from the European migrant experience frequently deploys an aesthetics of estrangement to rigorously interrogate the labyrinthine and oppressive structures of state bureaucracy. Literary analysts observe that modern authors systematically move beyond conventional, linear migration narratives, which typically center on simplistic cultural assimilation or superficial linguistic friction. Instead, these highly sophisticated texts articulate a profound existential dislocation by drawing explicit structural and thematic parallels to the surreal, menacing architectures found across Franz Kafka’s seminal oeuvre. In these narratives, the municipal immigration office, the isolated asylum accommodation center, and the rigid judicial courtroom are transfigured into contemporary iterations of Kafka''s The Castle—spaces fundamentally defined by arbitrary regulatory shifts, invisible authorities, and seemingly infinite procedural delays. The protagonist''s journey is characterized by a perpetual ontological suspension, wherein their legal identity, human rights, and very temporal existence are governed by an inaccessible administrative machinery. By utilizing highly stylized prose, fragmented narrative structures, and magical realist disruptions, these authors meticulously deconstruct the deep psychological trauma inflicted by systemic bureaucratic alienation. The text becomes a potent hermeneutic mirror, reflecting how the modern state utilizes complex paperwork, linguistic mistranslations, and shifting legislative mandates as deliberate instruments of socio-political containment. Consequently, this literary subgenre serves as a devastating epistemological critique of Western integration discourses, exposing the violence implicit in structural demands for absolute cultural compliance. Through the radical subversion of standard narrative conventions, transnational literature challenges readers to confront the institutional absurdities that reduce lived human experiences to static administrative files, thereby reaffirming the novel as a vital space for political critique and existential resistance."}', NULL, 2, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (346, 1, 'speaking', 'C1', 'speaking_prompt', 'Resource Realignment in Post-Carbon Markets', '{"topic": "geopolitics", "prompt": "Describe how the global transition toward renewable energy infrastructures orchestrates a profound geopolitical realignment, exposing Europe''s strategic vulnerabilities concerning critical mineral supply chains.", "title_ar": "إعادة توزيع الموارد بأسواق ما بعد الكربون", "prompt_ar": "اوصف كيف التحول العالمي نحو البنى التحتية للطاقة المتجددة عم يعمل إعادة تموضع جيوسياسي عميق، وعم يكشف نقاط ضعف أوروبا الاستراتيجية بسلاسل توريد المعادن الحساسة.", "min_seconds": 90, "question_type": "describe", "example_answer": "The transition away from fossil fuels is orchestrating an unprecedented geopolitical realignment, fundamentally redefining state sovereignty. For decades, international relations were heavily dominated by hydrocarbon protection, but power is now shifting decisively toward nations controlling critical rare earth minerals. What constitutes a critical vulnerability for the European Union is its absolute reliance on foreign jurisdictions for mineral extraction and processing. Were Europe to establish decentralized domestic mining and robust recycling frameworks, its strategic independence against geopolitical bottlenecks would be substantively reinforced."}', NULL, 5, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (347, 1, 'speaking', 'C1', 'speaking_prompt', 'Linguistic Hybridity and Socio-Cultural Capital', '{"topic": "integration", "prompt": "Discuss how fluid code-switching and mixed linguistic practices among second-generation diasporic communities function as sophisticated socio-cultural capital, despite the institutional pathologization by standard education systems.", "title_ar": "الهوية اللغوية الهجينة ورأس المال الثقافي", "prompt_ar": "ناقش كيف التبديل اللغوي المرن والممارسات اللغوية المخلطة عند مجتمعات الجيل الثاني من المغتربين بتشتغل كرأس مال اجتماعي وثقافي متطور، رغم النظرة السلبية والتعامل المرضي للمؤسسات التعليمية الرسمية مع هي الحالات.", "min_seconds": 90, "question_type": "discuss", "example_answer": "Contemporary sociolinguistic research clearly indicates that linguistic hybridity represents a highly sophisticated communicative competence rather than a structural deficiency. It is this multi-layered flexibility that empowers individuals to navigate distinct cultural spheres fluidly, maximizing their professional networking opportunities. What complicates this dynamic is the deep-seated institutional rigidity of pedagogical frameworks, which pathologize code-switching during professional examinations. Only by validating diverse communicative repertoires as authentic cognitive assets can educational systems effectively challenge the systemic marginalization of international students."}', NULL, 6, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (348, 1, 'speaking', 'C1', 'speaking_prompt', 'Digitalization of Administrative Systems and Inclusion', '{"topic": "bureaucracy", "prompt": "Express your perspective on the administrative shift toward centralized paperless registration portals in municipal migration offices, weighing efficiency gains against technological barriers for vulnerable populations.", "title_ar": "رقمنة الأنظمة الإدارية والاندماج", "prompt_ar": "عطينا نظرتك ورأيك بالتحول الإداري نحو منصات التسجيل الرقمية المركزية وبلا أوراق بمكاتب الإقامة والأجانب، ووازن بين مكاسب الكفاءة والعوائق التكنولوجية بوش الفئات الضعيفة.", "min_seconds": 90, "question_type": "opinion", "example_answer": "While the migration toward centralized digital platforms undoubtedly streamlines procedures and reduces the immense administrative backlog, it concurrently introduces significant socio-political hazards. Seldom do tech developers incorporate thorough cross-cultural usability testing prior to software deployment, which inadvertently creates insurmountable barriers for vulnerable migrants lacking digital literacy. In my view, administrative efficiency must never supersede equitable access. Therefore, municipal councils are legally and ethically obligated to sustain decentralized, in-person counseling infrastructure alongside modern paperless interfaces to preserve civic integration."}', NULL, 7, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (349, 1, 'speaking', 'C1', 'speaking_prompt', 'Socio-Economic Stratification in Early Academic Tracking', '{"topic": "school system", "prompt": "Discuss the structural consequences of early academic tracking in multi-track secondary education systems, focusing on how it reinforces socio-economic stratification and disproportionately impacts students from migrant backgrounds.", "title_ar": "الطبقية الاقتصادية والاجتماعية بالتقسيم الأكاديمي البكير", "prompt_ar": "ناقش العواقب الهيكلية للتقسيم الأكاديمي المبكر بأنظمة التعليم الثانوي متعددة المسارات، وركز على كيف هاد السيستم عم يثبت الطبقية الاجتماعية والاقتصادية وبيأثر بشكل غير عادل ع الطلاب من خلفيات مهاجرة.", "min_seconds": 90, "question_type": "discuss", "example_answer": "Early academic tracking within multi-track secondary systems frequently exacerbates systemic socio-economic stratification. It is this structural sorting at a premature stage of development that disproportionately directs international students away from university-bound tracks due to initial linguistic barriers. Educational researchers observe that the framework operates as an institutional mechanism of exclusion, reinforcing historical prestige rather than cultivating potential. Were secondary school curricula more comprehensively integrated, students would possess the flexibility to pivot between vocational and academic pathways fluidly as their competencies mature."}', NULL, 8, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (350, 1, 'speaking', 'C1', 'speaking_prompt', 'Data Protection Boundaries in Centralized Medical Records', '{"topic": "healthcare", "prompt": "Express your opinion on whether the clinical optimization provided by standardized electronic health records justifies the systemic vulnerabilities regarding unauthorized data surveillance and cyberattacks.", "title_ar": "حدود حماية البيانات بالسجلات الطبية المركزية", "prompt_ar": "عطينا رأيك إذا كان التحسين الطبي والمثالي يلي بتقدمه السجلات الصحية الإلكترونية الموحدة بيبرر الثغرات الممنهجة يلي عم تعملها بخصوص المراقبة غير المصرح فيها للبيانات والهجمات الإلكترونية.", "min_seconds": 90, "question_type": "opinion", "example_answer": "In my estimation, the clinical advantages of standardized digital health records, such as minimizing catastrophic medication errors, cannot justify the systematic erosion of patient privacy boundaries. Under no circumstances should highly sensitive diagnostic data be concentrated into vulnerable central repositories without implementing absolute encryption architectures. What privacy advocates rightly emphasize is the profound threat of unauthorized corporate surveillance and commercial exploitation. Unless statutory regulations guarantee rigorous, independent data protection auditing, public trust in the integrity of modern healthcare infrastructure will inevitably collapse."}', NULL, 9, true, '2026-06-23 04:29:17.972515+08');
INSERT INTO public.language_content_items VALUES (368, 1, 'listening', 'B2', 'lesson', 'The Debate on Artificial Intelligence in Education', '{"source": "ai_nightly", "title_ar": "النقاش حول الذكاء الصناعي بالتعليم", "questions": [{"stem": "What is Sarah''s main point about AI in education?", "choices": ["She believes AI is a controversial but viable solution for all educational aspects.", "She thinks AI is indispensable for personalized learning but has limitations.", "She argues that AI will inevitably replace human teachers.", "She is entirely convinced that AI algorithms can foster creativity."], "correct_index": 1}, {"stem": "What is Mark''s primary concern regarding the extensive use of AI in education?", "choices": ["He is worried about the high cost of implementing AI technology.", "He believes AI is not capable of personalizing learning effectively.", "He fears it could diminish critical thinking skills and social interaction by reducing the human element.", "He thinks AI is not controversial enough to warrant careful consideration."], "correct_index": 2}], "generated_at": "2026-06-23T23:44:19.339697+00:00", "instructions": "Listen to the discussion about Artificial Intelligence in education and answer the questions.", "audio_transcript": "Welcome to our discussion on the role of Artificial Intelligence in education. Sarah, you''ve been researching this extensively; what are your initial thoughts?\nSarah: Well, on the one hand, I tend to agree with those who see AI as an indispensable tool for personalized learning. It seems that AI algorithms can effectively tailor content to individual student needs, which is quite promising for improving engagement. Nevertheless, I''m not entirely convinced it''s a viable solution for every aspect of education, especially when it comes to fostering creativity.\nMark: I see your point, Sarah. I, however, respectfully disagree with the notion that it''s indispensable. While it certainly offers some benefits, I firmly believe the human element – the teacher''s emotional intelligence and ability to inspire – remains absolutely crucial. Consequently, relying too heavily on AI could inadvertently lead to a potential loss of critical thinking skills and social interaction. It''s undeniably a controversial topic, and we must proceed with caution.\nSarah: Indeed, Mark. It''s fundamentally about finding a sensible balance, isn''t it? Perhaps AI could primarily support teachers, rather than aiming to replace them entirely. It seems that''s where the growing consensus lies for many forward-thinking educators."}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (369, 1, 'listening', 'B2', 'lesson', 'Sustainable Urban Development: A Future Necessity', '{"source": "ai_nightly", "title_ar": "التطوير الحضري المستدام: ضرورة للمستقبل", "questions": [{"stem": "What is presented as an \"indispensable\" element for enhancing city dwellers'' quality of life?", "choices": ["The initial cost of sustainable initiatives.", "The promotion of public transportation and creation of green spaces.", "The economic benefits of urban development.", "The analysis of current global trends."], "correct_index": 1}, {"stem": "What is the speaker''s overall conclusion about integrating ecological principles into urban design?", "choices": ["It is an expensive option that few cities can afford.", "It is a necessity for future generations.", "It is a controversial topic with no clear consensus.", "It primarily focuses on mitigating the impacts of economic challenges."], "correct_index": 1}], "generated_at": "2026-06-23T23:44:19.339697+00:00", "instructions": "Listen to the presentation on sustainable urban development and answer the questions.", "audio_transcript": "Good morning, everyone. Allow me to elaborate on the crucial topic of sustainable urban development. The analysis of current global trends clearly shows an urgent need for innovative approaches. Furthermore, the implementation of green infrastructure has been widely recognized as a pivotal strategy. For instance, the promotion of public transportation, coupled with the creation of green spaces, is indispensable for enhancing city dwellers'' quality of life. It is often argued that such initiatives, though initially costly, ultimately lead to significant long-term economic and environmental benefits. Consequently, many cities are now actively pursuing policies that prioritize pedestrian zones and renewable energy sources. This shift towards a more holistic urban planning approach is viewed by many as a viable solution to mitigate the impacts of climate change. In conclusion, the successful integration of ecological principles into urban design is not merely an option but a necessity for future generations."}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (370, 1, 'listening', 'C1', 'lesson', 'Navigating Urban Integration', '{"source": "ai_nightly", "title_ar": "كيف نتأقلم مع الاندماج بالمدن؟", "questions": [{"stem": "What is one of the primary challenges of urban integration mentioned by Professor Anya?", "choices": ["Lack of job opportunities.", "Insufficient public transportation.", "Inadequate infrastructure to manage population changes.", "Difficulty in accessing higher education."], "correct_index": 2}, {"stem": "According to Mark, what is a crucial aspect often overlooked in the discussion of urban integration?", "choices": ["The economic strain on existing residents.", "The potential for cultural enrichment.", "The need for stricter immigration policies.", "The cost of housing for newcomers."], "correct_index": 1}], "generated_at": "2026-06-23T23:44:38.533739+00:00", "instructions": "Listen to the discussion about urban integration challenges and solutions.", "audio_transcript": "Good morning, Professor Anya. Our topic today, urban integration, is certainly a contentious one, isn''t it? The influx of diverse populations into metropolitan areas presents a myriad of challenges, but also unparalleled opportunities.\nProfessor Anya: Indeed, Mark. Be that as it may, the initial hurdles are often considerable. Infrastructure, for instance, is frequently ill-equipped to handle sudden demographic shifts. Furthermore, there''s the pervasive issue of social cohesion. Newcomers, needless to say, require not just housing but a sense of belonging.\nMark: Precisely. And often, the discourse tends to focus solely on the economic burden, overlooking the cultural enrichment. On the flip side, successful integration hinges on a multi-faceted approach. We''re talking about robust language programs, accessible public services, and spaces for intercultural dialogue. Were governments to invest more proactively in these areas, the long-term benefits would be immeasurable.\nProfessor Anya: Absolutely. The nominalization of ''integration'' often simplifies what is, in reality, a profoundly complex process. A salient point you raised about cultural enrichment cannot be overstated. When diverse perspectives are genuinely embraced, innovation thrives. It''s not merely about accommodating; it''s about fostering an environment where everyone can contribute meaningfully. The passive voice is often used to describe the process, ''communities are integrated,'' but it’s an active, ongoing effort from all sides, demanding collaborative endeavour."}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (371, 1, 'listening', 'C1', 'lesson', 'The Shifting Sands of Work in the Digital Age', '{"source": "ai_nightly", "title_ar": "مستقبل الشغل بعصر الرقمنة: شو ناطرنا؟", "questions": [{"stem": "What is the main concern discussed regarding the future of work?", "choices": ["The increasing cost of technology.", "The rapid pace of industry globalization.", "The profound impact of AI and machine learning on jobs.", "The lack of interest in new career paths."], "correct_index": 2}, {"stem": "According to the guest speaker, what is a key requirement for individuals to be prepared for the future job market?", "choices": ["Focusing on a single, highly specialized career.", "Embracing continuous learning and reskilling.", "Avoiding jobs that involve technology.", "Relying on traditional educational institutions only."], "correct_index": 1}], "generated_at": "2026-06-23T23:44:38.533739+00:00", "instructions": "Listen to the podcast segment discussing the impact of technology on the job market.", "audio_transcript": "Welcome back to ''Future Forward.'' Today, we''re delving into a topic that truly keeps many awake at night: the future of work in an increasingly automated world. Needless to say, artificial intelligence and machine learning are rapidly reshaping industries. The question isn''t if jobs will change, but how profoundly, and what skills will be paramount.\nGuest Speaker: You''ve hit the nail on the head. We''re seeing a significant skills gap emerging. Many traditional roles could well be rendered obsolete, whilst new, highly specialized positions are simultaneously being created. Had we not embraced continuous learning, we would find ourselves woefully unprepared. It''s a double-edged sword, really. Automation must have been seen as a threat by some, yet it also promises unprecedented efficiency and new avenues for human creativity.\nHost: So, it''s not just about adapting, but about proactively reskilling. Little do people realize the extent to which soft skills – critical thinking, adaptability, emotional intelligence – will become the bedrock of future employment. The days of a single career path are largely behind us. Be that as it may, the onus is on individuals and institutions alike to foster a culture of lifelong learning. It''s a paradigm shift that demands foresight, agility, and a commitment to perpetual growth."}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (372, 1, 'listening', 'C2', 'lesson', 'The Unforeseen Path: Navigating Life Abroad', '{"source": "ai_nightly", "title_ar": "درب ما حدا كان متوقعه: كيف نتدبر أمورنا بالغرب؟", "questions": [{"stem": "What is Omar''s primary sentiment regarding his decision to move abroad?", "choices": ["He deeply regrets the decision due to the unexpected difficulties encountered.", "He feels it was a mistake, despite the resilience and character it fostered.", "He acknowledges the difficulties but values the overall experience and personal growth it provided.", "He believes he was adequately prepared for all the challenges faced, contrary to Sarah''s view."], "correct_index": 2}, {"stem": "Sarah emphasizes the importance of which quality for successful integration and personal development?", "choices": ["Thorough pre-planning and extensive research before the move.", "Maintaining a strong, unwavering sense of one''s original cultural identity.", "A high level of adaptability to navigate unfamiliar situations and changes.", "Seeking constant external validation and support from established communities."], "correct_index": 2}], "generated_at": "2026-06-23T23:44:59.284595+00:00", "instructions": "Listen to the conversation between Omar and Sarah about their experience moving abroad and answer the questions.", "audio_transcript": "You know, Sarah, looking back, I often wonder if we truly grasped the full implications of that decision to move abroad. Had I but known the myriad challenges awaiting us – from navigating complex bureaucracy to the subtle shifts in social etiquette – I might have approached things differently. Not for a moment do I regret the adventure, mind you, for it has been an invaluable crucible, but the cultural nuances, the administrative labyrinth – they were far more intricate than we''d ever imagined.\n\nSarah: Indeed, Omar. It was a steep learning curve, wasn''t it? Though, I daresay, it''s precisely those hurdles that forged our resilience. Seldom do people truly appreciate the depth of character one develops when navigating such unfamiliar waters. It is imperative that one maintain a certain level of adaptability, lest one become utterly overwhelmed by the sheer volume of change.\n\nOmar: Absolutely. Never before had I understood the sheer weight of abstract concepts like ''belonging'' or ''identity'' until I found myself adrift in a new land. Yet, for all the initial struggles and moments of profound doubt, it has undeniably been a feather in our cap. Were we to do it again, perhaps we''d be better prepared, having learned to roll with the punches, but the raw experience itself was simply invaluable.\n\nSarah: Precisely. And it''s not just about overcoming external obstacles; it''s about the profound, subtle shifts in one''s internal perspective. Whom among us hasn''t felt that pang of longing for the familiar, only to discover new comforts and a broader sense of self? It’s a testament to the human spirit, wouldn''t you say? And should anyone ask, I''d advocate for the experience wholeheartedly. We''ve truly come into our own, wouldn''t you agree?"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (373, 1, 'listening', 'C2', 'lesson', 'The Ethics of Algorithmic Governance: A Critical Perspective', '{"source": "ai_nightly", "title_ar": "أخلاقيات حوكمة الخوارزميات: وجهة نظر نقدية", "questions": [{"stem": "What is the speaker''s main concern regarding the widespread adoption of algorithmic governance?", "choices": ["The algorithms are not yet efficient enough to handle complex societal decision-making effectively.", "The inherent biases embedded within the datasets and the potential erosion of human agency and accountability.", "The lack of advanced technological infrastructure to support the implementation of these sophisticated systems.", "The algorithms are too transparent, potentially revealing sensitive personal information to the public."], "correct_index": 1}, {"stem": "The speaker uses the phrase \"Can we truly delegate our moral compass to lines of code?\" primarily to achieve what effect?", "choices": ["To express genuine uncertainty about the technical feasibility of algorithms making ethical decisions.", "To suggest that algorithms are inherently superior moral decision-makers compared to humans.", "To emphasize the profound ethical dilemma and provoke critical thought and discussion among the audience.", "To advocate for a complete and immediate ban on all forms of algorithmic governance in society."], "correct_index": 2}], "generated_at": "2026-06-23T23:44:59.284595+00:00", "instructions": "Listen to the lecture on algorithmic governance and answer the questions based on the speaker''s main points.", "audio_transcript": "Good morning, everyone. Today, we delve into a topic of increasing salience: the ethics of algorithmic governance. It is not merely a question of efficiency or optimization; rather, we must contend with profound philosophical implications. Consider, if you will, the notion of ''fairness'' when an algorithm decides credit scores, or even eligibility for social services. Seldom do we pause to dissect the inherent biases embedded within the datasets that train these systems.\n\nFurthermore, one might argue that relinquishing decision-making to algorithms, however sophisticated, inevitably erodes human agency. Were we to fully embrace such a paradigm, what then becomes of individual accountability? It is imperative that we, as a society, establish robust frameworks to ensure transparency and redress. Lest we forget, these are tools designed by humans, and thus, inherit human imperfections.\n\nOne cannot deny the allure of automated systems promising impartiality. Yet, to assume algorithms are inherently neutral is a dangerous fallacy. They reflect the values, or indeed the prejudices, of their creators and the societies in which they operate. For instance, imagine a scenario where predictive policing algorithms disproportionately target certain demographics; the ramifications for social justice are immense.\n\nSo, the rhetorical question I pose is this: Can we truly delegate our moral compass to lines of code? Or should we, conversely, insist that the ultimate arbiters of justice and equity remain human, leveraging technology merely as an aid? The discourse surrounding this is complex, demanding a multidisciplinary approach, lest we inadvertently pave the way for unforeseen societal fractures."}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (374, 1, 'writing', 'B2', 'writing_prompt', 'The Impact of Digital Communication on Social Connections', '{"prompt": "It is often argued that while digital communication tools like social media and messaging apps offer convenience, they simultaneously weaken genuine human connections and face-to-face interaction. Write an essay discussing your agreement or disagreement with this statement. Support your arguments with specific examples and use hedging language where appropriate. Furthermore, consider both the advantages and disadvantages of relying heavily on digital platforms for social interaction.", "source": "ai_nightly", "title_ar": "تأثير التواصل الرقمي على الروابط الاجتماعية", "min_words": 250, "prompt_ar": "غالباً ما يُقال إن أدوات التواصل الرقمي متل السوشال ميديا وتطبيقات المراسلة بتقدّم راحة، بس بنفس الوقت بتضعف الروابط الإنسانية الحقيقية والتفاعل وجهاً لوجه. اكتب مقال بتناقش فيه موافقتك أو عدم موافقتك على هالعبارة. ادعم حججك بأمثلة محددة واستخدم لغة التحوّط (hedging language) لما يكون مناسب. وبالإضافة لهيك، فكّر بالإيجابيات والسلبيات تبع الاعتماد الكبير على المنصات الرقمية للتفاعل الاجتماعي.", "generated_at": "2026-06-23T23:45:15.990550+00:00", "min_sentences": 15}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (375, 1, 'writing', 'B2', 'writing_prompt', 'Analyzing Strategies for Sustainable Urban Traffic Management', '{"prompt": "Urban traffic congestion is a pervasive problem affecting quality of life, economic productivity, and environmental health in many major cities. Write a report analyzing the main causes of traffic congestion and evaluating at least two potential solutions (e.g., improved public transport, smart traffic systems, congestion pricing). You should present data (even if hypothetical) to support your points and discuss the feasibility and potential challenges of implementing these solutions. Use formal academic language, passive voice, and complex sentence structures.", "source": "ai_nightly", "title_ar": "تحليل استراتيجيات إدارة الازدحام المروري المستدام بالمدن", "min_words": 280, "prompt_ar": "الازدحام المروري بالمدن مشكلة منتشرة بتأثر على نوعية الحياة والإنتاجية الاقتصادية والصحة البيئية بكثير مدن رئيسية. اكتب تقرير بتحلل فيه الأسباب الرئيسية للازدحام المروري وبتقيّم حلّين محتملين على الأقل (مثلاً: تحسين النقل العام، أنظمة المرور الذكية، تسعير الازدحام). لازم تقدّم بيانات (حتى لو كانت افتراضية) لتدعم نقاطك وتناقش جدوى وتحديات تطبيق هالـ حلول المحتملة. استخدم لغة أكاديمية رسمية، صيغة المجهول (passive voice)، وتراكيب جمل معقدة.", "generated_at": "2026-06-23T23:45:15.990550+00:00", "min_sentences": 18}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (376, 1, 'writing', 'C1', 'writing_prompt', 'The Nuances of Cultural Integration', '{"prompt": "The process of integrating into a new culture is often fraught with complexities, yet it invariably offers profound opportunities for personal growth and societal enrichment. Consider the myriad challenges faced by individuals, particularly adult Arabic-speaking learners, when adapting to a new cultural milieu, be it in terms of social norms, professional expectations, or linguistic barriers. On the flip side, what are the undeniable benefits that a successful integration brings, not only to the individual but also to the host society? Discuss the pivotal role that both governmental policies and technological advancements play in facilitating or hindering this process. Had societies not invested in inclusive strategies, the repercussions would undoubtedly be far more pervasive. Your response should employ advanced discourse markers, complex conditional structures, and inversion for emphasis where appropriate.", "source": "ai_nightly", "title_ar": "تفاصيل الاندماج الثقافي الدقيقة", "min_words": 300, "prompt_ar": "عملية الاندماج بثقافة جديدة غالباً ما بتكون مليانة تعقيدات، بس بنفس الوقت بتقدم فرص عميقة للنمو الشخصي وإغناء المجتمع. شو التحديات الكبيرة يلي بتواجه الأفراد، وخصوصاً المتعلمين العرب الكبار، لما بيتأقلموا مع بيئة ثقافية جديدة، سواء كان هالشي من ناحية العادات الاجتماعية، التوقعات المهنية، أو الحواجز اللغوية؟ ومن ناحية تانية، شو الفوائد الأكيدة يلي بيجلبها الاندماج الناجح، مو بس للفرد، بل للمجتمع المضيف كمان؟ ناقش الدور المحوري يلي بتلعبه السياسات الحكومية والتطورات التكنولوجية بتسهيل أو إعاقة هالعملية. لو ما استثمرت المجتمعات باستراتيجيات شاملة، أكيد كانت النتائج رح تكون منتشرة أكتر بكتير. لازم تستخدم بتقريرك أدوات ربط متقدمة، صيغ شرطية معقدة، وقلب الجملة للتوكيد وين ما كان مناسب.", "generated_at": "2026-06-23T23:45:34.502727+00:00", "min_sentences": 18}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (377, 1, 'writing', 'C1', 'writing_prompt', 'The AI Revolution: Opportunity or Disruption?', '{"prompt": "Artificial Intelligence (AI) is undeniably poised to reshape myriad aspects of human existence, from the workplace to educational institutions. Craft an argumentative essay in which you explore the potential ramifications of AI on the global job market and existing educational paradigms. Will it lead to widespread job displacement, or will new roles emerge, necessitating a complete overhaul of skill sets? Furthermore, what strategies ought to be implemented to mitigate potential negative impacts whilst harnessing its transformative power? Suffice it to say, the future of work and learning will be profoundly influenced by our collective response to this technological paradigm shift. Be sure to incorporate academic collocations, cohesive devices for complex argumentation, nominalization, and modal verbs for speculation, along with idiomatic expressions.", "source": "ai_nightly", "title_ar": "ثورة الذكاء الاصطناعي: فرصة أو تعطيل؟", "min_words": 300, "prompt_ar": "الذكاء الاصطناعي (AI) أكيد رح يغير كتير من جوانب الوجود البشري، من أماكن الشغل للمؤسسات التعليمية. اكتب مقال جدلي بتستكشف فيه الآثار المحتملة للذكاء الاصطناعي على سوق العمل العالمي والأنماط التعليمية الموجودة. هل رح يؤدي لإزاحة واسعة النطاق للوظائف، أو رح تظهر أدوار جديدة بتستلزم تغيير كامل للمهارات؟ وشو الاستراتيجيات يلي لازم تتطبق لتخفيف الآثار السلبية المحتملة مع الاستفادة من قوته التحويلية؟ غني عن القول، مستقبل العمل والتعلم رح يتأثر بشكل عميق برد فعلنا الجماعي على هالتحول التكنولوجي النموذجي. تأكد من تضمين تراكيب أكاديمية، أدوات ترابط للحجج المعقدة، اشتقاق الأسماء من الأفعال، وأفعال المودال للتكهن، بالإضافة للتعبيرات الاصطلاحية.", "generated_at": "2026-06-23T23:45:34.502727+00:00", "min_sentences": 18}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (378, 1, 'writing', 'C2', 'writing_prompt', 'Navigating Cultural Labyrinths: A Personal Reflection', '{"prompt": "Reflect on a significant cultural misunderstanding or challenge you have encountered while integrating into a new society. Discuss how this experience, had it been handled differently, might have altered your perspective. Employ a range of advanced idiomatic structures, nuanced modal verbs (e.g., ''might have'', ''could have'', ''should have been'', ''were it not for''), complex inversion for emphasis (e.g., ''Never before had I felt...'', ''Little did I know...''), and the subjunctive mood (e.g., ''I wish it were...'', ''It is imperative that one understands...''). Consider the abstract nouns related to identity, belonging, and adaptation. Your response should demonstrate a sophisticated command of English appropriate for C2 level.", "source": "ai_nightly", "title_ar": "التنقل في متاهات الثقافة: تأمل شخصي", "min_words": 350, "prompt_ar": "تأمل في سوء فهم ثقافي كبير أو تحدي واجهته أثناء اندماجك في مجتمع جديد. ناقش كيف أن هذه التجربة، لو أنها عولجت بشكل مختلف، ربما كانت قد غيرت منظورك. استخدم مجموعة من التراكيب الاصطلاحية المتقدمة، الأفعال المساعدة ذات الفروق الدقيقة (مثل ''might have'', ''could have'', ''should have been'', ''were it not for'')، القلب المعقد للتأكيد (مثل ''Never before had I felt...'', ''Little did I know...'')، وصيغة الشرط (Subjunctive mood) (مثل ''I wish it were...'', ''It is imperative that one understands...''). فكر في الأسماء المجردة المتعلقة بالهوية، الانتماء، والتكيف. يجب أن يظهر ردك إتقانًا متطورًا للغة الإنجليزية يناسب مستوى C2.", "generated_at": "2026-06-23T23:45:47.386213+00:00", "min_sentences": 20}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (379, 1, 'writing', 'C2', 'writing_prompt', 'The Paradox of Progress: A Critical Examination', '{"prompt": "Write an argumentative essay exploring the assertion that ''technological advancement, while ostensibly enhancing human capabilities, often engenders unforeseen societal paradoxes and ethical dilemmas.'' Argue for or against this statement, or present a nuanced perspective. Your essay must incorporate advanced cohesive devices to ensure logical flow (e.g., ''consequently'', ''furthermore'', ''notwithstanding''), rhetorical questions to engage the reader, various conditional clauses (including mixed conditionals and inverted conditionals like ''Had it not been for...'', ''Should one consider...''), and the subjunctive mood for formal contexts (e.g., ''It is crucial that society consider...'', ''We recommend that policy be''). Utilize academic discourse markers, persuasive language, and formal register vocabulary, drawing upon abstract nouns pertinent to philosophy, ethics, and social science.", "source": "ai_nightly", "title_ar": "مفارقة التقدم: فحص نقدي", "min_words": 400, "prompt_ar": "اكتب مقالاً حجاجياً يستكشف التأكيد القائل بأن ''التقدم التكنولوجي، بينما يعزز ظاهرياً القدرات البشرية، غالباً ما يولد مفارقات مجتمعية ومعضلات أخلاقية غير متوقعة.'' دافع عن هذا البيان أو اعترض عليه، أو قدم منظوراً دقيقاً. يجب أن يتضمن مقالك أدوات ترابط متقدمة لضمان التدفق المنطقي (مثل ''consequently'', ''furthermore'', ''notwithstanding'')، أسئلة بلاغية لإشراك القارئ، جمل شرطية متنوعة (بما في ذلك الجمل الشرطية المختلطة والمنقلبة مثل ''Had it not been for...'', ''Should one consider...'')، وصيغة الشرط (Subjunctive mood) للسياقات الرسمية (مثل ''It is crucial that society consider...'', ''We recommend that policy be''). استخدم مؤشرات الخطاب الأكاديمي، اللغة الإقناعية، ومفردات السجل الرسمي، مستفيداً من الأسماء المجردة المتعلقة بالفلسفة، الأخلاق، والعلوم الاجتماعية.", "generated_at": "2026-06-23T23:45:47.386213+00:00", "min_sentences": 25}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (380, 1, 'speaking', 'B2', 'speaking_prompt', 'Debating the Impact of Technology on Social Interaction', '{"prompt": "Some people argue that modern technology is increasing our social isolation, while others believe it strengthens connections. What''s your perspective on this? Use expressions like ''I tend to believe that'', ''it seems to me that'', ''on the one hand... on the other hand'', and ''nevertheless'' to articulate your viewpoint persuasively, considering both sides of this controversial issue.", "source": "ai_nightly", "title_ar": "مناقشة تأثير التكنولوجيا على التفاعل الاجتماعي", "prompt_ar": "بعض الناس بيقولوا إنو التكنولوجيا الحديثة عم تزيد عزلتنا الاجتماعية، بينما آخرين بيعتقدوا إنها بتقوي الروابط. شو رأيك بهالشي؟ استخدم عبارات متل ''بميل للاعتقاد إنو''، ''بيتهيألي إنو''، ''من جهة... من جهة أخرى'' و''مع ذلك'' لتعبر عن وجهة نظرك بشكل مقنع، مع الأخذ بعين الاعتبار الجانبين لهي القضية المثيرة للجدل.", "min_seconds": 120, "generated_at": "2026-06-23T23:46:01.538855+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (381, 1, 'speaking', 'B2', 'speaking_prompt', 'Presenting Challenges and Solutions for Integration', '{"prompt": "Imagine you are presenting a report on the main challenges new arrivals face when integrating into a new country''s education system or workforce. What would be your key findings, and what viable solutions do you believe could be implemented? Use academic language, complex sentence structures, and phrases such as ''allow me to elaborate'', ''it is widely believed that'', and ''this could have been avoided if'' to support your analysis and recommendations.", "source": "ai_nightly", "title_ar": "عرض تحديات وحلول الاندماج", "prompt_ar": "تخيل إنك عم تقدم تقرير عن التحديات الأساسية اللي بيواجهوها الوافدين الجداد لما بيندمجوا بنظام التعليم أو سوق العمل ببلد جديد. شو هي النتائج الرئيسية اللي ممكن توصللها، وشو الحلول الممكنة اللي بتشوف إنو لازم تتطبق؟ استخدم لغة أكاديمية، جمل معقدة، وعبارات متل ''اسمحولي أوضح''، ''يُعتقد على نطاق واسع أن''، و''كان من الممكن تجنب هذا لو'' لدعم تحليلك وتوصياتك.", "min_seconds": 150, "generated_at": "2026-06-23T23:46:01.538855+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (382, 1, 'speaking', 'C1', 'speaking_prompt', 'Navigating Cultural Integration', '{"prompt": "The process of cultural integration for newcomers often presents a myriad of challenges, yet, on the flip side, it offers unparalleled opportunities for personal growth and societal enrichment. Discuss, drawing upon your own observations or experiences. To what extent do you believe host societies bear the responsibility for facilitating this integration, and what role, conversely, must immigrants play? Had governments invested more in community-led initiatives, might we not have seen more harmonious outcomes? Incorporate advanced discourse markers and complex conditionals in your response.", "source": "ai_nightly", "title_ar": "تحدّيات الاندماج الثقافي", "prompt_ar": "عملية الاندماج الثقافي للوافدين الجدد غالباً ما بتطرح عدد كبير من التحديات، ولكن، على الوجه الآخر، بتقدّم فرص لا مثيل إلها للنمو الشخصي وإغناء المجتمع. ناقش هالشي، مع الاستناد لملاحظاتك أو تجاربك الخاصة. لأي مدى بتعتقد إنو المجتمعات المضيفة بتحمل مسؤولية تسهيل هالاندماج، وشو الدور اللي لازم يلعبه المهاجرون بالمقابل؟ لو إنو الحكومات استثمرت أكتر بالمبادرات اللي بتقودها المجتمعات المحلية، ألم نكن لنرى نتائج أكتر انسجاماً؟ استخدم تعابير ربط متقدمة وجمل شرطية معقدة بإجابتك.", "min_seconds": 180, "generated_at": "2026-06-23T23:46:17.067290+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (383, 1, 'speaking', 'C1', 'speaking_prompt', 'The Digital Transformation of Learning', '{"prompt": "It is widely contended that the pervasive influence of technology has fundamentally reshaped educational paradigms and will undoubtedly continue to do so, impacting future career trajectories. Speculate on the long-term implications of this digital transformation. Might traditional academic institutions become obsolete, or will they merely adapt? Had artificial intelligence not advanced so rapidly, students might have been afforded more time to develop certain soft skills. Discuss the necessity of lifelong learning in such a dynamic environment, utilizing modal verbs for speculation and complex sentence structures, including nominalization.", "source": "ai_nightly", "title_ar": "التحوّل الرقمي بالتعليم", "prompt_ar": "يُقال على نطاق واسع إنو التأثير المنتشر للتكنولوجيا غيّر بشكل أساسي نماذج التعليم ورح يستمر بلا شك بهالشي، ورح يأثر على المسارات المهنية المستقبلية. تخيّل الآثار طويلة الأمد لهالتحوّل الرقمي. هل ممكن تصير المؤسسات الأكاديمية التقليدية قديمة، أو رح تتكيّف وبس؟ لو ما تطوّر الذكاء الاصطناعي بهالسرعة، كان يمكن للطلاب يحصلوا على وقت أكتر لتطوير مهارات ناعمة معينة. ناقش ضرورة التعلم مدى الحياة بهيك بيئة ديناميكية، مستخدماً الأفعال المساعدة للتخمين والجمل المعقدة، بما في ذلك تحويل الأفعال لأسماء (nominalization).", "min_seconds": 180, "generated_at": "2026-06-23T23:46:17.067290+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (384, 1, 'speaking', 'C2', 'speaking_prompt', 'Navigating Societal Expectations and Personal Autonomy', '{"prompt": "Consider the inherent tension between societal pressures (e.g., career paths, family obligations, cultural traditions) and individual aspirations for autonomy and self-realization. Discuss, with nuance and depth, how individuals might reconcile these conflicting demands, or indeed, challenge them. Be sure to employ advanced idiomatic expressions, a range of modal verbs to express degrees of certainty or obligation, complex inversion for emphasis, and the subjunctive mood where appropriate to articulate formal proposals or hypothetical scenarios. You might ponder, for instance, whether it is truly incumbent upon individuals to conform, or if society itself ought to adapt to evolving personal values.", "source": "ai_nightly", "title_ar": "كيف بتتعامل مع توقعات المجتمع واستقلاليتك الشخصية؟", "prompt_ar": "فكر بالتوتر الكامن بين ضغوط المجتمع (متل مسارات المهنة، الالتزامات العائلية، التقاليد الثقافية) وتطلعات الفرد للاستقلالية وتحقيق الذات. ناقش، بعمق ودقة، كيف ممكن الأفراد يوفقوا بين هالمتطلبات المتضاربة، أو حتى يتحدوها. تأكد من استخدام تعابير اصطلاحية متقدمة، ومجموعة من الأفعال المساعدة (modal verbs) للتعبير عن درجات اليقين أو الالتزام، والصيغ المعكوسة المعقدة للتشديد، وصيغة الشرط (subjunctive mood) عند الضرورة للتعبير عن مقترحات رسمية أو سيناريوهات افتراضية. ممكن تتأمل، مثلاً، إذا كان واجب على الأفراد إنهم يمتثلوا فعلاً، أو إذا كان لازم على المجتمع نفسه يتكيف مع القيم الشخصية المتطورة.", "min_seconds": 180, "generated_at": "2026-06-23T23:46:31.671794+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (385, 1, 'speaking', 'C2', 'speaking_prompt', 'Deconstructing Media Narratives and Public Discourse', '{"prompt": "Analyze a complex, multi-faceted news story or a significant public debate from recent times. Focus on how different media outlets might frame the narrative, the rhetorical strategies employed by various commentators, and the implicit biases or agendas that may underpin their reporting. Utilize academic discourse markers, persuasive language, and formal register vocabulary. Engage in rhetorical analysis, demonstrate your understanding of reported speech nuances, and use hedging language to express nuanced opinions. Consider the ethical implications of media representation and the responsibility of the audience in discerning truth from manipulation. What, in your considered opinion, is the ultimate objective of such discourse, and how might one best navigate its complexities?", "source": "ai_nightly", "title_ar": "كيف بتحلل روايات الإعلام والخطاب العام؟", "prompt_ar": "حلل قصة إخبارية معقدة ومتعددة الأوجه، أو نقاش عام مهم من الأوقات الأخيرة. ركز كيف ممكن وسائل الإعلام المختلفة تصيغ السرد، والاستراتيجيات البلاغية اللي بيستخدمها المعلقون المختلفون، والتحيزات أو الأجندات الضمنية اللي ممكن تكون أساس تقاريرهم. استخدم علامات الخطاب الأكاديمي، اللغة المقنعة، ومفردات السجل الرسمي. انخرط بالتحليل البلاغي، وأظهر فهمك لدقائق الكلام المنقول، واستخدم لغة التحوط للتعبير عن آراء دقيقة. فكر بالآثار الأخلاقية لتمثيل الإعلام ومسؤولية الجمهور بالتمييز بين الحقيقة والتلاعب. شو هو، برأيك المدروس، الهدف النهائي لهيك خطاب، وكيف ممكن الواحد يتنقل بأفضل شكل ضمن تعقيداته؟", "min_seconds": 240, "generated_at": "2026-06-23T23:46:31.671794+00:00"}', NULL, 0, true, '2026-06-24 07:42:10.717049+08');
INSERT INTO public.language_content_items VALUES (386, 1, 'listening', 'B1', 'lesson', 'A Memorable Trip to Italy', '{"source": "ai_nightly", "title_ar": "A Memorable Trip to Italy", "questions": [{"id": "q1", "stem": "What was the main reason the speaker enjoyed the food in Italy?", "type": "detail", "choices": ["It was cheap.", "The ingredients were fresh.", "They cooked it themselves.", "They ate at fancy restaurants."], "explanation": "The speaker explicitly states that they enjoyed the pasta and pizza ''because the ingredients were so fresh and delicious''.", "correct_index": 1, "evidence_quote": "I especially enjoyed the pasta and pizza, because the ingredients were so fresh and delicious."}, {"id": "q2", "stem": "The speaker and their family found it difficult to walk around Rome.", "type": "true_false_notgiven", "choices": ["True", "False", "Not Given"], "explanation": "The speaker said they stayed in a hotel near the city center, ''so it was easy to walk everywhere and explore on foot'', indicating it was not difficult.", "correct_index": 1, "evidence_quote": "We stayed in a small, charming hotel near the city center, so it was easy to walk everywhere and explore on foot."}, {"id": "q3", "stem": "Which city does the speaker plan to visit next year?", "type": "detail", "choices": ["Rome", "Paris", "Barcelona", "London"], "explanation": "The speaker mentions their plan for next year: ''Next year, we''re thinking about going to Spain, as I''ve always wanted to see Barcelona.''", "correct_index": 2, "evidence_quote": "Next year, we''re thinking about going to Spain, as I''ve always wanted to see Barcelona."}, {"id": "q4", "stem": "The speaker described their future travel experience as ____.", "type": "sentence_completion", "choices": ["boring", "challenging", "equally exciting", "relaxing"], "explanation": "The speaker believes their next trip ''will be a different but equally exciting experience''.", "correct_index": 2, "evidence_quote": "I believe it will be a different but equally exciting experience to explore a new culture."}], "generated_at": "2026-07-01T14:34:19.428047+00:00", "instructions": "Listen to the audio and answer the questions.", "audio_transcript": "Last summer, I went to Italy with my family. It was our first time exploring Rome, and we absolutely loved it! We visited the Colosseum and the Vatican City, which were both incredibly impressive. The local cuisine was outstanding; I especially enjoyed the pasta and pizza, because the ingredients were so fresh and delicious. We stayed in a small, charming hotel near the city center, so it was easy to walk everywhere and explore on foot. Although it was quite hot, we had a fantastic time. Next year, we''re thinking about going to Spain, as I''ve always wanted to see Barcelona. I believe it will be a different but equally exciting experience to explore a new culture."}', NULL, 0, true, '2026-07-01 22:33:51.883911+08');
INSERT INTO public.language_content_items VALUES (387, 1, 'listening', 'B1', 'lesson', 'The Pros and Cons of Remote Work', '{"source": "ai_nightly", "title_ar": "The Pros and Cons of Remote Work", "questions": [{"id": "q1", "stem": "What is the speaker''s main opinion about remote work?", "type": "main_idea", "choices": ["It''s always isolating.", "It offers many advantages but also challenges.", "It''s only good for some jobs.", "It makes people work less efficiently."], "explanation": "The speaker discusses both the ''many benefits'' like flexibility and work-life balance, and also mentions challenges like isolation and difficulty separating work from home life.", "correct_index": 1, "evidence_quote": "I think remote work has many benefits. ... However, some people might find it challenging... My colleague... sometimes feels a bit isolated..."}, {"id": "q2", "stem": "The speaker believes that remote work helps with work-life balance.", "type": "true_false_notgiven", "choices": ["True", "False", "Not Given"], "explanation": "The speaker explicitly states, ''I believe it also significantly helps with work-life balance''.", "correct_index": 0, "evidence_quote": "I believe it also significantly helps with work-life balance, allowing more personal time."}, {"id": "q3", "stem": "What is a disadvantage of remote work mentioned by the speaker''s colleague?", "type": "detail", "choices": ["Too many meetings.", "Feeling isolated.", "Lack of technology.", "Long working hours."], "explanation": "The speaker mentions their colleague ''sometimes feels a bit isolated'' when working from home.", "correct_index": 1, "evidence_quote": "My colleague, who works from home full-time, sometimes feels a bit isolated"}, {"id": "q4", "stem": "The speaker suggests companies should offer a ____ model for work.", "type": "sentence_completion", "choices": ["traditional", "fully remote", "hybrid", "flexible only"], "explanation": "The speaker states, ''In my opinion, companies should strongly consider offering a hybrid model.''", "correct_index": 2, "evidence_quote": "In my opinion, companies should strongly consider offering a hybrid model."}], "generated_at": "2026-07-01T14:34:19.428047+00:00", "instructions": "Listen to the audio about remote work and choose the best answers.", "audio_transcript": "I think remote work has many benefits. For me, the flexibility is the biggest advantage because I can manage my time better and avoid the daily commute. I believe it also significantly helps with work-life balance, allowing more personal time. However, some people might find it challenging to separate their work life from their home life. My colleague, who works from home full-time, sometimes feels a bit isolated, although he really enjoys the freedom of not having to travel to the office every day. In my opinion, companies should strongly consider offering a hybrid model. This way, employees get the best of both worlds – some office interaction and some flexible remote days. It''s an interesting topic, and I consider it very important for the future of work."}', NULL, 0, true, '2026-07-01 22:33:51.883911+08');
INSERT INTO public.language_content_items VALUES (388, 1, 'listening', 'B1', 'lesson', 'A Challenging Work Project', '{"source": "ai_nightly", "title_ar": "A Challenging Work Project", "questions": [{"id": "q1", "stem": "What is the main challenge the speaker mentions about their current project?", "type": "detail", "choices": ["Difficult colleagues.", "A very tight deadline.", "Lack of resources.", "Uninteresting work."], "explanation": "The speaker states, ''It''s quite challenging because we have a very tight deadline.''", "correct_index": 1, "evidence_quote": "It''s quite challenging because we have a very tight deadline"}, {"id": "q2", "stem": "The new software feature is designed to improve employee satisfaction.", "type": "true_false_notgiven", "choices": ["True", "False", "Not Given"], "explanation": "The transcript says the feature ''will improve customer experience significantly,'' not employee satisfaction.", "correct_index": 1, "evidence_quote": "We’re developing a new software feature that will improve customer experience significantly."}, {"id": "q3", "stem": "Who helped the team find a solution to the technical issue?", "type": "detail", "choices": ["A new employee.", "A consultant.", "Their manager.", "Another department."], "explanation": "The speaker mentions, ''My manager, who is always very supportive, helped us find a solution quickly.''", "correct_index": 2, "evidence_quote": "My manager, who is always very supportive, helped us find a solution quickly."}, {"id": "q4", "stem": "The speaker believes the project could lead to a ____ for some team members.", "type": "sentence_completion", "choices": ["holiday", "new job", "promotion", "transfer"], "explanation": "The speaker expresses optimism that the project ''could even lead to a promotion for some of us.''", "correct_index": 2, "evidence_quote": "could even lead to a promotion for some of us."}], "generated_at": "2026-07-01T14:34:19.428047+00:00", "instructions": "Listen to the speaker talk about their work and answer the questions.", "audio_transcript": "Currently, I''m working on a big project at my company. It''s quite challenging because we have a very tight deadline, but I enjoy working with my colleagues. We’re developing a new software feature that will improve customer experience significantly. Last week, we faced a major technical issue, which delayed us a bit. My manager, who is always very supportive, helped us find a solution quickly. We had to work extra hours, so it was tiring, but we’re making good progress now. I believe this project will be a great accomplishment for the whole team and could even lead to a promotion for some of us. It''s a busy time, but also very rewarding to see our hard work pay off."}', NULL, 0, true, '2026-07-01 22:33:51.883911+08');
INSERT INTO public.language_conversation_scenarios VALUES (3, 1, 'city_hall', 'Registering at the City Hall', 'تسجيل العنوان بالبلدية', 'Register your new address at the residents'' office and answer the clerk''s questions.', 'سجّل عنوان سكنك الجديد بمكتب المواطنين (Einwohnermeldeamt) وجاوب على أسئلة الموظف وقدّم أوراقك.', 'A2', 'a civil servant at the Einwohnermeldeamt', 'a resident registering their address', 'Good morning. How can I help you today? Are you here to register a new address?', false, 2, 'daily_conversation', '[]');
INSERT INTO public.language_conversation_scenarios VALUES (4, 1, 'apartment_search', 'Apartment Viewing', 'تأجير شقة', 'View an apartment with a landlord, ask about the rent and the rules, and decide if it suits you.', 'شوف الشقة مع صاحب البيت، واسأل عن الآجار والشروط والمصاريف، وقرّر إذا بتناسبك.', 'A2', 'a landlord showing an apartment', 'a prospective tenant', 'Hi, welcome! Come on in, let me show you around. This is the living room. So, what are you looking for in an apartment?', false, 3, 'daily_conversation', '[]');
INSERT INTO public.language_conversation_scenarios VALUES (6, 1, 'bank_account', 'Opening a Bank Account', 'فتح حساب بنكي', 'Open a new bank account, ask about the card, fees, and online banking.', 'افتح حساب جديد بالبنك، واسأل عن البطاقة والرسوم والخدمات أونلاين.', 'A2', 'a bank employee helping open an account', 'a new customer', 'Good afternoon, welcome. How can I help you today? Would you like to open a new account with us?', false, 5, 'daily_conversation', '[]');
INSERT INTO public.language_conversation_scenarios VALUES (7, 1, 'job_agency', 'Employment Agency (Jobcenter)', 'مكتب التوظيف (Jobcenter)', 'Meet an employment counselor, discuss the kind of work you want, and ask about support.', 'احكي مع مستشار التوظيف عن نوع الشغل يلي بتدوّر عليه، واسأل عن المساعدات والدورات.', 'B1', 'an employment counselor at the Jobcenter', 'a job seeker', 'Hello, please sit down. I''ve had a look at your file. Let''s talk about your job search — what kind of work are you looking for?', false, 6, 'daily_conversation', '[]');
INSERT INTO public.language_conversation_scenarios VALUES (5, 1, 'university_office', 'University Admissions Office', 'مكتب القبول الجامعي', 'Speak with an admissions officer about a study program, requirements, and the documents you need.', 'احكي مع موظف القبول عن التخصص يلي بدك ياه، والشروط، والأوراق المطلوبة للتسجيل.', 'B1', 'a university admissions officer', 'a prospective student', 'Hello, please come in. So, you''re interested in applying to our university? Which program are you considering?', false, 4, 'daily_conversation', '[]');
INSERT INTO public.language_conversation_scenarios VALUES (9, 1, 'airport_checkin', 'Airport Immigration', 'الجوازات في المطار', 'Answer simple questions at passport control. Show your passport and explain why you are visiting.', 'جاوب على أسئلة بسيطة عند الجوازات. ورّي جوازك واشرح ليش مسافر.', 'A1', 'an airport immigration officer', 'a traveler arriving at the airport', 'Good morning. Passport, please. Where are you flying from today?', true, 0, 'airport', '["speaking", "listening", "vocabulary"]');
INSERT INTO public.language_conversation_scenarios VALUES (10, 1, 'hotel_reception', 'Hotel Check-in', 'تسجيل الدخول بالفندق', 'Check in at the hotel desk, give your name, and ask about your room and breakfast.', 'سجّل دخولك عند استقبال الفندق، قدّم اسمك، واسأل عن الغرفة والإفطار.', 'A2', 'a hotel receptionist', 'a guest checking in', 'Hello, welcome to the Grand Hotel. Do you have a reservation with us?', true, 1, 'hotel', '["speaking", "listening", "vocabulary"]');
INSERT INTO public.language_conversation_scenarios VALUES (11, 1, 'restaurant_order', 'Ordering at a Restaurant', 'الطلب في المطعم', 'Order food and drinks, ask about ingredients, and request the bill.', 'اطلب أكل ومشروبات، اسأل عن المكونات، واطلب الفاتورة.', 'A2', 'a restaurant server', 'a customer at a restaurant', 'Hi there! Welcome. Are you ready to order, or do you need a few more minutes with the menu?', true, 2, 'restaurant', '["speaking", "vocabulary", "fluency"]');
INSERT INTO public.language_conversation_scenarios VALUES (12, 1, 'university_admissions', 'University Admissions Office', 'مكتب القبول الجامعي', 'Discuss your study program, entry requirements, deadlines, and required documents in detail.', 'ناقش التخصص، شروط القبول، المواعيد النهائية، والأوراق المطلوبة بالتفصيل.', 'B2', 'a university admissions officer', 'a prospective international student', 'Good afternoon. Thanks for coming in. Which program are you applying for, and what motivated you to choose it?', true, 3, 'university', '["speaking", "fluency", "grammar"]');
INSERT INTO public.language_conversation_scenarios VALUES (1, 1, 'job_interview', 'Job Interview', 'مقابلة عمل', 'Introduce yourself, describe your experience, and answer interview questions professionally.', 'عرّف عن حالك، احكي عن خبرتك، وجاوب على أسئلة المقابلة باحترافية.', 'B1', 'a hiring manager', 'a job applicant', 'Good morning, thank you for coming in. Please, have a seat. Could you tell me a little about yourself?', true, 4, 'job_interview', '["speaking", "fluency", "grammar"]');
INSERT INTO public.language_conversation_scenarios VALUES (2, 1, 'doctor_visit', 'Doctor Visit', 'زيارة الدكتور', 'Describe your symptoms, answer the doctor''s questions, and ask about treatment.', 'وصف أعراضك، جاوب على أسئلة الدكتور، واسأل عن العلاج.', 'A2', 'a doctor', 'a patient', 'Hello, please come in. What seems to be the problem today? How long have you felt this way?', true, 5, 'doctor', '["speaking", "vocabulary", "listening"]');
INSERT INTO public.language_conversation_scenarios VALUES (8, 1, 'daily_shopping', 'Daily Shopping', 'تسوّق يومي', 'Buy groceries, ask for help finding items, and pay at the checkout.', 'اشتري غراضك، اطلب مساعدة للعثور على منتج، وادفع عند الكاشير.', 'A1', 'a shop assistant', 'a customer shopping for groceries', 'Hello! Can I help you find anything today?', true, 6, 'shopping', '["speaking", "vocabulary", "listening"]');
INSERT INTO public.language_conversation_scenarios VALUES (13, 1, 'daily_conversation', 'Daily Conversation', 'محادثة يومية', 'Chat with a neighbor about your day, the weather, and weekend plans.', 'احكي مع جارك عن يومك، الطقس، وخطط نهاية الأسبوع.', 'A1', 'a friendly neighbor', 'a neighbor you just met', 'Hi! Nice to meet you. I''m Alex from next door. How''s your day going so far?', true, 7, 'daily_conversation', '["speaking", "fluency", "vocabulary"]');
