INSERT INTO public.language_placement_questions VALUES (27, 8, 'mcq', '{"stem": "Choose the correct meaning of: \"rapid\"", "choices": ["slow", "quick", "tired", "empty"]}', NULL, '{"correct_index": 1}', 1, 'A1', 0);
INSERT INTO public.language_placement_questions VALUES (28, 8, 'mcq', '{"stem": "Choose the correct word to complete: \"I ___ to school every day.\"", "choices": ["go", "goes", "going", "gone"]}', NULL, '{"correct_index": 0}', 1, 'A1', 1);
INSERT INTO public.language_placement_questions VALUES (29, 8, 'mcq', '{"stem": "Choose the correct meaning of: \"accurate\"", "choices": ["wrong", "exact", "small", "loud"]}', NULL, '{"correct_index": 1}', 1, 'A2', 2);
INSERT INTO public.language_placement_questions VALUES (30, 8, 'mcq', '{"stem": "Which sentence is correct?", "choices": ["She don’t like apples.", "She doesn’t likes apples.", "She doesn’t like apple.", "She not like apples."]}', NULL, '{"correct_index": 0}', 1, 'A2', 3);
INSERT INTO public.language_placement_questions VALUES (31, 8, 'mcq', '{"stem": "Short text: \"Tom missed the bus, so he arrived late.\" Why was Tom late?", "choices": ["He missed the bus.", "He lost his keys.", "He woke up early.", "He ran fast."]}', NULL, '{"correct_index": 0}', 1, 'B1', 4);
